end
local function thAccBright()
    local r,g,b=getAcc()
    return iv4(math.min(1,r*1.15),math.min(1,g*1.15),math.min(1,b*1.15))
end

local function getRowBgColor()
    if cfg.rowBgR >= 0 then
        return cfg.rowBgR, cfg.rowBgG, cfg.rowBgB
    end
    local r,g,b = getAcc()
    return r, g, b
end

function pcsRowA(base)
    local k = (tonumber(cfg.rowBgAlpha) or 0.98) / 0.98
    local a = (base or 0.98) * k
    if a < 0.02 then a = 0.02 end
    if a > 1.0 then a = 1.0 end
    return a
end

function PCS_TA(col)
    local k = PCS_TEXT_A
    if not k or k >= 0.999 then return col end
    local c = tonumber(col)
    if not c then return col end
    local a = math.floor(c / 16777216) % 256
    return (c - a * 16777216) + math.floor(a * k + 0.5) * 16777216
end
 St = {}
St.UI_SCALE      = 1.0   -- pereschityvaetsya kazhdyi kadr po DisplaySize
 St.UI_SCALE_MIN  = 0.88
 St.UI_SCALE_MAX  = 1.65
 St._lastSw, St._lastSh = 0, 0

local function S(n)
    return math.floor(n * St.UI_SCALE + 0.5)
end
local function Sf(n)
    return n * St.UI_SCALE
end
local function SFtext(n)
    local fs = (cfg.fontSize and cfg.fontSize > 0) and cfg.fontSize or 1.25
    return math.floor(n * St.UI_SCALE * fs + 0.5)
end

PCS_TAX_ALOG_PATH = nil
function PCS_taxALog(text)
    pcall(function()
        if not PCS_TAX_ALOG_PATH then PCS_TAX_ALOG_PATH = CFG_DIR .. "/tax_actions.log" end
        local f = io.open(PCS_TAX_ALOG_PATH, "a")
        if not f then return end
        if (f:seek("end") or 0) > 512 * 1024 then
            f:close()
            os.remove(PCS_TAX_ALOG_PATH .. ".old")
            os.rename(PCS_TAX_ALOG_PATH, PCS_TAX_ALOG_PATH .. ".old")
            f = io.open(PCS_TAX_ALOG_PATH, "a")
            if not f then return end
        end
        f:write(os.date("[%Y-%m-%d %H:%M:%S] ") .. (tostring(text):gsub("[\r\n]", " ")) .. "\n")
        f:close()
    end)
end

PCS_TR = (function()
    local path = CFG_DIR .. "/tax_trace.txt"
    local prev = CFG_DIR .. "/tax_trace_prev.txt"
    pcall(function() createDirectory("moonloader/config") end)
    pcall(function() createDirectory(CFG_DIR) end)
    pcall(function()
        local f = io.open(path, "rb")
        if f then
            local b = f:read("*a"); f:close()
            if b and #b > 0 then
                local o = io.open(prev, "wb")
                if o then o:write(b); o:close() end
            end
        end
    end)
    local f = io.open(path, "wb")
    -- UTF-8 BOM: Notepad & co show Cyrillic correctly instead of mojibake
    if f then pcall(function() f:write("\239\187\191") end) end
    local n, LW, NL = 0, 100, 40
    return function(text)
        if type(text) == "string" and text:sub(1, 4) == "tax:" then PCS_taxALog(text) end
        if not f then return end
        n = n + 1
        pcall(function()
            local line = string.format("%06d %.2f %s", n, os.clock(), tostring(text)):gsub("[\r\n]", " ")
            if #line > LW - 1 then
                line = line:sub(1, LW - 1)
                -- never cut a multibyte UTF-8 char in the middle (that gave "?" garbage at line end)
                local cut = #line
                local i = cut
                while i > 0 and i > cut - 4 do
                    local b = line:byte(i)
                    if b >= 0xC0 then
                        local need = (b >= 0xF0 and 4) or (b >= 0xE0 and 3) or 2
                        if cut - i + 1 < need then cut = i - 1 end
                        break
                    elseif b < 0x80 then
                        break
                    end
                    i = i - 1
                end
                line = line:sub(1, cut)
            end
            line = line .. string.rep(" ", LW - 1 - #line) .. "\n"
            f:seek("set", 3 + ((n - 1) % NL) * LW)
            f:write(line)
            f:flush()
        end)
    end
end)()

