local _socket_gettime = nil
do
    local ok, sock = pcall(require, "socket")
    if ok and sock and sock.gettime then
        _socket_gettime = sock.gettime
    end
end
local function getTime()
    if _socket_gettime then return _socket_gettime() end
    return os.clock()
end
local function now() return getTime() end
local function trim(s) return (tostring(s or "")):match("^%s*(.-)%s*$") end

local function stripColor(s)
    if not s then return "" end
    s = tostring(s)
    s = s:gsub("{%x%x%x%x%x%x}", "")
    s = s:gsub("{%x%x%x%x%x%x%x%x}", "")
    s = s:gsub("{#[%x%d]+}", "")
    s = s:gsub("%[%x%x%x%x%x%x%]", "")
    s = s:gsub("~[rgbypwsh]~", "")
    s = s:gsub("~n~", "\n")
    return s
end

local function stripBrackets(s)
    s = trim(s or "")
    if s:match("^%b[]$") then s=s:sub(2,-2) end
    return s
end

local function vOrDash(v)
    v = trim(stripBrackets(v or ""))
    return v ~= "" and v or "-"
end

local function hasVal(v)
    return trim(stripBrackets(v or "")) ~= ""
end

local function fmtDots(s)
    s = tostring(s or ""):gsub("%D","")
    if s=="" then return "0" end
    if #s<4 then return s end
    local rev = s:reverse()
    local out = rev:gsub("(%d%d%d)", "%1.")
    if out:sub(-1)=="." then out = out:sub(1,-2) end
    local result = out:reverse()
    if result:sub(1,1)=="." then result = result:sub(2) end
    return result
end

local function fmtMoney(v)
    if v == nil then return "-" end
    local s = trim(stripBrackets(tostring(v)))
    if s=="" or s=="-" then return "-" end
    local neg = s:match("^%-")
    if s:find("[eE]") then
        local n = tonumber(s)
        if n then s = string.format("%.0f", math.abs(n))
        else s = "0" end
    else
        s = s:gsub("%D","")
    end
    if s=="" or s=="0" then return "$0" end
    return (neg and "-$" or "$") .. fmtDots(s)
end

local function toNum(v)
    if v == nil then return 0 end
    local s = trim(stripBrackets(tostring(v)))
    if s == "" then return 0 end
    local neg = s:match("^%-") ~= nil
    s = s:gsub(",", ".")
    local numPart, suf = s:match("^([%d%.]+)%s*([%a\xe0-\xff]*)$")
    if numPart and suf and suf ~= "" then
        local lsuf = suf:lower()
        local mult = nil
        if lsuf:find("^kkk") or lsuf:find("^\xea\xea\xea") or lsuf == "b" then
            mult = 1e9
        elseif lsuf:find("^kk") or lsuf:find("^\xea\xea") or lsuf == "m" then
            mult = 1e6
        elseif lsuf:find("^k") or lsuf:find("^\xea") then
            mult = 1e3
        end
        if mult then
            local n2 = tonumber(numPart)
            if n2 then
                if neg then n2 = -n2 end
                return n2 * mult
            end
        end
    end
    s = s:gsub("[^%d%.]", "")
    if s:find("%.") then
        local segs = {}
        for part in (s.."."):gmatch("([^%.]*)%.") do segs[#segs+1] = part end
        local lastSeg = segs[#segs]
        if lastSeg and #lastSeg == 3 and #segs >= 2 then
            s = table.concat(segs)
        else
            local intSegs = {}
            for i=1,#segs-1 do intSegs[#intSegs+1] = segs[i] end
            s = table.concat(intSegs) .. "." .. (lastSeg or "")
        end
    end
    local n = tonumber(s) or 0
    if neg then n = -n end
    return n
end

local function fmtInt(n)
    n = tonumber(n) or 0
    local neg = n < 0
    local s = fmtDots(string.format("%.0f", math.abs(n)))
    return (neg and "-" or "") .. s
end

local function fmtAmt(n)
    n = tonumber(n) or 0
    if math.abs(n - math.floor(n+0.5)) < 0.001 then
        return fmtInt(math.floor(n+0.5))
    else
        return string.format("%.2f", n)
    end
end

local function looksTexture(t)
    if t == nil then return true end
    local s = tostring(t)
    return s == "" or s == " " or s == "null"
        or s:find("LD_", 1, true) or s:find("ld_", 1, true)
        or s:find(".txd", 1, true) or s:find(".saa", 1, true)
        or s:find("preview", 1, true)
end

local function isStatsPiece(t)
    local s = stripColor(t or "")
    return s:find("\xce\xf1\xed\xee\xe2\xed\xe0\xff \xf1\xf2\xe0\xf2\xe8\xf1\xf2\xe8\xea\xe0",1,true)
        or s:find("\xcd\xee\xec\xe5\xf0 \xe0\xea\xea\xe0\xf3\xed\xf2\xe0",1,true)
        or s:find("\xc8\xec\xff:",1,true)
        or s:find("\xcf\xee\xeb:",1,true)
        or s:find("\xc7\xe4\xee\xf0\xee\xe2\xfc\xe5:",1,true)
        or s:find("\xd3\xf0\xee\xe2\xe5\xed\xfc:",1,true)
        or s:find("\xd0\xe0\xe1\xee\xf2\xe0:",1,true)
        or s:find("AZ%-Coins",1,true)
        or s:find("\xc7\xe0\xf9\xe8\xf2\xe0:",1,true)
        or s:find("\xd3\xe4\xe0\xf7\xe0:",1,true)
end

local function parseStats(raw)
    local p = {
        accountNumber="",authDate="",accountState="",
        x3Payday="",x4Payday="",
        name="",gender="",health="",level="",respect="",
        cashSas="",cashVcs="",euro="",btc="",azCoins="",asc="",
        phone="",bank="",moneyDay="",bankCard="",
        acc={},
        job="",org="",position="",status="",citizenship="",family="",
        wanted="",lawfulness="",warnings="",addiction="",
        protection="",regen="",damage="",luck="",
        maxHp="",maxArmor="",stunChance="",bleedChance="",
        dodgeChance="",reflectDamage="",blockDamage="",
        fireRate="",recoil="",fruitStun="",
        hotel="",hotelRoom="",trailer="",
        firstLine="",
        extra={}
    }
    do
        local firstCl = ""
        for line in (raw.."\n"):gmatch("([^\n]*)\n") do
            local cl0 = trim(stripColor(line))
            if cl0 ~= "" and cl0 ~= u8"\xce\xf1\xed\xee\xe2\xed\xe0\xff \xf1\xf2\xe0\xf2\xe8\xf1\xf2\xe8\xea\xe0" then
                firstCl = cl0
                break
            end
        end
        p.firstLine = firstCl
    end
    for line in (raw.."\n"):gmatch("([^\n]*)\n") do
        local cl = trim(stripColor(line))
        if cl and cl ~= "" then
            local k,v = cl:match("^(.-):%s*(.+)$")
            if k and v then
                k=trim(k); v=trim(v)
                local ai = k:match("^\xd1\xee\xf1\xf2\xee\xff\xed\xe8\xe5 \xeb\xe8\xf7\xed\xee\xe3\xee \xf1\xf7\xe5\xf2[\xe0\xb8]%s*\xb9%s*(%d+)$")
                if ai then p.acc[tonumber(ai)] = v
                elseif cl:find("PayDay",1,true) or cl:find("PAYDAY",1,true) then
                    local s2 = cl:lower():gsub("[\xd7\xd5\xf5]","x"):gsub("%s","")
                    if s2:find("x4") or s2:find("4x") then p.x4Payday=v
                    elseif s2:find("x3") or s2:find("3x") then p.x3Payday=v end
                elseif k:find("\xcd\xee\xec\xe5\xf0 \xe0\xea\xea\xe0\xf3\xed\xf2\xe0",1,true) then p.accountNumber=v
                elseif k:find("\xc0\xe2\xf2\xee\xf0\xe8\xe7\xe0\xf6\xe8\xff",1,true) then p.authDate=v
                elseif k:find("\xd2\xe5\xea\xf3\xf9\xe5\xe5 \xf1\xee\xf1\xf2\xee\xff\xed\xe8\xe5",1,true) then p.accountState=v
                elseif k=="\xc8\xec\xff" then p.name=v
                elseif k=="\xcf\xee\xeb" then p.gender=v
                elseif k=="\xc7\xe4\xee\xf0\xee\xe2\xfc\xe5" then p.health=v
                elseif k=="\xd3\xf0\xee\xe2\xe5\xed\xfc" then p.level=v
                elseif k=="\xd3\xe2\xe0\xe6\xe5\xed\xe8\xe5" then p.respect=v
                elseif k:find("\xcd\xe0\xeb\xe8\xf7\xed\xfb\xe5 \xe4\xe5\xed\xfc\xe3\xe8 %(SA%$%)") then p.cashSas=v
                elseif k:find("\xcd\xe0\xeb\xe8\xf7\xed\xfb\xe5 \xe4\xe5\xed\xfc\xe3\xe8 %(VC%$%)") then p.cashVcs=v
                elseif k=="\xc5\xe2\xf0\xee"
                    or k:find("\xc0\xea\xf6\xe8\xe8",1,true)
                    or k:find("AAR+P")
                    or k:lower():find("aar+p")
                    or (k:find("Arizona",1,true) and not k:find("Coin",1,true))
                    or (k:lower():find("arizona",1,true) and not k:lower():find("coin",1,true)) then p.euro=v
                elseif (k:find("Arizona",1,true) and k:find("Coin",1,true))
                    or (k:lower():find("arizona",1,true) and k:lower():find("coin",1,true))
                    or k:find("ASC",1,true) then p.asc=v
                elseif k=="BTC" then p.btc=v
                elseif k:find("AZ",1,true) and k:find("oin",1,true) then p.azCoins=v
                elseif k=="\xcd\xee\xec\xe5\xf0 \xf2\xe5\xeb\xe5\xf4\xee\xed\xe0" then p.phone=v
                elseif k=="\xc4\xe5\xed\xfc\xe3\xe8 \xe2 \xe1\xe0\xed\xea\xe5" then p.bank=v
                elseif k:find("\xc4\xe5\xed\xfc\xe3\xe8 \xed\xe0 \xe4\xe5\xef\xee\xe7\xe8\xf2",1,true) then p.moneyDay=v
                elseif k=="\xc1\xe0\xed\xea\xee\xe2\xf1\xea\xe0\xff \xea\xe0\xf0\xf2\xe0" then p.bankCard=v
                elseif k=="\xd0\xe0\xe1\xee\xf2\xe0" then p.job=v
                elseif k=="\xce\xf0\xe3\xe0\xed\xe8\xe7\xe0\xf6\xe8\xff" then p.org=v
                elseif k=="\xc4\xee\xeb\xe6\xed\xee\xf1\xf2\xfc" then p.position=v
                elseif k=="\xd1\xf2\xe0\xf2\xf3\xf1" then p.status=v
                elseif k=="\xc3\xf0\xe0\xe6\xe4\xe0\xed\xf1\xf2\xe2\xee" then p.citizenship=v
                elseif k=="\xd1\xe5\xec\xfc\xff" then p.family=v
                elseif k=="\xd3\xf0\xee\xe2\xe5\xed\xfc \xf0\xee\xe7\xfb\xf1\xea\xe0" then p.wanted=v
                elseif k=="\xc7\xe0\xea\xee\xed\xee\xef\xee\xf1\xeb\xf3\xf8\xed\xee\xf1\xf2\xfc" then p.lawfulness=v
                elseif k=="\xcf\xf0\xe5\xe4\xf3\xef\xf0\xe5\xe6\xe4\xe5\xed\xe8\xff" then p.warnings=v
                elseif k:find("\xc7\xe0\xe2\xe8\xf1\xe8\xec\xee\xf1\xf2\xfc",1,true) then p.addiction=v
                elseif k=="\xc7\xe0\xf9\xe8\xf2\xe0" then p.protection=v
                elseif k=="\xd0\xe5\xe3\xe5\xed\xe5\xf0\xe0\xf6\xe8\xff" then p.regen=v
                elseif k=="\xd3\xf0\xee\xed" then p.damage=v
                elseif k=="\xd3\xe4\xe0\xf7\xe0" then p.luck=v
                elseif k=="\xcc\xe0\xea\xf1. HP" then p.maxHp=v
                elseif k:find("\xcc\xe0\xea\xf1.",1,true) and k:find("\xf0\xee\xed",1,true) then p.maxArmor=v
                elseif k=="\xd8\xe0\xed\xf1 \xee\xe3\xeb\xf3\xf8\xe5\xed\xe8\xff" then p.stunChance=v
                elseif k:find("\xd8\xe0\xed\xf1 \xee\xef",1,true) then p.bleedChance=v
                elseif k:find("\xd8\xe0\xed\xf1 \xe8\xe7\xe1\xe5\xe6",1,true) then p.dodgeChance=v
                elseif k=="\xce\xf2\xf0\xe0\xe6\xe5\xed\xe8\xe5 \xf3\xf0\xee\xed\xe0" then p.reflectDamage=v
                elseif k=="\xc1\xeb\xee\xea\xe8\xf0\xee\xe2\xea\xe0 \xf3\xf0\xee\xed\xe0" then p.blockDamage=v
                elseif k=="\xd1\xea\xee\xf0\xee\xf1\xf2\xf0\xe5\xeb\xfc\xed\xee\xf1\xf2\xfc" then p.fireRate=v
                elseif k=="\xce\xf2\xea\xe0\xf2" then p.recoil=v
                elseif k:find("\xcf\xeb\xee\xe4",1,true) then p.fruitStun=v
                elseif k=="\xce\xf2\xe5\xeb\xfc" then p.hotel=v
                elseif k:find("\xca\xee\xec\xed\xe0\xf2\xe0",1,true) then p.hotelRoom=v
                elseif k=="\xd2\xf0\xe5\xe9\xeb\xe5\xf0" then p.trailer=v
                else table.insert(p.extra,{k,v}) end
            end
        end
    end
    -- Premium VIP: по строке "Статус" из /stats (нужно для блокировки оплаты налогов с телефона)
    p.isPremium = ((p.status or ""):lower():find("premium", 1, true) ~= nil)
    local total=0; local found=false
    for i=1,6 do
        local v=p.acc[i]
        if v and trim(v)~="" then
            local n=tonumber((v:gsub("%D","")))
            if n then total=total+n; found=true end
        end
    end
    p.totalAcc = found and fmtMoney(string.format("%.0f", total)) or ""

    if p.asc=="" then
        for line in (raw.."\n"):gmatch("([^\n]*)\n") do
            local cl = trim(stripColor(line))
            if cl ~= "" and (cl:lower():find("arizona") and cl:lower():find("coin") or cl:find("ASC",1,true)) then
                local num = cl:match("([%d][%d%s.,]*)%s*$") or cl:match("([%d][%d%s.,]*)")
                if num then p.asc = trim(num); break end
            end
        end
    end
    if p.euro=="" then
        for line in (raw.."\n"):gmatch("([^\n]*)\n") do
            local cl = trim(stripColor(line))
            if cl ~= "" and cl:lower():find("aar+p") then
                local num = cl:match("([%d][%d%s.,]*)%s*$") or cl:match("([%d][%d%s.,]*)")
                if num then p.euro = trim(num) end
                break
            end
        end
    end
    return p
end

PCS_STYLE_FAIL = { col = false, v2 = false } -- globals: file is at the 200-locals limit
function setCol(C, idx, r, g, b, a)
    if not PCS_STYLE_FAIL.col then
        local ok = pcall(function()
            local c = C[idx]
            c.x = r; c.y = g; c.z = b; c.w = a or 1.0
        end)
        if ok then return end
        PCS_STYLE_FAIL.col = true
    end
    C[idx] = imgui.ImVec4(r, g, b, a or 1.0)
end
function setVec2(st, key, x, y)
    if not PCS_STYLE_FAIL.v2 then
        local ok = pcall(function()
            local v = st[key]
            v.x = x; v.y = y
        end)
        if ok then return end
        PCS_STYLE_FAIL.v2 = true
    end
    st[key] = imgui.ImVec2(x, y)
end
function PCS_isFinite(v)
    return type(v) == "number" and v == v and math.abs(v) < 1e7
end

local function applyStyle()
    local s   = imgui.GetStyle()
    local r,g,b = getAcc()
    local t   = getTheme()
    local C   = s.Colors
    -- прозрачность фона окна и текста (Настройки -> ползунки прозрачности);
    -- PCS_TEXT_A читает прокси imgui, чтобы применить её и к TextColored
    local wa = tonumber(cfg.winBgAlpha) or 1.0
    if wa < 0.05 then wa = 0.05 elseif wa > 1.0 then wa = 1.0 end
    local ta = tonumber(cfg.textAlpha) or 1.0
    if ta < 0.25 then ta = 0.25 elseif ta > 1.0 then ta = 1.0 end
    PCS_TEXT_A = ta
    if cfg.winBgR and cfg.winBgR >= 0 then
        setCol(C, imgui.Col.WindowBg, cfg.winBgR, cfg.winBgG, cfg.winBgB, wa)
        setCol(C, imgui.Col.ChildBg, cfg.winBgR, cfg.winBgG, cfg.winBgB, 0.55 * wa)
    elseif cfg.uiLightMode then
        setCol(C, imgui.Col.WindowBg, 0.95, 0.95, 0.97, wa)
        setCol(C, imgui.Col.ChildBg, 1.00, 1.00, 1.00, 0.55 * wa)
    else
        setCol(C, imgui.Col.WindowBg, 0.00, 0.00, 0.00, wa)
        setCol(C, imgui.Col.ChildBg, 0.00, 0.00, 0.00, 0.55 * wa)
    end
    local v2 = cfg.uiDesignV2 == true
    if v2 then
        setCol(C, imgui.Col.TitleBg, r*0.55, g*0.55, b*0.55, 1.0)
        setCol(C, imgui.Col.TitleBgActive, r*0.80, g*0.80, b*0.80, 1.0)
    else
        setCol(C, imgui.Col.TitleBg, r*0.08, g*0.08, b*0.08, 1.0)
        setCol(C, imgui.Col.TitleBgActive, r*0.14, g*0.14, b*0.14, 1.0)
    end
    if v2 then
        setCol(C, imgui.Col.Button, r*0.55, g*0.55, b*0.55, 1.0)
        setCol(C, imgui.Col.ButtonHovered, math.min(1,r*0.80), math.min(1,g*0.80), math.min(1,b*0.80), 1.0)
        setCol(C, imgui.Col.ButtonActive, math.min(1,r*1.05), math.min(1,g*1.05), math.min(1,b*1.05), 1.0)
    elseif cfg.uiLightMode then
        setCol(C, imgui.Col.Button, math.min(1,r*0.35+0.55), math.min(1,g*0.35+0.55), math.min(1,b*0.35+0.55), 1.0)
        setCol(C, imgui.Col.ButtonHovered, math.min(1,r*0.55+0.40), math.min(1,g*0.55+0.40), math.min(1,b*0.55+0.40), 1.0)
        setCol(C, imgui.Col.ButtonActive, r, g, b, 1.0)
    else
        setCol(C, imgui.Col.Button, r*0.10, g*0.10, b*0.10, 1.0)
        setCol(C, imgui.Col.ButtonHovered, r*0.45, g*0.45, b*0.45, 1.0)
        setCol(C, imgui.Col.ButtonActive, r*0.70, g*0.70, b*0.70, 1.0)
    end
    setCol(C, imgui.Col.ScrollbarBg, 0, 0, 0, 0.15)
    setCol(C, imgui.Col.ScrollbarGrab, r*0.45, g*0.45, b*0.45, 0.70)
    setCol(C, imgui.Col.ScrollbarGrabHovered, r*0.65, g*0.65, b*0.65, 0.85)
    setCol(C, imgui.Col.ScrollbarGrabActive, r,      g,      b,      1.0)
    C[imgui.Col.Separator]            = thSep()
    if v2 then
        setCol(C, imgui.Col.Header, r*0.42, g*0.42, b*0.42, 1.0)
        setCol(C, imgui.Col.HeaderHovered, r*0.60, g*0.60, b*0.60, 1.0)
    else
        setCol(C, imgui.Col.Header, r*0.15, g*0.15, b*0.15, 1.0)
        setCol(C, imgui.Col.HeaderHovered, r*0.28, g*0.28, b*0.28, 1.0)
    end
    if cfg.rainbowBorder then
        local hue = (os.clock() % 4.0) / 4.0
        local hr, hg, hb = hsv2rgb(hue, 0.75, 1.0)
        setCol(C, imgui.Col.Border, hr, hg, hb, 0.95)
    elseif cfg.outlineR >= 0 then
        setCol(C, imgui.Col.Border, cfg.outlineR, cfg.outlineG, cfg.outlineB, 0.90)
    elseif cfg.uiLightMode then
        setCol(C, imgui.Col.Border, 0.30, 0.32, 0.38, 0.95)
    else
        setCol(C, imgui.Col.Border, r*0.45, g*0.45, b*0.45, 0.90)
    end
    -- цвет текста — либо белый из темы (по умолчанию), либо кастомный
    -- цвет игрока (cfg.textR/G/B), выбранный в Настройках
    if cfg.textR >= 0 then
        setCol(C, imgui.Col.Text, cfg.textR, cfg.textG, cfg.textB, ta)
    elseif cfg.uiLightMode then
        setCol(C, imgui.Col.Text, 0.07, 0.07, 0.10, ta)
    else
        setCol(C, imgui.Col.Text, t.txt[1], t.txt[2], t.txt[3], ta)
    end
    if v2 then
        s.WindowRounding   = Sf(4.0)
        s.ChildRounding    = Sf(3.0)
        s.FrameRounding    = Sf(3.0)
        s.GrabRounding     = Sf(3.0)
        s.GrabMinSize      = Sf(12.0)
        s.ScrollbarSize    = Sf(8.0)
        setVec2(s, "ItemSpacing", S(8), S(7))
        setVec2(s, "WindowPadding", S(14), S(12))
        setVec2(s, "FramePadding", S(10), S(7))
        s.WindowBorderSize = math.max(1.5, Sf((cfg.borderThickness or 1.2) + 0.8))
        s.ChildBorderSize  = Sf(1.0)
    else
        s.WindowRounding   = Sf(16.0)
        s.ChildRounding    = Sf(10.0)
        s.FrameRounding    = Sf(12.0)
        s.GrabRounding     = Sf(12.0)
        s.GrabMinSize      = Sf(14.0)
        s.ScrollbarSize    = Sf(10.0)
        setVec2(s, "ItemSpacing", S(6), S(5))
        setVec2(s, "WindowPadding", S(12), S(10))
        setVec2(s, "FramePadding", S(8), S(6))
        s.WindowBorderSize = math.max(1.0, Sf(cfg.borderThickness or 1.2))
        s.ChildBorderSize  = 0.0
    end
end

local function secTitle(title)
    PCS_UI("ui:sec", PCS_HEX(title))
    imgui.Spacing()
    local r,g,b = getAcc()
    local dl    = imgui.GetWindowDrawList()
    local p     = imgui.GetCursorScreenPos()
    local avail = imgui.GetContentRegionAvail().x
    local h     = S(30)
    local br = math.max(r*0.22, 0.10)
    local bg2 = math.max(g*0.22, 0.10)
    local bb  = math.max(b*0.22, 0.10)
    dl:AddRectFilled(
        imgui.ImVec2(p.x,       p.y),
        imgui.ImVec2(p.x+avail, p.y+h),
        imgui.ColorConvertFloat4ToU32(iv4(br,bg2,bb,pcsRowA(0.97))), 5)
    dl:AddRect(
        imgui.ImVec2(p.x,       p.y),
        imgui.ImVec2(p.x+avail, p.y+h),
        imgui.ColorConvertFloat4ToU32(iv4(r*0.60,g*0.60,b*0.60,0.55)), 5, 0, 0.8)
    dl:AddRectFilled(
        imgui.ImVec2(p.x,   p.y+2),
        imgui.ImVec2(p.x+S(3), p.y+h-2),
        imgui.ColorConvertFloat4ToU32(iv4(r,g,b,1.0)), 2)
    dl:AddRectFilled(
        imgui.ImVec2(p.x+S(3),  p.y+2),
        imgui.ImVec2(p.x+S(18), p.y+h-2),
        imgui.ColorConvertFloat4ToU32(iv4(r*0.55,g*0.55,b*0.55,0.45)), 0)
    pcall(function()
        if PCS_titleSticker then PCS_titleSticker(dl, title, p.x + avail - S(20), p.y + h * 0.5, h * 0.30) end
    end)
    imgui.SetCursorPosY(imgui.GetCursorPosY()+4)
    imgui.SetCursorPosX(imgui.GetCursorPosX()+S(10))
    imgui.TextColored(thAccBright(), title)
    imgui.SetCursorPosY(imgui.GetCursorPosY()+2)
end

local _rowIndex = 0

local _colorPopupBufs = {}

-- vozvraschaet kastomnyy cvet elementa (esli zadan) libo peredannyy po umolchaniyu
local function getElemColor(id, colorDefault)
    local c = customColors[id]
    if c then
        local a = (colorDefault and colorDefault.w) or 1.0
        return iv4(fin01(c[1], 1.0), fin01(c[2], 1.0), fin01(c[3], 1.0), fin01(a, 1.0))
    end
    return colorDefault
end

local _colorPickerVec = {}

local function recolorOnClick(id)
    PCS_UI("ui:rc enter")
    pcall(function()
        if imgui.IsItemClicked and imgui.IsItemClicked() then
            PCS_UI("ui:rc click")
            imgui.OpenPopup(id)
        end
    end)
    PCS_UI("ui:rc hover")
    local okHov, isHov = pcall(function() return imgui.IsItemHovered and imgui.IsItemHovered() end)
    if okHov and isHov then
        pcall(function()
            imgui.BeginTooltip()
            imgui.TextColored(iv4(0.75,0.80,0.90,1.0),
                u8"\xed\xe0\xe6\xec\xe8\xf2\xe5, \xf7\xf2\xee\xe1\xfb \xf1\xec\xe5\xed\xe8\xf2\xfc \xf6\xe2\xe5\xf2")
            imgui.EndTooltip()
        end)
    end
    PCS_UI("ui:rc size")
    pcall(imgui.SetNextWindowSize, imgui.ImVec2(S(300), 0), imgui.Cond and imgui.Cond.Appearing or 0)
    PCS_UI("ui:rc popup")

    local beganPopup = false
    local ok, err = pcall(function()
    if imgui.BeginPopup(id) then
        beganPopup = true
        local buf = _colorPopupBufs[id]
        if not buf then
            local c = customColors[id]
            buf = { imgui.new.float(c and c[1] or 1.0),
                    imgui.new.float(c and c[2] or 1.0),
                    imgui.new.float(c and c[3] or 1.0) }
            _colorPopupBufs[id] = buf
        end
        imgui.TextColored(thDim(), u8"\xd6\xe2\xe5\xf2 \xfd\xf2\xee\xe3\xee \xf2\xe5\xea\xf1\xf2\xe0/\xf6\xe8\xf4\xf0\xfb:")
        imgui.Spacing()

        local changed = false

        -- пробуем полноценный визуальный пикер (квадрат насыщенности + вертикальная
        -- полоса тона + hex-поле), как в стандартном ImGui color picker
        local okPicker = pcall(function()
            local vec = _colorPickerVec[id]
            if not vec then
                vec = imgui.new("float[3]", {buf[1][0], buf[2][0], buf[3][0]})
                _colorPickerVec[id] = vec
            end
            local flags = 0
            pcall(function() flags = imgui.ColorEditFlags.PickerHueBar + imgui.ColorEditFlags.DisplayHex end)
            imgui.PushItemWidth(S(220))
            local okCP, pickedCP = pcall(imgui.ColorPicker3, "##cp"..id, vec, flags)
            pcall(imgui.PopItemWidth)
            if not okCP then error(pickedCP, 0) end
            if pickedCP then
                buf[1][0], buf[2][0], buf[3][0] = vec[0], vec[1], vec[2]
                changed = true
            end
        end)

        if not okPicker then
            -- запасной вариант (обычные ползунки), если ColorPicker3 недоступен в этой сборке mimgui
            imgui.PushItemWidth(150)
            local okSl, errSl = pcall(function()
                if imgui.SliderFloat("R##rc"..id, buf[1], 0.0, 1.0) then changed = true end
                if imgui.SliderFloat("G##rc"..id, buf[2], 0.0, 1.0) then changed = true end
                if imgui.SliderFloat("B##rc"..id, buf[3], 0.0, 1.0) then changed = true end
            end)
            pcall(imgui.PopItemWidth)
            if not okSl then PCS_quietErr("rc-slider", errSl) end
        end

        if changed then
            customColors[id] = {buf[1][0], buf[2][0], buf[3][0]}
            saveCfg()
        end

        imgui.Spacing()
        local awPop  = imgui.GetContentRegionAvail().x
        local halfWP = (awPop - 8) * 0.5
        imgui.PushStyleColor(imgui.Col.Button,        iv4(0.35,0.06,0.06,1.0))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(0.55,0.10,0.10,1.0))
        imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(0.75,0.16,0.16,1.0))
        if imgui.Button(u8"\xd1\xe1\xf0\xee\xf1 \xf6\xe2\xe5\xf2\xe0##rcreset", imgui.ImVec2(halfWP, S(28))) then
            customColors[id] = nil
            _colorPopupBufs[id] = nil
            _colorPickerVec[id] = nil
            saveCfg()
            imgui.CloseCurrentPopup()
        end
        imgui.PopStyleColor(3)
        imgui.SameLine(0, 8)
        do
            local pr,pg,pb = getAcc()
            imgui.PushStyleColor(imgui.Col.Button,        iv4(pr*0.22,pg*0.22,pb*0.22,1.0))
            imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(pr*0.40,pg*0.40,pb*0.40,1.0))
            imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(pr*0.58,pg*0.58,pb*0.58,1.0))
            if imgui.Button(u8"\xc7\xe0\xea\xf0\xfb\xf2\xfc##rcclose", imgui.ImVec2(halfWP, S(28))) then
                imgui.CloseCurrentPopup()
            end
            imgui.PopStyleColor(3)
        end
    end
    end) -- конец pcall

    if beganPopup then pcall(imgui.EndPopup) end
    if not ok then
        pcall(imgui.CloseCurrentPopup)
        PCS_quietErr("ui@6659", err)
    end
end

-- ===== ГРАДИЕНТНЫЕ КНОПКИ (стиль «красный -> синий») =====
function PCS_gradEnd(r, g, b)
    local ok, ar, ag, ab = pcall(function()
        if cfg and (cfg.gradR or -1) >= 0 and (cfg.custR or -1) >= 0
           and math.abs(r - cfg.custR) < 0.03 and math.abs(g - cfg.custG) < 0.03 and math.abs(b - cfg.custB) < 0.03 then
            return cfg.gradR, cfg.gradG, cfg.gradB
        end
        return nil
    end)
    if ok and ar then return ar, ag, ab end
    return math.min(1, r * 0.30 + 0.10), math.min(1, g * 0.30 + 0.20), math.min(1, b * 0.35 + 0.55)
end

-- горизонтальный градиент со скруглёнными краями
function PCS_gradRect(dl, x0, y0, x1, y1, r1, g1, b1, r2, g2, b2, a, rnd)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local w, h = x1 - x0, y1 - y0
    if w < 2 or h < 2 then return end
    rnd = math.max(0, math.min(rnd or 0, h * 0.5, w * 0.5))
    local fL, fR
    pcall(function() fL = imgui.ImDrawFlags.RoundCornersLeft; fR = imgui.ImDrawFlags.RoundCornersRight end)
    if rnd < 1 or not (fL and fR) then
        local c1, c2 = U32(iv4(r1, g1, b1, a)), U32(iv4(r2, g2, b2, a))
        dl:AddRectFilledMultiColor(V2(x0, y0), V2(x1, y1), c1, c2, c2, c1)
        return
    end
    local function mix(t) return U32(iv4(r1 + (r2 - r1) * t, g1 + (g2 - g1) * t, b1 + (b2 - b1) * t, a)) end
    dl:AddRectFilled(V2(x0, y0), V2(x0 + rnd, y1), mix(rnd * 0.5 / w), rnd, fL)
    dl:AddRectFilled(V2(x1 - rnd, y0), V2(x1, y1), mix(1 - rnd * 0.5 / w), rnd, fR)
    local mx0, mx1 = x0 + rnd, x1 - rnd
    if mx1 - mx0 < 1 then return end
    local c0, c1 = mix(rnd / w), mix(1 - rnd / w)
    dl:AddRectFilledMultiColor(V2(mx0, y0), V2(mx1, y1), c0, c1, c1, c0)
end

-- галочка (рисуется линиями, не зависит от шрифта)
function PCS_drawCheck(dl, cx, cy, sz)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local c = U32(iv4(1, 1, 1, 1))
    local th = math.max(2, sz * 0.28)
    dl:AddLine(V2(cx - sz * 0.55, cy), V2(cx - sz * 0.15, cy + sz * 0.45), c, th)
    dl:AddLine(V2(cx - sz * 0.15, cy + sz * 0.45), V2(cx + sz * 0.6, cy - sz * 0.45), c, th)
end

-- ── ЦВЕТА КНОПОК-ПРЕСЕТОВ (Настройки → Цвета интерфейса) ──
PCS_PRESET_DEF = {
    {u8"\xc7\xe5\xeb\xb8\xed\xfb\xe9",        "swatch", {{0.30,0.85,0.45},{0.12,0.50,0.22}}},
    {u8"\xd1\xe8\xed\xe8\xe9",          "swatch", {{0.25,0.55,0.95},{0.10,0.25,0.70}}},
    {u8"\xc1\xe5\xe6\xe5\xe2\xfb\xe9",        "swatch", {{0.92,0.82,0.62},{0.62,0.50,0.34}}},
    {u8"\xce\xf0\xe0\xed\xe6\xe5\xe2\xfb\xe9",      "swatch", {{0.98,0.58,0.15},{0.75,0.30,0.05}}},
    {u8"\xca\xf0\xe0\xf1\xed\xfb\xe9",        "swatch", {{0.92,0.22,0.22},{0.50,0.06,0.06}}},
    {u8"\xd4\xe8\xee\xeb\xe5\xf2\xee\xe2\xfb\xe9",     "swatch", {{0.70,0.35,0.98},{0.38,0.12,0.62}}},
    {u8"\xd0\xee\xe7\xee\xe2\xee-\xe3\xee\xeb\xf3\xe1\xee\xe9", "grad",   {{0.92,0.30,0.62},{0.30,0.62,0.98}}},
    {u8"\xca\xf0\xe0\xf1\xed\xee-\xf1\xe8\xed\xe8\xe9",   "grad",   {{0.92,0.20,0.25},{0.25,0.35,0.95}}},
    {u8"\xc7\xe0\xea\xe0\xf2",          "grad",   {{1.00,0.62,0.20},{0.95,0.30,0.55},{0.55,0.25,0.90}}},
    {u8"\xcd\xe5\xee\xed",           "grad",   {{0.25,0.95,0.55},{0.25,0.80,0.98},{0.35,0.45,1.00}}},
    {u8"\xce\xea\xe5\xe0\xed",          "grad",   {{0.10,0.80,0.80},{0.12,0.35,0.75}}},
}
PCS_PRESET_FILE = CFG_DIR .. "/presets.json"
PCS_PRESET_OVR  = {}
PCS_PRESET_BUF  = {}
pcall(function()
    local f = io.open(PCS_PRESET_FILE, "rb")
    if not f then return end
    local body = f:read("*a"); f:close()
    if type(decodeJson) == "function" and body and body ~= "" then
        local ok, t = pcall(decodeJson, body)
        if ok and type(t) == "table" then PCS_PRESET_OVR = t end
    end
end)
function PCS_presetSave()
    pcall(function()
        if type(encodeJson) ~= "function" then return end
        local f = io.open(PCS_PRESET_FILE, "wb")
        if f then f:write(encodeJson(PCS_PRESET_OVR)); f:close() end
    end)
end
-- текущие цвета пресета (с учётом сохранённых правок)
function PCS_presetStops(i)
    local d = PCS_PRESET_DEF[i]
    local o = PCS_PRESET_OVR[tostring(i)]
    local so = (type(o) == "table" and type(o.stops) == "table") and o.stops or nil
    local out = {}
    for k, dc in ipairs(d[3]) do
        local oc = so and so[k] or nil
        local ok = type(oc) == "table"
        out[k] = {
            (ok and tonumber(oc[1])) or dc[1],
            (ok and tonumber(oc[2])) or dc[2],
            (ok and tonumber(oc[3])) or dc[3],
        }
    end
    return out
end
function PCS_presetIsActive(st)
    local a = st[1]
    local cr = (cfg.custR >= 0) and cfg.custR or getTheme().acc[1]
    local cg = (cfg.custG >= 0) and cfg.custG or getTheme().acc[2]
    local cb = (cfg.custB >= 0) and cfg.custB or getTheme().acc[3]
    return math.abs(cr - a[1]) < 0.01 and math.abs(cg - a[2]) < 0.01 and math.abs(cb - a[3]) < 0.01
end
-- применить пресет: 1-й цвет — акцент меню, 2-й — фон строк, 3-й (или 2-й) — обводка
function PCS_presetApply(i)
    local st = PCS_presetStops(i)
    local a, b = st[1], st[2] or st[1]
    local o = st[3] or b
    cfg.gradR, cfg.gradG, cfg.gradB = -1, -1, -1
    cfg.custR, cfg.custG, cfg.custB = a[1], a[2], a[3]
    if St.custRbuf then St.custRbuf[0], St.custGbuf[0], St.custBbuf[0] = a[1], a[2], a[3] end
    cfg.rowBgR, cfg.rowBgG, cfg.rowBgB = b[1], b[2], b[3]
    if St.rowBgRbuf then St.rowBgRbuf[0], St.rowBgGbuf[0], St.rowBgBbuf[0] = b[1], b[2], b[3] end
    cfg.outlineR, cfg.outlineG, cfg.outlineB = o[1], o[2], o[3]
    if St.outlineRbuf then St.outlineRbuf[0], St.outlineGbuf[0], St.outlineBbuf[0] = o[1], o[2], o[3] end
    saveCfg()
end
function PCS_presetEditOpen(i)
    imgui.OpenPopup("presetedit" .. i)
end
function PCS_presetEditPopups()
    local labels = { u8"\xd6\xe2\xe5\xf2 1", u8"\xd6\xe2\xe5\xf2 2", u8"\xd6\xe2\xe5\xf2 3" }
    for i, cp in ipairs(PCS_PRESET_DEF) do
        if imgui.BeginPopup("presetedit" .. i) then
            imgui.Text(cp[1])
            local st = PCS_presetStops(i)
            local bufs = PCS_PRESET_BUF[i]
            if not bufs then
                bufs = {}
                for k, c in ipairs(st) do bufs[k] = imgui.new.float[3](c[1], c[2], c[3]) end
                PCS_PRESET_BUF[i] = bufs
            end
            local changed = false
            for k = 1, #st do
                imgui.Text(labels[k])
                if imgui.ColorEdit3("##presetC" .. i .. "_" .. k, bufs[k]) then changed = true end
            end
            if changed then
                local wasActive = PCS_presetIsActive(st)
                local newSt = {}
                for k = 1, #st do newSt[k] = { bufs[k][0], bufs[k][1], bufs[k][2] } end
                PCS_PRESET_OVR[tostring(i)] = { stops = newSt }
                PCS_presetSave()
                if wasActive then PCS_presetApply(i) end
            end
            if imgui.Button(u8"\xc2\xe5\xf0\xed\xf3\xf2\xfc \xf1\xf2\xe0\xed\xe4\xe0\xf0\xf2\xed\xfb\xe9##" .. i) then
                PCS_PRESET_OVR[tostring(i)] = nil
                PCS_PRESET_BUF[i] = nil
                PCS_presetSave()
            end
            imgui.EndPopup()
        end
    end
end

-- переливающаяся кнопка-градиент (стиль «ПРОДОЛЖИТЬ»): полосы, цвета сдвигаются со временем
function PCS_presetButton(uid, label, stops, btnW, bH, isAct, tip, animated)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local clicked = imgui.InvisibleButton("##" .. uid, V2(btnW, bH))
    local hov = imgui.IsItemHovered()
    local rclick = imgui.IsItemClicked(1) and true or false
    local rnd = math.min(S(9), bH * 0.5, btnW * 0.5)
    local n = #stops
    local now = os.clock()
    local x0, x1 = p.x, p.x + btnW
    -- inactive buttons are darkened toward the panel color instead of using alpha:
    -- opaque quads never overlap-darken, so no stripes are visible
    local k = (isAct or hov) and 1.0 or 0.84
    local function colAt(tt)
        if n <= 1 then return stops[1][1], stops[1][2], stops[1][3] end
        local segs = n - 1
        local u
        if animated then
            -- colors flow into each other and loop back (ping-pong), no hard border
            local L = segs * 2
            u = (tt * segs * 0.85 + now * 0.30) % L
            if u > segs then u = L - u end
        else
            u = tt * segs
        end
        local kk = math.floor(u)
        if kk >= segs then kk = segs - 1 end
        if kk < 0 then kk = 0 end
        local f = u - kk
        local a, b = stops[kk + 1], stops[kk + 2]
        return a[1] + (b[1] - a[1]) * f, a[2] + (b[2] - a[2]) * f, a[3] + (b[3] - a[3]) * f
    end
    local function cc(tt)
        local r, g, b = colAt(tt)
        return U32(iv4(r * k + 0.06 * (1 - k), g * k + 0.06 * (1 - k), b * k + 0.07 * (1 - k), 1.0))
    end
    local fL, fR
    pcall(function() fL = imgui.ImDrawFlags.RoundCornersLeft; fR = imgui.ImDrawFlags.RoundCornersRight end)
    local mx0, mx1 = x0, x1
    if fL and fR and rnd >= 1 then
        local tl = (rnd * 0.5) / btnW
        dl:AddRectFilled(V2(x0, p.y), V2(x0 + rnd, p.y + bH), cc(tl), rnd, fL)
        dl:AddRectFilled(V2(x1 - rnd, p.y), V2(x1, p.y + bH), cc(1 - tl), rnd, fR)
        mx0, mx1 = x0 + rnd, x1 - rnd
    end
    local SEG = 30
    local xa = mx0
    local ca = cc((xa - x0) / btnW)
    for s = 1, SEG do
        local xb = mx0 + (mx1 - mx0) * s / SEG
        local cb = cc((xb - x0) / btnW)
        dl:AddRectFilledMultiColor(V2(xa, p.y), V2(xb, p.y + bH), ca, cb, cb, ca)
        xa, ca = xb, cb
    end
    -- soft moving highlight
    local sh = (now * 0.22) % 1.5 - 0.25
    local bw = 0.14
    local c0, c1 = U32(iv4(1, 1, 1, 0)), U32(iv4(1, 1, 1, 0.20))
    dl:PushClipRect(V2(mx0, p.y), V2(mx1, p.y + bH), true)
    dl:AddRectFilledMultiColor(V2(x0 + (sh - bw) * btnW, p.y), V2(x0 + sh * btnW, p.y + bH), c0, c1, c1, c0)
    dl:AddRectFilledMultiColor(V2(x0 + sh * btnW, p.y), V2(x0 + (sh + bw) * btnW, p.y + bH), c1, c0, c0, c1)
    dl:PopClipRect()
    -- bottom shade for depth, glow around the selected button
    do
        local z, d0 = U32(iv4(0, 0, 0, 0)), U32(iv4(0, 0, 0, 0.24))
        dl:AddRectFilledMultiColor(V2(mx0, p.y + bH * 0.52), V2(mx1, p.y + bH - 1), z, z, d0, d0)
        if isAct then
            dl:AddRect(V2(x0 - 2, p.y - 2), V2(x1 + 2, p.y + bH + 2), U32(iv4(1, 1, 1, 0.28)), rnd + 2, 0, 1.5)
        end
    end
    -- top gloss and border
    dl:AddRectFilled(V2(x0 + rnd, p.y + 1.5), V2(x1 - rnd, p.y + bH * 0.42), U32(iv4(1, 1, 1, 0.09)), 0)
    dl:AddRect(p, V2(x1, p.y + bH), U32(iv4(1, 1, 1, isAct and 0.95 or (hov and 0.70 or 0.40))), rnd, 0, isAct and 2.0 or 1.0)
    -- check mark: shows which color is selected
    if isAct then
        local bx, by = x1 - S(15), p.y + S(15)
        dl:AddCircleFilled(V2(bx, by), S(12), U32(iv4(0.10, 0.62, 0.28, 1.0)), 20)
        dl:AddCircle(V2(bx, by), S(12), U32(iv4(1, 1, 1, 0.95)), 20, 1.6)
        PCS_drawCheck(dl, bx, by, S(5.5))
    end
    -- новый вид: название слева вверху + ряд точек-цветов градиента внизу
    local pushed = false
    if PCS_BOLD_FONT then pushed = pcall(imgui.PushFont, PCS_BOLD_FONT) end
    local tx, ty = x0 + S(11), p.y + S(6)
    dl:AddText(V2(tx + 1, ty + 1), U32(iv4(0, 0, 0, 0.6)), label)
    dl:AddText(V2(tx, ty), U32(iv4(1, 1, 1, 1)), label)
    if pushed then pcall(imgui.PopFont) end
    local dotY = p.y + bH - S(10)
    for si, st2 in ipairs(stops) do
        local cx = x0 + S(13) + (si - 1) * S(12)
        dl:AddCircleFilled(V2(cx, dotY), S(3.8), U32(iv4(st2[1], st2[2], st2[3], 1.0)), 16)
        dl:AddCircle(V2(cx, dotY), S(3.8), U32(iv4(1, 1, 1, 0.85)), 16, 1.0)
    end
    if hov and tip then
        imgui.BeginTooltip(); imgui.Text(tip); imgui.EndTooltip()
    end
    return clicked, rclick
end

-- иконка и цвет для строк раздела "Прочее" по названию (отдача, ЗП во фракции, ...)
function PCS_extraInfo(name)
    local n = tostring(name or "")
    if n:find("\xce\xf2\xe4\xe0\xf7", 1, true) then return PCS_IC.handdollar, { 0.45, 0.90, 0.55 } end
    if n:find("\xc7\xcf", 1, true) then return PCS_IC.wallet, { 0.98, 0.82, 0.30 } end
    if n:find("\xe2\xf0\xe5\xec\xe5\xed\xe8", 1, true) then return PCS_IC.clock, { 0.55, 0.80, 1.00 } end
    if n:find("\xd1\xf3\xef\xf0\xf3\xe3", 1, true) then return PCS_IC.heart, { 1.00, 0.45, 0.60 } end
    if n:find("\xcd\xee\xec\xe5\xf0 \xe2 \xee\xf2\xe5\xeb\xe5", 1, true) or n:find("\xee\xf2\xe5\xeb", 1, true) then return PCS_IC.home, { 0.90, 0.75, 0.45 } end
    return PCS_IC.tag, { 0.80, 0.80, 0.85 }
end

local function drawStyleSwatchButton(uid, label, aR,aG,aB, bR,bG,bB, btnW, bH_c, isAct, tooltipText)
    local dl_cb = imgui.GetWindowDrawList()
    local p_cb  = imgui.GetCursorScreenPos()
    local halfH = bH_c * 0.5
    local bgAlpha = isAct and 1.0 or 0.82
    local rnd = 10
    local flagsTop, flagsBot
    pcall(function() flagsTop = imgui.ImDrawFlags.RoundCornersTop end)
    pcall(function() flagsBot = imgui.ImDrawFlags.RoundCornersBottom end)
    if flagsTop then
        dl_cb:AddRectFilled(
            imgui.ImVec2(p_cb.x,           p_cb.y),
            imgui.ImVec2(p_cb.x+btnW,      p_cb.y+halfH),
            imgui.ColorConvertFloat4ToU32(iv4(aR,aG,aB,bgAlpha)), rnd, flagsTop)
    else
        dl_cb:AddRectFilled(
            imgui.ImVec2(p_cb.x,           p_cb.y),
            imgui.ImVec2(p_cb.x+btnW,      p_cb.y+halfH),
            imgui.ColorConvertFloat4ToU32(iv4(aR,aG,aB,bgAlpha)), 0)
    end
    if flagsBot then
        dl_cb:AddRectFilled(
            imgui.ImVec2(p_cb.x,           p_cb.y+halfH),
            imgui.ImVec2(p_cb.x+btnW,      p_cb.y+bH_c),
            imgui.ColorConvertFloat4ToU32(iv4(bR,bG,bB,bgAlpha)), rnd, flagsBot)
    else
        dl_cb:AddRectFilled(
            imgui.ImVec2(p_cb.x,           p_cb.y+halfH),
            imgui.ImVec2(p_cb.x+btnW,      p_cb.y+bH_c),
            imgui.ColorConvertFloat4ToU32(iv4(bR,bG,bB,bgAlpha)), 0)
    end
    local borderCol = isAct and iv4(aR,aG,aB,1.0) or iv4(aR*0.65,aG*0.65,aB*0.65,0.70)
    dl_cb:AddRect(
        imgui.ImVec2(p_cb.x,       p_cb.y),
        imgui.ImVec2(p_cb.x+btnW,  p_cb.y+bH_c),
        imgui.ColorConvertFloat4ToU32(borderCol), rnd, 0, isAct and 2.0 or 1.0)
    dl_cb:AddLine(
        imgui.ImVec2(p_cb.x+4,      p_cb.y+halfH),
        imgui.ImVec2(p_cb.x+btnW-4, p_cb.y+halfH),
        imgui.ColorConvertFloat4ToU32(iv4(1,1,1,0.12)), 1)
    imgui.PushStyleColor(imgui.Col.Button,        iv4(0,0,0,0))
    imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(1,1,1,0.16))
    imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(0,0,0,0.22))
    local clicked = imgui.Button(label.."##"..uid, imgui.ImVec2(btnW, bH_c))
    local rightClicked = imgui.IsItemClicked(1) and true or false
    if imgui.IsItemHovered() and tooltipText then
        imgui.BeginTooltip()
        imgui.Text(tooltipText)
        imgui.EndTooltip()
    end
    imgui.PopStyleColor(3)
    return clicked, rightClicked
end

local function applyGlobalNumColor(col)
    if cfg.globalNumColorOn and cfg.globalNumR >= 0 then
        local a = (col and col.w) or 1.0
        return iv4(cfg.globalNumR, cfg.globalNumG, cfg.globalNumB, a)
    end
    return col
end

PCS_DIAG_SKIP_WANTED = true
PCS_DIAG_NO_TEX = false
PCS_DIAG_NO_COMPANION = false
-- конечное число (защита от NaN/inf в координатах рисования)
function PCS_fin(v)
    return type(v) == "number" and v == v and math.abs(v) < 1e6
end

-- число в [0..1]; NaN/inf/nil/не число -> запасное значение (цвета и альфа строки)
function fin01(v, dflt)
    v = tonumber(v)
    if not v or v ~= v or v == math.huge or v == -math.huge then return dflt end
    if v < 0 then return 0 elseif v > 1 then return 1 end
    return v
end

function PCS_houseIcon(col)
    local dl = imgui.GetWindowDrawList()
    local p  = imgui.GetCursorScreenPos()
    local sz = S(14)
    if not (PCS_fin(p.x) and PCS_fin(p.y)) then p = { x = 0, y = 0 } end
    local r = fin01(col and col.x, 0.9)
    local g = fin01(col and col.y, 0.75)
    local b = fin01(col and col.z, 0.45)
    local u = imgui.ColorConvertFloat4ToU32(iv4(r, g, b, 1.0))
    local x0, y0 = p.x, p.y + S(1)
    dl:AddTriangleFilled(
        imgui.ImVec2(x0 + sz * 0.5, y0),
        imgui.ImVec2(x0,            y0 + sz * 0.48),
        imgui.ImVec2(x0 + sz,       y0 + sz * 0.48), u)
    dl:AddRectFilled(
        imgui.ImVec2(x0 + sz * 0.16, y0 + sz * 0.46),
        imgui.ImVec2(x0 + sz * 0.84, y0 + sz), u, 1)
    imgui.Dummy(imgui.ImVec2(sz, sz + S(1)))
end

local function dataRow(label, value, valColor, icon, iconCol)
    if not hasVal(value) then return end
    label = tostring(label or "")
    PCS_UI("ui:row", label)
    local r,g,b = getAcc()
    r, g, b = fin01(r, 0.5), fin01(g, 0.5), fin01(b, 0.5)
    local rr,rg,rb = getRowBgColor()
    rr, rg, rb = fin01(rr, 0.2), fin01(rg, 0.2), fin01(rb, 0.2)
    local dl    = imgui.GetWindowDrawList()
    PCS_UI("ui:row dl")
    local p     = imgui.GetCursorScreenPos()
    PCS_UI("ui:row pos")
    local avail = imgui.GetContentRegionAvail().x
    if avail ~= avail or avail < 1 then avail = 1 end
    if avail > 8192 then avail = 8192 end
    if not (PCS_fin(p.x) and PCS_fin(p.y)) then p = { x = 0, y = 0 } end
    local h     = S(36)
    PCS_UI("ui:row metrics")
    _rowIndex = _rowIndex + 1
    local shade = (_rowIndex % 2 == 0) and 0.13 or 0.07
    local minV  = (_rowIndex % 2 == 0) and 0.10 or 0.05
    local bgR = math.max(rr*shade, minV)
    local bgG = math.max(rg*shade, minV)
    local bgB = math.max(rb*shade, minV)
    dl:AddRectFilled(
        imgui.ImVec2(p.x,       p.y),
        imgui.ImVec2(p.x+avail, p.y+h),
        imgui.ColorConvertFloat4ToU32(iv4(bgR,bgG,bgB, St._softRows and 0.42 or fin01(cfg.rowBgAlpha, 0.98))), 5)
    PCS_UI("ui:row bg")
    dl:AddRect(
        imgui.ImVec2(p.x,       p.y),
        imgui.ImVec2(p.x+avail, p.y+h),
        imgui.ColorConvertFloat4ToU32(iv4(r*0.45,g*0.45,b*0.45,0.40)), 5, 0, 0.7)
    dl:AddRectFilled(
        imgui.ImVec2(p.x,   p.y+3),
        imgui.ImVec2(p.x+2, p.y+h-3),
        imgui.ColorConvertFloat4ToU32(iv4(r,g,b,0.85)), 1)
    local bgBright = bgR*0.299 + bgG*0.587 + bgB*0.114
    local labelCol = bgBright > 0.35 and iv4(0.05,0.05,0.08,1.0) or iv4(0.95,0.95,0.98,1.0)
    local autoValCol
    if not valColor then
        autoValCol = bgBright > 0.35 and iv4(0.05,0.05,0.10,1.0) or thTxt()
    else
        autoValCol = valColor
    end
    autoValCol = applyGlobalNumColor(autoValCol)
    local lblId = "lbl_"..label
    local valId = "val_"..label
    labelCol   = getElemColor(lblId, labelCol)
    autoValCol = getElemColor(valId, autoValCol)
    PCS_UI("ui:r1 hex", PCS_HEX(value))
    imgui.SetCursorPosY(imgui.GetCursorPosY()+S(6))
    PCS_UI("ui:r1a posY")
    imgui.SetCursorPosX(imgui.GetCursorPosX()+S(10))
    PCS_UI("ui:r1b posX")
    local iconW = 0
    if icon then
        PCS_UI("ui:r1c icon", PCS_HEX(icon))
        local icolV = iconCol and iv4(iconCol[1], iconCol[2], iconCol[3], 1.0) or labelCol
        if icon == PCS_IC.home then
            local okH = pcall(PCS_houseIcon, icolV)
            if not okH then imgui.Dummy(imgui.ImVec2(S(14), S(14))) end
        else
            imgui.TextColored(icolV, icon)
        end
        PCS_UI("ui:r1d icon drawn")
        iconW = S(14) + S(6)
        PCS_UI("ui:r1e icon calc")
        imgui.SameLine(0, S(6))
        PCS_UI("ui:r1f sameline")
    end
    PCS_UI("ui:r2 label")
    imgui.TextColored(labelCol, label)
    PCS_UI("ui:r3 recolor lbl")
    recolorOnClick(lblId)
    PCS_UI("ui:r4 u8")
    local valStr  = PCS_safeText(u8(tostring(vOrDash(value) or '-')))
    PCS_UI("ui:r5 calc")
    local labelW  = imgui.CalcTextSize(label).x + iconW
    local valW    = imgui.CalcTextSize(valStr).x
    PCS_UI("ui:r6 calc done")
    if not PCS_fin(labelW) then labelW = 0 end
    if not PCS_fin(valW) then valW = 0 end
    PCS_UI("ui:r6a widths ok")
    local rightPad = S(12)
    local maxValW = avail - labelW - S(24) - rightPad
    -- БЕЗ изменения размера шрифта: SetWindowFontScale посреди строки роняет игру.
    -- Если значение не влезает, просто обрезаем символы и ставим "..."
    if valW > maxValW and maxValW > S(10) then
        local s = valStr
        while #s > 0 and imgui.CalcTextSize(s .. "...").x > maxValW do
            s = s:sub(1, #s - 1)
            while #s > 0 and s:byte(#s) >= 0x80 and s:byte(#s) < 0xC0 do s = s:sub(1, #s - 1) end
            if #s > 0 and s:byte(#s) >= 0xC0 then s = s:sub(1, #s - 1) end
        end
        valStr = s .. "..."
        valW = imgui.CalcTextSize(valStr).x
    end
    PCS_UI("ui:r6b shrink done")
    local sameX = avail - valW - rightPad
    if not PCS_fin(sameX) or sameX < 0 then sameX = 0 end
    if sameX > 8192 then sameX = 8192 end
    PCS_UI("ui:r6c sameline", sameX)
    imgui.SameLine(sameX)
    PCS_UI("ui:r6d sameline done")
    PCS_UI("ui:val", valStr)
    imgui.TextColored(autoValCol, valStr)
    PCS_UI("ui:r7 val drawn")
    recolorOnClick(valId)
    PCS_UI("ui:r8 recolor val")
    imgui.SetCursorPosY(imgui.GetCursorPosY()+2)
end

 St._metricTileIdx = 0
local function metricTile(label, value, col, w, onClickFn)
    St._metricTileIdx = St._metricTileIdx + 1
    local h  = S(56)
    local r,g,b = getAcc()
    local rr,rg,rb = getRowBgColor()
    local dl = imgui.GetWindowDrawList()
    local p  = imgui.GetCursorScreenPos()
    local bgR = math.max(rr*0.18, 0.09)
    local bgG = math.max(rg*0.18, 0.09)
    local bgB = math.max(rb*0.18, 0.09)
    dl:AddRectFilled(
        imgui.ImVec2(p.x,   p.y),
        imgui.ImVec2(p.x+w, p.y+h),
        imgui.ColorConvertFloat4ToU32(iv4(bgR,bgG,bgB,pcsRowA(0.97))), 10)
    dl:AddRect(
        imgui.ImVec2(p.x,   p.y),
        imgui.ImVec2(p.x+w, p.y+h),
        imgui.ColorConvertFloat4ToU32(iv4(
            math.max(r*0.65,0.22), math.max(g*0.65,0.22), math.max(b*0.65,0.22), 0.85)),
        10, 0, 1.5)
    local ac = col or thAcc()
    dl:AddRectFilled(
        imgui.ImVec2(p.x,   p.y+6),
        imgui.ImVec2(p.x+3, p.y+h-6),
        imgui.ColorConvertFloat4ToU32(iv4(ac.x,ac.y,ac.z,1.0)), 2)

    imgui.PushStyleColor(imgui.Col.ChildBg, iv4(0,0,0,0))
    imgui.BeginChild("##mt"..tostring(St._metricTileIdx), imgui.ImVec2(w, h), false,
        imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoScrollWithMouse)

        local btnW = onClickFn and S(44) or 0
        local btnH = S(32)
        if onClickFn then
            imgui.SetCursorPos(imgui.ImVec2(w - btnW - S(6), (h - btnH)*0.5))
            imgui.PushStyleColor(imgui.Col.Button,        iv4(r*0.25,g*0.25,b*0.25,1.0))
            imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(r*0.65,g*0.65,b*0.65,1.0))
            imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(r,      g,      b,      1.0))
            do local _sv=0
            if pcall(imgui.PushStyleVar,imgui.StyleVar.FrameRounding,Sf(7.0)) then _sv=_sv+1 end
            if imgui.Button(">>##cp"..tostring(St._metricTileIdx),
                            imgui.ImVec2(btnW, btnH)) then
                pcall(onClickFn)
            end
            if _sv>0 then pcall(imgui.PopStyleVar,_sv) end end
            imgui.PopStyleColor(3)
        end

        imgui.SetCursorPos(imgui.ImVec2(S(10), S(7)))
        imgui.TextColored(thDim(), label)

        local valStr = u8(value~="" and value or "-")
        local mtId = "mt_"..label
        imgui.SetCursorPos(imgui.ImVec2(S(10), S(28)))
        imgui.TextColored(getElemColor(mtId, applyGlobalNumColor(col or thTxt())), valStr)
        recolorOnClick(mtId)

    imgui.EndChild()
    imgui.PopStyleColor()
end

 St._chipIdx = 0
 St.chipSide = false
local function chip(label, value, kind, icol)
    if not hasVal(value) then return end
    PCS_UI("ui:chip", label)
    St._chipIdx = St._chipIdx + 1
    local avail = imgui.GetContentRegionAvail().x
    local w  = (avail - S(6)) * 0.5
    local h  = S(56)
    local r0, g0, b0 = getAcc()
    local cr, cg, cb = r0, g0, b0
    if icol then cr, cg, cb = icol[1], icol[2], icol[3] end
    local dl = imgui.GetWindowDrawList()
    local U32 = imgui.ColorConvertFloat4ToU32
    local function render()
        local p = imgui.GetCursorScreenPos()
        local rnd = S(8)
        -- градиент: цвет характеристики у левого края, тёмный справа
        PCS_gradRect(dl, p.x, p.y, p.x + w, p.y + h, cr * 0.26, cg * 0.26, cb * 0.26, 0.05, 0.05, 0.08, 0.96, rnd)
        dl:AddRect(p, imgui.ImVec2(p.x + w, p.y + h), U32(iv4(cr, cg, cb, 0.55)), rnd, 0, 1.0)
        dl:AddRectFilled(imgui.ImVec2(p.x + 1, p.y + S(8)), imgui.ImVec2(p.x + S(4), p.y + h - S(8)), U32(iv4(cr, cg, cb, 0.95)), S(2))
        if kind then
            local ang, dy = PCS_stickerAnim(false, (St._chipIdx or 0) * 0.7)
            PCS_drawSticker(dl, kind, p.x + S(24), p.y + h * 0.5 + dy * 0.2, S(9), ang)
        end
        local tx = p.x + S(44)
        dl:AddText(imgui.ImVec2(tx, p.y + S(8)), U32(iv4(0.74, 0.77, 0.84, 1)), label)
        local pushed = false
        if PCS_BOLD_FONT then pushed = pcall(imgui.PushFont, PCS_BOLD_FONT) end
        dl:AddText(imgui.ImVec2(tx, p.y + S(27)), U32(iv4(cr, cg, cb, 1)), u8(vOrDash(value)))
        if pushed then pcall(imgui.PopFont) end
        imgui.Dummy(imgui.ImVec2(w, h))
    end
    if St.chipSide then
        imgui.SameLine(0, S(6))
        render()
        imgui.Spacing()
        St.chipSide = false
    else
        St.chipSide = true
        render()
    end
end

local function tabButton(label, active, w, r,g,b, hParam)
    local ar,ag,ab = getAcc()
    local br = r or ar; local bg2 = g or ag; local bb = b or ab
    local dl = imgui.GetWindowDrawList()
    local p  = imgui.GetCursorScreenPos()
    local h  = hParam or S(38)
    if active then
        imgui.PushStyleColor(imgui.Col.Button,        iv4(br*0.22,bg2*0.22,bb*0.22,1.0))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(br*0.38,bg2*0.38,bb*0.38,1.0))
        imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(br*0.55,bg2*0.55,bb*0.55,1.0))
    else
        imgui.PushStyleColor(imgui.Col.Button,        iv4(br*0.30,bg2*0.30,bb*0.30,0.95))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(br*0.46,bg2*0.46,bb*0.46,1.0))
        imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(br*0.55,bg2*0.55,bb*0.55,1.0))
    end
    local clicked = imgui.Button(label, imgui.ImVec2(w or 0, h))
    imgui.PopStyleColor(3)
    -- плавная анимация переключения: подсветка и линия «вырастают» от центра
    -- у выбранной вкладки и так же плавно сжимаются у бывшей
    PCS_TABA = PCS_TABA or {}
    local tkey = "tab|" .. tostring(label)
    local ta = PCS_TABA[tkey]
    if ta == nil then ta = active and 1 or 0 end
    if cfg and cfg.animAllOff == true then
        ta = active and 1 or 0
    else
        local tdt = 0.016
        pcall(function() tdt = imgui.GetIO().DeltaTime end)
        if type(tdt) ~= "number" or tdt <= 0 or tdt > 0.1 then tdt = 0.016 end
        local tgt = active and 1 or 0
        ta = ta + (tgt - ta) * math.min(1, tdt * 11)
        if math.abs(tgt - ta) < 0.004 then ta = tgt end
    end
    PCS_TABA[tkey] = ta
    if ta > 0.01 then
        pcall(function()
            local mn, mx = imgui.GetItemRectMin(), imgui.GetItemRectMax()
            local e = ta * ta * (3 - 2 * ta)
            local cx, half = (mn.x + mx.x) * 0.5, ((mx.x - mn.x) * 0.5 - S(4)) * e
            dl:AddRectFilled(mn, mx, imgui.ColorConvertFloat4ToU32(iv4(br, bg2, bb, 0.10 * e)), S(6))
            dl:AddRectFilled(imgui.ImVec2(cx - half, mx.y - 3), imgui.ImVec2(cx + half, mx.y),
                imgui.ColorConvertFloat4ToU32(iv4(br, bg2, bb, 0.95)), 2)
        end)
    end
    return clicked
end

