                dataRow(u8"\xca\xe0\xf0\xf2\xe0", s.bankCard, nil, PCS_IC.idcard or PCS_IC.user, {0.70,0.75,0.90})
                if hasVal(s.cashVcs) then dataRow(u8"VC$", fmtMoney(s.cashVcs), nil, PCS_IC.coins, {0.35,0.85,0.95}) end
                if hasVal(s.btc) then dataRow("BTC", fmtAmt(toNum(s.btc)), nil, PCS_IC.bitcoin, {0.95,0.70,0.20}) end
                if hasVal(s.euro) then dataRow(CUR_AARP_SHORT, fmtAmt(toNum(s.euro)), nil, PCS_IC.euro, {0.45,0.65,1.0}) end
                if hasVal(s.azCoins) or hasVal(s.accountState) then
                    local azRaw = hasVal(s.accountState) and s.accountState or s.azCoins
                    dataRow("AZ", fmtAmt(toNum(azRaw)), thGold(), PCS_IC.gem, {0.90,0.55,1.0})
                end
                do
                    local hasAccLeft = false
                    for i=1,6 do if hasVal(s.acc[i]) then hasAccLeft=true; break end end
                    if hasAccLeft then
                        _rowIndex = 0
                        secTitle(u8"\xd1\xf7\xb8\xf2\xe0")
                        for i=1,6 do
                            if hasVal(s.acc[i]) then
                                dataRow(u8"\xb9"..i, fmtMoney(s.acc[i]), thAcc())
                            end
                        end
                        if s.totalAcc ~= "" then
                            _rowIndex = 0
                            dataRow(u8"\xc8\xf2\xee\xe3", s.totalAcc, thGold())
                        end
                    end
                end
end

