local function rateInputRow(id, label, buf, cfgKey, suffix)
    local r,g,b = getAcc()
    imgui.TextColored(thDim(), label)
    if suffix and suffix ~= "" then
        imgui.SameLine(0, 4)
        imgui.TextColored(iv4(0.45,0.48,0.55,1.0), suffix)
    end
    -- dopolnitelnyy otstup mezhdu podpisyu i polem vvoda, chtoby oni ne slipalis
    imgui.Dummy(imgui.ImVec2(0, S(5)))
    -- poka pole aktivno (igrok pechataet) -- ne trogaem bufer, chtoby kursor ne skakal
    if not _rateActive[id] then
        buf[0] = math.floor((cfg[cfgKey] or 0) + 0.5)
    end
    imgui.PushStyleColor(imgui.Col.FrameBg,        iv4(r*0.16,g*0.16,b*0.16,1.0))
    imgui.PushStyleColor(imgui.Col.FrameBgHovered, iv4(r*0.28,g*0.28,b*0.28,1.0))
    imgui.PushStyleColor(imgui.Col.FrameBgActive,  iv4(r*0.40,g*0.40,b*0.40,1.0))
    imgui.PushStyleColor(imgui.Col.Border,         iv4(math.min(1,r*1.15),math.min(1,g*1.15),math.min(1,b*1.15),0.70))
    imgui.PushStyleColor(imgui.Col.Text,           iv4(1,1,1,1))
    local _svr = 0
    if pcall(imgui.PushStyleVar, imgui.StyleVar.FrameRounding, 8.0) then _svr = _svr + 1 end
    if pcall(imgui.PushStyleVar, imgui.StyleVar.FrameBorderSize, 1.6) then _svr = _svr + 1 end
    if pcall(imgui.PushStyleVar, imgui.StyleVar.FramePadding, imgui.ImVec2(12, 10)) then _svr = _svr + 1 end
    local ok, changed = pcall(imgui.InputInt, "##rate"..id, buf, 0, 0)
    if ok and changed then
        if buf[0] < 0 then buf[0] = 0 end
        cfg[cfgKey] = buf[0]
        saveCfg()
    end
    local okA, isActive = pcall(imgui.IsItemActive)
    _rateActive[id] = okA and isActive or false
    if _svr > 0 then pcall(imgui.PopStyleVar, _svr) end
    imgui.PopStyleColor(5)
    imgui.Spacing()
end

local CRYPTO_APP_ID = 39

local _cefFetching   = false
 St._cefLastResult = ""  -- текстовый статус последней попытки (для UI)

_phoneOpBusy = false
St._phoneOpBusySince = nil

St._phoneBuy       = nil
St._phoneBuyFor    = nil
St._phoneSell      = nil
St._phoneSellFor   = nil
St._phoneRatesTime = nil

-- true/"waiting", пока скрипт ждёт открытия диалога с курсами валют
local _phoneFetchState = false

-- отправляет сырые байты через RakNet-битстрим (аналог sendBytes из
-- CryptoRatesReader)
local function sendPhoneBytes(bytes)
    if type(bytes) ~= "table" or #bytes == 0 then return false end
    if type(raknetNewBitStream) ~= "function" then return false end
    local ok, err = pcall(function()
        local bitStream = raknetNewBitStream()
        if not bitStream then error("no bitstream") end
        local okW, errW = pcall(function()
            for _, byte in ipairs(bytes) do
                raknetBitStreamWriteInt8(bitStream, tonumber(byte) or 0)
            end
            raknetSendBitStream(bitStream)
        end)
        pcall(raknetDeleteBitStream, bitStream)
        if not okW then error(errW, 0) end
    end)
    if not ok then
        print("[PC Stats][tax] sendPhoneBytes fail: " .. tostring(err))
        return false
    end
    return true
end

St._dlgCloseAt = 0
PCS_NO_DIALOG_CLOSE = true
function PCS_closeDialogOnce()
    if PCS_NO_DIALOG_CLOSE then return false end
    local nowC = os.clock()
    if nowC - (St._dlgCloseAt or 0) < 1.2 then return false end
    local active = false
    pcall(function()
        if type(sampIsDialogActive) == "function" and sampIsDialogActive() then active = true end
    end)
    if not active then return false end
    St._dlgCloseAt = nowC
    -- предпочитаем WithButton(0); fallback на нативный close только если диалог точно открыт
    if type(sampCloseCurrentDialogWithButton) == "function" then
        return (pcall(sampCloseCurrentDialogWithButton, 0))
    end
    if type(sampCloseCurrentDialog) == "function" then
        return (pcall(sampCloseCurrentDialog, -1))
    end
    return false
end

function pcsCloseDialogIfActive()
    return PCS_closeDialogOnce()
end

function PCS_safeCloseDialog()
    return PCS_closeDialogOnce()
end

function PCS_taxClick(dlgId, idx, btn)
    btn = btn or 1
    local okA, act = pcall(function() return sampIsDialogActive() end)
    local okI, cur = pcall(function() return sampGetCurrentDialogId() end)
    if okA and act and okI and cur == dlgId
        and type(sampSetCurrentDialogListItem) == "function"
        and type(sampCloseCurrentDialogWithButton) == "function" then
        local ok1 = pcall(sampSetCurrentDialogListItem, idx)
        local ok2 = ok1 and pcall(sampCloseCurrentDialogWithButton, btn)
        if ok2 then PCS_TR("tax: click id=" .. tostring(dlgId) .. " item=" .. tostring(idx)); return true end
    end
    PCS_TR("tax: send(fallback) id=" .. tostring(dlgId) .. " item=" .. tostring(idx))
    return (pcall(sampSendDialogResponse, dlgId, btn, idx, ""))
end

function PCS_phoneRelease(cooldownSec, postPaySec)
    _phoneOpBusy = false
    St._phoneOpBusySince = nil
    St._closePhoneRunning = false
    St._closePhoneSince = nil
    if cooldownSec and cooldownSec > 0 then
        St._phoneCooldownUntil = math.max(St._phoneCooldownUntil or 0, os.time() + cooldownSec)
    end
    if postPaySec and postPaySec > 0 then
        St._postPayUntil = math.max(St._postPayUntil or 0, os.clock() + postPaySec)
    end
end

local function openCryptoAppDirect()
    local dialogActive = false
    pcall(function()
        if sampIsDialogActive and sampIsDialogActive() then dialogActive = true end
    end)
    if dialogActive then
        for _ = 1, 3 do
            if not pcsCloseDialogIfActive() then break end
            wait(120)
        end
        wait(200)
    end
    local payload = "launchedApp|" .. tostring(CRYPTO_APP_ID)
    local appPacket = {220, 18, #payload, 0}
    for i = 1, #payload do table.insert(appPacket, payload:byte(i)) end
    for _ = 1, 4 do table.insert(appPacket, 0) end
    sendPhoneBytes({220, 0, 80, 64}) -- открыть телефон
    wait(280)
    sendPhoneBytes(appPacket) -- открыть приложение "Криптовалюта"
end

local function parseGameNumber(str)
    if not str then return nil end
    local digits = tostring(str):gsub("[^%d]", "")
    if digits == "" then return nil end
    local n = tonumber(digits)
    if not n or n ~= n or n == math.huge or n == -math.huge then
        return nil
    end
    return n
end

local function cp1251Lower(s)
    s = s:lower()
    s = s:gsub("[\xc0-\xdf]", function(c) return string.char(c:byte() + 0x20) end)
    s = s:gsub("\xa8", "\xb8") -- Ё -> ё (не входит в диапазон выше)
    return s
end

local function extractPhoneRate(text, needles)
    if not text or text == "" then return nil end
    for line in (text .. "\n"):gmatch("(.-)\n") do
        local clean = stripColor(line)
        local low = cp1251Lower(clean)
        for _, n in ipairs(needles) do
            if low:find(n, 1, true) then
                local afterDollar = clean:match("%$%s*([%d%s%.,]+)%s*$")
                local numStr = afterDollar or clean:match("([%d%s%.,]+)")
                if numStr then
                    local v = parseGameNumber(numStr)
                    if v and v > 0 then return v end
                end
            end
        end
    end
    return nil
end

local function extractPhoneRateLineStart(text, needles)
    if not text or text == "" then return nil end
    for line in (text .. "\n"):gmatch("(.-)\n") do
        local clean = stripColor(line):gsub("^%s+", "")
        local low = cp1251Lower(clean)
        for _, n in ipairs(needles) do
            if low:find("^" .. n) then
                local afterDollar = clean:match("%$%s*([%d%s%.,]+)%s*$")
                local numStr = afterDollar or clean:match("([%d%s%.,]+)")
                if numStr then
                    local v = parseGameNumber(numStr)
                    if v and v > 0 then return v end
                end
            end
        end
    end
    return nil
end

local function extractPhoneRateLineNumber(text, lineNum)
    if not text or text == "" then return nil end
    local i = 0
    for line in (text .. "\n"):gmatch("(.-)\n") do
        i = i + 1
        if i == lineNum then
            local clean = stripColor(line):gsub("^%s+", ""):gsub("%s+$", "")
            local afterDollar = clean:match("%$%s*([%d%s%.,]+)%s*$")
            local numStr = afterDollar or clean:match("([%d%s%.,]+)")
            if numStr then
                local v = parseGameNumber(numStr)
                if v and v > 0 then return v end
            end
            return nil
        end
    end
    return nil
end

-- точный шаблон числа: пропускаем всё, что не цифра, до первой цифры,
-- затем забираем цифры/точки/запятые — так же, как NUM в CryptoRatesReader
local NUM_PATTERN = '[^%d]-(%d[%d,.]*)'

-- ищет rate по точному шаблону вида "Bitcoin (BTC): 12345" и возвращает
-- число (или nil, если не нашлось/не число)
local function phoneNumFromPattern(text, pattern)
    local v = text:match(pattern)
    if not v then return nil end
    local n = parseGameNumber(v)
    if n and n > 0 then return n end
    return nil
end

local function parsePhoneRatesText(text)
    if not text or text == "" then return false end
    local body = stripColor(text)
    local gotAny = false

    local rBTC = phoneNumFromPattern(body, 'Bitcoin%s*%(%s*BTC%s*%)%s*:' .. NUM_PATTERN)
        or extractPhoneRate(body, {"btc", "bitcoin", "\xe1\xe8\xf2\xea\xee\xe9\xed"})
    local rEUR = phoneNumFromPattern(body, '\xc0\xea\xf6\xe8\xe8%s+Arizona%s*%(%s*AAR+P%s*%)%s*:' .. NUM_PATTERN)
        or phoneNumFromPattern(body, '\xc5\xc2\xd0\xce%s*%(%s*euro%s*%)%s*:' .. NUM_PATTERN)
        or extractPhoneRate(body, {"aarrp", "aarp", "\xe0\xea\xf6\xe8\xe8", "arizona", "eur", "\xe5\xe2\xf0\xee"})
    local rASC = phoneNumFromPattern(body, 'Arizona%s+Coin%s*%(%s*ASC%s*%)%s*:' .. NUM_PATTERN)
        or extractPhoneRate(body, {"asc", "\xe0\xf0\xe8\xe7\xee\xed\xe0 \xf1\xf2\xe5\xe9\xe1\xeb"})
    local rAZ  = extractPhoneRate(body, {"az-coin", "az \xea\xee\xe8\xed", "\xe0\xe7-\xea\xee\xe8\xed"})
    local rVC  = extractPhoneRateLineStart(body, {"\xf2\xe5\xea\xf3\xf9\xe8\xe9 \xea\xf3\xf0\xf1 \xe4\xeb\xff \xef\xee\xea\xf3\xef"})
        or extractPhoneRate(body, {"vc$", "vice city", "\xe2\xe0\xe9\xf1 \xf1\xe8\xf2\xe8"})
        or extractPhoneRateLineNumber(body, 6)

    if rAZ  and rAZ  > 0 then cfg.rateAZ  = rAZ;  St.rateAZBuf[0]  = math.floor(rAZ  + 0.5); gotAny = true end
    if rBTC and rBTC > 0 then cfg.rateBTC = rBTC; St.rateBTCBuf[0] = math.floor(rBTC + 0.5); gotAny = true end
    if rEUR and rEUR > 0 then cfg.rateEUR = rEUR; St.rateEURBuf[0] = math.floor(rEUR + 0.5); gotAny = true end
    if rVC  and rVC  > 0 then cfg.rateVC  = rVC;  St.rateVCBuf[0]  = math.floor(rVC  + 0.5); gotAny = true end
    if rASC and rASC > 0 then cfg.rateASC = rASC; St.rateASCBuf[0] = math.floor(rASC + 0.5); gotAny = true end

    local bodyLow = cp1251Lower(body)
    local buy, buyFor = bodyLow:match(
        "\xf2\xe5\xea\xf3\xf9\xe8\xe9 \xea\xf3\xf0\xf1 \xe4\xeb\xff \xef\xee\xea\xf3\xef.-:" .. NUM_PATTERN .. NUM_PATTERN)
    local sell, sellFor = bodyLow:match(
        "\xf2\xe5\xea\xf3\xf9\xe8\xe9 \xea\xf3\xf0\xf1 \xe4\xeb\xff \xef\xf0\xee\xe4\xe0\xe6.-:" .. NUM_PATTERN .. NUM_PATTERN)
    if buy or sell then
        St._phoneBuy      = buy      or St._phoneBuy
        St._phoneBuyFor   = buyFor   or St._phoneBuyFor
        St._phoneSell     = sell     or St._phoneSell
        St._phoneSellFor  = sellFor  or St._phoneSellFor
        St._phoneRatesTime = os.date("%H:%M:%S")
        gotAny = true
        local sellN = tonumber(sell)
        if sellN and sellN > 0 then cfg.rateVCSell = sellN; St.rateVCSellBuf[0] = math.floor(sellN + 0.5) end
        local buyN = tonumber(buy)
        if buyN and buyN > 0 then cfg.rateVC = buyN; St.rateVCBuf[0] = math.floor(buyN + 0.5) end
        -- снимок в историю курса для графика "Курс VC$" (см. RH выше)
        pcall(function() if RH and RH.add then RH.add(tonumber(cfg.rateVC), tonumber(cfg.rateVCSell)) end end)
    end

    if gotAny then saveCfg() end
    return gotAny
end

local function isCryptoRatesDialog(title, text)
    local marker = "\xca\xf3\xf0\xf1 \xe2\xe0\xeb\xfe\xf2" -- "Курс валют"
    local h = stripColor(tostring(title or ""))
    local b = stripColor(tostring(text or ""))
    return h:find(marker, 1, true) ~= nil or b:find(marker, 1, true) ~= nil
end

local function fetchRatesViaCEF()
    pcall(PCS_texQuietFor, 8)
    if _cefFetching then return end
    if not isSampAvailable() then
        St._cefLastResult = "\xf1\xe0\xec\xef \xed\xe5 \xe4\xee\xf1\xf2\xf3\xef\xe5\xed"
        return
    end
    -- защита: телефон не трогаем, пока персонаж не заспавнен или игра на паузе
    do
        local okS, spawned = pcall(function() return sampIsLocalPlayerSpawned and sampIsLocalPlayerSpawned() end)
        if not (okS and spawned == true) then return end
        local okP, paused = pcall(function() return isGamePaused and isGamePaused() end)
        if okP and paused == true then return end
    end
    if St._phoneCooldownUntil and os.time() < St._phoneCooldownUntil then
        return
    end
    if _phoneOpBusy then
        St._cefLastResult = "\xf2\xe5\xeb\xe5\xf4\xee\xed\x20\xe7\xe0\xed\xff\xf2\x20\xe4\xf0\xf3\xe3\xee\xe9\x20\xee\xef\xe5\xf0\xe0\xf6\xe8\xe5\xe9\x2c\x20\xef\xee\xef\xf0\xee\xe1\xf3\xe9\xf2\xe5\x20\xf7\xe5\xf0\xe5\xe7\x20\xef\xe0\xf0\xf3\x20\xf1\xe5\xea\xf3\xed\xe4"
        pcall(sampAddChatMessage, "{FF6666}[Stats] " .. tostring(St._cefLastResult), -1)
        return
    end
    _phoneOpBusy     = true
    St._phoneOpBusySince = os.time()
    _cefFetching     = true
    _phoneFetchState = "waiting"
    St._cefLastResult   = "\xee\xf2\xea\xf0\xfb\xe2\xe0\xe5\xec \xf2\xe5\xeb\xe5\xf4\xee\xed..."
    lua_thread.create(function()
        local okOpen = pcall(openCryptoAppDirect)
        if not okOpen then
            _phoneFetchState = false
            _cefFetching     = false
            _phoneOpBusy     = false
            St._cefLastResult = "\xed\xe5 \xf3\xe4\xe0\xeb\xee\xf1\xfc \xee\xf2\xea\xf0\xfb\xf2\xfc \xef\xf0\xe8\xeb\xee\xe6\xe5\xed\xe8\xe5 \xca\xf0\xe8\xef\xf2\xee\xe2\xe0\xeb\xfe\xf2\xe0 \xe2 \xf2\xe5\xeb\xe5\xf4\xee\xed\xe5"
            pcall(sampAddChatMessage, "{FF6666}[Stats] " .. tostring(St._cefLastResult), -1)
            return
        end
        local waited = 0
        while _phoneFetchState and waited < 8000 do
            wait(100); waited = waited + 100
        end
        if _phoneFetchState then
            -- за 8 секунд диалог с курсами так и не пришёл
            _phoneFetchState = false
            St._cefLastResult = "\xed\xe5 \xf3\xe4\xe0\xeb\xee\xf1\xfc \xee\xf2\xea\xf0\xfb\xf2\xfc \xec\xe5\xed\xfe \xca\xf0\xe8\xef\xf2\xee\xe2\xe0\xeb\xfe\xf2\xe0 \xe2 \xf2\xe5\xeb\xe5\xf4\xee\xed\xe5"
            pcall(sampAddChatMessage, "{FF6666}[Stats] " .. tostring(St._cefLastResult), -1)
        end
        pcsCloseDialogIfActive()
        wait(400)
        pcall(PCS_sendPhoneClose, 1000)
        _cefFetching = false
        PCS_phoneRelease(3)
    end)
end

local TAX_STEP_DELAY  = 200
local TAX_TIMEOUT_SEC = 18

_taxOpenInProgress = false
_taxDlgSeq = 0
local _taxState = 0
_TAX_POST_PAY_WAIT_MS = 1200
PCS_TAX_CONFIRM_ENTER = false
_taxFinalizeDone = false
local function isPlayerActuallySpawned()
    local ok, res = pcall(function()
        return sampIsLocalPlayerSpawned and sampIsLocalPlayerSpawned()
    end)
    return ok and res == true
end
local _taxIsAuto = false
_taxPendingAmount = 0
-- вытаскивает сумму ($ХХХ) из текста диалога налогов тем же способом, что и
-- разбор чатового сообщения "вы оплатили..." ниже (sampev.onServerMessage)
function extractTaxAmount(text)
    local sumStr = (text or ""):match("%$%s*([%d%s%.,]+)")
    return sumStr and parseGameNumber(sumStr) or 0
end
_taxLoginWaitEndTime = nil
_taxLoginFired = false
_taxLoginSkippedRecent = false

local function splitTaxLines(text)
    local lines = {}
    for line in ((text or "") .. "\n"):gmatch("(.-)\n") do
        table.insert(lines, line)
    end
    return lines
end

local function openTaxAppDirect()
    if _taxOpenInProgress then return end
    _taxOpenInProgress = true
    lua_thread.create(function()
        local okT, errT = pcall(function()
            local function cancelled()
                return _taxState == 0
            end
            local function sendLaunchApp(appId)
                if cancelled() then return end   -- отмена: налоги уже не платим
                local payload = "launchedApp|" .. tostring(appId)
                local pkt = {220, 18, #payload, 0}
                for i = 1, #payload do table.insert(pkt, payload:byte(i)) end
                for _ = 1, 4 do table.insert(pkt, 0) end
                pcall(sendPhoneBytes, pkt)
            end
            if _taxPhoneAlreadyOpen then
                wait(150)
                if cancelled() then return end
                sendLaunchApp(24)
                wait(220)
                if cancelled() then return end
                sendLaunchApp(5656)
                return
            end
            if cancelled() then return end
            wait(250)
            if cancelled() then return end
            pcall(sendPhoneBytes, {220, 0, 80, 64}) -- открыть телефон
            _taxPhoneAlreadyOpen = true
            wait(350)
            if cancelled() then return end
            sendLaunchApp(24)
            wait(220)
            if cancelled() then return end
            sendLaunchApp(5656)
        end)
        _taxOpenInProgress = false
        if not okT then
            print("[PC Stats][tax] openTaxAppDirect error: " .. tostring(errT))
        end
    end)
end

LOG_RETENTION_DAYS = 30

-- переводит дату "YYYY-MM-DD" (как её пишут TX/PD) в os.time() на полдень
-- этого дня — возвращает nil, если строка не распознана как дата
function pcs_dateToEpoch(dateStr)
    if type(dateStr) ~= "string" then return nil end
    local y, m, d = dateStr:match("^(%d%d%d%d)-(%d%d)-(%d%d)$")
    if not y then return nil end
    local ok, t = pcall(os.time, {
        year = tonumber(y), month = tonumber(m), day = tonumber(d), hour = 12,
    })
    if ok and type(t) == "number" then return t end
    return nil
end

-- true, если запись с такой датой не старше maxDays дней (нераспознанную
-- дату не трогаем — считаем свежей, чтобы битая строка не удаляла лог)
function pcs_isEntryFresh(dateStr, maxDays)
    local ep = pcs_dateToEpoch(dateStr)
    if not ep then return true end
    return (os.time() - ep) <= (maxDays * 86400)
end

local TX = {}
TX.LOG_FILE        = CFG_DIR .. "/tax_log.txt"
TX.MAX_ENTRIES_MEM = 2000
TX.MAX_LINES_FILE  = 3000
St.taxEntries = St.taxEntries or {}
St.taxLogLoaded = false

function TX.loadLog()
    St.taxEntries = {}
    local allLines = readLogTail(TX.LOG_FILE, TX.MAX_LINES_FILE, 40)
    if #allLines > TX.MAX_LINES_FILE then
        local keepFrom = #allLines - TX.MAX_LINES_FILE + 1
        local trimmed = {}
        for i = keepFrom, #allLines do trimmed[#trimmed+1] = allLines[i] end
        allLines = trimmed
        pcall(function()
            ensureCfgDir()
            local out = io.open(TX.LOG_FILE, "w")
            if out then
                for _, ln in ipairs(allLines) do out:write(ln, "\n") end
                out:close()
            end
        end)
    end
    for i = #allLines, 1, -1 do
        local d, t, amt, auto, noTax, kind = allLines[i]:match(
            "^(%d%d%d%d%-%d%d%-%d%d)|(%d%d:%d%d)|(-?%d+)|([01])|([01])|(%w+)$")
        if not d then
            d, t, amt, auto, noTax = allLines[i]:match(
                "^(%d%d%d%d%-%d%d%-%d%d)|(%d%d:%d%d)|(-?%d+)|([01])|([01])$")
        end
        if not d then
            d, t, amt, auto = allLines[i]:match(
                "^(%d%d%d%d%-%d%d%-%d%d)|(%d%d:%d%d)|(-?%d+)|([01])$")
        end
        if d then
            local k = kind or "tax"
            if k ~= "family" and k ~= "org" then k = "tax" end
            table.insert(St.taxEntries, {
                date = d, time = t, amount = tonumber(amt) or 0, auto = (auto == "1"),
                noTax = (noTax == "1"), kind = k,
            })
            if #St.taxEntries >= TX.MAX_ENTRIES_MEM then break end
        end
    end
    St.taxLogLoaded = true
    TX.pruneOld()
end

function TX.pruneOld()
    local removed = false
    for i = #St.taxEntries, 1, -1 do
        if not pcs_isEntryFresh(St.taxEntries[i].date, LOG_RETENTION_DAYS) then
            table.remove(St.taxEntries, i)
            removed = true
        end
    end
    if not removed then return end
    pcall(function()
        ensureCfgDir()
        local out = io.open(TX.LOG_FILE, "w")
        if out then
            for i = #St.taxEntries, 1, -1 do
                local e = St.taxEntries[i]
                out:write(e.date .. "|" .. e.time .. "|" .. e.amount .. "|" ..
                    (e.auto and "1" or "0") .. "|" .. (e.noTax and "1" or "0") .. "|" .. tostring(e.kind or "tax") .. "\n")
            end
            out:close()
        end
    end)
end

RH = RH or {}
RH.LOG_FILE        = CFG_DIR .. "/rate_history.txt"
RH.MAX_ENTRIES_MEM = 500
RH.MAX_LINES_FILE  = 800
St.rateHistory     = St.rateHistory or {} -- {t=epoch, buy=, sell=}, новые сверху
St.rateHistLoaded  = false

function RH.load()
    St.rateHistory = {}
    local allLines = readLogTail(RH.LOG_FILE, RH.MAX_LINES_FILE, 24)
    for i = #allLines, 1, -1 do
        local t, buy, sell = allLines[i]:match("^(%d+)|([%d%.]+)|([%d%.]+)$")
        if t then
            table.insert(St.rateHistory, { t = tonumber(t), buy = tonumber(buy) or 0, sell = tonumber(sell) or 0 })
            if #St.rateHistory >= RH.MAX_ENTRIES_MEM then break end
        end
    end
    St.rateHistLoaded = true
end

function RH.add(buy, sell)
    if not St.rateHistLoaded then RH.load() end
    buy  = tonumber(buy)  or 0
    sell = tonumber(sell) or 0
    if buy <= 0 and sell <= 0 then return end
    local last = St.rateHistory[1]
    if last and (os.time() - (tonumber(last.t) or 0)) < 180 then return end
    table.insert(St.rateHistory, 1, { t = os.time(), buy = buy, sell = sell })
    while #St.rateHistory > RH.MAX_ENTRIES_MEM do table.remove(St.rateHistory) end
    pcall(function()
        ensureCfgDir()
        local f = io.open(RH.LOG_FILE, "a")
        if f then
            f:write(os.time() .. "|" .. buy .. "|" .. sell .. "\n")
            f:close()
        end
    end)
end

CH = CH or {}
CH.LOG_FILE        = CFG_DIR .. "/cur_rate_history.txt"
CH.MAX_ENTRIES_MEM = 500
CH.MAX_LINES_FILE  = 800
St.curHistory    = St.curHistory or {}
St.curHistLoaded = false

function CH.load()
    St.curHistory = {}
    local allLines = readLogTail(CH.LOG_FILE, CH.MAX_LINES_FILE, 24)
    for i = #allLines, 1, -1 do
        local t, az, btc, eur, vc, asc = allLines[i]:match(
            "^(%d+)|([%d%.]+)|([%d%.]+)|([%d%.]+)|([%d%.]+)|([%d%.]+)$")
        if t then
            table.insert(St.curHistory, {
                t = tonumber(t), az = tonumber(az) or 0, btc = tonumber(btc) or 0,
                eur = tonumber(eur) or 0, vc = tonumber(vc) or 0, asc = tonumber(asc) or 0,
            })
            if #St.curHistory >= CH.MAX_ENTRIES_MEM then break end
        end
    end
    St.curHistLoaded = true
end

function CH.add()
    local function writeEntry(e)
        table.insert(St.curHistory, 1, e)
        while #St.curHistory > CH.MAX_ENTRIES_MEM do table.remove(St.curHistory) end
        pcall(function()
            ensureCfgDir()
            local f = io.open(CH.LOG_FILE, "a")
            if f then
                f:write(e.t .. "|" .. e.az .. "|" .. e.btc .. "|" .. e.eur .. "|" .. e.vc .. "|" .. e.asc .. "\n")
                f:close()
            end
        end)
    end

    if not St.curHistLoaded then CH.load() end
    local az  = tonumber(cfg.rateAZ)  or 0
    local btc = tonumber(cfg.rateBTC) or 0
    local eur = tonumber(cfg.rateEUR) or 0
    local vc  = tonumber(cfg.rateVC)  or 0
    local asc = tonumber(cfg.rateASC) or 0
    if az <= 0 and btc <= 0 and eur <= 0 and vc <= 0 and asc <= 0 then return end
    local last = St.curHistory[1]
    local _chg = last and ((tonumber(last.az) or 0) ~= az or (tonumber(last.btc) or 0) ~= btc
        or (tonumber(last.eur) or 0) ~= eur or (tonumber(last.vc) or 0) ~= vc or (tonumber(last.asc) or 0) ~= asc)
    local _age = last and (os.time() - (tonumber(last.t) or 0)) or 99999
    if last and ((not _chg and _age < 180) or (_chg and _age < 5)) then return end
    if #St.curHistory == 0 then
        writeEntry({ t = os.time() - 180, az = az, btc = btc, eur = eur, vc = vc, asc = asc })
    end
    writeEntry({ t = os.time(), az = az, btc = btc, eur = eur, vc = vc, asc = asc })
end

function TX.addEntry(isAuto, amount, isNoTax, kind)
    if not St.taxLogLoaded then TX.loadLog() end
    amount = math.floor((amount or 0) + 0.5)
    -- kind: "tax" (личные налоги), "family" (семейная квартира), "org" (организация)
    kind = tostring(kind or "tax")
    if kind ~= "family" and kind ~= "org" then kind = "tax" end
    local d = os.date("%Y-%m-%d")
    local t = os.date("%H:%M")
    table.insert(St.taxEntries, 1, {
        date = d, time = t, amount = amount, auto = isAuto and true or false,
        noTax = isNoTax and true or false, kind = kind,
    })
    while #St.taxEntries > TX.MAX_ENTRIES_MEM do table.remove(St.taxEntries) end
    pcall(function()
        ensureCfgDir()
        local f = io.open(TX.LOG_FILE, "a")
        if f then
            f:write(d .. "|" .. t .. "|" .. amount .. "|" .. (isAuto and "1" or "0") ..
                "|" .. (isNoTax and "1" or "0") .. "|" .. kind .. "\n")
            f:close()
        end
    end)
    TX.pruneOld()
end

function TX.extractChatAmount(clean)
    if type(clean) ~= "string" or clean == "" then return 0 end
    local low = cp1251Lower(clean)
    -- 1) число после слова "сумм" (сумму / суммы) — независимо от символа валюты
    local from = low:find("\xf1\xf3\xec\xec", 1, true)
    if from then
        local numStr = clean:sub(from):match("%d[%d%.,]*")
        if numStr then
            numStr = numStr:gsub("[%.,]+$", "")
            local v = parseGameNumber(numStr)
            if v and v > 0 then return v end
        end
    end
    -- 2) запасной вариант — старый шаблон со знаком "$"
    local sumStr = clean:match("%$%s*([%d%s%.,]+)")
    local v2 = sumStr and parseGameNumber(sumStr) or 0
    return v2 or 0
end

function TX.fixLastAmount(amount)
    amount = math.floor((tonumber(amount) or 0) + 0.5)
    if amount <= 0 then return false end
    if not St.taxLogLoaded then TX.loadLog() end
    local e = St.taxEntries[1]
    if not e or e.noTax then return false end
    local old = tonumber(e.amount) or 0
    if old == amount then return true end
    e.amount = amount
    cfg.taxTotalPaid = math.max(0, (tonumber(cfg.taxTotalPaid) or 0) - old + amount)
    pcall(function()
        ensureCfgDir()
        local out = io.open(TX.LOG_FILE, "w")
        if out then
            -- St.taxEntries хранит новые сверху — на диске пишем в
            -- хронологическом порядке (как и pruneOld)
            for i = #St.taxEntries, 1, -1 do
                local x = St.taxEntries[i]
                out:write(x.date .. "|" .. x.time .. "|" .. x.amount .. "|" ..
                    (x.auto and "1" or "0") .. "|" .. (x.noTax and "1" or "0") .. "|" .. tostring(x.kind or "tax") .. "\n")
            end
            out:close()
        end
    end)
    return true
end

-- ── «тихое окно» для текстур (персонаж на фоне, смайлики) ──
PCS_TEX_QUIET_UNTIL = PCS_TEX_QUIET_UNTIL or 0
PCS_TEX_RECREATE_PENDING = PCS_TEX_RECREATE_PENDING or false
PCS_TEX_DEAD_SESSION = PCS_TEX_DEAD_SESSION or false
PCS_TEX_NO_RECREATE = PCS_TEX_NO_RECREATE or false
PCS_TEX_QUIET_THREAD = PCS_TEX_QUIET_THREAD or false
PCS_TEX_SHIELD_UNTIL = PCS_TEX_SHIELD_UNTIL or 0
PCS_NOUI_UNTIL = PCS_NOUI_UNTIL or 0
PCS_POSTPAY_SILENCE_SEC = 8
PCS_RELOAD_WAIT_PHONE = true
PCS_CLOSE_PHONE_AFTER = true
function PCS_texPhoneBegin()
    pcall(PCS_texForgetPool, "phone begin")
    lua_thread.create(function()
        wait(45000)
        if PCS_TEX_NO_RECREATE and not PCS_phoneStillBusy() then
            PCS_texPhoneEnd()
        end
    end)
end

-- true, пока телефон или операция ещё заняты (или открыт диалог сервера)
function PCS_phoneStillBusy()
    if _taxState ~= 0 or _phoneOpBusy == true or _cefFetching == true or _phoneFetchState then return true end
    if St._closePhoneRunning then return true end
    local okD, act = pcall(sampIsDialogActive)
    return (okD and act) and true or false
end

function PCS_texPhoneEnd()
    local waited = 0
    while PCS_phoneStillBusy() and waited < 20000 do
        wait(250)
        waited = waited + 250
    end
    wait(2000)
    PCS_TEX_NO_RECREATE = false
    PCS_TEX_RECREATE_PENDING = true
    pcall(PCS_texQuietFor, 2)
    pcall(PCS_TR, "phone: textures scheduled")
end

function PCS_closePhoneCmd(delayMs)
    pcall(PCS_texForgetPool, "phone op")
    if not PCS_CLOSE_PHONE_AFTER then
        lua_thread.create(function() PCS_texPhoneEnd() end)
        return
    end
    lua_thread.create(function()
        wait(tonumber(delayMs) or 0)
        if (PCS_POSTPAY_SILENCE_SEC or 0) > 0 then
            PCS_NOUI_UNTIL = math.max(PCS_NOUI_UNTIL or 0, os.clock() + PCS_POSTPAY_SILENCE_SEC)
        end
        local cmd = (type(cfg) == "table" and cfg.phoneOpenCmd) or "/phone"
        pcall(function()
            if isSampAvailable() then sampSendChat(cmd) end
        end)
        pcall(PCS_TR, "phone: sent " .. tostring(cmd) .. " (close)")
        PCS_texPhoneEnd()
    end)
end
PCS_TEX_RECREATE_TRIES = PCS_TEX_RECREATE_TRIES or 0
function PCS_texBlocked()
    if PCS_TEX_DEAD_SESSION then return true end
    if _taxState ~= 0 then return true end
    if os.clock() < (PCS_NOUI_UNTIL or 0) then return true end
    return os.clock() < (PCS_TEX_SHIELD_UNTIL or 0)
end
-- true while the menu must not be opened (phone operation or texture shield)
function PCS_uiLocked()
    return false
end
function PCS_texQuiet()
    if PCS_texBlocked() then return true end
    return os.clock() < (PCS_TEX_QUIET_UNTIL or 0)
end
function PCS_texShield(seconds, reason)
    seconds = tonumber(seconds) or 45
    if seconds < 15 then seconds = 15 end
    if seconds > 120 then seconds = 120 end
    PCS_TEX_SHIELD_UNTIL = math.max(PCS_TEX_SHIELD_UNTIL or 0, os.clock() + seconds)
    PCS_TEX_RECREATE_TRIES = 0
    PCS_COMPANION_TEX = nil
    local P = PCS_TEXPOOL
    if P and P.tex then
        for k, tx in pairs(P.tex) do
            if P.keep then P.keep[#P.keep + 1] = tx end
            P.tex[k] = nil
        end
        P.ready = false
    end
    pcall(function()
        if PCS_STICK then
            PCS_STICK.tex = nil
            PCS_STICK.texBroken = true
            PCS_STICK.reloadAt = os.clock() + seconds + 1
        end
    end)
    pcall(PCS_texQuietFor, seconds)
    pcall(PCS_TR, "tex shield ON " .. tostring(seconds) .. "s: " .. tostring(reason or ""))
end
function PCS_texForgetPool(reason)
    PCS_COMPANION_TEX = nil
    local P = PCS_TEXPOOL
    if P and P.tex then
        for k, tx in pairs(P.tex) do
            if P.keep then P.keep[#P.keep + 1] = tx end
            P.tex[k] = nil
        end
        P.ready = false
    end
    pcall(function()
        if PCS_STICK then
            PCS_STICK.tex = nil
            PCS_STICK.texBroken = true
            PCS_STICK.reloadAt = os.clock() + 86400
        end
    end)
    PCS_TEX_NO_RECREATE = true
    PCS_TEX_RECREATE_PENDING = false
    pcall(PCS_TR, "tex pool forgotten: " .. tostring(reason or ""))
end
function PCS_texSoftForget(reason)
    local P = PCS_TEXPOOL
    PCS_COMPANION_TEX = nil
    if P and P.tex then
        for k, tx in pairs(P.tex) do
            if P.keep then P.keep[#P.keep + 1] = tx end
            P.tex[k] = nil
        end
        P.ready = false
    end
    for _, tx in pairs(PCS_SRV_ICON_TEX or {}) do
        if tx and P and P.keep then P.keep[#P.keep + 1] = tx end
    end
    PCS_SRV_ICON_TEX = {}
    pcall(function()
        if PCS_STICK then
            PCS_STICK.tex = nil
            PCS_STICK.texBroken = true
            PCS_STICK.reloadAt = os.clock() + 10
        end
    end)
    pcall(PCS_TR, "tex soft-forget: " .. tostring(reason or ""))
end

PCS_WD_LAST_COMP = PCS_WD_LAST_COMP or 0
PCS_WD_LAST_ICON = PCS_WD_LAST_ICON or 0
function PCS_texWatchdogLoop()
    lua_thread.create(function()
        wait(10000) -- дождаться полной загрузки скрипта и mimgui
        while true do
            wait(1500)
            pcall(function()
                if PCS_TEX_DEAD_SESSION or PCS_TEX_NO_RECREATE or PCS_DIAG_NO_COMPANION then return end
                if PCS_texQuiet() then return end
                -- персонаж на фоне
                if cfg.companionBgEnabled ~= false and PCS_COMPANION_TEX == nil
                    and (os.clock() - PCS_WD_LAST_COMP) > 3 then
                    PCS_UI("tex:wd comp load")
                    PCS_TEX_RECREATE_PENDING = true
                    local _wdOk = true
                    if PCS_COMPANION_TEX then
                        PCS_TEX_QUIET_UNTIL = math.max(PCS_TEX_QUIET_UNTIL or 0, os.clock() + 1.5)
                    else
                        PCS_WD_LAST_COMP = os.clock() -- пауза только после неудачи
                    end
                end
                -- иконка текущего сервера
                local srv = (cfg.vcAutoDetectServer and detectArzServerName()) or cfg.vcServerName
                if srv and ARZ_SERVER_ICON and ARZ_SERVER_ICON[srv]
                    and PCS_SRV_ICON_TEX[srv] == nil and (os.clock() - PCS_WD_LAST_ICON) > 3 then
                    PCS_UI("tex:wd icon load")
                    local t = nil
                    if t then
                        PCS_TEX_QUIET_UNTIL = math.max(PCS_TEX_QUIET_UNTIL or 0, os.clock() + 1.5)
                    else
                        PCS_WD_LAST_ICON = os.clock() -- пауза только после неудачи
                    end
                end
            end)
        end
    end)
end
PCS_texWatchdogLoop()

function PCS_texQuietFor(sec)
    if PCS_TEX_DEAD_SESSION then PCS_COMPANION_TEX = nil; return end
    sec = tonumber(sec) or 10
    if sec < 3 then sec = 3 end
    if sec > 120 then sec = 120 end
    PCS_TEX_QUIET_UNTIL = math.max(PCS_TEX_QUIET_UNTIL or 0, os.clock() + sec)
    -- на время quiet не держим stale-указатель companion (AddImage = native crash)
    PCS_COMPANION_TEX = nil
    if PCS_TEX_QUIET_THREAD then return end
    PCS_TEX_QUIET_THREAD = true
    lua_thread.create(function()
        while os.clock() < (PCS_TEX_QUIET_UNTIL or 0) do wait(250) end
        PCS_TEX_QUIET_THREAD = false
        PCS_TEX_RECREATE_PENDING = not PCS_TEX_NO_RECREATE
        _pcsCompanionRetried = false
    end)
end

-- сумма для чата/уведомления: ": $1 234 567" или пусто, если сумма неизвестна
function taxAmtText(v)
    v = tonumber(v) or 0
    if v <= 0 then return "" end
    local s = string.format("%.0f", v):reverse():gsub("(%d%d%d)", "%1 "):reverse():gsub("^%s+", "")
    return ": $" .. s
end

function PCS_logErrLine(key, e)
    local path = CFG_DIR .. "/errors.log"
    local size = 0
    local f = io.open(path, "rb")
    if f then size = f:seek("end") or 0; f:close() end
    local w = io.open(path, (size > 200000) and "wb" or "ab")
    if w then
        w:write(os.date("%Y-%m-%d %H:%M:%S"), " [", tostring(key), "] ", tostring(e):sub(1, 400), "\n")
        w:close()
    end
end

function PCS_taxStageFile() return CFG_DIR .. "/tax_stage.txt" end
function PCS_taxSoftFile() return CFG_DIR .. "/tax_soft.flag" end
PCS_TAX_SOFT_REFRESH = false
pcall(function()
    local f = io.open(CFG_DIR .. "/tax_reload.flag", "rb")
    if f then f:close() end
end)

function PCS_taxStage(name)
    PCS_TAX_STAGE = tostring(name)
    pcall(function()
        local f = io.open(PCS_taxStageFile(), "wb")
        if f then f:write(PCS_TAX_STAGE); f:flush(); f:close() end
    end)
    pcall(PCS_TR, "tax: stage " .. PCS_TAX_STAGE)
end

function PCS_taxFail(stage, err)
    local e = tostring(err or "?"):gsub("[\r\n].*", ""):gsub("{%x%x%x%x%x%x}", "")
    if #e > 140 then e = e:sub(1, 140) .. "..." end
    pcall(PCS_TR, "tax: FAIL at " .. tostring(stage) .. ": " .. e)
    print("[PC Stats][tax] FAIL at " .. tostring(stage) .. ": " .. tostring(err))
    -- сбрасываем только состояние оплаты
    _taxState = 0
    _taxExpectedDialogId = nil
    _taxPhoneAlreadyOpen = false
    _phoneOpBusy = false
    St._taxDeferredPending = false
    St._taxReloadBusy = false
    St._taxReloadArmedAt = nil
    pcall(PCS_phoneRelease, 5, 2)
    -- пауза оплаты 10 минут (чтобы не зациклиться), остальной скрипт не трогаем
    local G = PCS_TAXG
    if not G then G = { t = {}, blockedUntil = 0 }; PCS_TAXG = G end
    G.blockedUntil = os.time() + 600
    pcall(PCS_taxStage, "DONE (error)")
    pcall(sampAddChatMessage, "{FF6666}[PC Stats] {FFFFFF}\xd1\xe1\xee\xe9 \xf4\xf3\xed\xea\xf6\xe8\xe8 \xee\xef\xeb\xe0\xf2\xfb \xed\xe0\xeb\xee\xe3\xee\xe2 {FFD700}(\xfd\xf2\xe0\xef: " ..
        tostring(stage) .. "){FFFFFF}. \xcf\xf0\xe8\xf7\xe8\xed\xe0: {FF9999}" .. e, -1)
    pcall(sampAddChatMessage, "{FFFFFF}[PC Stats] \xce\xef\xeb\xe0\xf2\xe0 \xed\xe0 \xef\xe0\xf3\xe7\xe5 10 \xec\xe8\xed\xf3\xf2, \xee\xf1\xf2\xe0\xeb\xfc\xed\xee\xe9 \xf1\xea\xf0\xe8\xef\xf2 \xf0\xe0\xe1\xee\xf2\xe0\xe5\xf2 \xea\xe0\xea \xee\xe1\xfb\xf7\xed\xee.", -1)
end

function PCS_taxThread(stage, fn)
    return lua_thread.create(function()
        local ok, err = xpcall(fn, function(m) return tostring(m) .. " | " .. tostring(debug.traceback("", 2)):gsub("[\r\n]+", " ") end)
        if not ok then PCS_taxFail(stage, err) end
    end)
end

function PCS_startTaxWatchdog()
    if St._taxWatchdogRunning then return end
    St._taxWatchdogRunning = true
    lua_thread.create(function()
        while true do
            wait(5000)
            pcall(function()
                if _taxState ~= 0 then
                    St._wdTaxSince = St._wdTaxSince or os.clock()
                    if os.clock() - St._wdTaxSince > 90 then
                        pcall(PCS_TR, "tax: watchdog reset state=" .. tostring(_taxState))
                        _taxState = 0
                        _taxExpectedDialogId = nil
                        _taxPhoneAlreadyOpen = false
                        St._wdTaxSince = nil
                        PCS_phoneRelease(3)
                    end
                else
                    St._wdTaxSince = nil
                end
                if _phoneOpBusy == true and St._phoneOpBusySince
                    and (os.time() - St._phoneOpBusySince) > 90 then
                    pcall(PCS_TR, "tax: watchdog reset phone lock")
                    PCS_phoneRelease(3)
                end
            end)
        end
    end)
end
PCS_startTaxWatchdog()

-- мягкое обновление: БЕЗ reload скрипта — только данные (/stats + вкладка налогов)
function PCS_taxSoftRefresh()
    if St._taxSoftBusy then return end
    St._taxSoftBusy = true
    PCS_taxThread("soft-refresh", function()
        PCS_taxStage("soft-refresh wait")
        wait(2500)
        pcall(PCS_taxFixTabState)
        St.statsData = St.statsData -- данные остаются видны, пока не придут новые
        PCS_taxStage("soft-refresh stats")
        -- БЕЗ force: /stats не уходит сразу после оплаты (St._statsQuietUntil), ждём окно тишины
        if requestStats then pcall(requestStats, false) end
        wait(1500)
        St._taxSoftBusy = false
        _phoneOpBusy = false
        St._closePhoneRunning = false
        PCS_taxStage("DONE (soft)")
    end)
end

-- сброс окон/флагов вкладки налогов (календарь, лог), чтобы вкладка перерисовалась с нуля
function PCS_taxFixTabState()
    St._taxCalendarPopupOpen = false
    St._taxCalendarPopupOpenedOnce = false
    St._taxLogEntriesPopupOpen = false
    St._taxLogEntriesOpenedOnce = false
end

PCS_TAX_RELOAD_AFTER_PAY = true
PCS_TAX_CHAT_WAIT_SEC = 6
-- путь к флагу "открыть меню после перезапуска" (хранится в config/PCStats)
function PCS_reopenFlagPath() return CFG_DIR .. "/reopen_menu.flag" end

function PCS_selfFileExists()
    local okS, scr = pcall(thisScript)
    local path = okS and scr and scr.path
    if type(path) ~= "string" or path == "" then return false end
    local f = io.open(path, "rb")
    if not f then return false end
    f:close()
    return true
end

function PCS_safeSelfReload()
    if not PCS_selfFileExists() then return false end
    local okS, scr = pcall(thisScript)
    if okS and scr and type(scr.reload) == "function" then
        return (pcall(function() scr:reload() end)) and true or false
    end
    return false
end

function PCS_sendPhoneClose(delayMs, opts)
    opts = opts or {}
    lua_thread.create(function()
        wait(tonumber(delayMs) or 0)
        pcall(function() St.winOpen = false; St._winVisible = false end)
        pcall(function()
            if isSampAvailable() then sampSendChat(tostring((type(cfg) == "table" and cfg.phoneOpenCmd) or "/phone")) end
        end)
        pcall(PCS_TR, "phone: /phone sent (noTex=" .. tostring(opts.noTex == true) .. ")")
        if opts.noTex then return end
        -- старые указатели после CEF-телефона мертвы: отпускаем их, держим тишину 3 с
        -- пока телефон закрывается, и только потом разрешаем пересоздание в кадре
        pcall(PCS_texSoftForget, "phone closed")
        PCS_TEX_NO_RECREATE = false
        pcall(PCS_texQuietFor, 3)
    end)
end

function PCS_taxReloadNow(delayMs)
    if St._taxReloadBusy then return end
    St._taxReloadBusy = true
    St._taxReloadArmedAt = nil
    local total = tonumber(delayMs) or 1000
    PCS_taxThread("reload", function()
        PCS_taxStage("reload wait")
        wait(300)
        for _, dId in ipairs(St._taxLeftIds or {}) do
            local okA, act = pcall(sampIsDialogActive)
            local okI, cur = pcall(sampGetCurrentDialogId)
            if okA and act and okI and cur == dId then
                pcall(sampCloseCurrentDialogWithButton, 0)
            end
        end
        St._taxLeftIds = {}
        pcall(PCS_sendPhoneClose, 0, { noTex = true })
        wait(2000)
        pcall(PCS_saveCfgNow)
        pcall(function()
            local f = io.open(PCS_reopenFlagPath(), "wb")
            if f then f:write(tostring(os.time())); f:close() end
        end)
        _phoneOpBusy = false
        St._closePhoneRunning = false
        PCS_taxStage("DONE (reload)")
        if PCS_selfFileExists() then
            PCS_safeSelfReload()
        else
            pcall(os.remove, PCS_reopenFlagPath())
            PCS_taxStage("DONE (soft, file missing)")
        end
        St._taxReloadBusy = false
    end)
end

function PCS_taxSuccessImpl(isAuto, amount)
    PCS_taxStage("success start")
    pcall(PCS_texForgetPool, "tax success")
    if (PCS_POSTPAY_SILENCE_SEC or 0) > 0 then
        PCS_NOUI_UNTIL = math.max(PCS_NOUI_UNTIL or 0, os.clock() + PCS_POSTPAY_SILENCE_SEC)
    end
    local _scriptRun = _taxScriptRun == true
    _taxScriptRun = false
    St._taxLeftIds = {}
    for dId in pairs(St._taxDlgIds or {}) do St._taxLeftIds[#St._taxLeftIds + 1] = dId end
    -- защита от повторного вызова (два пути: хук диалога и чат)
    if _taxFinalizeDone then return end
    if St._taxFinalizedAt and (os.time() - St._taxFinalizedAt) < 30 then return end
    St._taxFinalizedAt = os.time()
    _taxFinalizeDone = true
    if PCS_FXC.soundTax ~= false then pcall(PCS_FX.play, "tax") end

    -- 1) внутреннее состояние оплаты (ничего не делаем с игрой)
    _taxState = 0
    _taxExpectedDialogId = nil
    _taxPhoneAlreadyOpen = false
    St._taxDlgIds = {}
    -- снимаем замок телефона; короткая пауза, чтобы не открыть его сразу снова
    PCS_phoneRelease(3, 1.0)
    _phoneOpBusy = true
    St._phoneOpBusySince = os.time()
    -- не даём автозапросам /stats сработать сразу после оплаты
    St._statsQuietUntil = os.clock() + 60
    pcall(PCS_texQuietFor, 20)

    -- 2) сумма → данные налогов
    amount = tonumber(amount) or 0
    if amount ~= amount or amount < 0 or amount == math.huge then amount = 0 end
    if amount <= 0 then
        amount = (_taxPendingAmount and _taxPendingAmount > 0) and _taxPendingAmount or 0
    end
    cfg.taxLastPayTime = os.time()
    if amount > 0 then
        cfg.taxLastPayAmount = amount
        cfg.taxTotalPaid = (tonumber(cfg.taxTotalPaid) or 0) + amount
    end
    pcall(saveCfg)                       -- запись откладывается (см. saveCfg)
    pcall(TX.addEntry, isAuto, amount)   -- строка в логе налогов

    PCS_taxStage("success done")
    if PCS_TAX_SOFT_REFRESH then
        PCS_taxSoftRefresh()
    elseif PCS_TAX_RELOAD_AFTER_PAY and _scriptRun then
        local chatSeen = St._taxChatOkAt and (os.clock() - St._taxChatOkAt) < 5
        if chatSeen then
            PCS_taxReloadNow(1000)
        else
            St._taxReloadArmedAt = os.clock()
            lua_thread.create(function()
                local t0 = os.clock()
                while St._taxReloadArmedAt and (os.clock() - t0) < PCS_TAX_CHAT_WAIT_SEC do
                    wait(200)
                end
                if St._taxReloadArmedAt then PCS_taxReloadNow(1000) end
            end)
        end
    else
        _phoneOpBusy = false
        St._closePhoneRunning = false
    end
end

local function onTaxPaymentSuccess(isAuto, amount)
    local ok, err = pcall(PCS_taxSuccessImpl, isAuto, amount)
    if not ok then
        pcall(PCS_taxFail, tostring(PCS_TAX_STAGE or "success"), err)
        pcall(PCS_TR, "tax: success error " .. tostring(err))
        print("[PC Stats][tax] onTaxPaymentSuccess error: " .. tostring(err))
        _taxState = 0
        _taxExpectedDialogId = nil
        _taxPhoneAlreadyOpen = false
        _taxFinalizeDone = true
        St._taxFinalizedAt = os.time()
        St._statsQuietUntil = os.clock() + 60
        pcall(PCS_phoneRelease, 3)
        _phoneOpBusy = false
        St._closePhoneRunning = false
    end
end

function PCS_safeCloseDialog()
    return PCS_closeDialogOnce()
end

-- отложенное закрытие из отдельного потока (нельзя закрывать прямо внутри хука)
function PCS_closeDialogLater(delayMs)
    lua_thread.create(function()
        wait(tonumber(delayMs) or 150)
        pcall(PCS_safeCloseDialog)
    end)
end

-- true, пока телефон занят / ещё закрывается после оплаты
function PCS_phoneIsBusy()
    if _taxState ~= 0 or _phoneOpBusy == true or _phoneFetchState or _cefFetching == true then return true end
    if St._closePhoneRunning or St._taxDeferredPending then return true end
    if St._postPayUntil and os.clock() < St._postPayUntil then return true end
    return false
end

-- полный сброс состояния окна меню перед телефоном/оплатой (из 1.8.6)
function PCS_resetMenuState()
    St._winVisible = false
    St._menuOpenAnim = 0
    St._menuOpenAnimT = nil
    St._menuSlideAnchor = nil
    St._pendingCloseReset = false
    St._closeConfirmOpen = false
    St._taxCalendarPopupOpen = false
    St._taxCalendarPopupOpenedOnce = false
    St._taxLogEntriesPopupOpen = false
    St._taxLogEntriesOpenedOnce = false
    St._financeSettingsOpen = false
    St._settingsPanelOpen = false
    St._finShiftAnim = 0.0
    St._finShiftAppliedPx = 0.0
    St._finShiftAnchorX = nil
    St.awaitingHotkeyBind = false
