-- ответ в диалог налогов отправляем, только если операция не отменена и диалог не устарел
function PCS_taxAnswerOk(seq, expectedId)
    if _taxState == 0 or _taxDlgSeq ~= seq then return false end
    local okA, avail = pcall(isSampAvailable)
    if not okA or not avail then return false end
    if expectedId ~= nil then
        local okD, act = pcall(sampIsDialogActive)
        local okI, cur = pcall(sampGetCurrentDialogId)
        if not (okD and act and okI and cur == expectedId) then return false end
    end
    return true
end

-- вызов onTaxPaymentSuccess ИЗ ХУКОВ (onServerMessage / onShowDialog) — никогда синхронно
-- (там запись на диск, чат, уведомления), а в отдельном потоке с pcall
function PCS_taxSuccessDeferred(isAuto, amount)
    if St._taxDeferredPending and (os.clock() - (St._taxDeferredAt or 0)) < 15 then return end
    St._taxDeferredPending = true
    St._taxDeferredAt = os.clock()
    lua_thread.create(function()
        wait(120)
        local ok, err = pcall(onTaxPaymentSuccess, isAuto, amount)
        St._taxDeferredPending = false
        if not ok then
            pcall(PCS_taxFail, "deferred-success", err)
            print("[PC Stats][tax] onTaxPaymentSuccess error: " .. tostring(err))
            _taxState = 0
            _taxExpectedDialogId = nil
            _taxPhoneAlreadyOpen = false
            St._closePhoneRunning = false
            _phoneOpBusy = false
        end
    end)
end

TAX_MIN_REPAY_SEC = 3600
local function payTaxesNow(isAuto)
    -- защита от флуда: не чаще интервала игрока (минимум 1 час)
    do
        local minGap = math.max(TAX_MIN_REPAY_SEC, math.max(1, tonumber(cfg.taxAutoIntervalHours) or 1) * 3600)
        if cfg.taxLastPayTime and cfg.taxLastPayTime ~= 0
            and (os.time() - cfg.taxLastPayTime) < minGap then
            if isAuto then
                -- тихо: автооплата просто ждёт следующий круг
                return
            end
            -- ручная: один раз говорим, что налогов нет / рано
            pcall(sampAddChatMessage, "{FFD700}[PC Stats] " ..
                "\xcd\xe0\xeb\xee\xe3\xe8 \xf3\xe6\xe5 \xee\xef\xeb\xe0\xf7\xe5\xed\xfb (\xef\xee\xe2\xf2\xee\xf0 \xf7\xe5\xf0\xe5\xe7 " ..
                tostring(math.ceil((minGap - (os.time() - cfg.taxLastPayTime)) / 60)) .. " \xec\xe8\xed)", -1)
            pcall(pcs_notify, u8"\xcd\xe0\xeb\xee\xe3\xe8 \xf3\xe6\xe5 \xee\xef\xeb\xe0\xf7\xe5\xed\xfb", "info")
            return
        end
    end
    if St._phoneCooldownUntil and os.time() < St._phoneCooldownUntil then
        if not isAuto then
            pcall(sampAddChatMessage, "{FF6666}[PC Stats] " ..
                "\xf2\xe5\xeb\xe5\xf4\xee\xed\x20\xe5\xf9\xb8\x20\xe7\xe0\xed\xff\xf2\x2c\x20\xef\xee\xe4\xee\xe6\xe4\xe8\x20\xef\xe0\xf0\xf3\x20\xf1\xe5\xea\xf3\xed\xe4", -1)
        end
        return
    end
    if _taxState ~= 0 then
        if not isAuto then
            pcall(sampAddChatMessage, "{FF6666}[PC Stats] " ..
                "\xd3\xe6\xe5\x20\xe2\xfb\xef\xee\xeb\xed\xff\xe5\xf2\xf1\xff\x2c\x20\xef\xee\xe4\xee\xe6\xe4\xe8\x2e", -1)
            pcall(pcs_notify, u8"\xd3\xe6\xe5\x20\xe2\xfb\xef\xee\xeb\xed\xff\xe5\xf2\xf1\xff\x2c\x20\xef\xee\xe4\xee\xe6\xe4\xe8\x2e", "warning")
        end
        return
    end
    if _phoneOpBusy then
        if not isAuto then
            pcall(sampAddChatMessage, "{FF6666}[PC Stats] " ..
                "\xd2\xe5\xeb\xe5\xf4\xee\xed\x20\xe7\xe0\xed\xff\xf2\x20\xe4\xf0\xf3\xe3\xee\xe9\x20\xee\xef\xe5\xf0\xe0\xf6\xe8\xe5\xe9\x2c\x20\xef\xee\xef\xf0\xee\xe1\xf3\xe9\xf2\xe5\x20\xf7\xe5\xf0\xe5\xe7\x20\xef\xe0\xf0\xf3\x20\xf1\xe5\xea\xf3\xed\xe4", -1)
            pcall(pcs_notify, u8"\xd2\xe5\xeb\xe5\xf4\xee\xed\x20\xe7\xe0\xed\xff\xf2\x20\xe4\xf0\xf3\xe3\xee\xe9\x20\xee\xef\xe5\xf0\xe0\xf6\xe8\xe5\xe9\x2c\x20\xef\xee\xef\xf0\xee\xe1\xf3\xe9\xf2\xe5\x20\xf7\xe5\xf0\xe5\xe7\x20\xef\xe0\xf0\xf3\x20\xf1\xe5\xea\xf3\xed\xe4", "warning")
        end
        return
    end
    if not isPlayerActuallySpawned() then
        if not isAuto then
            pcall(sampAddChatMessage, "{FF6666}[PC Stats] " ..
                "\xed\xe5\xeb\xfc\xe7\xff\x20\xee\xef\xeb\xe0\xf2\xe8\xf2\xfc\x20\xed\xe0\xeb\xee\xe3\xe8\x20\xe4\xee\x20\xf1\xef\xe0\xe2\xed\xe0\x20\xef\xe5\xf0\xf1\xee\xed\xe0\xe6\xe0", -1)
        end
        return
    end
    do
        local okP, paused = pcall(function() return isGamePaused and isGamePaused() end)
        if okP and paused == true then return end
    end
    do
        local G = PCS_TAXG
        if not G then G = { t = {}, blockedUntil = 0 }; PCS_TAXG = G end
        local nowT = os.time()
        if nowT < G.blockedUntil then return end
        local keep = {}
        for _, t0 in ipairs(G.t) do if nowT - t0 < 120 then keep[#keep + 1] = t0 end end
        G.t = keep
        if #G.t >= 4 then
            G.blockedUntil = nowT + 600
            pcall(PCS_TR, "tax: loop guard tripped, pause 600s")
            print("[PC Stats][tax] loop guard: too many attempts, pause 10 min")
            pcall(sampAddChatMessage, "{FF6666}\x5b\x50\x43\x20\x53\x74\x61\x74\x73\x5d\x20\xcd\xe0\xeb\xee\xe3\xe8\x3a\x20\xf1\xeb\xe8\xf8\xea\xee\xec\x20\xec\xed\xee\xe3\xee\x20\xef\xee\xef\xfb\xf2\xee\xea\x20\xef\xee\xe4\xf0\xff\xe4\x2c\x20\xef\xe0\xf3\xe7\xe0\x20\x31\x30\x20\xec\xe8\xed\xf3\xf2", -1)
            return
        end
        G.t[#G.t + 1] = nowT
    end
    if St._closePhoneRunning or St._taxDeferredPending
        or (St._postPayUntil and os.clock() < St._postPayUntil) then
        return
    end
    -- текстуры персонажа/иконок не рисуем, пока телефон открыт (CEF сбрасывает D3D)
    pcall(PCS_texQuietFor, 8)
    _taxIsAuto = isAuto
    _taxPhoneAlreadyOpen = false
    _phoneOpBusy = true
    St._phoneOpBusySince = os.time()
    _taxState  = 1
    _taxScriptRun = true
    _taxNavAttempts = 0
    _taxFinalizeDone = false
    PCS_TR("tax: payTaxesNow start auto=" .. tostring(isAuto))
    PCS_taxStage("start (open phone)")
    _taxPendingAmount = 0
    local okOpen = pcall(openTaxAppDirect)
    if not okOpen then
        _taxState = 0
        _taxExpectedDialogId = nil
        _phoneOpBusy = false
        pcall(sampAddChatMessage, "{FF6666}[PC Stats] " ..
            "\xed\xe5\x20\xf3\xe4\xe0\xeb\xee\xf1\xfc\x20\xee\xf2\xea\xf0\xfb\xf2\xfc\x20\xef\xf0\xe8\xeb\xee\xe6\xe5\xed\xe8\xe5\x20\xcd\xe0\xeb\xee\xe3\xe8\x20\xe2\x20\xf2\xe5\xeb\xe5\xf4\xee\xed\xe5", -1)
        pcall(pcs_notify, u8"\xed\xe5\x20\xf3\xe4\xe0\xeb\xee\xf1\xfc\x20\xee\xf2\xea\xf0\xfb\xf2\xfc\x20\xef\xf0\xe8\xeb\xee\xe6\xe5\xed\xe8\xe5\x20\xcd\xe0\xeb\xee\xe3\xe8\x20\xe2\x20\xf2\xe5\xeb\xe5\xf4\xee\xed\xe5", "error")
        return
    end
    lua_thread.create(function()
        local waited = 0
        local resent = false
        while _taxState ~= 0 and waited < TAX_TIMEOUT_SEC * 1000 do
            wait(100); waited = waited + 100
            if not resent and _taxState == 1 and waited >= math.floor(TAX_TIMEOUT_SEC * 1000 / 2) then
                resent = true
                _taxPhoneAlreadyOpen = true
                pcall(openTaxAppDirect)
            end
        end
        if _taxState ~= 0 then
            _taxState = 0
            _taxExpectedDialogId = nil
            _taxPhoneAlreadyOpen = false
            pcall(sampAddChatMessage, "{FF6666}[PC Stats] " ..
                "\xed\xe0\xeb\xee\xe3\xee\xe2\xfb\xe9\x20\xec\xe5\xed\xfe\x20\xed\xe5\x20\xee\xf2\xea\xf0\xfb\xeb\xf1\xff\x20\xe2\xee\xe2\xf0\xe5\xec\xff", -1)
            pcall(pcs_notify, u8"\xed\xe0\xeb\xee\xe3\xee\xe2\xfb\xe9\x20\xec\xe5\xed\xfe\x20\xed\xe5\x20\xee\xf2\xea\xf0\xfb\xeb\xf1\xff\x20\xe2\xee\xe2\xf0\xe5\xec\xff", "error")
            wait(400)
            PCS_phoneRelease(5)
        end
    end)
end

