-- pure arithmetic (no os.time): safe for any year, never returns nil
function Cal.isLeap(y) return (y % 4 == 0 and y % 100 ~= 0) or (y % 400 == 0) end

function Cal.daysInMonth(y, m)
    if m == 2 then return Cal.isLeap(y) and 29 or 28 end
    if m == 4 or m == 6 or m == 9 or m == 11 then return 30 end
    return 31
end

-- weekday of the 1st of the month, 1=Mon..7=Sun (Sakamoto algorithm)
function Cal.firstWeekdayMonFirst(y, m)
    local t = { 0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4 }
    local yy = y
    if m < 3 then yy = yy - 1 end
    local w = (yy + math.floor(yy / 4) - math.floor(yy / 100) + math.floor(yy / 400) + t[m] + 1) % 7
    return (w == 0) and 7 or w
end

function Cal.fmt(y, m, d) return string.format("%04d-%02d-%02d", y, m, d) end

function Cal.dateLabel(y, m, d)
    local wd = (Cal.firstWeekdayMonFirst(y, m) - 1 + d - 1) % 7 + 1
    return string.format("%d ", d) .. Cal.MONTHS_GEN[m] .. string.format(" %d, ", y) .. Cal.WDLONG[wd]
end

Cal.PAD = 10
-- cell size / gap / inner width; fit=true shrinks to the available width (never grows)
function Cal.metrics(avail, fit)
    local gap = S(4)
    local cell = S(34)
    if fit and avail and PCS_fin(avail) and avail > 0 then
        local c = math.floor((avail - 2 * S(Cal.PAD) - 6 * gap) / 7)
        if c < cell then cell = math.max(S(22), c) end
    end
    return cell, gap, 7 * cell + 6 * gap
end

-- full card width (inner width + padding on both sides)
function Cal.cardW()
    local _, _, W = Cal.metrics(nil, false)
    return W + 2 * S(Cal.PAD)
end

function Cal.btn(id, x, y, w, h, label, o)
    o = o or {}
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local r, g, b = getAcc()
    r, g, b = fin01(r, 0.5), fin01(g, 0.5), fin01(b, 0.5)
    local dl = imgui.GetWindowDrawList()
    imgui.SetCursorScreenPos(V2(x, y))
    local clicked = imgui.InvisibleButton(id, V2(w, h))
    local hov = (not o.disabled) and imgui.IsItemHovered()
    local held = (not o.disabled) and imgui.IsItemActive()
    local rd = o.round or S(8)
    local a, bb = V2(x, y), V2(x + w, y + h)
    local txt = iv4(0.86, 0.88, 0.93, 1.0)
    if o.sel and o.glow then
        dl:AddRectFilled(V2(x - S(2), y - S(2)), V2(x + w + S(2), y + h + S(2)), U32(iv4(r, g, b, 0.22)), rd + S(2))
    end
    local glass = o.glass and not o.dim and not o.disabled
    if glass then
        -- стеклянный квадрат: тень, полупрозрачная заливка, светлая кромка и блик сверху
        local tr, tg, tb, fa = 1, 1, 1, hov and 0.26 or 0.14
        if o.sel then
            tr, tg, tb = r * 0.5 + 0.5, g * 0.5 + 0.5, b * 0.5 + 0.5
            fa = held and 0.80 or 0.62
        elseif o.marked then
            tr, tg, tb = r * 0.45 + 0.55, g * 0.45 + 0.55, b * 0.45 + 0.55
            fa = hov and 0.42 or 0.32
        end
        dl:AddRectFilled(V2(x + Sf(1), y + Sf(3)), V2(x + w - Sf(1), y + h + Sf(1)), U32(iv4(0, 0, 0, 0.35)), rd)
        dl:AddRectFilled(a, bb, U32(iv4(tr, tg, tb, fa)), rd)
        dl:AddRectFilled(V2(x + Sf(2), y + Sf(1.5)), V2(x + w - Sf(2), y + h * 0.48), U32(iv4(1, 1, 1, 0.22)), rd * 0.8)
        dl:AddRect(a, bb, U32(iv4(1, 1, 1, o.sel and 0.95 or (hov and 0.85 or 0.45))), rd, 0, Sf(1.0))
        txt = iv4(1, 1, 1, 1)
    elseif o.sel then
        dl:AddRectFilled(a, bb, U32(iv4(r, g, b, held and 0.85 or 1.0)), rd)
        if (r * 0.299 + g * 0.587 + b * 0.114) > 0.62 then txt = iv4(0.05, 0.06, 0.09, 1.0) else txt = iv4(1, 1, 1, 1) end
    elseif o.marked then
        dl:AddRectFilled(a, bb, U32(iv4(r * 0.55, g * 0.55, b * 0.55, hov and 1.0 or 0.92)), rd)
        txt = iv4(1, 1, 1, 1)
    elseif o.bg then
        local c = o.bg
        if hov then c = o.hbg or c end
        dl:AddRectFilled(a, bb, U32(c), rd)
        if not o.dim then txt = iv4(1, 1, 1, 1) end
    elseif hov then
        dl:AddRectFilled(a, bb, U32(iv4(r * 0.40 + 0.04, g * 0.40 + 0.04, b * 0.40 + 0.04, held and 1.0 or 0.92)), rd)
        txt = iv4(1, 1, 1, 1)
    elseif o.fill ~= false and not o.dim then
        dl:AddRectFilled(a, bb, U32(iv4(0.15, 0.16, 0.21, 0.80)), rd)
    end
    if o.wk and not o.sel and not o.marked and not hov then txt = iv4(0.95, 0.62, 0.62, 1.0) end
    if o.dim then txt = iv4(0.40, 0.41, 0.47, 1.0) end
    if o.today then dl:AddRect(a, bb, U32(iv4(r, g, b, 0.95)), rd, 0, Sf(1.6)) end
    if o.col then txt = o.col end
    label = tostring(label or "")
    if label ~= "" then
        local pushed = false
        if o.bold and PCS_BOLD_FONT then pushed = pcall(imgui.PushFont, PCS_BOLD_FONT) end
        local ts = imgui.CalcTextSize(label)
        local tw = PCS_fin(ts.x) and ts.x or 0
        local th = PCS_fin(ts.y) and ts.y or 0
        local lx, ly = x + (w - tw) * 0.5, y + (h - th) * 0.5
        if glass then dl:AddText(V2(lx + Sf(1), ly + Sf(1)), U32(iv4(0, 0, 0, 0.55)), label) end
        dl:AddText(V2(lx, ly), U32(txt), label)
        if pushed then pcall(imgui.PopFont) end
    end
    if o.marked and not o.sel then
        dl:AddCircleFilled(V2(x + w * 0.5, y + h - Sf(5)), Sf(2.0), U32(iv4(1.0, 0.90, 0.50, 1.0)), 8)
    end
    return (clicked and not o.disabled) and true or false, hov
end

-- round arrow button (triangle drawn by hand: no font glyph needed). dir<0 left, dir>0 right
function Cal.arrow(id, x, y, sz, dir, dbl, disabled)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local clicked, hov = Cal.btn(id, x, y, sz, sz, "", { disabled = disabled, round = math.floor(sz / 2) })
    local dl = imgui.GetWindowDrawList()
    local c
    if disabled then c = iv4(0.35, 0.36, 0.40, 1.0)
    elseif hov then c = iv4(1, 1, 1, 1)
    else c = iv4(0.80, 0.84, 0.94, 1.0) end
    local u = U32(c)
    local cx, cy, k = x + sz * 0.5, y + sz * 0.5, sz * 0.15
    local function tri(ox)
        if dir < 0 then
            dl:AddTriangleFilled(V2(cx + ox + k, cy - k * 1.4), V2(cx + ox - k, cy), V2(cx + ox + k, cy + k * 1.4), u)
        else
            dl:AddTriangleFilled(V2(cx + ox - k, cy - k * 1.4), V2(cx + ox - k, cy + k * 1.4), V2(cx + ox + k, cy), u)
        end
    end
    if dbl then tri(-k * 0.9); tri(k * 0.9) else tri(0) end
    return clicked
end

function Cal.widget(st, o)
    o = o or {}
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local r, g, b = getAcc()
    r, g, b = fin01(r, 0.5), fin01(g, 0.5), fin01(b, 0.5)
    local uid = o.uid or "cal"
    local now = os.date("*t")
    local ymin, ymax = o.minY or Cal.YMIN, o.maxY or Cal.YMAX
    st.calY = tonumber(st.calY) or now.year
    st.calM = tonumber(st.calM) or now.month
    if st.calY < ymin then st.calY = ymin elseif st.calY > ymax then st.calY = ymax end
    if st.calM < 1 then st.calM = 1 elseif st.calM > 12 then st.calM = 12 end
    -- popup was closed for a while -> next open starts from the day grid
    local clk = os.clock()
    if (not o.fit) and clk - (st._lastDraw or 0) > 0.5 then st.view = "days" end
    st._lastDraw = clk
    st.view = st.view or "days"

    local avail = imgui.GetContentRegionAvail().x
    local cell, gap, W = Cal.metrics(avail, o.fit)
    local pad = S(Cal.PAD)
    local dl = imgui.GetWindowDrawList()
    local p0 = imgui.GetCursorScreenPos()
    if not (PCS_fin(p0.x) and PCS_fin(p0.y)) then p0 = { x = 0, y = 0 } end
    if o.fit and PCS_fin(avail) and avail > W + 2 * pad then p0 = { x = p0.x + math.floor((avail - W - 2 * pad) / 2), y = p0.y } end
    local ox, oy = p0.x + pad, p0.y + pad       -- content origin

    local picked = nil
    local hh = S(44)
    local bs = S(30)
    local by = oy + (hh - bs) * 0.5
    local rowH = cell
    local labH = S(24)
    local Hb = labH + 6 * (rowH + gap)
    local bodyY = oy + hh + S(4)
    local footH = S(30)
    local total = hh + S(4) + Hb + S(4) + footH
    local cardW, cardH = W + 2 * pad, total + 2 * pad

    -- card: soft shadow, body, accent border, accent strip at the top
    dl:AddRectFilled(V2(p0.x + S(2), p0.y + S(3)), V2(p0.x + cardW + S(2), p0.y + cardH + S(3)), U32(iv4(0, 0, 0, 0.30)), S(16))
    dl:AddRectFilled(V2(p0.x, p0.y), V2(p0.x + cardW, p0.y + cardH), U32(iv4(0.105, 0.112, 0.145, 1.0)), S(16))
    dl:AddRectFilled(V2(p0.x, p0.y), V2(p0.x + cardW, p0.y + hh + pad + S(2)),
        U32(iv4(r * 0.24 + 0.05, g * 0.24 + 0.05, b * 0.24 + 0.06, 1.0)), S(16))
    dl:AddRectFilled(V2(p0.x, p0.y + hh + pad - S(10)), V2(p0.x + cardW, p0.y + hh + pad + S(2)),
        U32(iv4(r * 0.24 + 0.05, g * 0.24 + 0.05, b * 0.24 + 0.06, 1.0)), 0)
    dl:AddRect(V2(p0.x, p0.y), V2(p0.x + cardW, p0.y + cardH), U32(iv4(r * 0.7, g * 0.7, b * 0.7, 0.55)), S(16), 0, Sf(1.2))

    local function setYM(y, m)
        if m < 1 then m = 12; y = y - 1 elseif m > 12 then m = 1; y = y + 1 end
        if y < ymin or y > ymax then return end
        st.calY, st.calM = y, m
    end
    local view = st.view
    local pid = "##" .. uid
    local function tw(s, bold)
        local pushed = false
        if bold and PCS_BOLD_FONT then pushed = pcall(imgui.PushFont, PCS_BOLD_FONT) end
        local t = imgui.CalcTextSize(s).x
        if pushed then pcall(imgui.PopFont) end
        return PCS_fin(t) and t or 0
    end
    local hi = iv4(r * 0.4 + 0.6, g * 0.4 + 0.6, b * 0.4 + 0.6, 1)
    if view == "days" then
        if Cal.arrow(pid .. "yp", ox, by, bs, -1, true, st.calY <= ymin) then setYM(st.calY - 1, st.calM) end
        if Cal.arrow(pid .. "mp", ox + bs + gap, by, bs, -1, false, st.calY <= ymin and st.calM <= 1) then setYM(st.calY, st.calM - 1) end
        if Cal.arrow(pid .. "mn", ox + W - 2 * bs - gap, by, bs, 1, false, st.calY >= ymax and st.calM >= 12) then setYM(st.calY, st.calM + 1) end
        if Cal.arrow(pid .. "yn", ox + W - bs, by, bs, 1, true, st.calY >= ymax) then setYM(st.calY + 1, st.calM) end
        local mName, yStr = Cal.MONTHS[st.calM], tostring(st.calY)
        local mw, yw = tw(mName, true), tw(yStr, true)
        local sp = S(8)
        local tx = ox + (W - (mw + sp + yw)) / 2
        if Cal.btn(pid .. "tm", tx - S(6), by, mw + S(12), bs, mName, { fill = false, bold = true, col = iv4(1, 1, 1, 1) }) then st.view = "months" end
        if Cal.btn(pid .. "ty", tx + mw + sp - S(6), by, yw + S(12), bs, yStr, { fill = false, bold = true, col = hi }) then
            st.view = "years"; st.yBase = st.calY - ((st.calY - ymin) % 12)
        end
    elseif view == "months" then
        if Cal.arrow(pid .. "yp", ox, by, bs, -1, false, st.calY <= ymin) then setYM(st.calY - 1, st.calM) end
        if Cal.arrow(pid .. "yn", ox + W - bs, by, bs, 1, false, st.calY >= ymax) then setYM(st.calY + 1, st.calM) end
        local yStr = tostring(st.calY)
        local yw = tw(yStr, true)
        if Cal.btn(pid .. "ty", ox + (W - yw) / 2 - S(10), by, yw + S(20), bs, yStr, { fill = false, bold = true, col = hi }) then
            st.view = "years"; st.yBase = st.calY - ((st.calY - ymin) % 12)
        end
    else
        st.yBase = st.yBase or (st.calY - ((st.calY - ymin) % 12))
        local base = st.yBase
        if Cal.arrow(pid .. "yp", ox, by, bs, -1, false, base <= ymin) then st.yBase = base - 12 end
        if Cal.arrow(pid .. "yn", ox + W - bs, by, bs, 1, false, base + 12 > ymax) then st.yBase = base + 12 end
        local rng = tostring(base) .. " - " .. tostring(base + 11)
        local rw = tw(rng, true)
        Cal.btn(pid .. "tr", ox + (W - rw) / 2 - S(10), by, rw + S(20), bs, rng, { fill = false, disabled = true, bold = true, col = iv4(1, 1, 1, 1) })
    end

    local todayStr = Cal.fmt(now.year, now.month, now.day)
    if view == "days" then
        for i = 1, 7 do
            local wx = ox + (i - 1) * (cell + gap)
            local ts = imgui.CalcTextSize(Cal.WD[i])
            local w1 = PCS_fin(ts.x) and ts.x or 0
            local c = (i >= 6) and iv4(0.90, 0.50, 0.50, 0.95) or iv4(0.58, 0.62, 0.74, 1.0)
            dl:AddText(V2(wx + (cell - w1) / 2, bodyY + S(3)), U32(c), Cal.WD[i])
        end
        dl:AddRectFilled(V2(ox, bodyY + labH - S(3)), V2(ox + W, bodyY + labH - S(2)), U32(iv4(1, 1, 1, 0.07)), 0)
        local dim = Cal.daysInMonth(st.calY, st.calM)
        local startWd = Cal.firstWeekdayMonFirst(st.calY, st.calM)
        local pm, py = st.calM - 1, st.calY
        if pm < 1 then pm = 12; py = py - 1 end
        local dimPrev = Cal.daysInMonth(py, pm)
        local rnd = math.floor(cell / 2)
        for idx = 0, 41 do
            local col, row = idx % 7, math.floor(idx / 7)
            local dn = idx - (startWd - 1) + 1
            local x = ox + col * (cell + gap)
            local y = bodyY + labH + row * (rowH + gap)
            if dn < 1 or dn > dim then
                local lbl = (dn < 1) and (dimPrev + dn) or (dn - dim)
                Cal.btn(pid .. "f" .. idx, x, y, cell, rowH, tostring(lbl),
                    { fill = false, dim = true, disabled = true, round = rnd, col = iv4(0.30, 0.31, 0.37, 1.0) })
            else
                local ds = Cal.fmt(st.calY, st.calM, dn)
                local marked = (o.marked and o.marked[ds] == true) or false
                local disabled = (o.onlyMarked and not marked) or (o.minStr and ds < o.minStr) or false
                local isSel = (o.selected == ds)
                if Cal.btn(pid .. "d" .. dn, x, y, cell, rowH, tostring(dn), {
                        sel = isSel, glow = true, today = (ds == todayStr), marked = marked and not isSel,
                        dim = disabled, disabled = disabled, wk = (col >= 5), round = S(10), bold = true, glass = true }) then
                    picked = ds
                end
            end
        end
    else
        local mw = math.floor((W - 2 * gap) / 3)
        local mh = math.floor((Hb - 3 * gap) / 4)
        if view == "months" then
            for m = 1, 12 do
                local col, row = (m - 1) % 3, math.floor((m - 1) / 3)
                if Cal.btn(pid .. "m" .. m, ox + col * (mw + gap), bodyY + row * (mh + gap), mw, mh, Cal.MONTHS[m], {
                        sel = (m == st.calM), today = (m == now.month and st.calY == now.year), round = S(12) }) then
                    st.calM = m; st.view = "days"
                end
            end
        else
            local base = st.yBase or st.calY
            for i = 0, 11 do
                local yr = base + i
                local col, row = i % 3, math.floor(i / 3)
                local dis = (yr < ymin or yr > ymax)
                if Cal.btn(pid .. "y" .. i, ox + col * (mw + gap), bodyY + row * (mh + gap), mw, mh, tostring(yr), {
                        sel = (yr == st.calY), today = (yr == now.year), dim = dis, disabled = dis, round = S(12) }) then
                    st.calY = yr; st.view = "months"
                end
            end
        end
    end

    -- footer: jump to today
    local fy = oy + hh + S(4) + Hb + S(4)
    if Cal.btn(pid .. "today", ox, fy, W, footH, u8"\xd1\xe5\xe3\xee\xe4\xed\xff" .. "  " .. string.format("%02d.%02d.%04d", now.day, now.month, now.year), {
            round = S(15), col = hi, bg = iv4(r * 0.18 + 0.05, g * 0.18 + 0.05, b * 0.18 + 0.06, 1.0),
            hbg = iv4(r * 0.34 + 0.05, g * 0.34 + 0.05, b * 0.34 + 0.06, 1.0) }) then
        st.calY = math.max(ymin, math.min(ymax, now.year)); st.calM = now.month; st.view = "days"
        if o.todayPicks and not (o.minStr and todayStr < o.minStr) then picked = todayStr end
    end

    imgui.SetCursorScreenPos(V2(p0.x, p0.y + cardH))
    imgui.Dummy(V2(cardW, 1))
    if picked and o.onPick then o.onPick(picked) end
    return picked
end

-- old entry point (PayDay / tax log popups): only days with records are clickable
function Cal.draw(state, markedDates, onPickDate)
    local picked = Cal.widget(state, { uid = "cd", marked = markedDates or {}, onlyMarked = true, onPick = onPickDate })
    if picked then pcall(imgui.CloseCurrentPopup) end
end

-- ── настройки всплывающих уведомлений (плашек): перенесены из Market Helper
-- (вкладка "Вид" -> "Уведомления (плашки)"). Вызывается из drawSettingsInner ──
function PCS_drawToastSettings()
    local T, DEF = PCS_TOAST, PCS_TOAST_DEF
    if type(T) ~= "table" then return end
    local U = PCS_TOAST_UI
    if not U then U = {}; PCS_TOAST_UI = U end
    local function changed()
        if PCS_toastSave then PCS_toastSave() end
        if pcs_apply_toast_settings then pcs_apply_toast_settings() end
    end

    if drawToggleSwitch("##toastEnabledSw", T.enabled ~= false) then
        T.enabled = not (T.enabled ~= false)
        changed()
    end
    imgui.SameLine(0, S(8))
    imgui.TextColored(iv4(1, 1, 1, 1), u8"\xcf\xee\xea\xe0\xe7\xfb\xe2\xe0\xf2\xfc \xe2\xf1\xef\xeb\xfb\xe2\xe0\xfe\xf9\xe8\xe5 \xf3\xe2\xe5\xe4\xee\xec\xeb\xe5\xed\xe8\xff")
    imgui.TextColored(thDim(), "  " .. u8"\xc4\xf3\xe1\xeb\xe8\xf0\xf3\xfe\xf2 \xe2\xf1\xe5 \xf1\xee\xee\xe1\xf9\xe5\xed\xe8\xff \xf1\xea\xf0\xe8\xef\xf2\xe0 \xe8\xe7 \xf7\xe0\xf2\xe0")
    imgui.Spacing()

    -- расположение на экране
    imgui.TextColored(iv4(0.70, 0.82, 1.0, 1.0), u8"\xd0\xe0\xf1\xef\xee\xeb\xee\xe6\xe5\xed\xe8\xe5 \xed\xe0 \xfd\xea\xf0\xe0\xed\xe5:")
    do
        local r, g, b = getAcc()
        local gap = S(4)
        local bw = math.floor((imgui.GetContentRegionAvail().x - gap * 3) / 4)
        local function posBtn(label, cur, apply)
            local col = cur and { r, g, b } or { 0.45, 0.47, 0.55 }
            if PCS_gdButton(label, bw, S(26), col, 6.0) then apply(); changed() end
        end
        posBtn(u8"\xd1\xeb\xe5\xe2\xe0##toastL", T.pos_h == "left", function() T.pos_h = "left" end)
        imgui.SameLine(0, gap)
        posBtn(u8"\xd1\xef\xf0\xe0\xe2\xe0##toastR", T.pos_h ~= "left", function() T.pos_h = "right" end)
        imgui.SameLine(0, gap)
        posBtn(u8"\xd1\xe2\xe5\xf0\xf5\xf3##toastT", T.pos_v == "top", function() T.pos_v = "top" end)
        imgui.SameLine(0, gap)
        posBtn(u8"\xd1\xed\xe8\xe7\xf3##toastB", T.pos_v ~= "top", function() T.pos_v = "bottom" end)
    end
    imgui.Spacing()

    local advOpen = PCS_settFold("toastAdv", u8"\xc2\xe8\xe4 \xef\xeb\xe0\xf8\xe5\xea: \xf0\xe0\xe7\xec\xe5\xf0\xfb, \xee\xf2\xf1\xf2\xf3\xef\xfb, \xf6\xe2\xe5\xf2\xe0",
        u8"\xd2\xee\xed\xea\xe0\xff \xed\xe0\xf1\xf2\xf0\xee\xe9\xea\xe0 \xe2\xed\xe5\xf8\xed\xe5\xe3\xee \xe2\xe8\xe4\xe0 \xef\xeb\xe0\xf8\xe5\xea. \xce\xe1\xfb\xf7\xed\xee \xec\xe5\xed\xff\xf2\xfc \xed\xe5 \xed\xf3\xe6\xed\xee.")
    if PCS_gdSliderStyle then PCS_gdSliderStyle(true) end
    local function slider(key, label, mn, mx, fmt, isInt)
        local buf = U[key]
        if not buf then buf = imgui.new.float(T[key] or DEF[key]); U[key] = buf end
        buf[0] = T[key] or DEF[key]
        imgui.TextColored(iv4(0.70, 0.82, 1.0, 1.0), label)
        imgui.PushItemWidth(-1)
        if imgui.SliderFloat("##toastsl_" .. key, buf, mn, mx, fmt) then
            T[key] = isInt and math.floor(buf[0] + 0.5) or buf[0]
            changed()
        end
        imgui.PopItemWidth()
    end
    if advOpen then
    slider("width",         u8"\xd8\xe8\xf0\xe8\xed\xe0 \xef\xeb\xe0\xf8\xea\xe8",            200, 520, "%.0f px", false)
    slider("corner_radius", u8"\xd1\xea\xf0\xf3\xe3\xeb\xe5\xed\xe8\xe5 \xf3\xe3\xeb\xee\xe2",         0,   24,  "%.0f px", false)
    slider("accent_width",  u8"\xd8\xe8\xf0\xe8\xed\xe0 \xf6\xe2\xe5\xf2\xed\xee\xe9 \xef\xee\xeb\xee\xf1\xfb",    0,   12,  "%.0f px", false)
    slider("padding_x",     u8"\xce\xf2\xf1\xf2\xf3\xef \xef\xee \xe3\xee\xf0\xe8\xe7\xee\xed\xf2\xe0\xeb\xe8",    4,   40,  "%.0f px", false)
    slider("padding_y",     u8"\xce\xf2\xf1\xf2\xf3\xef \xef\xee \xe2\xe5\xf0\xf2\xe8\xea\xe0\xeb\xe8",      4,   30,  "%.0f px", false)
    slider("spacing",       u8"\xd0\xe0\xf1\xf1\xf2\xee\xff\xed\xe8\xe5 \xec\xe5\xe6\xe4\xf3 \xef\xeb\xe0\xf8\xea\xe0\xec\xe8", 0,  30,  "%.0f px", false)
    slider("margin_x",      u8"\xce\xf2\xf1\xf2\xf3\xef \xee\xf2 \xea\xf0\xe0\xff (X)",       0,   200, "%.0f px", false)
    slider("margin_y",      u8"\xce\xf2\xf1\xf2\xf3\xef \xee\xf2 \xea\xf0\xe0\xff (Y)",       0,   200, "%.0f px", false)
    slider("duration",      u8"\xc2\xf0\xe5\xec\xff \xef\xee\xea\xe0\xe7\xe0",             1,   20,  "%.1f \xf1\xe5\xea", false)
    slider("anim_speed",    u8"\xd1\xea\xee\xf0\xee\xf1\xf2\xfc \xe0\xed\xe8\xec\xe0\xf6\xe8\xe8",        2,   30,  "%.1f", false)
    slider("max_visible",   u8"\xcf\xeb\xe0\xf8\xe5\xea \xee\xe4\xed\xee\xe2\xf0\xe5\xec\xe5\xed\xed\xee",      1,   10,  "%.0f", true)
    slider("font_scale",    u8"\xd0\xe0\xe7\xec\xe5\xf0 \xf2\xe5\xea\xf1\xf2\xe0",            0.6, 2.0, "%.2f", false)
    slider("bg_a",          u8"\xcf\xf0\xee\xe7\xf0\xe0\xf7\xed\xee\xf1\xf2\xfc \xf4\xee\xed\xe0",        0.1, 1.0, "%.2f", false)
    end
    if PCS_gdSliderStyle then PCS_gdSliderStyle(false) end
    imgui.Spacing()

    -- цвета фона и текста
    local function color3(key, label, kr, kg, kb)
        local buf = U[key]
        if not buf then buf = imgui.new("float[3]", { T[kr], T[kg], T[kb] }); U[key] = buf end
        buf[0], buf[1], buf[2] = T[kr], T[kg], T[kb]
        imgui.TextColored(iv4(0.70, 0.82, 1.0, 1.0), label)
        imgui.PushItemWidth(-1)
        if imgui.ColorEdit3("##toastcol_" .. key, buf) then
            T[kr], T[kg], T[kb] = buf[0], buf[1], buf[2]
            changed()
        end
        imgui.PopItemWidth()
    end
    if advOpen then
    color3("bgc",   u8"\xd6\xe2\xe5\xf2 \xf4\xee\xed\xe0",  "bg_r",   "bg_g",   "bg_b")
    color3("textc", u8"\xd6\xe2\xe5\xf2 \xf2\xe5\xea\xf1\xf2\xe0", "text_r", "text_g", "text_b")
    end
    imgui.Spacing()

    -- рамка плашки
    -- персонаж-стикер в плашках
    if drawToggleSwitch("##toastCharSw", T.char_enabled ~= false) then
        T.char_enabled = not (T.char_enabled ~= false)
        changed()
    end
    imgui.SameLine(0, S(8))
    imgui.TextColored(iv4(1, 1, 1, 1), u8"\xcf\xe5\xf0\xf1\xee\xed\xe0\xe6\x2d\xf1\xf2\xe8\xea\xe5\xf0\x20\xab\xe3\xee\xe2\xee\xf0\xe8\xf2\xbb\x20\xf3\xe2\xe5\xe4\xee\xec\xeb\xe5\xed\xe8\xe5")
    PCS_settHint(u8"\xcc\xe8\xed\xe8-\xef\xe5\xf0\xf1\xee\xed\xe0\xe6 \xf0\xff\xe4\xee\xec \xf1 \xf2\xe5\xea\xf1\xf2\xee\xec \xef\xeb\xe0\xf8\xea\xe8.")
        -- выбор персонажа для всплывающих уведомлений (с превью картинки)
    if T.char_enabled ~= false then
        imgui.Dummy(imgui.ImVec2(0, S(6)))
        imgui.TextColored(iv4(0.70, 0.82, 1.0, 1.0), u8"\xcf\xe5\xf0\xf1\xee\xed\xe0\xe6 \xe2 \xf3\xe2\xe5\xe4\xee\xec\xeb\xe5\xed\xe8\xe8:")
        imgui.TextColored(thDim(), "  " .. u8"\xcd\xe0\xe6\xec\xe8\xf2\xe5 \xea\xe0\xf0\xf2\xee\xf7\xea\xf3 \x97 \xf3\xe2\xe8\xe4\xe8\xf2\xe5 \xea\xf2\xee \xe3\xee\xe2\xee\xf0\xe8\xf2 \xe2 \xf2\xee\xf1\xf2\xe0\xf5")
        do
            local r, g, b = getAcc()
            local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
            local dl = imgui.GetWindowDrawList()
            local gap = S(6)
            local names = {
                u8"\xca\xe0\xea \xec\xe5\xed\xfe",
                u8"\xca\xeb\xe0\xf1\xf1.",
                u8"\xd5\xf3\xe4\xe8",
                u8"\xd4\xee\xf2\xee 1",
                u8"\xd4\xee\xf2\xee 2",
                u8"\xd4\xee\xf2\xee 3",
            }
            local cur = tonumber(T.char_skin) or 0
            local nCards = 6
            local aw = imgui.GetContentRegionAvail().x
            local cw = (aw - gap * (nCards - 1)) / nCards
            local ch = S(88)
            local row = imgui.GetCursorScreenPos()
            local menuSkin = tonumber(PCS_CompanionSel and PCS_CompanionSel.skin) or 1
            for si = 0, 5 do
                local x0 = row.x + si * (cw + gap)
                local y0 = row.y
                local on = (cur == si)
                local bgA = on and 0.28 or 0.10
                local bdA = on and 0.90 or 0.35
                dl:AddRectFilled(V2(x0, y0), V2(x0 + cw, y0 + ch), U32(iv4(r * bgA, g * bgA, b * bgA, 0.95)), 8)
                dl:AddRect(V2(x0, y0), V2(x0 + cw, y0 + ch), U32(iv4(r, g, b, bdA)), 8, 0, on and 2.0 or 1.0)
                local skinIdx = (si == 0) and menuSkin or si
                local tex = PCS_TEXPOOL and PCS_TEXPOOL.tex and PCS_TEXPOOL.tex[skinIdx]
                local pv = math.min(cw - S(12), ch - S(28))
                local px = x0 + (cw - pv) * 0.5
                local py = y0 + S(6)
                if tex and not PCS_DIAG_NO_TEX and not PCS_texQuiet() then
                    local asp = (PCS_TEXPOOL.aspect and PCS_TEXPOOL.aspect[skinIdx]) or 1
                    local iw, ih = pv, pv
                    if asp >= 1 then ih = pv / asp else iw = pv * asp end
                    pcall(function()
                        dl:AddImage(tex, V2(px + (pv - iw) * 0.5, py + (pv - ih) * 0.5),
                            V2(px + (pv + iw) * 0.5, py + (pv + ih) * 0.5),
                            V2(0, 0), V2(1, 1), U32(iv4(1, 1, 1, 1)))
                    end)
                else
                    local cx, cy = x0 + cw * 0.5, py + pv * 0.45
                    dl:AddCircleFilled(V2(cx, cy - S(8)), S(7), U32(iv4(0.55, 0.58, 0.65, 0.7)), 16)
                    dl:AddRectFilled(V2(cx - S(9), cy), V2(cx + S(9), cy + S(14)), U32(iv4(0.55, 0.58, 0.65, 0.7)), 4)
                end
                local label = names[si + 1]
                local ts = imgui.CalcTextSize(label)
                imgui.SetCursorScreenPos(V2(x0 + (cw - ts.x) * 0.5, y0 + ch - S(18)))
                imgui.TextColored(on and iv4(1, 1, 1, 1) or thDim(), label)
                imgui.SetCursorScreenPos(V2(x0, y0))
                if imgui.InvisibleButton("##toastSkinCard" .. tostring(si), V2(cw, ch)) then
                    T.char_skin = si
                    if cfg then cfg.toastCharSkin = si end
                    changed()
                    pcall(saveCfg)
                    if pcs_toast_test then pcall(pcs_toast_test, "info") end
                end
                -- анимация карточки как у кнопок
                if PCS_btnFxRect then
                    pcall(PCS_btnFxRect, dl, V2(x0, y0), V2(x0 + cw, y0 + ch),
                        imgui.IsItemHovered and imgui.IsItemHovered() or false,
                        imgui.IsItemActive and imgui.IsItemActive() or false,
                        "toastSkinCard" .. tostring(si), 8)
                end
                if on and tex then
                    local breath = 0.5 + 0.5 * math.sin(os.clock() * 2.4 + si * 0.5)
                    dl:AddRect(V2(x0 + 1, y0 + 1), V2(x0 + cw - 1, y0 + ch - 1),
                        U32(iv4(r, g, b, 0.12 + 0.22 * breath)), 8, 0, 1.4)
                end
            end
            imgui.SetCursorScreenPos(V2(row.x, row.y + ch + S(6)))
            imgui.Dummy(V2(aw, 1))
        end
    end

    if T.char_enabled ~= false then
        if PCS_gdSliderStyle then PCS_gdSliderStyle(true) end
        slider("char_size", u8"\xd0\xe0\xe7\xec\xe5\xf0\x20\xef\xe5\xf0\xf1\xee\xed\xe0\xe6\xe0", 40, 140, "%.0f px", false)
        if PCS_gdSliderStyle then PCS_gdSliderStyle(false) end
    end
    if drawToggleSwitch("##toastTypeSw", T.typewriter ~= false) then
        T.typewriter = not (T.typewriter ~= false)
        changed()
    end
    imgui.SameLine(0, S(8))
    imgui.TextColored(iv4(1, 1, 1, 1), u8"\xd2\xe5\xea\xf1\xf2\x20\xab\xef\xe5\xf7\xe0\xf2\xe0\xe5\xf2\xf1\xff\xbb\x20\xea\xe0\xea\x20\xf0\xe5\xf7\xfc")
    PCS_settHint(u8"\xc1\xf3\xea\xe2\xfb \xef\xee\xff\xe2\xeb\xff\xfe\xf2\xf1\xff \xef\xee\xf1\xf2\xe5\xef\xe5\xed\xed\xee, \xea\xe0\xea \xe1\xf3\xe4\xf2\xee \xef\xe5\xf0\xf1\xee\xed\xe0\xe6 \xe3\xee\xe2\xee\xf0\xe8\xf2.")
    if T.typewriter ~= false then
        if PCS_gdSliderStyle then PCS_gdSliderStyle(true) end
        slider("typewriter_speed", u8"\xd1\xea\xee\xf0\xee\xf1\xf2\xfc\x20\xef\xe5\xf7\xe0\xf2\xe8\x20\x28\xf1\xe8\xec\xe2\x2f\xf1\xe5\xea\x29", 15, 200, "%.0f", false)
        if PCS_gdSliderStyle then PCS_gdSliderStyle(false) end
    end
    if drawToggleSwitch("##toastProgSw", T.show_progress ~= false) then
        T.show_progress = not (T.show_progress ~= false)
        changed()
    end
    imgui.SameLine(0, S(8))
    imgui.TextColored(iv4(1, 1, 1, 1), u8"\xcf\xee\xeb\xee\xf1\xea\xe0\x20\xee\xf1\xf2\xe0\xe2\xf8\xe5\xe3\xee\xf1\xff\x20\xe2\xf0\xe5\xec\xe5\xed\xe8")
    PCS_settHint(u8"\xd2\xee\xed\xea\xe0\xff \xeb\xe8\xed\xe8\xff \xe2\xed\xe8\xe7\xf3 \xef\xeb\xe0\xf8\xea\xe8: \xef\xee\xea\xe0\xe7\xfb\xe2\xe0\xe5\xf2, \xf1\xea\xee\xeb\xfc\xea\xee \xee\xed\xe0 \xe5\xf9\xb8 \xe1\xf3\xe4\xe5\xf2 \xed\xe0 \xfd\xea\xf0\xe0\xed\xe5.")
    imgui.Spacing()

    if drawToggleSwitch("##toastPdRemSw", T.payday_remind ~= false) then
        T.payday_remind = not (T.payday_remind ~= false)
        changed()
    end
    imgui.SameLine(0, S(8))
