PCS_AD.loaded = PCS_AD.loaded or false
PCS_AD.sent  = PCS_AD.sent or 0

PCS_AD.WAIT_TTL      = 12
PCS_AD.WAIT_HARD_TTL = 25
PCS_AD.SEND_MIN_GAP  = 1.0
PCS_AD.ANSWER_DELAY  = 0.15

