    ["/al"] = { 0.70, 0.48, 1.00 }, ["/fam"] = { 0.30, 0.80, 0.50 }, ["/r"]  = { 0.35, 0.65, 0.95 },
    ["/rb"] = { 0.45, 0.62, 0.82 }, ["/f"]  = { 0.95, 0.78, 0.22 }, ["/fb"] = { 0.78, 0.66, 0.35 },
