    ["/r"] = "text", ["/rb"] = "text", ["/f"] = "shield", ["/fb"] = "shield", ["/g"] = "chart",
}
-- набор стикеров, по которому карточка переключается кликом
PCS_AD.STK_LIST = { "mega", "bell", "star", "money", "tag", "shield", "chart", "plane", "check", "clock", "list", "link" }

function PCS_AD.toGame(s)
    s = tostring(s or "")
    local ok, r = pcall(function() return _u8_raw:decode(s) end)
    if ok and type(r) == "string" then return r end
    return s
end

PCS_AD.MAX_SEND = 240
function PCS_AD.clampGame(s)
    s = tostring(s or "")
    if #s <= PCS_AD.MAX_SEND then return s, false end
    s = s:sub(1, PCS_AD.MAX_SEND)
    s = s:gsub(":u%x*$", "")
    s = s:gsub("%s+$", "")
    return s, true
end

function PCS_AD.fmt(sec)
    sec = math.max(0, math.floor(tonumber(sec) or 0))
    if sec >= 3600 then return string.format("%d:%02d:%02d", math.floor(sec / 3600), math.floor((sec % 3600) / 60), sec % 60) end
    return string.format("%d:%02d", math.floor(sec / 60), sec % 60)
end

function PCS_AD.cmdOf(ad)
    return PCS_AD.CHATS[(tonumber(ad.chatIdx) or 0) + 1] or "/vr"
end

function PCS_AD.stickerOf(ad)
    if ad.sticker and PCS_STICKER_COL and PCS_STICKER_COL[ad.sticker] then return ad.sticker end
    return PCS_AD.STK[PCS_AD.cmdOf(ad)] or "mega"
end

function PCS_AD.colOf(ad)
    return PCS_AD.COL[PCS_AD.cmdOf(ad)] or { 0.95, 0.55, 0.25 }
end

function PCS_AD.activeCount()
    local n = 0
    for _, ad in ipairs(PCS_AD.ads) do if ad.active then n = n + 1 end end
    return n
end

function PCS_AD.notify(text, kind)
    pcall(function() if pcs_notify then pcs_notify(text, kind or "info", 3) end end)
end

function PCS_AD.path() return CFG_DIR .. "/ads.json" end

function PCS_AD.esc(s)
    return (tostring(s or ""):gsub('[%c"\\]', function(c)
        if c == '"' then return '\\"' elseif c == "\\" then return "\\\\"
        elseif c == "\n" then return "\\n" elseif c == "\r" then return "\\r"
        elseif c == "\t" then return "\\t" end
        return ""
    end))
end

function PCS_AD._jstr(line, key)
    local _, e = line:find('"' .. key .. '"%s*:%s*"')
    if not e then return nil end
    local out, i, n = {}, e + 1, #line
    while i <= n do
        local c = line:sub(i, i)
        if c == '"' then break end
        if c == "\\" then
            local d = line:sub(i + 1, i + 1)
            if d == "n" then out[#out + 1] = "\n"
            elseif d == "t" then out[#out + 1] = "\t"
            elseif d == "r" then -- пропускаем
            else out[#out + 1] = d end
            i = i + 2
        else
            out[#out + 1] = c; i = i + 1
        end
    end
    return table.concat(out)
end

function PCS_AD.serialize()
    local parts = { string.format('{"saveDelay":%s,"v":2}', PCS_AD.cfg.saveDelay and "true" or "false") }
    for _, ad in ipairs(PCS_AD.ads) do
        parts[#parts + 1] = string.format(
            '{"text":"%s","sticker":"%s","interval":%d,"chatIdx":%d,"active":%s,"vrWithAd":%s,"radioIdx":%d,"vip":%s,"nextSend":%d,"lastSend":%d}',
            PCS_AD.esc(ad.text), PCS_AD.esc(ad.sticker or ""),
            math.max(5, math.floor(tonumber(ad.interval) or 300)),
            math.max(0, math.floor(tonumber(ad.chatIdx) or 0)),
            ad.active and "true" or "false",
            ad.vrWithAd and "true" or "false",
            math.max(0, math.floor(tonumber(ad.adRadioIdx) or 0)),
            ad.adVip and "true" or "false",
            math.max(0, math.floor(tonumber(ad.nextSend) or 0)),
            math.max(0, math.floor(tonumber(ad.lastSend) or 0)))
    end
    return table.concat(parts, "\n") .. "\n"
end

-- запись откладывается: UI может вызывать save() на каждый символ
function PCS_AD.save() PCS_AD._dirtyAt = os.clock() end

function PCS_AD.flush()
    if not PCS_AD._dirtyAt then return end
    PCS_AD._dirtyAt = nil
    pcall(function()
        pcall(function() if createDirectory then createDirectory(CFG_DIR) end end)
        local f = io.open(PCS_AD.path(), "wb")
        if f then f:write(PCS_AD.serialize()); f:close() end
    end)
end

function PCS_AD.load()
    PCS_AD.loaded = true
    PCS_AD.ads = {}
    local f = io.open(PCS_AD.path(), "rb")
    if not f then return end
    local body = f:read("*a") or ""
    f:close()
    if body == "" then return end
    PCS_AD.cfg.saveDelay = body:find('"saveDelay"%s*:%s*true') ~= nil
    local now = os.time()
    for line in (body .. "\n"):gmatch("(.-)\r?\n") do
        local text = PCS_AD._jstr(line, "text")
        if text then
            local ad = {
                text       = text,
                sticker    = PCS_AD._jstr(line, "sticker"),
                interval   = math.max(5, tonumber(line:match('"interval"%s*:%s*(%d+)')) or 300),
                chatIdx    = tonumber(line:match('"chatIdx"%s*:%s*(%d+)')) or 0,
                active     = line:find('"active"%s*:%s*true') ~= nil,
                vrWithAd   = line:find('"vrWithAd"%s*:%s*true') ~= nil,
                adRadioIdx = math.min(3, tonumber(line:match('"radioIdx"%s*:%s*(%d+)')) or 0),
                adVip      = line:find('"vip"%s*:%s*true') ~= nil,
                nextSend   = tonumber(line:match('"nextSend"%s*:%s*(%d+)')) or 0,
                lastSend   = tonumber(line:match('"lastSend"%s*:%s*(%d+)')) or 0,
            }
            if ad.sticker == "" then ad.sticker = nil end
            if ad.chatIdx >= #PCS_AD.CHATS then ad.chatIdx = 0 end
            -- "битый"/просроченный таймер -> заново
            if not PCS_AD.cfg.saveDelay or ad.nextSend < now - 86400 or ad.nextSend > now + 86400 * 7 then
                ad.nextSend = now + ad.interval
                ad.lastSend = now
            end
            PCS_AD.ads[#PCS_AD.ads + 1] = ad
        end
    end
end

function PCS_AD.busyOther()
    if _phoneOpBusy or _cefFetching or _phoneFetchState or _taxState ~= 0 then return true end
    if St._closePhoneRunning or St._taxDeferredPending then return true end
    if St._postPayUntil and os.clock() < St._postPayUntil then return true end
    if St._phoneCooldownUntil and os.time() < St._phoneCooldownUntil then return true end
    return false
end

function PCS_AD.send(ad)
    if PCS_AD.isMuted() then return false end
    if type(ad) ~= "table" then return false end
    local text = tostring(ad.text or ""):gsub("[\r\n]+", " "):gsub("^%s+", ""):gsub("%s+$", "")
    if text == "" then return false end
    if PCS_AD.busyOther() then return false end
    if PCS_AD.vrState.pending or PCS_AD.adState.pending then return false end

    local nowC = os.clock()
    if nowC - (PCS_AD._lastSendClock or 0) < PCS_AD.SEND_MIN_GAP then return false end

    local spawned = false
    pcall(function() if isPlayerActuallySpawned then spawned = isPlayerActuallySpawned() and true or false end end)
    if not spawned then return false end

    local cmd = PCS_AD.cmdOf(ad)
    local now = os.time()
    if cmd == "/vr" then
        PCS_AD.vrState.pending, PCS_AD.vrState.withAd, PCS_AD.vrState.t = true, ad.vrWithAd and true or false, now
    elseif cmd == "/ad" then
        local s = PCS_AD.adState
        s.pending, s.t, s.radio, s.vip, s.step = true, now, tonumber(ad.adRadioIdx) or 0, ad.adVip and true or false, 0
    end

    local gameText, clamped = PCS_AD.clampGame(PCS_AD.toGame(text))
    if gameText == "" then
        PCS_AD.vrState.pending = false
        PCS_AD.adState.pending = false
        return false
    end
    if clamped and os.clock() - (PCS_AD._lastClampNote or -999) > 60 then
        PCS_AD._lastClampNote = os.clock()
        pcall(PCS_AD.notify, u8"\xce\xe1\xfa\xff\xe2\xeb\xe5\xed\xe8\xe5\x20\xf1\xeb\xe8\xf8\xea\xee\xec\x20\xe4\xeb\xe8\xed\xed\xee\xe5\x20\x2d\x20\xee\xf2\xef\xf0\xe0\xe2\xeb\xe5\xed\xee\x20\xee\xe1\xf0\xe5\xe7\xe0\xed\xed\xfb\xec", "warn")
    end
    local ok = pcall(sampSendChat, cmd .. " " .. gameText)
    if not ok then
        PCS_AD.vrState.pending = false
        PCS_AD.adState.pending = false
        return false
    end
    PCS_AD._lastSendClock = nowC
    PCS_AD.sent = PCS_AD.sent + 1
    pcall(PCS_TR, "ad: sent " .. cmd)
    return true
end

function PCS_AD.toggle(ad)
    if type(ad) == "table" and not ad.active and PCS_AD.isMuted() then
        pcall(PCS_AD.notify, u8"\xc2\xee \xe2\xf0\xe5\xec\xff \xec\xf3\xf2\xe0 \xee\xe1\xfa\xff\xe2\xeb\xe5\xed\xe8\xff \xed\xe5 \xe7\xe0\xef\xf3\xf1\xea\xe0\xfe\xf2\xf1\xff", "warn")
        return
    end
    if type(ad) ~= "table" then return end
    ad.active = not ad.active
    local now = os.time()
    if ad.active then
        -- первая отправка сразу (если можно), дальше по интервалу
        if PCS_AD.send(ad) then ad.lastSend = now end
        ad.nextSend = now + (tonumber(ad.interval) or 300)
    end
    PCS_AD.save()
end

function PCS_AD.setAll(on)
    if on and PCS_AD.isMuted() then
        pcall(PCS_AD.notify, u8"\xc2\xee \xe2\xf0\xe5\xec\xff \xec\xf3\xf2\xe0 \xee\xe1\xfa\xff\xe2\xeb\xe5\xed\xe8\xff \xed\xe5 \xe7\xe0\xef\xf3\xf1\xea\xe0\xfe\xf2\xf1\xff", "warn")
        return
    end
    local now = os.time()
    for _, ad in ipairs(PCS_AD.ads) do
        if ad.active ~= on then
            ad.active = on
            if on then ad.nextSend = now + (tonumber(ad.interval) or 300) end
        end
    end
    PCS_AD.save()
end

function PCS_AD.newAd()
    local now = os.time()
    PCS_AD.ads[#PCS_AD.ads + 1] = {
        text = "", interval = 300, chatIdx = 0, active = false, vrWithAd = false,
        adRadioIdx = 0, adVip = false, nextSend = now + 300, lastSend = now,
    }
    PCS_AD.save()
end

function PCS_AD.watchdog()
    local now = os.time()
    if now - (PCS_AD._watchdogLast or 0) < 3 then return end
    PCS_AD._watchdogLast = now
    if PCS_AD.vrState.pending and now - PCS_AD.vrState.t > PCS_AD.WAIT_HARD_TTL then
        PCS_AD.vrState.pending = false
    end
    if PCS_AD.adState.pending and now - PCS_AD.adState.t > PCS_AD.WAIT_HARD_TTL then
        PCS_AD.adState.pending = false
        PCS_AD.adState.step = 0
    end
end

PCS_AD.muteUntil = PCS_AD.muteUntil or 0    -- os.time(), до которого действует мут
PCS_AD.muteSec   = PCS_AD.muteSec or 0      -- длительность последнего мута, сек
PCS_AD.muteSaved = PCS_AD.muteSaved or nil  -- номера объявлений, которые мут выключил
PCS_AD.muteLog   = PCS_AD.muteLog or nil    -- записи лога мутов (грузятся лениво)

function PCS_AD.isMuted()
    return (PCS_AD.muteUntil or 0) > os.time()
end

function PCS_AD.muteLogPath() return CFG_DIR .. "/mute_log.txt" end

function PCS_AD.loadMuteLog()
    if PCS_AD.muteLog then return end
    PCS_AD.muteLog = {}
    pcall(function()
        local f = io.open(PCS_AD.muteLogPath(), "r")
        if not f then return end
        for line in f:lines() do
            local t, sec, nick, reason = line:match("^(%d+)|(%d+)|([^|]*)|(.*)$")
            if t then
                table.insert(PCS_AD.muteLog, { t = tonumber(t), sec = tonumber(sec), nick = nick, reason = reason })
            end
        end
        f:close()
    end)
end

function PCS_AD.appendMuteLog(entry)
    PCS_AD.loadMuteLog()
    table.insert(PCS_AD.muteLog, entry)
    pcall(function()
        local f = io.open(PCS_AD.muteLogPath(), "a")
        if not f then return end
        local reason = tostring(entry.reason or ""):gsub("[\r\n|]", " ")
        f:write(string.format("%d|%d|%s|%s\n", entry.t, entry.sec, tostring(entry.nick or ""), reason))
        f:close()
    end)
end

-- слово целиком (чтобы ник "Ivan" не срабатывал внутри "Ivan_Petrov")
function PCS_AD._hasWord(s, w)
    if not w or w == "" then return false end
    local init = 1
    while true do
        local a, b = s:find(w, init, true)
        if not a then return false end
        local before = (a > 1) and s:sub(a - 1, a - 1) or " "
        local after = s:sub(b + 1, b + 1)
        if not before:match("[%w_]") and not after:match("[%w_]") then return true end
        init = a + 1
    end
end

-- разбор строки чата: мут НАШЕГО игрока -> { sec, reason, nick } или nil
function PCS_AD.parseMute(text)
    local clean = stripColor(tostring(text or ""))
    if clean == "" then return nil end
    local low = cp1251Lower(clean)
    if not (low:find("\xec\xf3\xf2", 1, true) or low:find("\xe7\xe0\xe3\xeb\xf3\xf8", 1, true)) then return nil end
    -- снятие мута — это не мут
    if low:find("\xf0\xe0\xe7\xec\xf3\xf2", 1, true) or low:find("\xf1\xed\xff\xeb", 1, true) or low:find("\xf1\xed\xff\xf2", 1, true) then return nil end
    local nick = PCS_getNick()
    if nick == "" then return nil end
    local nl = cp1251Lower(nick)
    if not (PCS_AD._hasWord(low, nl) or PCS_AD._hasWord(low, (nl:gsub("_", " ")))) then return nil end
    local secRaw = low:match("(%d+)%s*\xf1\xe5\xea")
    local sec = secRaw and tonumber(secRaw) or nil
    if not sec then
        local minRaw = low:match("(%d+)%s*\xec\xe8\xed")
        if minRaw then sec = tonumber(minRaw) * 60 end
    end
    if not sec or sec <= 0 then return nil end
    local reason = "\xed\xe5 \xf3\xea\xe0\xe7\xe0\xed\xe0"
    local _, e = low:find("\xef\xf0\xe8\xf7\xe8\xed[\xe0\xfb\xf3]?%s*:%s*")
    if e then
        local r = trim(clean:sub(e + 1))
        if r ~= "" then reason = r end
    end
    return { sec = sec, reason = reason, nick = nick }
end

function PCS_AD.startMute(sec, reason, nick)
    local now = os.time()
    local wasMuted = PCS_AD.isMuted()
    PCS_AD.muteUntil = now + sec
    PCS_AD.muteSec = sec
    if not wasMuted then
        -- запоминаем, какие объявления работали, и выключаем их на время мута
        PCS_AD.muteSaved = {}
        for i, ad in ipairs(PCS_AD.ads) do
            if ad.active then
                table.insert(PCS_AD.muteSaved, i)
                ad.active = false
            end
        end
    end
    PCS_AD.save()
    PCS_AD.appendMuteLog({ t = now, sec = sec, nick = nick, reason = reason })
    pcall(PCS_AD.notify, u8"\xcc\xf3\xf2: \xe0\xe2\xf2\xee-\xef\xe8\xe0\xf0 \xee\xf1\xf2\xe0\xed\xee\xe2\xeb\xe5\xed \xe4\xee \xea\xee\xed\xf6\xe0 \xec\xf3\xf2\xe0", "warn")
    pcall(sampAddChatMessage, "{FF6666}[PC Stats] " .. "\xcc\xf3\xf2 \xed\xe0 " .. tostring(sec) .. " \xf1\xe5\xea, \xe0\xe2\xf2\xee-\xef\xe8\xe0\xf0 \xee\xf1\xf2\xe0\xed\xee\xe2\xeb\xe5\xed. \xcf\xf0\xe8\xf7\xe8\xed\xe0: " .. tostring(reason), -1)
end

-- вызывается из sampev.onServerMessage для каждой строки чата
function PCS_AD.onServerMessage(text)
    local info = PCS_AD.parseMute(text)
    if info then PCS_AD.startMute(info.sec, info.reason, info.nick) end
end

-- каждый тик: когда мут закончился — снова запускаем объявления, которые мут выключил
function PCS_AD.muteTick()
    if PCS_AD.isMuted() then return end
    local saved = PCS_AD.muteSaved
    if not saved then return end
    PCS_AD.muteSaved = nil
    if #saved == 0 then return end
    local now = os.time()
    local resumed = 0
    for _, i in ipairs(saved) do
        local ad = PCS_AD.ads[i]
        if ad then
            ad.active = true
            ad.nextSend = now + 5
            resumed = resumed + 1
        end
    end
    PCS_AD.save()
    if resumed > 0 then
        pcall(PCS_AD.notify, u8"\xcc\xf3\xf2 \xe7\xe0\xea\xee\xed\xf7\xe8\xeb\xf1\xff \x97 \xe0\xe2\xf2\xee-\xef\xe8\xe0\xf0 \xf1\xed\xee\xe2\xe0 \xe7\xe0\xef\xf3\xf9\xe5\xed", "info")
    end
end

-- лог мутов для вкладки "Авто-пиар" (новые сверху)
function PCS_AD.drawMuteLog(avW)
    PCS_AD.loadMuteLog()
    local V2 = imgui.ImVec2
    imgui.Dummy(V2(0, S(10)))
    imgui.Separator()
    imgui.Dummy(V2(0, S(6)))
    imgui.TextColored(iv4(1.0, 0.55, 0.40, 1), u8"\xcb\xee\xe3\xe8 \xec\xf3\xf2\xee\xe2")
    local n = #PCS_AD.muteLog
    if n == 0 then
        imgui.TextColored(iv4(0.55, 0.55, 0.60, 1), u8"\xcc\xf3\xf2\xee\xe2 \xef\xee\xea\xe0 \xed\xe5 \xe1\xfb\xeb\xee. \xc7\xe0\xef\xe8\xf1\xe8 \xef\xee\xff\xe2\xff\xf2\xf1\xff, \xea\xee\xe3\xe4\xe0 \xe2\xe0\xec \xe2\xfb\xe4\xe0\xe4\xf3\xf2 \xec\xf3\xf2.")
        return
    end
    local shown = 0
    for i = n, 1, -1 do
        if shown >= 20 then break end
        local e = PCS_AD.muteLog[i]
        imgui.TextColored(iv4(1, 1, 1, 1), u8(os.date("%d.%m.%Y %H:%M", e.t) .. "  -  " .. tostring(e.sec) .. " \xf1\xe5\xea"))
        imgui.TextColored(iv4(0.75, 0.75, 0.82, 1), u8("\xcf\xf0\xe8\xf7\xe8\xed\xe0: " .. tostring(e.reason or "")))
        imgui.Dummy(V2(0, S(3)))
        shown = shown + 1
    end
end

function PCS_AD.tick()
    local ok, err = pcall(function()
        if not PCS_AD.loaded then PCS_AD.load() end
        PCS_AD.watchdog()
        PCS_AD.muteTick()
        if PCS_AD._dirtyAt and os.clock() - PCS_AD._dirtyAt > 1.0 then PCS_AD.flush() end
        if #PCS_AD.ads == 0 then return end

        local busyChat, busyDlg = false, false
        pcall(function() busyChat = sampIsChatInputActive and sampIsChatInputActive() end)
        pcall(function() busyDlg  = sampIsDialogActive and sampIsDialogActive() end)
        if busyChat or busyDlg then return end
        if PCS_AD.busyOther() then return end
        if PCS_AD.vrState.pending or PCS_AD.adState.pending then return end

        local now = os.time()
        for _, ad in ipairs(PCS_AD.ads) do
            if ad.active and (tonumber(ad.nextSend) or 0) <= now then
                if PCS_AD.send(ad) then
                    ad.lastSend = now
                    ad.nextSend = now + (tonumber(ad.interval) or 300)
                    PCS_AD.save()
                else
                    ad.nextSend = now + 15
                end
                break -- не больше одного объявления за тик
            end
        end
    end)
    if not ok then pcall(PCS_TR, "ad: tick error " .. tostring(err)) end
end

function PCS_AD._answerLater(id, button, listbox)
    PCS_AD._dlgSeq = PCS_AD._dlgSeq + 1
    local seq = PCS_AD._dlgSeq
    lua_thread.create(function()
        wait(math.floor(PCS_AD.ANSWER_DELAY * 1000))
        if seq ~= PCS_AD._dlgSeq then return end
        local ok = PCS_sendDialogIfId(id, button, listbox or 0, "")
        if not ok then pcall(PCS_TR, "ad: answer failed id=" .. tostring(id)) end
    end)
end

-- возвращает true, если диалог обработан (хук должен вернуть false)
function PCS_AD.onDialog(id, style, title, btn1, btn2, text)
    if not id then return false end
    if PCS_AD.busyOther() then return false end
    local now = os.time()

    if PCS_AD.vrState.pending then
        if now - PCS_AD.vrState.t > PCS_AD.WAIT_TTL then
            PCS_AD.vrState.pending = false
            return false
        end
        PCS_AD.vrState.pending = false
        PCS_AD._answerLater(id, PCS_AD.vrState.withAd and 1 or 0, 0)
        return true
    end

    if PCS_AD.adState.pending then
        local s = PCS_AD.adState
        if now - s.t > PCS_AD.WAIT_TTL then
            s.pending, s.step = false, 0
            return false
        end
        local t = tostring(title or "")
        local body = tostring(text or "")

        -- шаг 1: выбор радиостанции
        if t:find("\xc2\xfb\xe1\xe5\xf0\xe8\xf2\xe5 \xf0\xe0\xe4\xe8\xee\xf1\xf2\xe0\xed\xf6\xe8\xfe", 1, true) and body:find("\xd0\xe0\xe4\xe8\xee\xf1\xf2\xe0\xed\xf6\xe8\xff", 1, true) then
            local lines = {}
            for l in (body .. "\n"):gmatch("(.-)\n") do lines[#lines + 1] = l end
            local bestIdx, bestElapsed = 0, math.huge
            for i = 2, #lines do
                local line = lines[i]
                if s.radio > 0 then
                    local name = PCS_AD.RADIO[s.radio]
                    if name and line:find(name, 1, true) then bestIdx = i - 2; break end
                else
                    local h = tonumber(line:match("(%d+)%s*\xf7\xe0\xf1"))
                    local m = tonumber(line:match("(%d+)%s*\xec\xe8\xed"))
                    local sc = tonumber(line:match("(%d+)%s*\xf1\xe5\xea"))
                    if h or m or sc then
                        local el = (h or 0) * 3600 + (m or 0) * 60 + (sc or 0)
                        if el < bestElapsed then bestElapsed = el; bestIdx = i - 2 end
                    end
                end
            end
            s.t, s.step = now, 1
            PCS_AD._answerLater(id, 1, bestIdx)
            return true

        -- шаг 2: тип объявления
        elseif t:find("\xf2\xe8\xef \xee\xe1\xfa\xff\xe2\xeb\xe5\xed\xe8\xff", 1, true) then
            s.t, s.step = now, 2
            PCS_AD._answerLater(id, 1, s.vip and 1 or 0)
            return true

        -- шаг 3: подтверждение
        elseif t:find("\xcf\xee\xe4\xe0\xf7\xe0 \xee\xe1\xfa\xff\xe2\xeb\xe5\xed\xe8\xff", 1, true) and t:find("\xcf\xee\xe4\xf2\xe2\xe5\xf0\xe6\xe4\xe5\xed\xe8\xe5", 1, true) then
            s.pending, s.step = false, 0
            PCS_AD._answerLater(id, 1, 65535)
            return true
        end
    end
    return false
end

function PCS_AD.bufOf(ad)
    local B = PCS_AD.ui.bufs
    local b = B[ad]
    if not b then
        b = {
            text = imgui.new("char[501]"),
            interval = imgui.new("int[1]", math.max(5, tonumber(ad.interval) or 300)),
        }
        local t = tostring(ad.text or "")
        if #t > 500 then t = t:sub(1, 500) end
        ffi.copy(b.text, t)
        B[ad] = b
    end
    return b
end

function PCS_AD.round()
    local r = 12.0
    pcall(function() r = imgui.GetStyle().FrameRounding end)
    if type(r) ~= "number" or r < 6 then r = 12.0 end
    return r
end

-- сброс настроек вкладки: тексты объявлений остаются, всё остальное по умолчанию
function PCS_AD.resetSettings()
    local now = os.time()
    for _, ad in ipairs(PCS_AD.ads) do
        ad.active = false
        ad.interval = 300
        ad.chatIdx = 0
        ad.vrWithAd = false
        ad.adRadioIdx = 0
        ad.adVip = false
        ad.nextSend = now + 300
        PCS_AD.ui.bufs[ad] = nil
    end
    PCS_AD.cfg.saveDelay = false
    PCS_AD.save()
end

function PCS_AD.drawHeader(avW)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local h = S(74)
    local c = { 0.95, 0.55, 0.25 }
    dl:AddRectFilled(V2(p.x - 2, p.y - 2), V2(p.x + avW + 2, p.y + h + 2), U32(iv4(c[1], c[2], c[3], 0.10)), S(14))
    dl:AddRectFilled(p, V2(p.x + avW, p.y + h), U32(iv4(c[1] * 0.20, c[2] * 0.16, c[3] * 0.12, 0.96)), S(12))
    dl:AddRectFilled(p, V2(p.x + avW, p.y + h * 0.45), U32(iv4(1, 1, 1, 0.05)), S(12))
    dl:AddRect(p, V2(p.x + avW, p.y + h), U32(iv4(c[1], c[2], c[3], 0.70)), S(12), 0, 1.4)

    local ang, dy, sc = PCS_stickerAnim(false, 0.4)
    PCS_drawSticker(dl, "mega", p.x + S(40), p.y + h * 0.5 + dy, S(18) * sc, ang)
    -- маленькие стикеры-спутники
    local a2, d2, s2 = PCS_stickerAnim(false, 1.7)
    PCS_drawSticker(dl, "star", p.x + S(78), p.y + S(20) + d2, S(7) * s2, a2 + 0.25)
    local a3, d3, s3 = PCS_stickerAnim(false, 2.9)
    PCS_drawSticker(dl, "plane", p.x + S(80), p.y + h - S(18) + d3, S(7) * s3, a3 - 0.15)

    local tx = p.x + S(98)
    local pushed = false
    if PCS_BOLD_FONT then pushed = pcall(imgui.PushFont, PCS_BOLD_FONT) end
    dl:AddText(V2(tx, p.y + S(12)), U32(iv4(1, 1, 1, 1)), u8"\xc0\xe2\xf2\xee-\xef\xe8\xe0\xf0")
    if pushed then pcall(imgui.PopFont) end
    dl:AddText(V2(tx, p.y + S(34)), U32(iv4(0.95, 0.80, 0.62, 0.95)), u8"\xce\xe1\xfa\xff\xe2\xeb\xe5\xed\xe8\xff \xe2 \xf7\xe0\xf2 \xef\xee \xf2\xe0\xe9\xec\xe5\xf0\xf3")

    -- чипы статистики справа
    local nAct = PCS_AD.activeCount()
    local function chip(x, label, col)
        local ts = imgui.CalcTextSize(label)
        local w = ts.x + S(18)
        local y0 = p.y + h - S(26)
        dl:AddRectFilled(V2(x, y0), V2(x + w, y0 + S(19)), U32(iv4(col[1] * 0.45, col[2] * 0.45, col[3] * 0.45, 0.95)), S(9))
        dl:AddRect(V2(x, y0), V2(x + w, y0 + S(19)), U32(iv4(col[1], col[2], col[3], 0.85)), S(9), 0, 1.0)
        dl:AddText(V2(x + S(9), y0 + (S(19) - ts.y) * 0.5), U32(iv4(1, 1, 1, 1)), label)
        return x + w + S(6)
    end
    local x = tx
    x = chip(x, u8"\xc0\xea\xf2\xe8\xe2\xed\xfb\xf5: " .. nAct, nAct > 0 and { 0.30, 0.80, 0.45 } or { 0.50, 0.55, 0.65 })
    x = chip(x, u8"\xc2\xf1\xe5\xe3\xee: " .. #PCS_AD.ads, { 0.35, 0.65, 0.95 })
    chip(x, u8"\xce\xf2\xef\xf0\xe0\xe2\xeb\xe5\xed\xee: " .. PCS_AD.sent, { 0.95, 0.70, 0.20 })

    imgui.SetCursorScreenPos(V2(p.x, p.y + h + S(8)))
    imgui.Dummy(V2(avW, 1))
end

-- карточка одного объявления
function PCS_AD.drawCard(idx, ad, avW)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local stkExtra = 0
    if PCS_STICK.enabled then
        local okT, nT = pcall(PCS_STICK.countTokens, ad.text)
        if okT and (nT or 0) > 0 then stkExtra = S(30) end
    end
    local cardH = S(168) + stkExtra
    local col = PCS_AD.colOf(ad)
    local cr, cg, cb = col[1], col[2], col[3]
    local cmd = PCS_AD.cmdOf(ad)
    local buf = PCS_AD.bufOf(ad)
    local now = os.time()
    local active = ad.active and true or false

    -- фон, свечение и рамка
    if active then
        dl:AddRectFilled(V2(p.x - 2, p.y - 2), V2(p.x + avW + 2, p.y + cardH + 2), U32(iv4(cr, cg, cb, 0.14)), S(13))
    end
    local k = active and 0.20 or 0.11
    dl:AddRectFilled(p, V2(p.x + avW, p.y + cardH), U32(iv4(cr * k, cg * k, cb * k + 0.02, pcsRowA(0.96))), S(11))
    dl:AddRectFilled(p, V2(p.x + avW, p.y + S(46)), U32(iv4(1, 1, 1, 0.04)), S(11))
    dl:AddRect(p, V2(p.x + avW, p.y + cardH), U32(iv4(cr, cg, cb, active and 0.85 or 0.40)), S(11), 0, active and 1.6 or 1.2)
    dl:AddRectFilled(V2(p.x + 1, p.y + S(10)), V2(p.x + 4, p.y + cardH - S(10)), U32(iv4(cr, cg, cb, active and 1.0 or 0.45)), 2)

    -- стикер (клик - сменить)
    imgui.SetCursorScreenPos(V2(p.x + S(12), p.y + S(9)))
    if imgui.InvisibleButton("##adStk" .. idx, V2(S(42), S(42))) then
        local cur = PCS_AD.stickerOf(ad)
        local ni = 1
        for i, nm in ipairs(PCS_AD.STK_LIST) do if nm == cur then ni = i % #PCS_AD.STK_LIST + 1; break end end
        ad.sticker = PCS_AD.STK_LIST[ni]
        PCS_AD.save()
    end
    local hovS = imgui.IsItemHovered()
    local ang, dy, sc = PCS_stickerAnim(hovS, idx * 0.9)
    if active then sc = sc * 1.04 end
    PCS_drawSticker(dl, PCS_AD.stickerOf(ad), p.x + S(33), p.y + S(30) + dy, S(14.5) * sc, ang)
    if hovS then
        pcall(function()
            imgui.BeginTooltip()
            imgui.TextColored(thDim(), u8"\xca\xeb\xe8\xea - \xf1\xec\xe5\xed\xe8\xf2\xfc \xf1\xf2\xe8\xea\xe5\xf0")
            imgui.EndTooltip()
        end)
    end

    -- заголовок и статус
    local tx = p.x + S(66)
    local pushed = false
    if PCS_BOLD_FONT then pushed = pcall(imgui.PushFont, PCS_BOLD_FONT) end
    dl:AddText(V2(tx, p.y + S(9)), U32(iv4(1, 1, 1, 1)), u8"\xce\xe1\xfa\xff\xe2\xeb\xe5\xed\xe8\xe5 " .. "#" .. idx)
    if pushed then pcall(imgui.PopFont) end

    local ts = imgui.CalcTextSize(cmd)
    dl:AddRectFilled(V2(tx, p.y + S(29)), V2(tx + ts.x + S(14), p.y + S(47)), U32(iv4(cr * 0.5, cg * 0.5, cb * 0.5, 0.95)), S(8))
    dl:AddText(V2(tx + S(7), p.y + S(29) + (S(18) - ts.y) * 0.5), U32(iv4(1, 1, 1, 1)), cmd)

    local stText, stCol
    if active then
        local left = math.max(0, (tonumber(ad.nextSend) or now) - now)
        local waiting = (PCS_AD.vrState.pending or PCS_AD.adState.pending)
        stText = waiting and u8"\xe6\xe4\xb8\xec \xe4\xe8\xe0\xeb\xee\xe3..." or (u8"\xf7\xe5\xf0\xe5\xe7 " .. PCS_AD.fmt(left))
        stCol = { 0.45, 0.92, 0.55 }
    else
        stText = u8"\xe2\xfb\xea\xeb\xfe\xf7\xe5\xed\xee"
        stCol = { 0.60, 0.64, 0.72 }
    end
    dl:AddText(V2(tx + ts.x + S(22), p.y + S(29) + (S(18) - ts.y) * 0.5), U32(iv4(stCol[1], stCol[2], stCol[3], 1)), stText)

    -- переключатель вкл/выкл
    imgui.SetCursorScreenPos(V2(p.x + avW - S(48), p.y + S(16)))
    if drawToggleSwitch("##adTog" .. idx, active) then PCS_AD.toggle(ad) end

    -- полоса прогресса до следующей отправки
    local barX, barY, barW = p.x + S(14), p.y + S(56), avW - S(28)
    dl:AddRectFilled(V2(barX, barY), V2(barX + barW, barY + S(4)), U32(iv4(0, 0, 0, 0.35)), 2)
    if active then
        local iv = math.max(5, tonumber(ad.interval) or 300)
        local left = math.max(0, (tonumber(ad.nextSend) or now) - now)
        local frac = math.max(0, math.min(1, 1 - left / iv))
        if frac > 0 then
            dl:AddRectFilled(V2(barX, barY), V2(barX + barW * frac, barY + S(4)), U32(iv4(cr, cg, cb, 0.95)), 2)
        end
    end

    -- текст объявления
    imgui.SetCursorScreenPos(V2(p.x + S(14), p.y + S(68)))
    imgui.PushItemWidth(avW - S(28))
    local ch = PCS_input("##adTxt" .. idx, buf.text, 501, u8"\xd2\xe5\xea\xf1\xf2 \xee\xe1\xfa\xff\xe2\xeb\xe5\xed\xe8\xff...", PCS_AD.stickerOf(ad),
        { w = avW - S(28), counter = true, phase = idx * 0.6 })
    imgui.PopItemWidth()
    if ch then
        ad.text = ffi.string(buf.text)
        PCS_AD.save()
    end

    -- смайлы из текста картинками (под полем текста)
    if stkExtra > 0 then
        PCS_UI("ui:stk preview")
        local okPv, errPv = PCS_GUARD.call(PCS_STICK.preview, dl, ad.text, p.x + S(14), p.y + S(112), avW - S(28))
        if not okPv then PCS_quietErr("stickers preview", errPv) end
    end

    -- нижний ряд: команда, интервал, опции, кнопки
    local rowY = p.y + S(118) + stkExtra
    imgui.SetCursorScreenPos(V2(p.x + S(14), rowY))
    local popId = "##adCmdPop" .. idx
    if PCS_gdButton(cmd .. "  v##adCmd" .. idx, S(78), S(34), col, PCS_AD.round()) then
        imgui.OpenPopup(popId)
    end
    if imgui.BeginPopup(popId) then
        for ci, nm in ipairs(PCS_AD.CHATS) do
            if imgui.Selectable(nm .. "##adCmdSel" .. idx .. "_" .. ci, (ad.chatIdx or 0) == ci - 1) then
                ad.chatIdx = ci - 1
                PCS_AD.save()
            end
        end
        imgui.EndPopup()
    end

    imgui.SameLine(0, S(8))
    imgui.PushItemWidth(S(104))
    PCS_pushInput(S(7), S(8))
    buf.interval[0] = math.max(5, tonumber(ad.interval) or 300)
    if imgui.InputInt("##adInt" .. idx, buf.interval, 5, 60) then
        ad.interval = math.max(5, math.min(86400, buf.interval[0]))
        ad.nextSend = os.time() + ad.interval
        PCS_AD.save()
    end
    PCS_popInput()
    imgui.PopItemWidth()
    if imgui.IsItemHovered() then
        pcall(function()
            imgui.BeginTooltip()
            imgui.TextColored(thDim(), u8"\xc8\xed\xf2\xe5\xf0\xe2\xe0\xeb, \xf1\xe5\xea\xf3\xed\xe4")
            imgui.EndTooltip()
        end)
    end

    -- опции команды
    imgui.SameLine(0, S(10))
    if cmd == "/vr" then
        imgui.AlignTextToFramePadding()
        if drawToggleSwitch("##adVr" .. idx, ad.vrWithAd == true) then
            ad.vrWithAd = not (ad.vrWithAd == true); PCS_AD.save()
        end
        imgui.SameLine(0, S(5))
        imgui.AlignTextToFramePadding()
        imgui.TextColored(thDim(), u8"\xf1 \xf0\xe5\xea\xeb.")
    elseif cmd == "/ad" then
        local rl = { [0] = u8"\xc0\xe2\xf2\xee", [1] = "LS", [2] = "LV", [3] = "SF" }
        if PCS_gdButton(PCS_IC.headset .. "  " .. u8"\xd0\xe0\xe4\xe8\xee: " .. rl[tonumber(ad.adRadioIdx) or 0] .. "##adRad" .. idx, S(78), S(34), { 0.35, 0.65, 0.95 }, PCS_AD.round()) then
            ad.adRadioIdx = ((tonumber(ad.adRadioIdx) or 0) + 1) % 4
            PCS_AD.save()
        end
        imgui.SameLine(0, S(6))
        if PCS_gdButton(PCS_IC.star .. "  " .. "VIP##adVip" .. idx, S(44), S(34), ad.adVip and { 0.95, 0.75, 0.20 } or { 0.45, 0.48, 0.55 }, PCS_AD.round()) then
            ad.adVip = not (ad.adVip == true); PCS_AD.save()
        end
    end

    -- кнопка смайлов: маленькое меню, смайл вставляется в текст объявления (без текстур)
    if PCS_STICK.enabled then
        PCS_UI("ui:stk btn")
        local stkX = p.x + avW - S(14) - S(40) * 2 - S(6) - S(40) - S(6)
        imgui.SetCursorScreenPos(V2(stkX, rowY))
        PCS_AD.ui.stkOpen = PCS_AD.ui.stkOpen or {}
        if PCS_gdButton("##adStkBtn" .. idx, S(40), S(34), { 0.95, 0.70, 0.25 }, PCS_AD.round()) then
            PCS_AD.ui.stkOpen[ad] = true
            imgui.OpenPopup("##stkPop" .. idx)
        end
        local okIc, errIc = PCS_GUARD.call(PCS_drawSticker, dl, "star", stkX + S(20), rowY + S(17), S(11), 0)
        if not okIc then PCS_STICK.fail("icon", errIc) end
        if imgui.IsItemHovered() then
            imgui.BeginTooltip()
            imgui.TextColored(thDim(), u8"\xd1\xec\xe0\xe9\xeb\xfb")
            imgui.EndTooltip()
        end
        -- смайлы — всплывающее меню под кнопкой (imgui-попап, а не встроенный блок)
        local ds = imgui.GetIO().DisplaySize
        local popW, popH = S(460), S(440)
        local popX = math.max(S(8), math.min(stkX - popW + S(40), ds.x - popW - S(8)))
        local popY = math.max(S(8), math.min(rowY + S(42), ds.y - popH - S(8)))
        imgui.SetNextWindowPos(V2(popX, popY), imgui.Cond.Appearing)
        imgui.SetNextWindowSize(V2(popW, popH), imgui.Cond.Appearing)
        local stylesN = pushModernPopupStyle()
        if imgui.BeginPopup("##stkPop" .. idx) then
            PCS_UI("stk popup begin")
            local okP, res = PCS_GUARD.call(PCS_STICK.popupBody, ad, buf)
            if not okP then PCS_STICK.fail("popup", res) end
            if (okP and res) or PCS_gdButton(u8"\xc7\xe0\xea\xf0\xfb\xf2\xfc##stkClose" .. idx, S(120), S(30), { 0.45, 0.48, 0.55 }, 8.0) then
                imgui.CloseCurrentPopup()
                PCS_AD.ui.stkOpen[ad] = nil
            end
            imgui.EndPopup()
            PCS_UI("stk popup end")
        else
            PCS_AD.ui.stkOpen[ad] = nil
        end
        popModernPopupStyle(stylesN)
    end

    -- кнопки справа: отправить сейчас, удалить
    imgui.SetCursorScreenPos(V2(p.x + avW - S(14) - S(40) * 2 - S(6), rowY))
    if PCS_gdButton("##adNow" .. idx, S(40), S(34), { 0.30, 0.78, 0.45 }, PCS_AD.round()) then
        if PCS_AD.send(ad) then
            ad.lastSend = os.time()
            if ad.active then ad.nextSend = ad.lastSend + (tonumber(ad.interval) or 300) end
            PCS_AD.save()
        else
            PCS_AD.notify(u8"\xcd\xe5 \xf3\xe4\xe0\xeb\xee\xf1\xfc \xee\xf2\xef\xf0\xe0\xe2\xe8\xf2\xfc: \xf7\xe0\xf2/\xe4\xe8\xe0\xeb\xee\xe3/\xf2\xe5\xeb\xe5\xf4\xee\xed \xe7\xe0\xed\xff\xf2\xfb", "warn")
        end
    end
    PCS_stickerCenterOnLastItem("plane", idx * 0.7)
    if imgui.IsItemHovered() then
        pcall(function()
            imgui.BeginTooltip()
            imgui.TextColored(thDim(), u8"\xce\xf2\xef\xf0\xe0\xe2\xe8\xf2\xfc \xf1\xe5\xe9\xf7\xe0\xf1")
            imgui.EndTooltip()
        end)
    end
    imgui.SameLine(0, S(6))
    local del = false
    if PCS_gdButton("##adDel" .. idx, S(40), S(34), { 0.92, 0.30, 0.30 }, PCS_AD.round()) then del = true end
    PCS_stickerCenterOnLastItem("trash", idx * 0.5)

    imgui.SetCursorScreenPos(V2(p.x, p.y + cardH + S(8)))
    imgui.Dummy(V2(avW, 1))
    return del
end

function PCS_AD.drawEmpty(avW)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local h = S(120)
    dl:AddRectFilled(p, V2(p.x + avW, p.y + h), U32(iv4(0.12, 0.10, 0.08, 0.80)), S(12))
    dl:AddRect(p, V2(p.x + avW, p.y + h), U32(iv4(0.95, 0.55, 0.25, 0.40)), S(12), 0, 1.2)
    local ang, dy, sc = PCS_stickerAnim(false, 0.9)
    PCS_drawSticker(dl, "mega", p.x + avW * 0.5, p.y + S(42) + dy, S(18) * sc, ang)
    local t1 = u8"\xcf\xee\xea\xe0 \xed\xe5\xf2 \xee\xe1\xfa\xff\xe2\xeb\xe5\xed\xe8\xe9"
    local t2 = u8"\xcd\xe0\xe6\xec\xe8\xf2\xe5 \xab\xcd\xee\xe2\xee\xe5 \xee\xe1\xfa\xff\xe2\xeb\xe5\xed\xe8\xe5\xbb, \xf7\xf2\xee\xe1\xfb \xed\xe0\xf7\xe0\xf2\xfc"
    local s1, s2 = imgui.CalcTextSize(t1), imgui.CalcTextSize(t2)
    dl:AddText(V2(p.x + (avW - s1.x) * 0.5, p.y + S(76)), U32(iv4(1, 1, 1, 1)), t1)
    dl:AddText(V2(p.x + (avW - s2.x) * 0.5, p.y + S(76) + s1.y + S(2)), U32(iv4(0.65, 0.68, 0.76, 0.95)), t2)
    imgui.SetCursorScreenPos(V2(p.x, p.y + h + S(8)))
    imgui.Dummy(V2(avW, 1))
end

-- содержимое вкладки (без собственного child: можно вставлять куда угодно)
function PCS_AD.drawBody()
    if not PCS_AD.loaded then PCS_AD.load() end
    local V2 = imgui.ImVec2
    local avW = imgui.GetContentRegionAvail().x
    PCS_AD.drawHeader(avW)

    -- кнопки управления
    local gap = S(6)
    local bw = math.floor((avW - gap * 2) / 3)
    if PCS_gdButton(u8"\xcd\xee\xe2\xee\xe5" .. "##adNew", bw, S(36), { 0.30, 0.78, 0.45 }, PCS_AD.round()) then PCS_AD.newAd() end
    PCS_btnSticker("plus", 0.3, "left")
    imgui.SameLine(0, gap)
    if PCS_gdButton(u8"\xd1\xf2\xe0\xf0\xf2 \xe2\xf1\xe5" .. "##adAllOn", bw, S(36), { 0.30, 0.65, 0.95 }, PCS_AD.round()) then PCS_AD.setAll(true) end
    PCS_btnSticker("check", 0.9, "left")
    imgui.SameLine(0, gap)
    if PCS_gdButton(u8"\xd1\xf2\xee\xef \xe2\xf1\xe5" .. "##adAllOff", bw, S(36), { 0.92, 0.35, 0.35 }, PCS_AD.round()) then PCS_AD.setAll(false) end
    PCS_btnSticker("power", 1.5, "left")
    imgui.Dummy(V2(0, S(6)))

    if drawToggleSwitch("##adSaveDelay", PCS_AD.cfg.saveDelay == true) then
        PCS_AD.cfg.saveDelay = not (PCS_AD.cfg.saveDelay == true)
        PCS_AD.save()
    end
    imgui.SameLine(0, S(8))
    imgui.AlignTextToFramePadding()
    imgui.TextColored(iv4(1, 1, 1, 1), u8"\xcd\xe5 \xf1\xe1\xf0\xe0\xf1\xfb\xe2\xe0\xf2\xfc \xf2\xe0\xe9\xec\xe5\xf0 \xef\xf0\xe8 \xef\xe5\xf0\xe5\xe7\xe0\xf5\xee\xe4\xe5")
    imgui.Dummy(V2(0, S(8)))

    if PCS_AD.isMuted() then
        imgui.TextColored(iv4(1.0, 0.45, 0.35, 1), u8"\xcc\xf3\xf2: \xe0\xe2\xf2\xee-\xef\xe8\xe0\xf0 \xed\xe0 \xef\xe0\xf3\xe7\xe5, \xe4\xee \xea\xee\xed\xf6\xe0 \xec\xf3\xf2\xe0 \xee\xf1\xf2\xe0\xeb\xee\xf1\xfc " .. PCS_AD.fmt((PCS_AD.muteUntil or 0) - os.time()))
        imgui.Dummy(V2(0, S(6)))
    end
    if #PCS_AD.ads == 0 then
        PCS_AD.drawEmpty(avW)
    else
        local delIdx
        for i, ad in ipairs(PCS_AD.ads) do
            if PCS_AD.drawCard(i, ad, avW) then delIdx = i end
        end
        if delIdx then
            local gone = table.remove(PCS_AD.ads, delIdx)
            if gone then PCS_AD.ui.bufs[gone] = nil end
            PCS_AD.save()
        end
    end
    imgui.Dummy(V2(0, S(14)))
    PCS_AD.drawMuteLog(avW)
end

-- отдельная вкладка (St.activeTab == 9)
function PCS_AD.draw(contentH)
    imgui.PushStyleColor(imgui.Col.ChildBg, iv4(0, 0, 0, 0))
    imgui.BeginChild("##adTab", imgui.ImVec2(0, contentH), false)
    local ok, err = PCS_GUARD.call(PCS_AD.drawBody)
    imgui.EndChild()
    imgui.PopStyleColor()
    if not ok then
        PCS_quietErr("autoad ui", err)
    end
end

