-- разбирает список смайлов; вызывается один раз
function PCS_STICK.build()
    local st = PCS_STICK
    if st.list then return end
    local list, cats = {}, {}
    st.byToken = {}
    for c = 1, #st.CATS do
        cats[c] = { name = st.CATS[c], items = {} }
    end
    for line in st.DATA:gmatch("[^\n]+") do
        local f, pos = {}, 1
        while true do
            local s = line:find("\t", pos, true)
            if not s then
                f[#f + 1] = line:sub(pos)
                break
            end
            f[#f + 1] = line:sub(pos, s - 1)
            pos = s + 1
        end
        local cp = tonumber(f[2]) or 0
        local e = {
            name = f[1],
            token = string.format(":u%x:", cp),
            slot = tonumber(f[4]) or 0,
            cells = tonumber(f[5]) or 1,
            search = (f[1] .. " " .. (f[6] or "")):lower(),
        }
        list[#list + 1] = e
        st.byToken[e.token] = e
        local cat = cats[tonumber(f[3]) or 1]
        if cat then cat.items[#cat.items + 1] = e end
    end
    st.list = list
    st.cats = cats
end

function PCS_STICK.init()
    local st = PCS_STICK
    if st.inited then return st.enabled end
    st.inited = true
    st.enabled = false
    if not PCS_STICK_ENABLED then return false end
    local ok, err = pcall(function()
        PCS_STICK.build()
        if #st.list ~= 1584 then error("bad sticker count " .. #st.list) end
        for _, e in ipairs(st.list) do
            if e.slot < 0 or math.floor(e.slot / 51) >= 51 or e.cells < 1 or e.cells > 8 then
                error("bad sticker slot " .. tostring(e.slot))
            end
        end
    end)
    if ok then
        st.enabled = true
    else
        st.err = tostring(err)
        print("[PC Stats] stickers disabled: " .. st.err)
    end
    return st.enabled
end

function PCS_STICK.loadTex()
    if PCS_TEX_DEAD_SESSION then return end
    local st = PCS_STICK
    if st.tex or st.texFailed then return end
    if PCS_DIAG_NO_TEX or PCS_STICK_NO_TEX then st.texFailed = true; return end
    if not imgui or not imgui.CreateTextureFromFileInMemory or not st.PNG then
        st.texFailed = true
        return
    end
    local okD, raw = pcall(b64decode, st.PNG)
    if not okD or type(raw) ~= "string" or #raw < 100 then
        st.texFailed = true
        print("[PC Stats] stickers: atlas decode failed")
        return
    end
    local okT, tex = pcall(imgui.CreateTextureFromFileInMemory, raw, #raw)
    if not okT or not tex then
        st.texFailed = true
        print("[PC Stats] stickers: texture failed: " .. tostring(tex))
        return
    end
    st.tex = tex -- ссылку не отпускаем: текстуру не освобождаем
end

-- UV прямоугольника смайла в атласе: ячейка 40 px, 51 колонка, 2048 px
function PCS_STICK.uv(e)
    local k = 40 / 2048
    local c = e.slot % 51
    local r = math.floor(e.slot / 51)
    return c * k, r * k, (c + e.cells) * k, (r + 1) * k
end

-- рисует смайл картинкой в прямоугольнике; false если картинки нет
function PCS_STICK.drawIcon(dl, e, x0, y0, x1, y1)
    if PCS_texQuiet() then return false end
    local st = PCS_STICK
    if PCS_DIAG_NO_TEX or PCS_STICK_NO_TEX then return false end
    local tex = st.tex
    if not tex or st.texBroken then return false end
    local V2 = imgui.ImVec2
    local u0, v0, u1, v1 = PCS_STICK.uv(e)
    dl:AddImage(tex, V2(x0, y0), V2(x1, y1), V2(u0, v0), V2(u1, v1),
        imgui.ColorConvertFloat4ToU32(iv4(1, 1, 1, 1)))
    return true
end

-- подсчёт смайлов в тексте объявления
function PCS_STICK.countTokens(text)
    local n = 0
    for _ in tostring(text or ""):gmatch(":u%x+:") do n = n + 1 end
    return n
end

-- строка под текстом объявления: смайлы из текста картинками (после вставки)
function PCS_STICK.preview(dl, text, x0, y0, maxW)
    local st = PCS_STICK
    if not st.enabled or not st.byToken then return end
    local list = {}
    for tok in tostring(text or ""):gmatch(":u%x+:") do
        local e = st.byToken[tok:lower()]
        if e then list[#list + 1] = e end
    end
    local cell = S(26)
    local x = x0
    local h = S(26)
    for i, e in ipairs(list) do
        local w = e.cells * cell
        if x + w - x0 > maxW then
            local left = #list - i + 1
            dl:AddText(imgui.ImVec2(x, y0 + S(2)), imgui.ColorConvertFloat4ToU32(iv4(0.62, 0.66, 0.74, 1)),
                "+" .. tostring(left))
            break
        end
        local okD, drawn = pcall(PCS_STICK.drawIcon, dl, e, x, y0, x + w, y0 + h)
        if not okD then
            drawn = false
            PCS_STICK.texBroken = true
            PCS_STICK.reloadAt = os.clock() + 5
        end
        if not drawn then
            dl:AddText(imgui.ImVec2(x, y0 + S(2)), imgui.ColorConvertFloat4ToU32(iv4(1, 0.80, 0.25, 1)), e.name)
            w = imgui.CalcTextSize(e.name).x
        end
        x = x + w + S(4)
    end
end

function PCS_STICK.fail(tag, err)
    local st = PCS_STICK
    st.fails = (st.fails or 0) + 1
    PCS_quietErr("stickers " .. tag, err)
    if st.fails >= 3 and st.enabled then
        st.enabled = false
        pcall(PCS_AD.notify, u8"\xd1\xec\xe0\xe9\xeb\xfb\x20\xee\xf2\xea\xeb\xfe\xf7\xe5\xed\xfb\x20\xe8\xe7\x2d\xe7\xe0\x20\xee\xf8\xe8\xe1\xee\xea", "warn")
    end
end

-- вставка кода смайла в конец текста объявления (буфер char[501], как в PCS_AD.bufOf)
function PCS_STICK.insert(ad, buf, token)
    local cur = ffi.string(buf.text)
    if cur ~= "" and not cur:find("%s$") then cur = cur .. " " end
    local new = cur .. token
    if #new > 500 then
        PCS_AD.notify(u8"\xd2\xe5\xea\xf1\xf2\x20\xee\xe1\xfa\xff\xe2\xeb\xe5\xed\xe8\xff\x20\xf1\xeb\xe8\xf8\xea\xee\xec\x20\xe4\xeb\xe8\xed\xed\xfb\xe9", "warn")
        return false
    end
    ffi.copy(buf.text, new)
    ad.text = new
    PCS_AD.save()
    return true
end

-- сетка по категориям: смайл картинкой (клик вставляет код); без картинки — текст
function PCS_STICK.grid(q, onPick)
    local st = PCS_STICK
    -- после сброса устройства текстуру пересоздаём (не чаще раза в 5 с, до 3 раз)
    if st.texBroken and not PCS_TEX_NO_RECREATE and (st.reloads or 0) < 3 and st.reloadAt and os.clock() >= st.reloadAt then
        st.reloads = (st.reloads or 0) + 1
        st.tex, st.texFailed, st.texBroken, st.reloadAt = nil, false, false, nil
        pcall(PCS_STICK.loadTex)
    end
    -- ленивое создание атласа: один раз, уже в кадре, когда игра отрисовывает
    if not st.tex and not st.texFailed and not PCS_texQuiet() and not PCS_TEX_NO_RECREATE then
        pcall(PCS_STICK.loadTex)
    end
    local U32 = imgui.ColorConvertFloat4ToU32
    local spacing = imgui.GetStyle().ItemSpacing.x
    local avail = imgui.GetContentRegionAvail().x
    local useImg = st.tex and not st.texBroken
    local cellPx = S(38)
    local h = useImg and cellPx or S(22)
    local any = false
    for _, cat in ipairs(st.cats) do
        local shown = {}
        for _, e in ipairs(cat.items) do
            if q == "" or e.search:find(q, 1, true) then shown[#shown + 1] = e end
        end
        if #shown > 0 then
            any = true
            imgui.TextColored(iv4(0.55, 0.78, 1.00, 1), cat.name)
            imgui.Separator()
            local x = 0
            for _, e in ipairs(shown) do
                local w
                if useImg then
                    w = e.cells * cellPx + S(6)
                else
                    w = math.max(imgui.CalcTextSize(e.name).x + 14, 40)
                end
                if x > 0 then
                    if x + spacing + w <= avail then
                        imgui.SameLine()
                        x = x + spacing
                    else
                        x = 0
                    end
                end
                local clicked
                if useImg then
                    clicked = imgui.InvisibleButton("##stk" .. e.slot, imgui.ImVec2(w, h))
                    local mn, mx = imgui.GetItemRectMin(), imgui.GetItemRectMax()
                    local dl = imgui.GetWindowDrawList()
                    dl:AddRectFilled(mn, mx, U32(iv4(0.16, 0.19, 0.26, 0.85)), S(7))
                    if imgui.IsItemHovered() then
                        dl:AddRectFilled(mn, mx, U32(iv4(1, 1, 1, 0.16)), S(7))
                    end
                    local okD, drawn = PCS_GUARD.call(PCS_STICK.drawIcon, dl, e, mn.x + S(3), mn.y + S(3), mx.x - S(3), mx.y - S(3))
                    if not okD then
                        -- мёртвая текстура (сброс устройства): дальше только текст
                        st.texBroken = true
                        st.reloadAt = os.clock() + 5
                        PCS_quietErr("stickers draw", drawn)
                        drawn = false
                    end
                    if not drawn then
                        dl:AddText(imgui.ImVec2(mn.x + S(4), mn.y + S(3)), U32(iv4(1, 0.80, 0.25, 1)), e.name)
                    end
                else
                    clicked = imgui.Button(e.name .. "##stk" .. e.slot, imgui.ImVec2(w, h))
                end
                if clicked then
                    onPick(e)
                end
                if imgui.IsItemHovered() then
                    imgui.SetTooltip(e.name .. "  " .. e.token)
                end
                x = x + w
            end
            imgui.Spacing()
        end
    end
    if not any then
        imgui.TextColored(iv4(0.62, 0.66, 0.74, 1), u8"\xcd\xe8\xf7\xe5\xe3\xee\x20\xed\xe5\x20\xed\xe0\xe9\xe4\xe5\xed\xee")
    end
end

PCS_STICK_POP_SEARCH = false
function PCS_STICK.popupBody(ad, buf)
    local st = PCS_STICK
    st.pickedNow = false
    if not st.enabled then
        imgui.TextColored(iv4(1, 0.45, 0.45, 1), u8"\xd1\xec\xe0\xe9\xeb\xfb\x20\xee\xf2\xea\xeb\xfe\xf7\xe5\xed\xfb\x20\xe8\xe7\x2d\xe7\xe0\x20\xee\xf8\xe8\xe1\xee\xea")
        return
    end
    PCS_popupHeader(u8"\xd1\xec\xe0\xe9\xeb\xfb", u8"\xc2\xfb\xe1\xe5\xf0\xe8\xf2\xe5 \xf1\xec\xe0\xe9\xeb \xe4\xeb\xff \xe2\xf1\xf2\xe0\xe2\xea\xe8")
    local q = ""
    if PCS_STICK_POP_SEARCH then
        if not st.searchBuf then st.searchBuf = ffi.new("char[64]") end
        imgui.PushItemWidth(S(420))
        local okI, errI = PCS_GUARD.call(imgui.InputText, "##stkPopSearch", st.searchBuf, 64, 0)
        imgui.PopItemWidth()
        if not okI then PCS_STICK.fail("search", errI) end
        q = ffi.string(st.searchBuf):lower()
    end
    PCS_UI("stk grid begin")
    imgui.BeginChild("##stkPopGrid", imgui.ImVec2(S(420), S(380)), true)
    local ok, err = PCS_GUARD.call(PCS_STICK.grid, q, function(e)
        if PCS_STICK.insert(ad, buf, e.token) then
            st.pickedNow = true
        end
    end)
    imgui.EndChild()
    PCS_UI("stk grid end")
    if not ok then
        if st.tex then st.texBroken = true; st.reloadAt = os.clock() + 5 end
        PCS_STICK.fail("grid", err)
    end
    return st.pickedNow
end

function PCS_AD.openTab()
    pcall(function()
        if St and not St.winOpen and type(toggleMenuWindow) == "function" then toggleMenuWindow() end
        St.activeTab = 9
        if cfg.lastTab ~= 9 then cfg.lastTab = 9; pcall(saveCfg) end
    end)
end

function PCS_AD.registerCmds()
    pcall(sampRegisterChatCommand, "adlist", function() PCS_AD.openTab() end)
    pcall(sampRegisterChatCommand, "adstart", function()
        PCS_AD.setAll(true)
        pcall(sampAddChatMessage, "{00FF88}[PC Stats] " .. "\xe0\xe2\xf2\xee-\xef\xe8\xe0\xf0 \xe2\xea\xeb\xfe\xf7\xb8\xed", -1)
    end)
    pcall(sampRegisterChatCommand, "adstop", function()
        PCS_AD.setAll(false)
        pcall(sampAddChatMessage, "{FFAA00}[PC Stats] " .. "\xe0\xe2\xf2\xee-\xef\xe8\xe0\xf0 \xe2\xfb\xea\xeb\xfe\xf7\xe5\xed", -1)
    end)
    pcall(sampRegisterChatCommand, "adnow", function()
        if #PCS_AD.ads == 0 then
            pcall(sampAddChatMessage, "{FFAA00}[PC Stats] " .. "\xed\xe5\xf2 \xee\xe1\xfa\xff\xe2\xeb\xe5\xed\xe8\xe9", -1)
            return
        end
        if PCS_AD.send(PCS_AD.ads[1]) then
            pcall(sampAddChatMessage, "{00FF88}[PC Stats] " .. "\xee\xf2\xef\xf0\xe0\xe2\xeb\xe5\xed\xee", -1)
        else
            pcall(sampAddChatMessage, "{FFAA00}[PC Stats] " .. "\xed\xe5 \xf3\xe4\xe0\xeb\xee\xf1\xfc \xee\xf2\xef\xf0\xe0\xe2\xe8\xf2\xfc", -1)
        end
    end)
end

function PCS_AD.init()
    pcall(PCS_AD.load)
    pcall(PCS_AD.registerCmds)
end

PCS_NOTES = PCS_NOTES or {}
PCS_NOTES.list, PCS_NOTES.nextId, PCS_NOTES.loaded = PCS_NOTES.list or {}, PCS_NOTES.nextId or 1, PCS_NOTES.loaded or false
PCS_NOTES.ui = PCS_NOTES.ui or { open = {}, formOpen = false, editId = nil }

function PCS_NOTES.path() return CFG_DIR .. "/notes.dat" end

function PCS_NOTES.save()
    local ok, err = pcall(function()
        if type(createDirectory) == "function" then
            pcall(createDirectory, "moonloader/config"); pcall(createDirectory, CFG_DIR)
        end
        local parts = {}
        for _, n in ipairs(PCS_NOTES.list) do
            parts[#parts + 1] = string.format("%d\t%d\t%d\t%s\t%s\n", n.id, n.created or 0, n.upd or 0,
                PCS_REM.esc(n.title or ""), PCS_REM.esc(n.text or ""))
        end
        local f = io.open(PCS_NOTES.path(), "wb")
        if not f then error("cannot open file") end
        f:write(table.concat(parts)); f:close()
    end)
    if not ok then print("[PC Stats][notes] save fail: " .. tostring(err)) end
end

function PCS_NOTES.load()
    if PCS_NOTES.loaded then return end
    PCS_NOTES.loaded = true
    PCS_NOTES.list = {}
    local f = io.open(PCS_NOTES.path(), "rb")
    if not f then return end
    local body = f:read("*a") or ""
    f:close()
    for line in body:gmatch("[^\r\n]+") do
        local id, cr, up, title, text = line:match("^(%d+)\t(%d+)\t(%d+)\t([^\t]*)\t(.*)$")
        if id then
            id = tonumber(id)
            PCS_NOTES.list[#PCS_NOTES.list + 1] = { id = id, created = tonumber(cr), upd = tonumber(up),
                title = PCS_REM.unesc(title), text = PCS_REM.unesc(text) }
            if id >= PCS_NOTES.nextId then PCS_NOTES.nextId = id + 1 end
        end
    end
end

function PCS_NOTES.clean(title, text)
    title = tostring(title or ""):gsub("[\t\r\n]", " ")
    title = title:match("^%s*(.-)%s*$") or ""
    text = tostring(text or ""):gsub("\r", "")
    text = text:match("^%s*(.-)%s*$") or ""
    return PCS_utf8cut(title, 100), PCS_utf8cut(text, 2000)
end

function PCS_NOTES.add(title, text)
    PCS_NOTES.load()
    title, text = PCS_NOTES.clean(title, text)
    if title == "" and text == "" then return nil end
    local now = os.time()
    local n = { id = PCS_NOTES.nextId, title = title, text = text, created = now, upd = now }
    PCS_NOTES.nextId = PCS_NOTES.nextId + 1
    PCS_NOTES.list[#PCS_NOTES.list + 1] = n
    PCS_NOTES.save()
    return n
end

function PCS_NOTES.update(id, title, text)
    title, text = PCS_NOTES.clean(title, text)
    for _, n in ipairs(PCS_NOTES.list) do
        if n.id == id then
            n.title, n.text, n.upd, n._wk = title, text, os.time(), nil
            break
        end
    end
    PCS_NOTES.save()
end

function PCS_NOTES.del(id)
    for i, n in ipairs(PCS_NOTES.list) do
        if n.id == id then table.remove(PCS_NOTES.list, i); break end
    end
    PCS_NOTES.ui.open[id] = nil
    PCS_NOTES.save()
end

function PCS_NOTES.buf()
    local U = PCS_NOTES.ui
    if not U.titleBuf then
        U.titleBuf = imgui.new("char[101]")
        U.textBuf = imgui.new("char[2001]")
    end
    return U
end

function PCS_NOTES.openForm(n)
    local U = PCS_NOTES.buf()
    ffi.fill(U.titleBuf, 101, 0)
    ffi.fill(U.textBuf, 2001, 0)
    if n then
        ffi.copy(U.titleBuf, PCS_utf8cut(n.title or "", 100))
        ffi.copy(U.textBuf, PCS_utf8cut(n.text or "", 2000))
        U.editId = n.id
    else
        U.editId = nil
    end
    U.formOpen = true
end

function PCS_NOTES.drawHeader(nCount)
    local U, V2 = PCS_NOTES.ui, imgui.ImVec2
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local aw = imgui.GetContentRegionAvail().x
    local hs = S(0)
    imgui.SetCursorScreenPos(V2(p.x + hs * 2 + S(14), p.y + S(4)))
    local title = u8"\xc7\xe0\xec\xe5\xf2\xea\xe8"
    if U.formOpen then title = U.editId and u8"\xc8\xe7\xec\xe5\xed\xe8\xf2\xfc \xe7\xe0\xec\xe5\xf2\xea\xf3" or u8"\xcd\xee\xe2\xe0\xff \xe7\xe0\xec\xe5\xf2\xea\xe0" end
    imgui.TextColored(iv4(0.60, 0.85, 1.0, 1.0), title)
    imgui.SetCursorScreenPos(V2(p.x + hs * 2 + S(14), p.y + S(23)))
    if U.formOpen then
        imgui.TextColored(thDim(), u8"\xc7\xe0\xef\xee\xeb\xed\xe8\xf2\xe5 \xe8 \xed\xe0\xe6\xec\xe8\xf2\xe5 \xab\xd1\xee\xf5\xf0\xe0\xed\xe8\xf2\xfc\xbb")
    else
        imgui.TextColored(thDim(), u8"\xc2\xf1\xe5\xe3\xee: " .. nCount)
    end
    local bw, bh = S(128), S(36)
    imgui.SetCursorScreenPos(V2(p.x + aw - bw - S(4), p.y + S(3)))
    if PCS_headBtnEx("##noteHeadBtn", bw, bh, U.formOpen and u8"\xc7\xe0\xea\xf0\xfb\xf2\xfc" or u8"\xc4\xee\xe1\xe0\xe2\xe8\xf2\xfc",
            U.formOpen and "cross" or "plus", U.formOpen and { 0.90, 0.32, 0.32 } or { 0.30, 0.72, 0.98 }) then
        if U.formOpen then U.formOpen = false; U.editId = nil else PCS_NOTES.openForm(nil) end
    end
    imgui.SetCursorScreenPos(V2(p.x, p.y + S(46)))
    imgui.Dummy(V2(0, 0))
    imgui.Separator()
    imgui.Spacing()
end

function PCS_NOTES.drawForm()
    local U, V2 = PCS_NOTES.ui, imgui.ImVec2
    local lblCol = iv4(0.70, 0.82, 1.0, 1.0)
    PCS_stickerLabel("tag", u8"\xcd\xe0\xe7\xe2\xe0\xed\xe8\xe5 \xe7\xe0\xec\xe5\xf2\xea\xe8", lblCol, 0.2)
    PCS_input("##noteTitle", U.titleBuf, 101, u8"\xcd\xe0\xef\xf0\xe8\xec\xe5\xf0: \xcf\xeb\xe0\xed\xfb \xed\xe0 \xed\xe5\xe4\xe5\xeb\xfe", "tag", { counter = true, phase = 0.3 })
    imgui.Spacing()
    PCS_stickerLabel("text", u8"\xd2\xe5\xea\xf1\xf2 \xe7\xe0\xec\xe5\xf2\xea\xe8", lblCol, 0.8)
    PCS_input("##noteText", U.textBuf, 2001, u8"\xcf\xe8\xf8\xe8\xf2\xe5 \xe7\xe4\xe5\xf1\xfc \xf7\xf2\xee \xf3\xe3\xee\xe4\xed\xee...", "note",
        { multiline = true, h = S(190), counter = true, phase = 1.2 })
    imgui.Spacing()
    local half = math.floor((imgui.GetContentRegionAvail().x - S(6)) / 2)
    if PCS_gdButton(PCS_IC.save .. "  " .. u8"\xd1\xee\xf5\xf0\xe0\xed\xe8\xf2\xfc" .. "##noteSave", half, S(38), { 0.30, 0.72, 0.98 }, 10.0) then
        local t, x = ffi.string(U.titleBuf), ffi.string(U.textBuf)
        if t:gsub("%s", "") == "" and x:gsub("%s", "") == "" then
            pcall(pcs_notify, u8"\xc2\xe2\xe5\xe4\xe8\xf2\xe5 \xed\xe0\xe7\xe2\xe0\xed\xe8\xe5 \xe8\xeb\xe8 \xf2\xe5\xea\xf1\xf2 \xe7\xe0\xec\xe5\xf2\xea\xe8", "warning", 4)
        else
            if U.editId then PCS_NOTES.update(U.editId, t, x) else PCS_NOTES.add(t, x) end
            U.formOpen = false
            U.editId = nil
            pcall(pcs_notify, u8"\xc7\xe0\xec\xe5\xf2\xea\xe0 \xf1\xee\xf5\xf0\xe0\xed\xe5\xed\xe0", "success", 3)
        end
    end
    imgui.SameLine(0, S(6))
    if PCS_gdButton(PCS_IC.xmark .. "  " .. u8"\xce\xf2\xec\xe5\xed\xe0" .. "##noteCancel", half, S(38), { 0.50, 0.55, 0.65 }, 10.0) then
        U.formOpen = false
        U.editId = nil
    end
end

function PCS_NOTES.drawEmpty()
    local V2 = imgui.ImVec2
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local aw = imgui.GetContentRegionAvail().x

    local t1 = u8"\xc7\xe0\xec\xe5\xf2\xee\xea \xef\xee\xea\xe0 \xed\xe5\xf2"
    local t2 = u8"\xcd\xe0\xe6\xec\xe8\xf2\xe5 \xab\xc4\xee\xe1\xe0\xe2\xe8\xf2\xfc\xbb \xf1\xef\xf0\xe0\xe2\xe0 \xe2\xe2\xe5\xf0\xf5\xf3"
    local s1, s2 = imgui.CalcTextSize(t1), imgui.CalcTextSize(t2)
    imgui.SetCursorScreenPos(V2(p.x + (aw - s1.x) * 0.5, p.y + S(108)))
    imgui.TextColored(iv4(0.60, 0.85, 1.0, 1.0), t1)
    imgui.SetCursorScreenPos(V2(p.x + (aw - s2.x) * 0.5, p.y + S(130)))
    imgui.TextColored(thDim(), t2)
    imgui.SetCursorScreenPos(V2(p.x, p.y + S(160)))
    imgui.Dummy(V2(0, 0))
end

function PCS_NOTES.drawCard(n)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local U = PCS_NOTES.ui
    local p = imgui.GetCursorScreenPos()
    local w = imgui.GetContentRegionAvail().x
    local isOpen = U.open[n.id] == true
    local tx = S(18)
    local maxw = w - tx - S(14)
    local maxLines = isOpen and 60 or 3
    local key = math.floor(maxw) .. ":" .. maxLines .. ":" .. tostring(n.upd or 0) .. ":" .. tostring(St.UI_SCALE)
    if n._wk ~= key then
        n._lines = PCS_wrapTextN(n.text or "", maxw, maxLines)
        n._wk = key
    end
    local lines = n._lines or {}
    local lh = imgui.GetTextLineHeight() + S(3)
    local hasTitle = (n.title or "") ~= ""
    local h = S(14) + (hasTitle and S(24) or 0) + #lines * lh + (lines.more and lh or 0) + S(46)
    h = math.max(h, S(88))
    local bodyH = h - S(40)

    imgui.SetCursorScreenPos(p)
    if imgui.InvisibleButton("##noteTgl" .. n.id, V2(w, bodyH)) then U.open[n.id] = not isOpen end
    local hov = imgui.IsItemHovered()

    dl:AddRectFilled(p, V2(p.x + w, p.y + h), U32(iv4(0.05, 0.11, 0.17, hov and 0.98 or 0.92)), S(8))
    dl:AddRect(p, V2(p.x + w, p.y + h), U32(iv4(0.35, 0.72, 0.98, hov and 0.85 or 0.55)), S(8), 0, 1.2)
    dl:AddRectFilled(V2(p.x + 1, p.y + S(8)), V2(p.x + 4, p.y + h - S(8)), U32(iv4(0.35, 0.72, 0.98, 1)), 2)

    local y = p.y + S(10)
    if hasTitle then
        local pushed = false
        if PCS_BOLD_FONT then pushed = pcall(imgui.PushFont, PCS_BOLD_FONT) end
        dl:AddText(V2(p.x + tx, y), U32(iv4(0.70, 0.90, 1.0, 1)), PCS_REM.cut(n.title, maxw))
        if pushed then pcall(imgui.PopFont) end
        y = y + S(24)
    end
    for _, ln in ipairs(lines) do
        if ln ~= "" then dl:AddText(V2(p.x + tx, y), U32(iv4(1, 1, 1, 1)), ln) end
        y = y + lh
    end
    if lines.more and not isOpen then
        dl:AddText(V2(p.x + tx, y), U32(iv4(0.55, 0.75, 0.95, 0.95)), u8"... \xed\xe0\xe6\xec\xe8\xf2\xe5, \xf7\xf2\xee\xe1\xfb \xf0\xe0\xe7\xe2\xe5\xf0\xed\xf3\xf2\xfc")
    elseif isOpen and #lines > 3 then
        dl:AddText(V2(p.x + w - S(190), p.y + S(10)), U32(iv4(0.55, 0.75, 0.95, 0.8)), u8"\xed\xe0\xe6\xec\xe8\xf2\xe5, \xf7\xf2\xee\xe1\xfb \xf1\xe2\xe5\xf0\xed\xf3\xf2\xfc")
    end
    dl:AddText(V2(p.x + tx, p.y + h - S(28)), U32(iv4(0.55, 0.62, 0.72, 1)), PCS_REM.fmtTime(n.upd or n.created or os.time()))

    -- кнопки: Копировать / Изменить / Удалить
    local bw1, bw2, bw3, gap = S(118), S(108), S(104), S(6)
    imgui.SetCursorScreenPos(V2(p.x + w - (bw1 + bw2 + bw3 + gap * 2) - S(10), p.y + h - S(36)))
    if PCS_gdButton(u8"\xca\xee\xef\xe8\xf0\xee\xe2\xe0\xf2\xfc" .. "##noteCp" .. n.id, bw1, S(28), { 0.42, 0.55, 0.85 }, 6.0) then
        local s = (n.title ~= "" and (n.title .. "\n") or "") .. (n.text or "")
        pcall(imgui.SetClipboardText, s)
        pcall(pcs_notify, u8"\xd1\xea\xee\xef\xe8\xf0\xee\xe2\xe0\xed\xee \xe2 \xe1\xf3\xf4\xe5\xf0 \xee\xe1\xec\xe5\xed\xe0", "success", 3)
    end
    PCS_btnSticker("copy", 0.3, "left")
    imgui.SameLine(0, gap)
    if PCS_gdButton(u8"\xc8\xe7\xec\xe5\xed\xe8\xf2\xfc" .. "##noteEd" .. n.id, bw2, S(28), { 0.95, 0.62, 0.18 }, 6.0) then
        PCS_NOTES.openForm(n)
    end
    PCS_btnSticker("edit", 1.1, "left")
    imgui.SameLine(0, gap)
    if PCS_gdButton(u8"\xd3\xe4\xe0\xeb\xe8\xf2\xfc" .. "##noteDel" .. n.id, bw3, S(28), { 0.92, 0.30, 0.30 }, 6.0) then
        PCS_NOTES.del(n.id)
    end
    PCS_btnSticker("trash", 2.0, "left")
    imgui.SetCursorScreenPos(V2(p.x, p.y + h + S(6)))
    imgui.Dummy(V2(0, 0))
end

function PCS_NOTES.drawBody()
    local U = PCS_NOTES.buf()
    local list = {}
    for _, n in ipairs(PCS_NOTES.list) do list[#list + 1] = n end
    table.sort(list, function(a, b)
        local ua, ub = a.upd or 0, b.upd or 0
        if ua ~= ub then return ua > ub end
        return a.id > b.id
    end)
    PCS_NOTES.drawHeader(#list)
    if U.formOpen then
        PCS_NOTES.drawForm()
        return
    end
    if #list == 0 then
        PCS_NOTES.drawEmpty()
        return
    end
    for _, n in ipairs(list) do PCS_NOTES.drawCard(n) end
    imgui.Dummy(imgui.ImVec2(0, S(6)))
end

function PCS_fancyToolBtn(id, icon, title, sub, w, h, col, active, stickerIcon, stickerChar)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local th = imgui.GetTextLineHeight()
    h = math.max(h, th * 2 + S(14))
    local clicked = imgui.InvisibleButton(id, V2(w, h))
    local hov  = imgui.IsItemHovered()
    local held = imgui.IsItemActive()
    local r, g, b = col[1], col[2], col[3]
    local rnd = S(10)
    local k = active and 0.40 or (held and 0.36 or (hov and 0.32 or 0.25))

    if hov or active then
        dl:AddRectFilled(V2(p.x - 2, p.y - 2), V2(p.x + w + 2, p.y + h + 2), U32(iv4(r, g, b, 0.16)), rnd + 2)
    end
    dl:AddRectFilled(p, V2(p.x + w, p.y + h), U32(iv4(r * k * 0.7, g * k * 0.7, b * k * 0.7, 0.98)), rnd)
    dl:AddLine(V2(p.x + rnd, p.y + 1.5), V2(p.x + w - rnd, p.y + 1.5), U32(iv4(1, 1, 1, 0.12)), 1.0)
    dl:AddRect(p, V2(p.x + w, p.y + h), U32(iv4(r, g, b, (active or hov) and 0.95 or 0.60)), rnd, 0, 1.4)
    if active then
        dl:AddRectFilled(V2(p.x + rnd, p.y + h - 4), V2(p.x + w - rnd, p.y + h - 2), U32(iv4(r, g, b, 1.0)), 1)
    end

    local function drawCalcSticker(cx0, cy0, hw, hh, ang)
        local ca, sa = math.cos(ang), math.sin(ang)
        local cx, cy = cx0, cy0
        local function R(lx, ly) return V2(cx + lx * ca - ly * sa, cy + lx * sa + ly * ca) end
        local function quad(x0, y0, x1, y1, col)
            dl:AddQuadFilled(R(x0, y0), R(x1, y0), R(x1, y1), R(x0, y1), col)
        end
        local function rquad(x0, y0, x1, y1, rr, col)
            quad(x0 + rr, y0, x1 - rr, y1, col)
            quad(x0, y0 + rr, x1, y1 - rr, col)
            dl:AddCircleFilled(R(x0 + rr, y0 + rr), rr, col, 10)
            dl:AddCircleFilled(R(x1 - rr, y0 + rr), rr, col, 10)
            dl:AddCircleFilled(R(x0 + rr, y1 - rr), rr, col, 10)
            dl:AddCircleFilled(R(x1 - rr, y1 - rr), rr, col, 10)
        end
        local u = hw / 13
        local b = 2 * u
        cx, cy = cx0 + 1.6 * u, cy0 + 2.2 * u
        rquad(-hw - b, -hh - b, hw + b, hh + b, 6 * u, U32(iv4(0, 0, 0, 0.35)))
        cx, cy = cx0, cy0
        rquad(-hw - b, -hh - b, hw + b, hh + b, 6 * u, U32(iv4(1, 1, 1, 0.96)))
        rquad(-hw, -hh, hw, hh, 4.5 * u, U32(iv4(0.36, 0.30, 0.78, 1.0)))
        quad(-hw + 3 * u, -hh + 1 * u, hw - 3 * u, -hh + 2 * u, U32(iv4(1, 1, 1, 0.22)))
        rquad(-hw + 3 * u, -hh + 3 * u, hw - 3 * u, -hh + 11.5 * u, 2 * u, U32(iv4(0.74, 0.96, 0.86, 1.0)))
        quad(hw - 12 * u, -hh + 6 * u, hw - 5 * u, -hh + 8.2 * u, U32(iv4(0.13, 0.33, 0.27, 1.0)))
        quad(hw - 15.5 * u, -hh + 6 * u, hw - 13 * u, -hh + 8.2 * u, U32(iv4(0.13, 0.33, 0.27, 0.55)))
        local gx0, gx1 = -hw + 3 * u, hw - 3 * u
        local gy0, gy1 = -hh + 14 * u, hh - 3 * u
        local gap = 1.6 * u
        local cw = (gx1 - gx0 - gap * 2) / 3
        local chh = (gy1 - gy0 - gap * 2) / 3
        for row = 0, 2 do
            for col = 0, 2 do
                local x0 = gx0 + col * (cw + gap)
                local y0 = gy0 + row * (chh + gap)
                local colr = (col == 2) and U32(iv4(1.0, 0.68, 0.20, 1.0)) or U32(iv4(0.90, 0.90, 1.0, 1.0))
                quad(x0, y0, x0 + cw, y0 + chh, colr)
            end
        end
    end

    -- круглый значок с иконкой
    local cx, cy = p.x + h * 0.5, p.y + h * 0.5
    if stickerChar and (stickerChar == true or (type(stickerChar) == "string" and PCS_STICKER_COL[stickerChar])) then
        local angA, dyA, scA = PCS_stickerAnim(hov, w)
        if stickerChar == true then
            drawCalcSticker(cx, cy + 1 + dyA, h * 0.27 * scA, h * 0.345 * scA, angA)
        else
            PCS_drawSticker(dl, tostring(stickerChar), cx, cy + 1 + dyA, h * 0.30 * scA, angA)
        end
    else
    local rad = h * 0.30
    dl:AddCircleFilled(V2(cx, cy), rad + 2, U32(iv4(r, g, b, 0.18)), 28)
    dl:AddCircleFilled(V2(cx, cy), rad, U32(iv4(r * 0.95, g * 0.95, b * 0.95, 1.0)), 28)
    dl:AddCircle(V2(cx, cy), rad, U32(iv4(1, 1, 1, 0.30)), 28, 1.2)
    local isz = imgui.CalcTextSize(icon)
    dl:AddText(V2(cx - isz.x * 0.5, cy - isz.y * 0.5), U32(iv4(0.05, 0.05, 0.08, 1.0)), icon)
    end

    -- заголовок (жирным) + подпись
    local tx = p.x + h + S(2)
    local ty = p.y + h * 0.5 - th - 1
    local pushed = false
    if PCS_BOLD_FONT then pushed = pcall(imgui.PushFont, PCS_BOLD_FONT) end
    dl:AddText(V2(tx, ty), U32(iv4(1, 1, 1, 1)), title)
    if pushed then pcall(imgui.PopFont) end
    dl:AddText(V2(tx, p.y + h * 0.5 + 1), U32(iv4(r * 0.55 + 0.40, g * 0.55 + 0.40, b * 0.55 + 0.40, 0.95)), sub)

    -- стикер: слегка наклонённая наклейка с белой каймой и тенью
    local drewChar = false
    PCS_btnFxRect(dl, p, V2(p.x + w, p.y + h), hov, held, "ft|" .. tostring(id), rnd)
    if PCS_BTN_STICKERS and stickerIcon and not drewChar and w > S(170) then
        local sx, sy = p.x + w - S(22), p.y + S(15)
        local half = S(11)
        local ang = -0.21
        local ca, sa = math.cos(ang), math.sin(ang)
        local function quad(off, hs, colr)
            local pts = {}
            for i, c in ipairs({ { -1, -1 }, { 1, -1 }, { 1, 1 }, { -1, 1 } }) do
                local x, y = c[1] * hs, c[2] * hs
                pts[i] = V2(sx + off + x * ca - y * sa, sy + off + x * sa + y * ca)
            end
            dl:AddQuadFilled(pts[1], pts[2], pts[3], pts[4], colr)
        end
        quad(S(2), half + 1, U32(iv4(0, 0, 0, 0.35)))          -- тень
        quad(0, half + 1, U32(iv4(1, 1, 1, 0.95)))             -- белая кайма
        quad(0, half - 1, U32(iv4(1.0, 0.78, 0.22, 1.0)))      -- сама наклейка
        local ssz = imgui.CalcTextSize(stickerIcon)
        dl:AddText(V2(sx - ssz.x * 0.5, sy - ssz.y * 0.5), U32(iv4(0.25, 0.14, 0.02, 1.0)), stickerIcon)
    end
    return clicked
end

-- ── верхний ряд вкладки "Финансы", 2-я строка: "Курс валют" (график) и
-- "Калькулятор" — перенесены сюда к кнопкам "Настройки" и "Охранник" ──
function PCS_drawFinanceToolRow(r, g, b, halfW)
    imgui.Dummy(imgui.ImVec2(0, S(4)))
    local gap = S(6)
