-- ===== КАЛЬКУЛЯТОР ДЕПОЗИТА =====
PCS_DEP = PCS_DEP or { vip = 0, lvl = 0, houses = 0, rank = 0, ins = 0, lavka = 0, gramota = 0, skin = 0, ring = 0,
                       fix = 0, cur = 0, manual = 0, loaded = false }
PCS_DEPB = { house_max = 6000000, ins = 15, lavka = 12, gramota = 7, skin = 12, ring = 8,
             vip_profit = { 1500, 1150, 800 },
             lvl_max = { 0, 20000000, 30000000, 50000000, 70000000, 100000000 },
             lvl_bonus = { 0, 5, 10, 18, 26, 35 },
             rank = { 15, 25, 30 } }
PCS_DEP_KEYS = { "vip", "lvl", "houses", "rank", "ins", "lavka", "gramota", "skin", "ring", "fix", "cur", "manual" }

function PCS_depLoad()
    if PCS_DEP.loaded then return end
    PCS_DEP.loaded = true
    pcall(function()
        local f = io.open(CFG_DIR .. "/deposit_calc.txt", "r")
        if not f then return end
        for line in f:lines() do
            local k, v = line:match("^(%w+)=(%-?%d+)$")
            if k and k ~= "loaded" and PCS_DEP[k] ~= nil then PCS_DEP[k] = tonumber(v) or 0 end
        end
        f:close()
    end)
    PCS_DEP.vip = math.max(0, math.min(2, PCS_DEP.vip))
    PCS_DEP.lvl = math.max(0, math.min(5, PCS_DEP.lvl))
    PCS_DEP.houses = math.max(0, math.min(15, PCS_DEP.houses))
    PCS_DEP.rank = math.max(0, math.min(10, PCS_DEP.rank))
end

function PCS_depSave()
    pcall(function()
        local f = io.open(CFG_DIR .. "/deposit_calc.txt", "w")
        if not f then return end
        for _, k in ipairs(PCS_DEP_KEYS) do
            f:write(k, "=", tostring(math.floor(tonumber(PCS_DEP[k]) or 0)), "\n")
        end
        f:close()
    end)
end

-- подтянуть депозит, ранг и VIP из статистики (/stats), которую уже читает скрипт
function PCS_depSyncStats()
    local s = St.statsData
    if not s then return false end
    local got = false
    local md = tostring(s.moneyDay or "")
    local inner = md:match("%[(.-)%]") or md
    local num = inner:match("%d[%d,%.%s]*")
    if num then
        local digits = num:gsub("%D", "")
        if digits ~= "" then PCS_DEP.cur = tonumber(digits) or PCS_DEP.cur; got = true end
    end
    local rk = tostring(s.position or ""):match("%((%d+)%)")
    if rk then PCS_DEP.rank = math.max(0, math.min(10, tonumber(rk))); got = true end
    local st = tostring(s.status or "")
    if st:find("Premium", 1, true) then PCS_DEP.vip = 2; got = true
    elseif st:find("Titan", 1, true) then PCS_DEP.vip = 1; got = true end
    if got then PCS_depSave() end
    return got
end

function PCS_depCur()
    if (PCS_DEP.manual or 0) > 0 then return PCS_DEP.manual end
    return PCS_DEP.cur or 0
end
function PCS_depMax()
    return 200000000 + PCS_DEPB.house_max * (PCS_DEP.houses or 0) + (PCS_DEPB.lvl_max[(PCS_DEP.lvl or 0) + 1] or 0)
end
function PCS_depPercent()
    local d, b = PCS_DEP, PCS_DEPB
    local p = 0
    if d.ins == 1 then p = p + b.ins end
    if d.rank >= 1 and d.rank <= 3 then p = p + b.rank[1]
    elseif d.rank >= 4 and d.rank <= 7 then p = p + b.rank[2]
    elseif d.rank >= 8 and d.rank <= 10 then p = p + b.rank[3] end
    if d.lavka == 1 then p = p + b.lavka end
    if d.gramota == 1 then p = p + b.gramota end
    if d.lvl ~= 0 then p = p + (b.lvl_bonus[(d.lvl or 0) + 1] or 0) end
    if d.skin == 1 then p = p + b.skin end
    if d.ring == 1 then p = p + b.ring end
    return p
end
function PCS_depProfitFor(cur)
    local vp = PCS_DEPB.vip_profit[(PCS_DEP.vip or 0) + 1] or 1
    if not (vp > 0) then vp = 1 end
    local base = (tonumber(cur) or 0) / vp
    local pre = base + base / 100 * PCS_depPercent()
    local fin = pre - pre / 100 * (PCS_DEP.fix or 0)
    return math.floor(fin / 2)
end
function PCS_depProfit()
    return PCS_depProfitFor(math.min(PCS_depCur(), PCS_depMax()))
end
function PCS_depPaydays()
    local cur, mx = PCS_depCur(), PCS_depMax()
    if cur >= mx or cur <= 0 then return 0 end
    local it = 0
    while cur < mx and it < 5000 do
        local fin = PCS_depProfitFor(cur)
        if not (fin > 0) or fin == math.huge then break end
        cur = cur + fin
        it = it + 1
    end
    return it
end
function PCS_depFmt(n)
    local s = tostring(math.floor(tonumber(n) or 0))
    local neg = s:sub(1, 1) == "-"
    if neg then s = s:sub(2) end
    s = s:reverse():gsub("(%d%d%d)", "%1,"):reverse()
    s = s:gsub("^,", "")
    return (neg and "-" or "") .. s
end

function PCS_depRgb2Hsv(r, g, b)
    local mx, mn = math.max(r, g, b), math.min(r, g, b)
    local d = mx - mn
    local h = 0
    if d > 1e-6 then
        if mx == r then h = ((g - b) / d) % 6
        elseif mx == g then h = (b - r) / d + 2
        else h = (r - g) / d + 4 end
        h = h / 6
    end
    local s = (mx > 1e-6) and (d / mx) or 0
    return h, s, mx
end

-- оттенок палитры: сдвиг от акцента темы по кругу HSV (k = 0 -> сам акцент)
function PCS_depShade(k, vm)
    local r, g, b = getAcc()
    local h, s, v = PCS_depRgb2Hsv(r, g, b)
    vm = vm or 1
    local vv = math.min(1, math.max(0.35, v * vm))
    if s < 0.18 then return vv, vv, vv end -- серый/белый акцент: без сдвига оттенка
    return hsv2rgb((h + k) % 1.0, s, vv)
end

function PCS_depPal()
    local r, g, b = getAcc()
    return {
        a = { r, g, b },
        b = { PCS_depShade(0.07) },
        c = { PCS_depShade(0.14) },
        d = { PCS_depShade(-0.07) },
        e = { PCS_depShade(-0.14) },
    }
end

function PCS_depAnimOn() return not (cfg and cfg.animAllOff == true) end

-- число покороче: 1.2M / 3.4B (если полное не помещается)
function PCS_depShort(n)
    n = tonumber(n) or 0
    if n >= 1e9 then return string.format("%.2fB", n / 1e9)
    elseif n >= 1e6 then return string.format("%.1fM", n / 1e6)
    elseif n >= 1e3 then return string.format("%.1fK", n / 1e3) end
    return tostring(math.floor(n))
end

-- заголовок группы настроек: стикер + белый текст + (необязательно) плашка-значение справа
function PCS_depHeader(title, kind, tip, badge)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local aw0 = imgui.GetContentRegionAvail().x
    local th = imgui.GetTextLineHeight()
    local ang, dy = PCS_stickerAnim(false, p.y * 0.013)
    PCS_drawSticker(dl, kind, p.x + th * 0.72, p.y + th * 0.55 + dy * 0.4, th * 0.62, ang)
    imgui.SetCursorScreenPos(V2(p.x + th * 1.8, p.y))
    imgui.TextColored(iv4(1, 1, 1, 1), title)
    if tip and imgui.IsItemHovered() then
        imgui.BeginTooltip(); imgui.Text(tip); imgui.EndTooltip()
    end
    if badge then
        local pc = (PCS_DEPP and PCS_DEPP.cur) or { 1, 1, 1 }
        local bsz = imgui.CalcTextSize(badge)
        local x1 = p.x + aw0 - (PCS_DEP_PAD or 0)
        local x0 = x1 - bsz.x - S(16)
        dl:AddRectFilled(V2(x0, p.y), V2(x1, p.y + th + S(2)), U32(iv4(pc[1] * 0.30, pc[2] * 0.30, pc[3] * 0.30, 1)), S(9))
        dl:AddRect(V2(x0, p.y), V2(x1, p.y + th + S(2)), U32(iv4(pc[1], pc[2], pc[3], 0.85)), S(9), 0, 1.2)
        dl:AddText(V2(x0 + S(8), p.y + S(1)), U32(iv4(1, 1, 1, 1)), badge)
    end
    imgui.Dummy(imgui.ImVec2(0, S(5)))
end

-- ряд кнопок-вариантов: выбранная - градиент цвета карточки + белая рамка + свечение,
-- у вариантов Нету/Есть (yn=true) на выбранной появляется стикер-галочка/крестик
function PCS_depChoices(key, labels, cols, col, yn)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local aw = imgui.GetContentRegionAvail().x - (PCS_DEP_PAD or 0)
    local gap = S(5)
    cols = math.min(cols, #labels)
    local bw = (aw - gap * (cols - 1)) / cols
    local bh = S(32)
    local DIM = 0.72
    local r, g, b = col[1] * DIM, col[2] * DIM, col[3] * DIM
    local h0, s0, v0 = PCS_depRgb2Hsv(r, g, b)
    local r2, g2, b2 = r, g, b
    if s0 >= 0.18 then r2, g2, b2 = hsv2rgb((h0 + 0.06) % 1.0, s0, v0) end
    local YN_OK  = { 0.16, 0.68, 0.34 }
    local YN_BAD = { 0.70, 0.16, 0.18 }
    for i = 1, #labels do
        if (i - 1) % cols > 0 then imgui.SameLine(0, gap) end
        local p = imgui.GetCursorScreenPos()
        local clicked = imgui.InvisibleButton("##dep" .. key .. i, V2(bw, bh))
        local hov, held = imgui.IsItemHovered(), imgui.IsItemActive()
        local sel = (PCS_DEP[key] == i - 1)
        local cr, cg, cb, cr2, cg2, cb2 = r, g, b, r2, g2, b2
        if yn then
            local c = sel and YN_OK or YN_BAD
            cr, cg, cb = c[1], c[2], c[3]
            cr2, cg2, cb2 = c[1] * 0.80, c[2] * 0.80, c[3] * 0.80
        end
        local rnd = S(9)
        if sel then
            dl:AddRectFilled(V2(p.x - 2, p.y - 2), V2(p.x + bw + 2, p.y + bh + 2), U32(iv4(cr, cg, cb, 0.20)), rnd + 2)
            PCS_gradRect(dl, p.x, p.y, p.x + bw, p.y + bh, cr * 0.80, cg * 0.80, cb * 0.80, cr2 * 0.55, cg2 * 0.55, cb2 * 0.55, 1.0, rnd)
            dl:AddRectFilled(V2(p.x + rnd, p.y + 1.5), V2(p.x + bw - rnd, p.y + bh * 0.40), U32(iv4(1, 1, 1, 0.12)), 0)
            dl:AddRect(p, V2(p.x + bw, p.y + bh), U32(iv4(1, 1, 1, 0.80)), rnd, 0, 1.5)
        else
            local k = held and 0.46 or (hov and 0.36 or 0.26)
            if yn then k = held and 0.80 or (hov and 0.66 or 0.56) end
            PCS_gradRect(dl, p.x, p.y, p.x + bw, p.y + bh, cr * k, cg * k, cb * k, cr2 * k * 0.6, cg2 * k * 0.6, cb2 * k * 0.6, 0.95, rnd)
            dl:AddRect(p, V2(p.x + bw, p.y + bh), U32(iv4(cr, cg, cb, hov and 0.95 or 0.60)), rnd, 0, 1.1)
        end
        local lbl = labels[i]
        local tsz = imgui.CalcTextSize(lbl)
        local kind, icoW = nil, 0
        if yn and sel then kind = (i == 2) and "check" or "cross"; icoW = S(24) end
        local tx = p.x + (bw - tsz.x - icoW) * 0.5 + icoW
        local ty = p.y + (bh - tsz.y) * 0.5
        if sel then
            dl:AddText(V2(tx + 1, ty + 1), U32(iv4(0, 0, 0, 0.45)), lbl)
            dl:AddText(V2(tx, ty), U32(iv4(1, 1, 1, 1)), lbl)
            if kind then
                local ang, dy = PCS_stickerAnim(hov, i * 1.3)
                PCS_drawSticker(dl, kind, tx - S(13), p.y + bh * 0.5 + dy * 0.3, S(8), ang)
            elseif not yn and bw >= S(70) then
                local bx, by = p.x + bw - S(10), p.y + S(10)
                dl:AddCircleFilled(V2(bx, by), S(7), U32(iv4(r * 0.40, g * 0.40, b * 0.40, 1)), 16)
                dl:AddCircle(V2(bx, by), S(7), U32(iv4(1, 1, 1, 0.95)), 16, 1.2)
                PCS_drawCheck(dl, bx, by, S(3.4))
            end
        else
            dl:AddText(V2(tx, ty), U32(iv4(cr + (1 - cr) * 0.55, cg + (1 - cg) * 0.55, cb + (1 - cb) * 0.55, hov and 1.0 or 0.92)), lbl)
        end
        if clicked then
            PCS_DEP[key] = i - 1
            PCS_depSave()
        end
    end
    imgui.Dummy(imgui.ImVec2(0, S(4)))
end

-- плитка с суммой прибыли: градиент, блик, стикер слева, плашка xN справа
function PCS_depTile(x, y, w, h, title, value, c1, c2, badge, kind, phase)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local rnd = S(8)
    local ar, ag, ab = c1[1], c1[2], c1[3]
    -- тёмная карточка с цветной рамкой (как карточки «Баланс»)
    dl:AddRectFilled(V2(x, y), V2(x + w, y + h), U32(iv4(0.07, 0.07, 0.10, 0.94)), rnd)
    dl:AddRectFilled(V2(x + 1, y + 1), V2(x + w - 1, y + h * 0.5), U32(iv4(ar, ag, ab, 0.07)), rnd)
    dl:AddRect(V2(x, y), V2(x + w, y + h), U32(iv4(ar, ag, ab, 0.85)), rnd, 0, 1.2)
    -- иконка в цветной плашке слева
    local isz = S(26)
    local ix, iy = x + S(10), y + (h - isz) * 0.5
    dl:AddRectFilled(V2(ix, iy), V2(ix + isz, iy + isz), U32(iv4(ar, ag, ab, 0.28)), S(6))
    dl:AddRect(V2(ix, iy), V2(ix + isz, iy + isz), U32(iv4(ar, ag, ab, 0.90)), S(6), 0, 1.0)
    local ang, dy = PCS_stickerAnim(false, phase or 0)
    PCS_drawSticker(dl, kind, ix + isz * 0.5, iy + isz * 0.5 + dy * 0.2, S(8), ang)
    local tx = ix + isz + S(10)
    -- название слева сверху, множитель справа сверху цветом плитки (без плашки)
    dl:AddText(V2(tx, y + S(7)), U32(iv4(0.85, 0.87, 0.92, 1)), title)
    if badge then
        local bsz = imgui.CalcTextSize(badge)
        dl:AddText(V2(x + w - S(10) - bsz.x, y + S(7)), U32(iv4(ar, ag, ab, 1)), badge)
    end
    -- сумма крупно цветом плитки
    local pushed = false
    if PCS_BOLD_FONT then pushed = pcall(imgui.PushFont, PCS_BOLD_FONT) end
    local th = imgui.GetTextLineHeight()
    dl:AddText(V2(tx + 1, y + h - th - S(13) + 1), U32(iv4(0, 0, 0, 0.45)), value)
    dl:AddText(V2(tx, y + h - th - S(13)), U32(iv4(ar, ag, ab, 1)), value)
    if pushed then pcall(imgui.PopFont) end
    -- полоска прогресса внизу: множитель / 4
    local mult = tonumber(tostring(badge or ""):match("%d+")) or 1
    local ratio = math.min(1, mult / 4)
    local barY = y + h - S(6)
    local bx0, bx1 = x + S(10), x + w - S(10)
    dl:AddRectFilled(V2(bx0, barY), V2(bx1, barY + S(2)), U32(iv4(1, 1, 1, 0.08)), S(1))
    dl:AddRectFilled(V2(bx0, barY), V2(bx0 + (bx1 - bx0) * ratio, barY + S(2)), U32(iv4(ar, ag, ab, 0.95)), S(1))
end

-- заголовок раздела (вне карточек): стикер + текст цвета акцента + линия
function PCS_depSection(title, kind, col)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local aw = imgui.GetContentRegionAvail().x
    local th = imgui.GetTextLineHeight()
    local ang, dy = PCS_stickerAnim(false, p.y * 0.011)
    PCS_drawSticker(dl, kind, p.x + th * 0.78, p.y + th * 0.78 + dy * 0.4, th * 0.64, ang)
    imgui.SetCursorScreenPos(V2(p.x + th * 1.9, p.y + S(3)))
    local pushed = false
    if PCS_BOLD_FONT then pushed = pcall(imgui.PushFont, PCS_BOLD_FONT) end
    imgui.TextColored(iv4(col[1], col[2], col[3], 1), title)
    if pushed then pcall(imgui.PopFont) end
    dl:AddLine(V2(p.x + th * 1.9, p.y + th * 1.65), V2(p.x + aw, p.y + th * 1.65), U32(iv4(col[1], col[2], col[3], 0.35)), 1.0)
    imgui.SetCursorScreenPos(V2(p.x, p.y + th * 1.65 + S(8)))
    imgui.Dummy(V2(aw, 1))
end

-- большая кнопка со стикером и градиентом
function PCS_depButton(id, label, kind, w, h, col, tip)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local clicked = imgui.InvisibleButton("##" .. id, V2(w, h))
    local hov, held = imgui.IsItemHovered(), imgui.IsItemActive()
    local r, g, b = col[1], col[2], col[3]
    local h0, s0, v0 = PCS_depRgb2Hsv(r, g, b)
    local r2, g2, b2 = r, g, b
    if s0 >= 0.18 then r2, g2, b2 = hsv2rgb((h0 + 0.06) % 1.0, s0, v0) end
    local k = held and 0.80 or (hov and 0.68 or 0.52)
    local rnd = S(10)
    if hov then
        dl:AddRectFilled(V2(p.x - 2, p.y - 2), V2(p.x + w + 2, p.y + h + 2), U32(iv4(r, g, b, 0.18)), rnd + 2)
    end
    PCS_gradRect(dl, p.x, p.y, p.x + w, p.y + h, r * k, g * k, b * k, r2 * k * 0.72, g2 * k * 0.72, b2 * k * 0.72, 1.0, rnd)
    dl:AddRectFilled(V2(p.x + rnd, p.y + 1.5), V2(p.x + w - rnd, p.y + h * 0.40), U32(iv4(1, 1, 1, 0.11)), 0)
    dl:AddRect(p, V2(p.x + w, p.y + h), U32(iv4(r, g, b, hov and 1.0 or 0.75)), rnd, 0, 1.3)
    local tsz = imgui.CalcTextSize(label)
    local icoW = S(26)
    local x0 = p.x + (w - tsz.x - icoW) * 0.5
    local ang, dy = PCS_stickerAnim(hov, w * 0.01)
    PCS_drawSticker(dl, kind, x0 + S(10), p.y + h * 0.5 + dy * 0.3, S(8), ang)
    local ty = p.y + (h - tsz.y) * 0.5
    dl:AddText(V2(x0 + icoW + 1, ty + 1), U32(iv4(0, 0, 0, 0.40)), label)
    dl:AddText(V2(x0 + icoW, ty), U32(iv4(1, 1, 1, 1)), label)
    if hov and tip then
        imgui.BeginTooltip(); imgui.Text(tip); imgui.EndTooltip()
    end
    return clicked
end

-- пояснение в карточке со стикером; высота запоминается с прошлого кадра
function PCS_depNote(kind, col, text)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local aw = imgui.GetContentRegionAvail().x
    local h = St._depNoteH or S(44)
    local r, g, b = col[1], col[2], col[3]
    dl:AddRectFilled(p, V2(p.x + aw, p.y + h), U32(iv4(r * 0.09, g * 0.09, b * 0.09, pcsRowA(0.92))), S(10))
    dl:AddRect(p, V2(p.x + aw, p.y + h), U32(iv4(r, g, b, 0.50)), S(10), 0, 1.1)
    dl:AddRectFilled(V2(p.x, p.y + S(8)), V2(p.x + S(3), p.y + h - S(8)), U32(iv4(r, g, b, 1)), S(2))
    local ang, dy = PCS_stickerAnim(false, 2.3)
    PCS_drawSticker(dl, kind, p.x + S(26), p.y + h * 0.5 + dy * 0.3, S(9), ang)
    imgui.SetCursorScreenPos(V2(p.x + S(50), p.y + S(8)))
    local wp = imgui.GetWindowPos()
    imgui.PushTextWrapPos((p.x + aw - S(10)) - wp.x)
    imgui.TextColored(iv4(0.92, 0.94, 0.98, 1), text)
    imgui.PopTextWrapPos()
    local ey = imgui.GetCursorScreenPos().y
    St._depNoteH = math.max(S(40), (ey - p.y) + S(2))
    imgui.SetCursorScreenPos(V2(p.x, p.y + St._depNoteH + S(6)))
    imgui.Dummy(V2(aw, 1))
end

-- ── Персонаж на фоне: размер и положение (ползунки + кнопки-стрелки) ──
function PCS_depArrowBtn(id, dir, sz, col)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local clicked = imgui.InvisibleButton("##" .. id, V2(sz, sz))
    local hov, held = imgui.IsItemHovered(), imgui.IsItemActive()
    local r, g, b = col[1], col[2], col[3]
    local k = held and 0.55 or (hov and 0.38 or 0.20)
    local rnd = S(8)
    dl:AddRectFilled(p, V2(p.x + sz, p.y + sz), U32(iv4(r * k, g * k, b * k, 1)), rnd)
    dl:AddRectFilled(V2(p.x + rnd, p.y + 1.5), V2(p.x + sz - rnd, p.y + sz * 0.40), U32(iv4(1, 1, 1, 0.10)), 0)
    dl:AddRect(p, V2(p.x + sz, p.y + sz), U32(iv4(r, g, b, hov and 1.0 or 0.65)), rnd, 0, 1.2)
    local cx, cy, q = p.x + sz * 0.5, p.y + sz * 0.5, sz * 0.22
    local white = U32(iv4(1, 1, 1, 1))
    if dir == "l" then dl:AddTriangleFilled(V2(cx - q, cy), V2(cx + q * 0.8, cy - q), V2(cx + q * 0.8, cy + q), white)
    elseif dir == "r" then dl:AddTriangleFilled(V2(cx + q, cy), V2(cx - q * 0.8, cy - q), V2(cx - q * 0.8, cy + q), white)
    elseif dir == "u" then dl:AddTriangleFilled(V2(cx, cy - q), V2(cx - q, cy + q * 0.8), V2(cx + q, cy + q * 0.8), white)
    elseif dir == "d" then dl:AddTriangleFilled(V2(cx, cy + q), V2(cx - q, cy - q * 0.8), V2(cx + q, cy - q * 0.8), white)
    else
        dl:AddCircle(V2(cx, cy), q, white, 16, 1.8)
        dl:AddCircleFilled(V2(cx, cy), q * 0.35, white, 10)
    end
    return clicked
end

function PCS_drawCompanionTransform()
    local V2 = imgui.ImVec2
    local r, g, b = getAcc()
    local col = { r, g, b }
    local function clampv(v, lo, hi) return math.max(lo, math.min(hi, v)) end

    imgui.TextColored(iv4(0.70, 0.82, 1.0, 1.0), u8"\xd0\xe0\xe7\xec\xe5\xf0 \xe8 \xef\xee\xeb\xee\xe6\xe5\xed\xe8\xe5 \xef\xe5\xf0\xf1\xee\xed\xe0\xe6\xe0:")
    imgui.Spacing()

    PCS_gdSliderStyle(true)
    imgui.PushItemWidth(S(180))
    local sBuf = imgui.new("float[1]", { cfg.companionScale or 1.0 })
    if imgui.SliderFloat(u8"\xd0\xe0\xe7\xec\xe5\xf0##companionScaleMain", sBuf, 0.3, 3.0, "x%.2f") then
        cfg.companionScale = sBuf[0]
        saveCfg()
    end
    local xBuf = imgui.new("float[1]", { cfg.companionOffX or 0.0 })
    if imgui.SliderFloat(u8"\xc2\xeb\xe5\xe2\xee / \xe2\xef\xf0\xe0\xe2\xee##companionOffXMain", xBuf, -0.8, 0.8, "%.2f") then
        cfg.companionOffX = xBuf[0]
        saveCfg()
    end
    local yBuf = imgui.new("float[1]", { cfg.companionOffY or 0.0 })
    if imgui.SliderFloat(u8"\xc2\xe2\xe5\xf0\xf5 / \xe2\xed\xe8\xe7##companionOffYMain", yBuf, -0.8, 0.8, "%.2f") then
        cfg.companionOffY = yBuf[0]
        saveCfg()
    end
    imgui.PopItemWidth()
    PCS_gdSliderStyle(false)
    imgui.Spacing()

    -- крестовина со стрелками: шаг 0.02 за клик, по центру - сброс положения
    local sz, gp = S(34), S(5)
    local base = imgui.GetCursorScreenPos()
    local step = 0.02
    local function cell(cx, cy, id, dir)
        imgui.SetCursorScreenPos(V2(base.x + cx * (sz + gp), base.y + cy * (sz + gp)))
        return PCS_depArrowBtn(id, dir, sz, col)
    end
    if cell(1, 0, "compUp", "u") then cfg.companionOffY = clampv((cfg.companionOffY or 0) - step, -0.8, 0.8); saveCfg() end
    if cell(0, 1, "compLeft", "l") then cfg.companionOffX = clampv((cfg.companionOffX or 0) - step, -0.8, 0.8); saveCfg() end
    if cell(1, 1, "compCenter", "c") then cfg.companionOffX = 0.0; cfg.companionOffY = 0.0; saveCfg() end
    if cell(2, 1, "compRight", "r") then cfg.companionOffX = clampv((cfg.companionOffX or 0) + step, -0.8, 0.8); saveCfg() end
    if cell(1, 2, "compDown", "d") then cfg.companionOffY = clampv((cfg.companionOffY or 0) + step, -0.8, 0.8); saveCfg() end

    -- справа от крестовины: кнопки +/- размера и полный сброс
    local rx = base.x + 3 * (sz + gp) + S(10)
    imgui.SetCursorScreenPos(V2(rx, base.y))
    imgui.TextColored(thDim(), u8"\xd0\xe0\xe7\xec\xe5\xf0:")
    imgui.SetCursorScreenPos(V2(rx, base.y + S(22)))
    if PCS_depButton("compSizeMinus", u8"\xcc\xe5\xed\xfc\xf8\xe5", "download", S(86), S(30), col) then
        cfg.companionScale = clampv((cfg.companionScale or 1.0) - 0.05, 0.3, 3.0); saveCfg()
    end
    imgui.SetCursorScreenPos(V2(rx + S(92), base.y + S(22)))
    if PCS_depButton("compSizePlus", u8"\xc1\xee\xeb\xfc\xf8\xe5", "plus", S(86), S(30), col) then
        cfg.companionScale = clampv((cfg.companionScale or 1.0) + 0.05, 0.3, 3.0); saveCfg()
    end
    imgui.SetCursorScreenPos(V2(rx, base.y + S(60)))
    if PCS_depButton("compResetAll", u8"\xd1\xe1\xf0\xee\xf1\xe8\xf2\xfc \xf0\xe0\xe7\xec\xe5\xf0 \xe8 \xef\xee\xe7\xe8\xf6\xe8\xfe", "refresh", S(178), S(30), { 0.95, 0.40, 0.42 },
            u8"\xc2\xe5\xf0\xed\xf3\xf2\xfc \xf0\xe0\xe7\xec\xe5\xf0 x1.00 \xe8 \xef\xee\xeb\xee\xe6\xe5\xed\xe8\xe5 \xef\xee \xf6\xe5\xed\xf2\xf0\xf3") then
        cfg.companionScale = 1.0; cfg.companionOffX = 0.0; cfg.companionOffY = 0.0; saveCfg()
    end

    imgui.SetCursorScreenPos(V2(base.x, base.y + 3 * (sz + gp) + S(2)))
    imgui.Dummy(V2(1, 1))
end

-- shared "< Back" bar (same look in Deposit and Guard tabs): blue button + coloured title
function PCS_drawBackBar(titleU8, tr, tg, tb, id)
    imgui.PushStyleColor(imgui.Col.Button,        iv4(0.20, 0.55, 0.85, 1.0))
    imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(0.28, 0.65, 0.95, 1.0))
    imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(0.15, 0.45, 0.75, 1.0))
    local clicked = imgui.Button(u8"\x3c\x20\xcd\xe0\xe7\xe0\xe4" .. "##" .. tostring(id), imgui.ImVec2(S(120), S(32)))
    imgui.PopStyleColor(3)
    imgui.SameLine(0, S(10))
    imgui.TextColored(iv4(tr, tg, tb, 1), titleU8)
    imgui.Dummy(imgui.ImVec2(0, S(6)))
    return clicked
end

-- плашка-показатель: тёмная карточка в цвет, стикер слева, подпись + значение
function PCS_depChip(x, y, w, h, label, value, col, kind, phase, valueShort)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local r, g, b = col[1], col[2], col[3]
    local rnd = S(10)
    dl:AddRectFilled(V2(x, y), V2(x + w, y + h), U32(iv4(r * 0.10, g * 0.10, b * 0.10, pcsRowA(0.92))), rnd)
    dl:AddRect(V2(x, y), V2(x + w, y + h), U32(iv4(r, g, b, 0.55)), rnd, 0, 1.2)
    dl:AddRectFilled(V2(x + S(8), y), V2(x + w - S(8), y + 3), U32(iv4(r, g, b, 1)), 2)
    local ang, dy = PCS_stickerAnim(false, phase or 0)
    PCS_drawSticker(dl, kind, x + S(19), y + h * 0.5 + 1 + dy * 0.3, S(8), ang)
    local tx = x + S(37)
    dl:AddText(V2(tx, y + S(6)), U32(iv4(0.66, 0.70, 0.78, 1)), label)
    local vs = value
    if valueShort and (tx + imgui.CalcTextSize(vs).x) > (x + w - S(6)) then vs = valueShort end
    dl:AddText(V2(tx, y + h - imgui.GetTextLineHeight() - S(5)), U32(iv4(r + (1 - r) * 0.45, g + (1 - g) * 0.45, b + (1 - b) * 0.45, 1)), vs)
end

-- карточка настроек: тёмный тон цвета, рамка, верхняя полоска, заголовок со стикером
-- (высота запоминается с прошлого кадра; PCS_depCardEnd её обновляет)
function PCS_depCardBegin(key, title, col, kind)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local aw = imgui.GetContentRegionAvail().x
    local r, g, b = col[1], col[2], col[3]
    St._depCardH = St._depCardH or {}
    local ch = St._depCardH[key]
    local hh = ch or S(44)
    local rnd = S(12)
    if ch then
        dl:AddRectFilled(p, V2(p.x + aw, p.y + ch), U32(iv4(r * 0.07, g * 0.07, b * 0.07, pcsRowA(0.90))), rnd)
    end
    dl:AddRect(p, V2(p.x + aw, p.y + hh), U32(iv4(r, g, b, 0.55)), rnd, 0, 1.2)
    dl:AddRectFilled(V2(p.x + S(12), p.y), V2(p.x + aw - S(12), p.y + 3), U32(iv4(r, g, b, 1)), 2)
    St._depCard = { key = key, y0 = p.y }
    PCS_DEPP = PCS_DEPP or {}
    PCS_DEPP.cur = { r, g, b }
    imgui.Dummy(V2(0, S(8)))
    imgui.Indent(S(12))
    local cp = imgui.GetCursorScreenPos()
    local th = imgui.GetTextLineHeight()
    local ang, dy = PCS_stickerAnim(false, p.y * 0.017)
    PCS_drawSticker(dl, kind or "gear", cp.x + th * 0.80, cp.y + th * 0.70 + dy * 0.4, th * 0.70, ang)
    imgui.SetCursorScreenPos(V2(cp.x + th * 2.0, cp.y + S(2)))
    local pushed = false
    if PCS_BOLD_FONT then pushed = pcall(imgui.PushFont, PCS_BOLD_FONT) end
    imgui.TextColored(iv4(r + (1 - r) * 0.35, g + (1 - g) * 0.35, b + (1 - b) * 0.35, 1), title)
    if pushed then pcall(imgui.PopFont) end
    local ly = cp.y + th * 1.6
    dl:AddLine(V2(cp.x, ly), V2(p.x + aw - S(12), ly), U32(iv4(r, g, b, 0.30)), 1.0)
    imgui.SetCursorScreenPos(V2(cp.x, ly + S(7)))
    imgui.Dummy(V2(1, 1))
    PCS_DEP_PAD = S(14)
end

function PCS_depCardEnd()
    PCS_DEP_PAD = 0
    imgui.Unindent(S(12))
    local c = St._depCard
    if c then
        local p = imgui.GetCursorScreenPos()
        St._depCardH[c.key] = (p.y - c.y0) + S(4)
        St._depCard = nil
    end
    imgui.Dummy(imgui.ImVec2(0, S(10)))
end

function PCS_depContent()
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    if St._depPendingSync and St.statsData ~= St._depLastStats then
        St._depPendingSync = false
        PCS_depSyncStats()
    end
    -- палитра берётся из акцента темы скрипта (Настройки -> тема / свой цвет)
    local P = PCS_depPal()
    PCS_DEPP = PCS_DEPP or {}
    local ar, ag, ab = P.a[1], P.a[2], P.a[3]
    local dl = imgui.GetWindowDrawList()
    local aw = imgui.GetContentRegionAvail().x
    local cur, mx = PCS_depCur(), PCS_depMax()
    local gap = S(6)
    local anim = PCS_depAnimOn()
    local tnow = os.clock()

    if PCS_drawBackBar(u8"\xc4\xe5\xef\xee\xe7\xe8\xf2", ar, ag, ab, "depBack") then
        St.activeTab = 3
        St._depositOpen = false
        St._resetCharScroll = true
    end

    PCS_DEP_PAD = 0

    -- ════════ шапка: градиентная карточка с кольцом прогресса ════════
    local p = imgui.GetCursorScreenPos()
    local bh = S(120)
    local rnd = S(16)
    local frac = (mx > 0) and math.min(1, cur / mx) or 0
    dl:AddRectFilled(V2(p.x + 2, p.y + 4), V2(p.x + aw + 2, p.y + bh + 4), U32(iv4(0, 0, 0, 0.30)), rnd)
    PCS_gradRect(dl, p.x, p.y, p.x + aw, p.y + bh, ar * 0.42, ag * 0.42, ab * 0.42, P.b[1] * 0.09, P.b[2] * 0.09, P.b[3] * 0.09, 1.0, rnd)
    dl:AddRectFilled(V2(p.x + S(16), p.y + 1.5), V2(p.x + aw - S(16), p.y + bh * 0.28), U32(iv4(1, 1, 1, 0.06)), 0)
    dl:AddRect(V2(p.x - 1, p.y - 1), V2(p.x + aw + 1, p.y + bh + 1), U32(iv4(ar, ag, ab, 0.20)), rnd + 1, 0, 3.0)
    dl:AddRect(p, V2(p.x + aw, p.y + bh), U32(iv4(ar, ag, ab, 0.80)), rnd, 0, 1.4)
    dl:AddRectFilled(V2(p.x + S(14), p.y), V2(p.x + aw - S(14), p.y + 3), U32(iv4(ar, ag, ab, 1)), 2)

    -- кольцо прогресса
    local RR = S(38)
    local ccx, ccy = p.x + S(62), p.y + bh * 0.5
    local pulse = anim and (0.5 + 0.5 * math.sin(tnow * 2.0)) or 0.5
    dl:AddCircleFilled(V2(ccx, ccy), RR + S(10), U32(iv4(0, 0, 0, 0.32)), 48)
    dl:AddCircle(V2(ccx, ccy), RR + S(11) + pulse * S(2), U32(iv4(ar, ag, ab, 0.10 + 0.12 * pulse)), 48, 2.0)
    dl:AddCircle(V2(ccx, ccy), RR, U32(iv4(1, 1, 1, 0.12)), 48, S(9))
    if frac > 0.003 then
        local segs = math.max(2, math.ceil(72 * frac))
        for i = 0, segs - 1 do
            local a0 = -math.pi / 2 + 2 * math.pi * frac * i / segs
            local a1 = -math.pi / 2 + 2 * math.pi * frac * (i + 1) / segs + 0.025
            local k = i / segs
            local cr = ar + (P.b[1] - ar) * k
            local cg = ag + (P.b[2] - ag) * k
            local cb = ab + (P.b[3] - ab) * k
            local wk = 0.12 + 0.30 * k
            dl:AddLine(V2(ccx + math.cos(a0) * RR, ccy + math.sin(a0) * RR),
                V2(ccx + math.cos(a1) * RR, ccy + math.sin(a1) * RR),
                U32(iv4(cr + (1 - cr) * wk, cg + (1 - cg) * wk, cb + (1 - cb) * wk, 1)), S(9))
        end
        local ae = -math.pi / 2 + 2 * math.pi * frac
        local ex, ey = ccx + math.cos(ae) * RR, ccy + math.sin(ae) * RR
        dl:AddCircleFilled(V2(ex, ey), S(8), U32(iv4(ar, ag, ab, 0.35)), 16)
        dl:AddCircleFilled(V2(ex, ey), S(4.5), U32(iv4(1, 1, 1, 0.97)), 14)
    end
    dl:AddCircleFilled(V2(ccx, ccy), RR - S(8), U32(iv4(0, 0, 0, 0.28)), 40)
    local th0 = imgui.GetTextLineHeight()
    local pctTxt = tostring(math.floor(frac * 100 + 0.5)) .. "%"
    local pcSz = imgui.CalcTextSize(pctTxt)
    dl:AddText(V2(ccx - pcSz.x * 0.5, ccy - pcSz.y * 0.5), U32(iv4(1, 1, 1, 1)), pctTxt)

    -- сумма и максимум
    local tx0 = p.x + S(122)
    dl:AddText(V2(tx0, p.y + S(12)), U32(iv4(1, 1, 1, 0.78)), u8"\xc4\xe5\xed\xfc\xe3\xe8 \xed\xe0 \xe4\xe5\xef\xee\xe7\xe8\xf2\xe5")
    local pushed = false
    if PCS_BOLD_FONT then pushed = pcall(imgui.PushFont, PCS_BOLD_FONT) end
    local valTxt = "$" .. PCS_depFmt(cur)
    local vy = p.y + S(14) + th0
    dl:AddText(V2(tx0 + 1, vy + 1), U32(iv4(0, 0, 0, 0.45)), valTxt)
    dl:AddText(V2(tx0, vy), U32(iv4(ar + (1 - ar) * 0.78, ag + (1 - ag) * 0.78, ab + (1 - ab) * 0.78, 1)), valTxt)
    local vh = imgui.GetTextLineHeight()
    if pushed then pcall(imgui.PopFont) end
    dl:AddText(V2(tx0, vy + vh + S(3)), U32(iv4(1, 1, 1, 0.62)), u8"\xcc\xe0\xea\xf1\xe8\xec\xf3\xec $" .. PCS_depFmt(mx))

    -- тонкая полоса заполнения внизу
    do
        local bx0, bx1 = tx0, p.x + aw - S(16)
        local by = p.y + bh - S(17)
        if bx1 - bx0 > 20 then
            dl:AddRectFilled(V2(bx0, by), V2(bx1, by + S(7)), U32(iv4(1, 1, 1, 0.13)), S(4))
            if frac > 0.01 then
                local fx = bx0 + (bx1 - bx0) * frac
                PCS_gradRect(dl, bx0, by, fx, by + S(7), ar, ag, ab, P.b[1], P.b[2], P.b[3], 1.0, S(4))
            end
        end
    end

    -- стикеры и искорки справа
    local ang1, dy1 = PCS_stickerAnim(false, 0.4)
    PCS_drawSticker(dl, "money", p.x + aw - S(30), p.y + S(28) + dy1, S(14), ang1)
    local ang2, dy2 = PCS_stickerAnim(false, 1.7)
    PCS_drawSticker(dl, "star", p.x + aw - S(72), p.y + S(20) + dy2, S(7.5), ang2 + 0.25)
    local function sparkle(x, y, sz, ph)
        local a = anim and (0.30 + 0.45 * math.sin(tnow * 2.4 + ph)) or 0.45
        local c = U32(iv4(1, 1, 1, math.max(0.05, a)))
        dl:AddLine(V2(x - sz, y), V2(x + sz, y), c, 1.4)
        dl:AddLine(V2(x, y - sz), V2(x, y + sz), c, 1.4)
    end
    sparkle(p.x + aw - S(100), p.y + S(36), S(4), 0.0)
    sparkle(p.x + aw - S(52), p.y + S(56), S(3), 2.1)
    imgui.Dummy(V2(aw, bh + S(8)))

    -- ════════ три плашки-показателя ════════
    do
        local cgap = S(6)
        local cw = (aw - cgap * 2) / 3
        local chh = S(50)
        local cp = imgui.GetCursorScreenPos()
        local pdN = PCS_depPaydays()
        local free = math.max(0, mx - cur)
        PCS_depChip(cp.x, cp.y, cw, chh, u8"\xc1\xee\xed\xf3\xf1", "+" .. tostring(PCS_depPercent()) .. "%", P.b, "plus", 0.3)
        PCS_depChip(cp.x + cw + cgap, cp.y, cw, chh, u8"\xd1\xe2\xee\xe1\xee\xe4\xed\xee", "$" .. PCS_depFmt(free), P.a, "download", 1.1, "$" .. PCS_depShort(free))
        PCS_depChip(cp.x + (cw + cgap) * 2, cp.y, cw, chh, u8"\xc4\xee \xec\xe0\xea\xf1\xe8\xec\xf3\xec\xe0", pdN > 0 and (tostring(pdN) .. " PAYDAY") or "-", P.c, "clock", 2.0)
        imgui.Dummy(V2(aw, chh + S(8)))
    end

    -- ════════ пояснение со стикером ════════
    do
        local note, kind, ncol
        if cur > mx then
            note = u8"\xcb\xe8\xf8\xed\xe8\xe5 $" .. PCS_depFmt(cur - mx) .. u8" - \xef\xf0\xe8\xe1\xfb\xeb\xfc \xf1 \xed\xe8\xf5 \xed\xe5 \xe8\xe4\xb8\xf2, \xe8\xf5 \xec\xee\xe6\xed\xee \xf1\xed\xff\xf2\xfc."
            kind, ncol = "warn", { 1.0, 0.75, 0.30 }
        elseif cur >= 10000 and cur < mx then
            local pd = PCS_depPaydays()
            note = u8"\xc4\xee \xec\xe0\xea\xf1\xe8\xec\xf3\xec\xe0: \xef\xee\xef\xee\xeb\xed\xe8\xf2\xe5 \xe5\xf9\xb8 \xed\xe0 $" .. PCS_depFmt(mx - cur) .. u8" \xe8\xeb\xe8 \xe6\xe4\xe8\xf2\xe5 " .. pd ..
                   " (" .. math.floor(pd / 4) .. u8" \xe5\xf1\xeb\xe8 X4) PAYDAY."
            kind, ncol = "info", P.a
        elseif cur == mx then
            note = u8"\xc4\xe5\xef\xee\xe7\xe8\xf2 \xe7\xe0\xef\xee\xeb\xed\xe5\xed - \xea\xe0\xe6\xe4\xfb\xe9 PAYDAY \xe8\xe4\xb8\xf2 \xec\xe0\xea\xf1\xe8\xec\xe0\xeb\xfc\xed\xe0\xff \xef\xf0\xe8\xe1\xfb\xeb\xfc."
            kind, ncol = "check", { 0.30, 0.90, 0.50 }
        else
            note = u8"\xc4\xe5\xef\xee\xe7\xe8\xf2 \xed\xe5 \xef\xf0\xe8\xed\xee\xf1\xe8\xf2 \xef\xf0\xe8\xe1\xfb\xeb\xfc: \xed\xf3\xe6\xed\xee \xec\xe8\xed\xe8\xec\xf3\xec $10000."
            kind, ncol = "cross", { 1.0, 0.45, 0.45 }
        end
        PCS_depNote(kind, ncol, note)
    end

    -- ════════ прибыль за PAYDAY: 4 цветные плитки ════════
    PCS_depSection(u8"\xcf\xf0\xe8\xe1\xfb\xeb\xfc \xe7\xe0 PAYDAY", "money", P.a)
    local profit = PCS_depProfit()
    local tw = (aw - gap) / 2
    local th2 = S(62)
    local tiles = {
        { u8"\xcf\xf0\xee\xf1\xf2\xee\xe9 PAYDAY",    1, "money" },
        { u8"X2 (\xcc\xcf / X2 \xe4\xee\xec)",  2, "chart" },
        { u8"X3 (\xed\xee\xe2\xe8\xf7\xea\xe8)",      3, "star"  },
        { u8"X4 PAYDAY",         4, "mega"  },
    }
    local sp = imgui.GetCursorScreenPos()
    local accents = {
        { 0.30, 0.90, 0.55 },
        { 0.35, 0.68, 1.00 },
        { 1.00, 0.72, 0.28 },
        { 0.80, 0.50, 1.00 },
    }
    for i, tl in ipairs(tiles) do
        local cx = sp.x + ((i - 1) % 2) * (tw + gap)
        local cy = sp.y + math.floor((i - 1) / 2) * (th2 + gap)
        local ac = accents[i]
        PCS_depTile(cx, cy, tw, th2, tl[1], "$" .. PCS_depFmt(profit * tl[2]), ac, ac, "x" .. tostring(tl[2]), tl[3], i * 0.9)
    end
    imgui.Dummy(V2(aw, th2 * 2 + gap + S(4)))
    imgui.PushTextWrapPos(0)
    imgui.TextColored(iv4(0.55, 0.55, 0.60, 1), u8"\xd0\xe5\xe0\xeb\xfc\xed\xe0\xff \xef\xf0\xe8\xe1\xfb\xeb\xfc \xec\xee\xe6\xe5\xf2 \xed\xe5\xec\xed\xee\xe3\xee \xee\xf2\xeb\xe8\xf7\xe0\xf2\xfc\xf1\xff \xe8\xe7-\xe7\xe0 \xed\xe0\xf1\xf2\xf0\xee\xe5\xea \xfd\xea\xee\xed\xee\xec\xe8\xea\xe8 \xf1\xe5\xf0\xe2\xe5\xf0\xe0 (\xf4\xe8\xea\xf1-\xef\xf0\xee\xf6\xe5\xed\xf2 \xee\xf2 \xc3\xc0/\xca\xc0).")
    imgui.PopTextWrapPos()
    imgui.Dummy(V2(0, S(8)))

    -- ════════ кнопки: из статистики / сбросить ════════
    local bw2 = (aw - gap) / 2
    if PCS_depButton("depSync", u8"\xc8\xe7 \xf1\xf2\xe0\xf2\xe8\xf1\xf2\xe8\xea\xe8", "refresh", bw2, S(38), P.a, u8"\xcf\xee\xe4\xf2\xff\xed\xf3\xf2\xfc \xe4\xe5\xef\xee\xe7\xe8\xf2, \xf0\xe0\xed\xe3 \xe8 VIP \xe8\xe7 /stats") then
        St._depLastStats = St.statsData
        St._depPendingSync = true
        if not PCS_depSyncStats() then pcall(requestStats, true) end
    end
    imgui.SameLine(0, gap)
    if PCS_depButton("depReset", u8"\xd1\xe1\xf0\xee\xf1\xe8\xf2\xfc", "trash", bw2, S(38), { 0.95, 0.35, 0.40 }, u8"\xc2\xe5\xf0\xed\xf3\xf2\xfc \xe2\xf1\xe5 \xf3\xf1\xeb\xee\xe2\xe8\xff \xea \xed\xf3\xeb\xfe") then
        for _, k in ipairs({ "vip", "lvl", "houses", "rank", "ins", "lavka", "gramota", "skin", "ring", "fix", "manual" }) do PCS_DEP[k] = 0 end
        St._depManualBuf = nil; St._depFixBuf = nil
        PCS_depSave()
    end
    imgui.Dummy(V2(0, S(10)))

    local no, yes = u8"\xcd\xe5\xf2\xf3", u8"\xc5\xf1\xf2\xfc"
    local vipNames = { u8"\xc1\xe5\xe7 VIP", "Titan", "Premium" }

    -- ════════ карточка 1: статус и ранг ════════
    PCS_depCardBegin("a", u8"\xd1\xf2\xe0\xf2\xf3\xf1 \xe8 \xf0\xe0\xed\xe3", P.a, "star")
    local _okC_a, _errC_a = pcall(function()
    PCS_depHeader(u8"\xc2\xe0\xf8 VIP \xf1\xf2\xe0\xf2\xf3\xf1", "star", u8"Premium \xe4\xe0\xb8\xf2 +50%, Titan +25%", vipNames[(PCS_DEP.vip or 0) + 1])
    PCS_depChoices("vip", { u8"\xc1\xe5\xe7 VIP", "Titan", "Premium" }, 3, P.a)
    PCS_depHeader(u8"\xcd\xee\xec\xe5\xf0 \xf0\xe0\xed\xe3\xe0 \xe2 \xee\xf0\xe3\xe0\xed\xe8\xe7\xe0\xf6\xe8\xe8", "info", u8"1-3: +15%, 4-7: +25%, 8-10: +30%", tostring(PCS_DEP.rank or 0))
    local rl = {}
    for i = 0, 10 do rl[#rl + 1] = tostring(i) end
    PCS_depChoices("rank", rl, 6, P.a)
    end)
    PCS_depCardEnd()
    if not _okC_a then PCS_quietErr("dep card a", _errC_a) end

    -- ════════ карточка 2: прокачка депозита ════════
    PCS_depCardBegin("b", u8"\xcf\xf0\xee\xea\xe0\xf7\xea\xe0 \xe4\xe5\xef\xee\xe7\xe8\xf2\xe0", P.b, "chart")
    local _okC_b, _errC_b = pcall(function()
    PCS_depHeader(u8"\xd3\xf0\xee\xe2\xe5\xed\xfc \xef\xf0\xee\xea\xe0\xf7\xe8\xe2\xe0\xe5\xec\xee\xe3\xee \xe4\xe5\xef\xee\xe7\xe8\xf2\xe0", "chart", u8"\xcf\xf0\xee\xea\xe0\xf7\xe8\xe2\xe0\xe5\xf2\xf1\xff \xe2 \xe1\xe0\xed\xea\xe5, \xf3\xf0\xee\xe2\xed\xe8 1-5 \xef\xee\xe2\xfb\xf8\xe0\xfe\xf2 \xef\xf0\xe8\xe1\xfb\xeb\xfc", tostring(PCS_DEP.lvl or 0))
    PCS_depChoices("lvl", { "0", "1", "2", "3", "4", "5" }, 6, P.b)
    PCS_depHeader(u8"\xc4\xee\xec\xe0 \xf1 \xf3\xeb\xf3\xf7\xf8\xe5\xed\xe8\xe5\xec \xe4\xe5\xef\xee\xe7\xe8\xf2\xe0", "tag", u8"\xca\xe0\xe6\xe4\xfb\xe9 \xe4\xee\xec: +$6,000,000 \xea \xec\xe0\xea\xf1\xe8\xec\xe0\xeb\xfc\xed\xee\xec\xf3 \xe4\xe5\xef\xee\xe7\xe8\xf2\xf3", tostring(PCS_DEP.houses or 0))
    local hl = {}
    for i = 0, 15 do hl[#hl + 1] = tostring(i) end
    PCS_depChoices("houses", hl, 8, P.b)
    end)
    PCS_depCardEnd()
    if not _okC_b then PCS_quietErr("dep card b", _errC_b) end

    -- ════════ карточка 3: бонусы к прибыли ════════
    PCS_depCardBegin("c", u8"\xc1\xee\xed\xf3\xf1\xfb \xea \xef\xf0\xe8\xe1\xfb\xeb\xe8", P.c, "plus")
    local _okC_c, _errC_c = pcall(function()
    PCS_depHeader(u8"\xcf\xe5\xed\xf1\xe8\xee\xed\xed\xee\xe5 \xf1\xf2\xf0\xe0\xf5\xee\xe2\xe0\xed\xe8\xe5 (+15%)", "shield", u8"\xcf\xee\xea\xf3\xef\xe0\xe5\xf2\xf1\xff \xe2 \xd1\xf2\xf0\xe0\xf5\xee\xe2\xee\xe9 \xca\xee\xec\xef\xe0\xed\xe8\xe8 \xe7\xe0 $200,000,000")
    PCS_depChoices("ins", { no, yes }, 2, P.c, true)
    PCS_depHeader(u8"\xdd\xeb\xe8\xf2\xed\xe0\xff / \xcc\xe0\xe3\xe8\xf7\xe5\xf1\xea\xe0\xff \xeb\xe0\xe2\xea\xe0 / \xd0\xfb\xe1\xe0\xf6\xea\xe8\xe9 \xf0\xfe\xea\xe7\xe0\xea (+12%)", "money")
    PCS_depChoices("lavka", { no, yes }, 2, P.c, true)
    PCS_depHeader(u8"\xc3\xf0\xe0\xec\xee\xf2\xe0 \xe2\xe5\xf2\xe5\xf0\xe0\xed\xe0 (+7%)", "note")
    PCS_depChoices("gramota", { no, yes }, 2, P.c, true)
    PCS_depHeader(u8"\xd1\xea\xe8\xed TRON (+12%)", "star")
    PCS_depChoices("skin", { no, yes }, 2, P.c, true)
    PCS_depHeader(u8"\xca\xee\xeb\xfc\xf6\xee TRON (+8%)", "plus")
    PCS_depChoices("ring", { no, yes }, 2, P.c, true)
    end)
    PCS_depCardEnd()
    if not _okC_c then PCS_quietErr("dep card c", _errC_c) end

    -- ════════ карточка 4: тонкая настройка ════════
    PCS_depCardBegin("d", u8"\xd2\xee\xed\xea\xe0\xff \xed\xe0\xf1\xf2\xf0\xee\xe9\xea\xe0", P.d, "gear")
    local _okC_d, _errC_d = pcall(function()
    PCS_depHeader(u8"\xd1\xe2\xee\xe9 \xe4\xe5\xef\xee\xe7\xe8\xf2 ($), 0 = \xe1\xf0\xe0\xf2\xfc \xe8\xe7 /stats", "edit")
    if not St._depManualBuf then St._depManualBuf = imgui.new.int(math.floor(PCS_DEP.manual or 0)) end
    imgui.PushStyleColor(imgui.Col.FrameBg,        iv4(P.d[1] * 0.16, P.d[2] * 0.16, P.d[3] * 0.16, 1.0))
    imgui.PushStyleColor(imgui.Col.FrameBgHovered, iv4(P.d[1] * 0.24, P.d[2] * 0.24, P.d[3] * 0.24, 1.0))
    imgui.PushStyleColor(imgui.Col.FrameBgActive,  iv4(P.d[1] * 0.30, P.d[2] * 0.30, P.d[3] * 0.30, 1.0))
    imgui.PushItemWidth(imgui.GetContentRegionAvail().x - S(14))
    local okI, chI = pcall(imgui.InputInt, "##depManual", St._depManualBuf, 0, 0)
    imgui.PopItemWidth()
    imgui.PopStyleColor(3)
    if okI and chI then
        PCS_DEP.manual = math.max(0, St._depManualBuf[0])
        PCS_depSave()
    end
    imgui.Dummy(V2(0, S(8)))

    PCS_depHeader(u8"\xd4\xe8\xea\xf1 \xfd\xea\xee\xed\xee\xec\xe8\xea\xe8, % (\xee\xf2 \xc3\xc0/\xca\xc0: -25..+25)", "gear", nil,
        ((PCS_DEP.fix or 0) > 0 and "+" or "") .. tostring(PCS_DEP.fix or 0) .. "%")
    if not St._depFixBuf then St._depFixBuf = imgui.new.int(math.floor(PCS_DEP.fix or 0)) end
    PCS_gdSliderStyle(true)
    imgui.PushItemWidth(imgui.GetContentRegionAvail().x - S(14))
    local okS, chS = pcall(imgui.SliderInt, "##depFix", St._depFixBuf, -25, 25, "%d%%")
    imgui.PopItemWidth()
    PCS_gdSliderStyle(false)
    if okS and chS then
        PCS_DEP.fix = St._depFixBuf[0]
        PCS_depSave()
    end
    imgui.Dummy(V2(0, S(6)))
    end)
    PCS_depCardEnd()
    if not _okC_d then PCS_quietErr("dep card d", _errC_d) end

    imgui.Dummy(V2(0, S(6)))
end

-- Депозит — отдельная вкладка (St.activeTab == 10), а не плавающее окно поверх меню
function PCS_drawDepositTab(contentH)
    imgui.PushStyleColor(imgui.Col.ChildBg, iv4(0, 0, 0, 0))
    imgui.BeginChild("##depositTab", imgui.ImVec2(0, contentH), false)
    local ok, err = PCS_GUARD.call(function()
        PCS_depLoad()
        PCS_depContent()
    end)
    imgui.EndChild()
    imgui.PopStyleColor()
    if not ok then PCS_quietErr("deposit tab", err) end
end

function PCS_drawDepositPanel()
    if not St._depositOpen then return end
    if not St._mainWinPos or not St._mainWinSize then return end
    PCS_depLoad()
    local panelW = S(440)
    local panelH = math.min(S(760), math.max(S(520), St._mainWinSize.y))
    pcall(imgui.SetNextWindowSize, imgui.ImVec2(panelW, panelH), imgui.Cond.Once)
    pcall(imgui.SetNextWindowPos, imgui.ImVec2(St._mainWinPos.x + St._mainWinSize.x + S(10), St._mainWinPos.y), imgui.Cond.Once)
    applyStyle()
    if not St._depBuf then St._depBuf = imgui.new.bool(true) end
    St._depBuf[0] = true
    local began = false
    local ok, err = pcall(function()
        local okBeg = imgui.Begin(u8"\xc4\xe5\xef\xee\xe7\xe8\xf2" .. "###depositPanel", St._depBuf, imgui.WindowFlags.NoCollapse)
        began = true
        if not okBeg then return end
        imgui.SetWindowFontScale(St.UI_SCALE * (cfg.fontSize > 0 and cfg.fontSize or 1.25))
        PCS_depContent()
    end)
    if began then pcall(imgui.End) end
    if not St._depBuf[0] then St._depositOpen = false end
    if not ok then PCS_quietErr("deposit", err) end
end

local function drawFinanceSettingsPanel()
    if not St._financeSettingsOpen then return end
    if not St._mainWinPos or not St._mainWinSize then return end

    local panelW = S(320)

    if not St._financeSettingsDetached then
        pcall(imgui.SetNextWindowPos, imgui.ImVec2(St._mainWinPos.x + St._mainWinSize.x + S(10), St._mainWinPos.y), imgui.Cond.Always)
        pcall(imgui.SetNextWindowSize, imgui.ImVec2(panelW, St._mainWinSize.y), imgui.Cond.Always)
    else
        pcall(imgui.SetNextWindowSize, imgui.ImVec2(panelW, St._mainWinSize.y), imgui.Cond.Once)
        if _financeSettingsPos then
            pcall(imgui.SetNextWindowPos, imgui.ImVec2(_financeSettingsPos.x, _financeSettingsPos.y), imgui.Cond.Once)
        else
            pcall(imgui.SetNextWindowPos, imgui.ImVec2(St._mainWinPos.x + St._mainWinSize.x + S(10), St._mainWinPos.y), imgui.Cond.Once)
        end
    end

    applyStyle()
    local flags = imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize
    local beganPanel = false
    local panelOk = pcall(function()
        local okBeg = imgui.Begin("###financeSettingsPanel", nil, flags)
        beganPanel = true
        if not okBeg then return end
        imgui.SetWindowFontScale(St.UI_SCALE * (cfg.fontSize > 0 and cfg.fontSize or 1.25))

        if St._financeSettingsDetached then
            local okP, p = pcall(imgui.GetWindowPos)
            if okP and p then _financeSettingsPos = {x = p.x, y = p.y} end
        end

        -- ── шапка панели: заголовок + кнопка "Открепить/Закрепить" ──
        do
            local aw = imgui.GetContentRegionAvail().x
            imgui.TextColored(iv4(1,1,1,1), u8"\xcd\xe0\xf1\xf2\xf0\xee\xe9\xea\xe8 \xf4\xe8\xed\xe0\xed\xf1\xee\xe2")
            imgui.SameLine(math.max(0, aw - S(104)))
            local pr,pg,pb = getAcc()
            imgui.PushStyleColor(imgui.Col.Button,        iv4(pr*0.22,pg*0.22,pb*0.22,1.0))
            imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(pr*0.40,pg*0.40,pb*0.40,1.0))
            imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(pr*0.58,pg*0.58,pb*0.58,1.0))
            local detachLbl = St._financeSettingsDetached
                and u8"\xc7\xe0\xea\xf0\xe5\xef\xe8\xf2\xfc"
                or  u8"\xce\xf2\xea\xf0\xe5\xef\xe8\xf2\xfc"
            if imgui.Button(detachLbl.."##financeDetachBtn", imgui.ImVec2(S(104), S(24))) then
                St._financeSettingsDetached = not St._financeSettingsDetached
                if St._financeSettingsDetached then
                    local okP, p = pcall(imgui.GetWindowPos)
                    if okP and p then _financeSettingsPos = {x = p.x, y = p.y} end
                end
            end
            imgui.PopStyleColor(3)
        end
        imgui.Separator()
        imgui.Spacing()

        local r, g, b = getAcc()
        drawFinanceSettingsPanelContent(r, g, b)
    end)

    if beganPanel then
        pcall(imgui.End)
    end
    if not panelOk then
        St._financeSettingsOpen = false
    end
end

-- ── кнопка-копия итога "ВСЕГО ВИРТОВ" в чат: тоже вынесена отдельно ──
function drawGrandTotalCopyButton(aw, hh, r, g, b, bigTxt)
    local btnW2, btnH2 = S(44), S(32)
