-- карточка-заголовок блока; возвращает true, если блок раскрыт
-- settings sections are now tabs (was: collapsible cards); returns true for the active tab
function PCS_settBlock(key, kind, title, desc, col, openByDefault)
    return (St._settTab or "win") == key
end

PCS_SETT_KIND = { tabs = "list", win = "gear", look = "tag", char = "star", ai = "star", notif = "bell", sound = "bell", tg = "plane", rc = "refresh", spawn = "list" }

-- высота текста t при переносе по ширине w
function PCS_textH(t, w)
    if not t or t == "" then return 0 end
    local lh = imgui.GetTextLineHeight()
    local ok, sz = pcall(imgui.CalcTextSize, t, nil, false, w)
    if ok and sz and sz.y and sz.y > 0 then return sz.y end
    return lh * math.max(1, math.ceil(#t * lh * 0.5 / math.max(w, 20)))
end

-- текст с переносом в заданной точке экрана
function PCS_textAt(x, y, w, col, t)
    imgui.SetCursorScreenPos(imgui.ImVec2(x, y))
    imgui.PushTextWrapPos(imgui.GetCursorPosX() + w)
    imgui.TextColored(col, tostring(t or ""))
    imgui.PopTextWrapPos()
end

-- карточка-секция: стикер + название + пояснение (kind — необязательно)
-- ползунок часов: значение лежит в PCS_TOAST, сохраняется отложенно
function PCS_clkSlider(key, label, mn, mx, fmt)
    local T = PCS_TOAST
    if type(T) ~= "table" then return end
    local bkey = "clkBuf_" .. key
    if not St[bkey] then St[bkey] = imgui.new.float(T[key] or 0) end
    local buf = St[bkey]
    buf[0] = T[key] or 0
    imgui.TextColored(iv4(0.70, 0.82, 1.0, 1.0), label)
    imgui.PushItemWidth(-1)
    if imgui.SliderFloat("##clk_" .. key, buf, mn, mx, fmt) then
        T[key] = buf[0]
        PCS_toastSave()
    end
    imgui.PopItemWidth()
end

-- блок «Часы на экране»: вкл/выкл, правка положения, прозрачность
-- clock tab panel: all clock settings in one block
function PCS_clockPanel()
    local T = PCS_TOAST
    if type(T) ~= "table" then return end
    if PCS_gdSliderStyle then PCS_gdSliderStyle(true) end
    local ok1, e1 = pcall(PCS_clockSettings)
    local ok2, e2 = true, nil
    if T.clock_enabled ~= false then ok2, e2 = pcall(PCS_clockLookSettings) end
    if PCS_gdSliderStyle then PCS_gdSliderStyle(false) end
    if not ok1 and PCS_TR then PCS_TR("clock settings: " .. tostring(e1)) end
    if not ok2 and PCS_TR then PCS_TR("clock look: " .. tostring(e2)) end
end

function PCS_clockSettings()
    local T = PCS_TOAST
    if type(T) ~= "table" then return end
    PCS_settSub(u8"\xd7\xe0\xf1\xfb \xed\xe0 \xfd\xea\xf0\xe0\xed\xe5", u8"\xd2\xe5\xea\xf3\xf9\xe5\xe5 \xe2\xf0\xe5\xec\xff \xe8 \xf2\xe0\xe9\xec\xe5\xf0 \xe4\xee PayDay \xef\xee\xe2\xe5\xf0\xf5 \xe8\xe3\xf0\xfb. \xc8\xf5 \xec\xee\xe6\xed\xee \xef\xe5\xf0\xe5\xf2\xe0\xf1\xea\xe8\xe2\xe0\xf2\xfc \xec\xfb\xf8\xea\xee\xe9.")
    if PCS_settToggleRow("##clkEnabledRow", T.clock_enabled ~= false, u8"\xcf\xee\xea\xe0\xe7\xfb\xe2\xe0\xf2\xfc \xf7\xe0\xf1\xfb \xed\xe0 \xfd\xea\xf0\xe0\xed\xe5",
            u8"\xc2\xfb\xea\xeb\xfe\xf7\xe8\xf2\xe5, \xe5\xf1\xeb\xe8 \xf7\xe0\xf1\xfb \xec\xe5\xf8\xe0\xfe\xf2 \xe2 \xe8\xe3\xf0\xe5.") then
        T.clock_enabled = not (T.clock_enabled ~= false)
        PCS_toastSave()
    end
    if T.clock_enabled == false then return end
    imgui.Spacing()
    if PCS_gdButton(u8"\xd0\xe5\xe4\xe0\xea\xf2\xe8\xf0\xee\xe2\xe0\xf2\xfc \xef\xee\xeb\xee\xe6\xe5\xed\xe8\xe5##clkEdit", imgui.GetContentRegionAvail().x, S(34), { 0.30, 0.60, 0.95 }, 8.0) then
        PCS_clkEditStart()
    end
    PCS_settHint(u8"\xcc\xe5\xed\xfe \xf1\xea\xf0\xee\xe5\xf2\xf1\xff, \xe0 \xe2\xed\xe8\xe7\xf3 \xfd\xea\xf0\xe0\xed\xe0 \xef\xee\xff\xe2\xff\xf2\xf1\xff \xab\xce\xf2\xec\xe5\xed\xe0\xbb \xe8 \xab\xd1\xee\xf5\xf0\xe0\xed\xe8\xf2\xfc\xbb. \xd7\xe0\xf1\xfb \xe4\xe2\xe8\xe3\xe0\xfe\xf2\xf1\xff \xcb\xca\xcc \xe8\xeb\xe8 \xcf\xca\xcc; \xef\xf0\xe8 \xee\xf2\xea\xf0\xfb\xf2\xee\xec \xec\xe5\xed\xfe \x97 \xcf\xca\xcc.")
    imgui.Spacing()
    PCS_clkSlider("clock_alpha", u8"\xcf\xf0\xee\xe7\xf0\xe0\xf7\xed\xee\xf1\xf2\xfc \xf7\xe0\xf1\xee\xe2", 0.10, 1.0, "%.2f")
    PCS_settHint(u8"1.00 \x97 \xf7\xe0\xf1\xfb \xef\xee\xeb\xed\xee\xf1\xf2\xfc\xfe \xe2\xe8\xe4\xed\xfb, \xec\xe5\xed\xfc\xf8\xe5 \x97 \xf4\xee\xed \xe8 \xf2\xe5\xea\xf1\xf2 \xf1\xf2\xe0\xed\xee\xe2\xff\xf2\xf1\xff \xef\xf0\xee\xe7\xf0\xe0\xf7\xed\xe5\xe5.")
end

-- блок «Вид часов»: цвет, размер и положение
function PCS_clockLookSettings()
    local T = PCS_TOAST
    if type(T) ~= "table" then return end
    PCS_settSub(u8"\xc2\xe8\xe4 \xf7\xe0\xf1\xee\xe2", u8"\xd6\xe2\xe5\xf2, \xf0\xe0\xe7\xec\xe5\xf0 \xe8 \xec\xe5\xf1\xf2\xee, \xe3\xe4\xe5 \xf1\xf2\xee\xff\xf2 \xf7\xe0\xf1\xfb. \xcf\xee\xeb\xee\xe6\xe5\xed\xe8\xe5 \xec\xee\xe6\xed\xee \xe7\xe0\xe4\xe0\xf2\xfc \xe8 \xef\xee\xeb\xe7\xf3\xed\xea\xe0\xec\xe8.")
    if PCS_settToggleRow("##clkColorRow", T.clock_useAcc == true, u8"\xd6\xe2\xe5\xf2 \xea\xe0\xea \xf3 \xec\xe5\xed\xfe \xf1\xea\xf0\xe8\xef\xf2\xe0",
            u8"\xc2\xea\xeb\xfe\xf7\xe5\xed\xee: \xf7\xe0\xf1\xfb \xe1\xe5\xf0\xf3\xf2 \xee\xf1\xed\xee\xe2\xed\xee\xe9 \xf6\xe2\xe5\xf2 \xec\xe5\xed\xfe \xe8 \xec\xe5\xed\xff\xfe\xf2\xf1\xff \xe2\xec\xe5\xf1\xf2\xe5 \xf1 \xed\xe8\xec. \xc2\xfb\xea\xeb\xfe\xf7\xe5\xed\xee: \xf1\xe2\xee\xe9 \xf6\xe2\xe5\xf2 \xed\xe8\xe6\xe5.") then
        T.clock_useAcc = not (T.clock_useAcc == true)
        PCS_toastSave()
    end
    if T.clock_useAcc ~= true then
        if not St.clkColBuf then
            St.clkColBuf = imgui.new.float[3](T.clock_r or 0.43, T.clock_g or 0.71, T.clock_b or 1.0)
        end
        local cf = 0
        pcall(function() cf = imgui.ColorEditFlags.NoInputs + imgui.ColorEditFlags.NoLabel + (imgui.ColorEditFlags.PickerHueBar or 0) end)
        imgui.TextColored(iv4(0.70, 0.82, 1.0, 1.0), u8"\xd1\xe2\xee\xe9 \xf6\xe2\xe5\xf2 \xf7\xe0\xf1\xee\xe2")
        imgui.SameLine(0, S(10))
        if imgui.ColorEdit3("##clkCol", St.clkColBuf, cf) then
            T.clock_r, T.clock_g, T.clock_b = St.clkColBuf[0], St.clkColBuf[1], St.clkColBuf[2]
            PCS_toastSave()
        end
    end
    imgui.Spacing()
    PCS_clkSlider("clock_scale", u8"\xd0\xe0\xe7\xec\xe5\xf0", 0.6, 2.0, "%.2f")
    PCS_clkSlider("clock_x", u8"\xcf\xee\xeb\xee\xe6\xe5\xed\xe8\xe5 \xef\xee \xe3\xee\xf0\xe8\xe7\xee\xed\xf2\xe0\xeb\xe8", 0, 1, "%.2f")
    PCS_clkSlider("clock_y", u8"\xcf\xee\xeb\xee\xe6\xe5\xed\xe8\xe5 \xef\xee \xe2\xe5\xf0\xf2\xe8\xea\xe0\xeb\xe8", 0, 1, "%.2f")
end

function PCS_settSubClassic(title, desc, kind)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local r, g, b = getAcc()
    kind = kind or PCS_SETT_KIND[St._settTab or "win"] or "gear"
    imgui.Spacing()
    local dl = imgui.GetWindowDrawList()
    local aw = imgui.GetContentRegionAvail().x
    local p = imgui.GetCursorScreenPos()
    local pad, stkW = S(10), S(40)
    local tw = math.max(S(40), aw - stkW - pad)
    local th = PCS_textH(tostring(title or ""), tw)
    local dh = (desc and desc ~= "") and PCS_textH(desc, tw) or 0
    local h = math.max(S(40), pad + th + (dh > 0 and (S(3) + dh) or 0) + pad)
    imgui.Dummy(V2(aw, h))
    local hov = imgui.IsItemHovered()
    local q = V2(p.x + aw, p.y + h)
    dl:AddRectFilled(p, q, U32(iv4(r * 0.13, g * 0.13, b * 0.13, pcsRowA(0.96))), S(10))
    dl:AddRect(p, q, U32(iv4(r * 0.55, g * 0.55, b * 0.55, 0.65)), S(10), 0, 1.1)
    dl:AddRectFilled(V2(p.x + S(1), p.y + S(8)), V2(p.x + S(4), p.y + h - S(8)), U32(iv4(r, g, b, 1.0)), S(2))
    local ang, dy, sc = PCS_stickerAnim(hov, 0.4)
    PCS_drawSticker(dl, kind, p.x + S(8) + S(14), p.y + h * 0.5 + dy, S(9.5) * sc, ang)
    PCS_textAt(p.x + stkW, p.y + pad, tw, iv4(r * 0.45 + 0.55, g * 0.45 + 0.55, b * 0.45 + 0.55, 1.0), title)
    if dh > 0 then
        PCS_textAt(p.x + stkW, p.y + pad + th + S(3), tw, thDim(), desc)
    end
    imgui.SetCursorScreenPos(V2(p.x, p.y + h))
    imgui.Dummy(V2(1, S(6)))
end

-- пояснение (серым, с переносом строк) под элементом настроек
function PCS_settHint(desc)
    imgui.Indent(S(10))
    imgui.PushStyleColor(imgui.Col.Text, thDim())
    imgui.TextWrapped(desc)
    imgui.PopStyleColor()
    imgui.Unindent(S(10))
    imgui.Dummy(imgui.ImVec2(0, S(4)))
end

-- строка-карточка «тумблер + название + пояснение»; true при клике.
-- cfg.settToggleAlign: "top" — тумблер слева, "bottom" — справа
function PCS_settToggleRowClassic(id, isOn, label, desc)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local r, g, b = getAcc()
    local left = not (cfg and cfg.settToggleAlign == "bottom")
    local dl = imgui.GetWindowDrawList()
    local aw = imgui.GetContentRegionAvail().x
    local p = imgui.GetCursorScreenPos()
    local pad = S(10)
    local swW, swH = S(34), S(18)
    local tw = math.max(S(40), aw - swW - pad * 3)
    label = tostring(label or "")
    local lblH = PCS_textH(label, tw)
    local dh = (desc and desc ~= "") and PCS_textH(desc, tw) or 0
    local h = math.max(S(40), pad + lblH + (dh > 0 and (S(2) + dh) or 0) + pad)
    imgui.Dummy(V2(aw, h))
    local hov = imgui.IsItemHovered()
    local q = V2(p.x + aw, p.y + h)
    local k = hov and 0.17 or 0.11
    dl:AddRectFilled(p, q, U32(iv4(r * k, g * k, b * k, pcsRowA(0.95))), S(10))
    if isOn then
        dl:AddRect(p, q, U32(iv4(0.25, 0.85, 0.45, hov and 0.80 or 0.50)), S(10), 0, 1.2)
        dl:AddRectFilled(V2(p.x + S(1), p.y + S(8)), V2(p.x + S(4), p.y + h - S(8)), U32(iv4(0.25, 0.88, 0.48, 1.0)), S(2))
    else
        dl:AddRect(p, q, U32(iv4(r * 0.45, g * 0.45, b * 0.45, hov and 0.80 or 0.50)), S(10), 0, 1.2)
        dl:AddRectFilled(V2(p.x + S(1), p.y + S(8)), V2(p.x + S(4), p.y + h - S(8)), U32(iv4(0.80, 0.25, 0.25, 0.85)), S(2))
    end
    local tx, sx
    if left then
        sx = p.x + pad + S(4)
        tx = sx + swW + pad
    else
        tx = p.x + pad + S(4)
        sx = p.x + aw - pad - swW
    end
    PCS_textAt(tx, p.y + pad, tw - S(4), iv4(1, 1, 1, 1), label)
    if dh > 0 then
        PCS_textAt(tx, p.y + pad + lblH + S(2), tw - S(4), thDim(), desc)
    end
    imgui.SetCursorScreenPos(V2(sx, p.y + (h - swH) * 0.5))
    local clicked = drawToggleSwitch(id, isOn)
    imgui.SetCursorScreenPos(V2(p.x, p.y + h))
    imgui.Dummy(V2(1, S(5)))
    return clicked
end

-- ── карточка с динамической высотой (фон рисуется ПОСЛЕ содержимого
-- через ChannelsSplit; если каналы недоступны — только рамка) ──
function PCS_cardW()
    return imgui.GetContentRegionAvail().x - (PCS_CARD and PCS_CARD.pad or 0)
end

function PCS_cardBegin(c)
    if PCS_CARD then return nil end
    local V2 = imgui.ImVec2
    local dl = imgui.GetWindowDrawList()
    local okS = pcall(function() dl:ChannelsSplit(2) end)
    local card = { dl = dl, p = imgui.GetCursorScreenPos(), aw = imgui.GetContentRegionAvail().x,
                   split = okS, c = c or { 0.5, 0.6, 0.9 }, pad = S(12) }
    if okS then dl:ChannelsSetCurrent(1) end
    local okBegin = pcall(imgui.BeginGroup)
    if not okBegin then
        if card.split then pcall(function() card.dl:ChannelsMerge() end) end
        return nil
    end
    PCS_CARD = card
    pcall(function()
        imgui.Dummy(V2(1, card.pad - S(4)))
        imgui.Indent(card.pad)
    end)
    return card
end

function PCS_cardEnd(card)
    if not card then return end
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    imgui.Unindent(card.pad)
    imgui.Dummy(V2(1, card.pad - S(6)))
    imgui.EndGroup()
    local c = card.c
    local mn = card.p
    local mx = V2(card.p.x + card.aw, imgui.GetItemRectMax().y)
    if card.split then
        card.dl:ChannelsSetCurrent(0)
        card.dl:AddRectFilled(mn, mx, U32(iv4(c[1] * 0.08, c[2] * 0.08, c[3] * 0.08, pcsRowA(0.94))), S(12))
        card.dl:AddRect(mn, mx, U32(iv4(c[1] * 0.60, c[2] * 0.60, c[3] * 0.60, 0.65)), S(12), 0, 1.2)
        card.dl:ChannelsMerge()
    else
        card.dl:AddRect(mn, mx, U32(iv4(c[1] * 0.60, c[2] * 0.60, c[3] * 0.60, 0.65)), S(12), 0, 1.2)
    end
    PCS_CARD = nil
    imgui.Dummy(V2(1, S(6)))
end

function PCS_cardFlush()
    if PCS_CARD then
        pcall(function() PCS_CARD.dl:ChannelsMerge() end)
        PCS_CARD = nil
    end
end

-- безопасная карточка: fn() всегда завершается корректным End
function PCS_card(c, fn)
    local card = PCS_cardBegin(c)
    local ok, err = pcall(fn)
    PCS_cardEnd(card)
    if not ok then print("[PC Stats][card] " .. tostring(err)) end
end

function PCS_settFold(key, title, desc)
    local O = St._settOpen
    if O[key] == nil then O[key] = false end
    local r, g, b = getAcc()
    local lbl = (O[key] and "v  " or ">  ") .. title
    if PCS_gdButton(lbl .. "##fold" .. key, imgui.GetContentRegionAvail().x, S(28), { r, g, b }, 6.0) then
        O[key] = not O[key]
    end
    if desc and desc ~= "" then PCS_settHint(desc) end
    return O[key]
end

-- ── значок сервера: цвет по названию (не официальный логотип) + название ──
function PCS_serverColor(name)
    local h = 0
    for i = 1, #name do h = (h * 31 + name:byte(i)) % 360 end
    return hsv2rgb(h / 360, 0.55, 0.95)
end

-- ── иконки серверов: PNG 64x64, встроены в скрипт (base64) ──
-- Чтобы добавить сервер: ARZ_SERVER_ICON["Название"] = "<base64 PNG>"
ARZ_SERVER_ICON = ARZ_SERVER_ICON or {
    ["Brainburg"] = "",
    ["Bumble Bee"] = "",
    ["Casa Grande"] = "",
    ["Chandler"] = "",
    ["Christmas"] = "",
    ["Drake"] = "",
    ["Faraway"] = "",
    ["Gilbert"] = "",
    ["Glendale"] = "",
    ["Holiday"] = "",
    ["Kingman"] = "",
    ["Love"] = "",
    ["Mesa"] = "",
    ["Mirage"] = "",
    ["Page"] = "",
    ["Payson"] = "",
    ["Phoenix"] = "",
    ["Prescott"] = "",
    ["Queen Creek"] = "",
    ["Red Rock"] = "",
    ["Saint Rose"] = "",
    ["Scottdale"] = "",
    ["Sedona"] = "",
    ["Show Low"] = "",
    ["Space"] = "",
    ["Sun City"] = "",
    ["Surprise"] = "",
    ["Tucson"] = "",
    ["Wednesday"] = "",
    ["Winslow"] = "",
    ["Yava"] = "",
    ["Yuma"] = "",
}
PCS_SRV_ICON_TEX = PCS_SRV_ICON_TEX or {}

function PCS_serverIconTex(name)
    if not name or not ARZ_SERVER_ICON[name] then return nil end
    if PCS_TEX_NO_RECREATE or PCS_TEX_DEAD_SESSION then return nil end
    if PCS_texQuiet() then return nil end
    local cached = PCS_SRV_ICON_TEX[name]
    if cached then return cached end
    if cached == false then return nil end
    if not imgui or not imgui.CreateTextureFromFileInMemory then PCS_SRV_ICON_TEX[name] = false; return nil end
    local okD, raw = pcall(b64decode, ARZ_SERVER_ICON[name])
    if not okD or type(raw) ~= "string" or #raw < 50 then PCS_SRV_ICON_TEX[name] = false; return nil end
    local okT, tex = pcall(imgui.CreateTextureFromFileInMemory, raw, #raw)
    if not okT or not tex then PCS_SRV_ICON_TEX[name] = false; return nil end
    PCS_SRV_ICON_TEX[name] = tex
    PCS_TEX_QUIET_UNTIL = math.max(PCS_TEX_QUIET_UNTIL or 0, os.clock() + 1.5)
    return nil
end

function PCS_serverBadge(name, sz, showName)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    sz = sz or S(26)
    local r, g, b = PCS_serverColor(name)
    local drawn = false
    local tex = PCS_serverIconTex(name)
    if tex then drawn = pcall(imgui.Image, tex, V2(sz, sz)) end
    if not drawn then
        local p = imgui.GetCursorScreenPos()
        local c = V2(p.x + sz * 0.5, p.y + sz * 0.5)
        dl:AddCircleFilled(c, sz * 0.5 + S(3), U32(iv4(r, g, b, 0.25)), 32)
        dl:AddCircleFilled(c, sz * 0.5, U32(iv4(r, g, b, 1.0)), 32)
        dl:AddCircle(c, sz * 0.5, U32(iv4(1, 1, 1, 0.85)), 32, 1.5)
        local letter = name:sub(1, 1):upper()
        local ls = imgui.CalcTextSize(letter)
        dl:AddText(V2(c.x - ls.x * 0.5, c.y - ls.y * 0.5), U32(iv4(1, 1, 1, 1)), letter)
        imgui.Dummy(V2(sz, sz))
    end
    if showName ~= false then
        imgui.SameLine(0, S(8))
        imgui.TextColored(iv4(0.55 + r * 0.45, 0.55 + g * 0.45, 0.55 + b * 0.45, 1.0), name)
    end
end

-- содержимое блока "Вкладки": включить/выключить показ вкладок в верхней панели
function PCS_drawTabsVisibility()
    if type(cfg.hiddenTabs) ~= "table" then cfg.hiddenTabs = {} end
    imgui.PushStyleColor(imgui.Col.Text, thDim())
    imgui.TextWrapped(u8"\xc2\xfb\xea\xeb\xfe\xf7\xe8\xf2\xe5 \xe2\xea\xeb\xe0\xe4\xea\xe8, \xea\xee\xf2\xee\xf0\xfb\xec\xe8 \xed\xe5 \xef\xee\xeb\xfc\xe7\xf3\xe5\xf2\xe5\xf1\xfc: \xee\xed\xe8 \xef\xf0\xee\xef\xe0\xe4\xf3\xf2 \xe8\xe7 \xe2\xe5\xf0\xf5\xed\xe5\xe9 \xef\xe0\xed\xe5\xeb\xe8. \xc2\xea\xeb\xe0\xe4\xea\xf3 \xab\xcd\xe0\xf1\xf2\xf0\xee\xe9\xea\xe8\xbb \xf1\xea\xf0\xfb\xf2\xfc \xed\xe5\xeb\xfc\xe7\xff \x97 \xf7\xe5\xf0\xe5\xe7 \xed\xe5\xb8 \xe2\xfb \xe2\xf1\xe5\xe3\xe4\xe0 \xf1\xec\xee\xe6\xe5\xf2\xe5 \xe2\xe5\xf0\xed\xf3\xf2\xfc \xee\xf1\xf2\xe0\xeb\xfc\xed\xfb\xe5.")
    imgui.PopStyleColor()
    imgui.Spacing()
    for _, t in ipairs(PCS_TAB_LIST) do
        local id = t[1]
        local isOn = cfg.hiddenTabs[id] ~= true
        if PCS_settToggleRow("##tabvis" .. id, isOn, t[2], t[3]) then
            if isOn then cfg.hiddenTabs[id] = true else cfg.hiddenTabs[id] = nil end
            saveCfg()
        end
    end
    if next(cfg.hiddenTabs) ~= nil then
        if PCS_gdButton(u8"\xcf\xee\xea\xe0\xe7\xe0\xf2\xfc \xe2\xf1\xe5 \xe2\xea\xeb\xe0\xe4\xea\xe8##tabvisAll", imgui.GetContentRegionAvail().x, S(28), { 0.30, 0.65, 0.95 }, 6.0) then
            cfg.hiddenTabs = {}
            saveCfg()
        end
    end
    if PCS_settToggleRow("##aisHideSw", cfg.aisHidden ~= true,
        u8"\xcc\xee\xe4\xf3\xeb\xfc \xee\xf5\xf0\xe0\xed\xed\xe8\xea\xee\xe2 (AIS)",
        u8"\xc2\xfb\xea\xeb\xfe\xf7\xe0\xe5\xf2 \xe2\xea\xeb\xe0\xe4\xea\xf3 \xab\xce\xf5\xf0\xe0\xed\xed\xe8\xea\xbb \xe8 \xea\xee\xec\xe0\xed\xe4\xfb /ais, /sppet \xe8 \xf2.\xe4.") then
        cfg.aisHidden = not (cfg.aisHidden == true)
        PCS_AIS_HIDDEN = cfg.aisHidden
        saveCfg()
    end
    imgui.Spacing()
end

-- Панель "Меню" (открывается шестерёнкой в шапке): расположение вкладок + видимость вкладок
function PCS_drawMenuSettings()
    PCS_settSub(u8"\xc2\xe8\xe4 \xec\xe5\xed\xfe", u8"\xca\xe0\xea \xef\xee\xea\xe0\xe7\xfb\xe2\xe0\xfe\xf2\xf1\xff \xe2\xea\xeb\xe0\xe4\xea\xe8: \xee\xe4\xed\xe8\xec \xf0\xff\xe4\xee\xec \xea\xed\xee\xef\xee\xea \xf1\xe2\xe5\xf0\xf5\xf3 (\xea\xe0\xea \xf0\xe0\xed\xfc\xf8\xe5) \xe8\xeb\xe8 \xe1\xee\xea\xee\xe2\xfb\xec \xec\xe5\xed\xfe \xf1\xeb\xe5\xe2\xe0.")
    local aw = imgui.GetContentRegionAvail().x
    local side = cfg.sidebarLayout == true
    if PCS_fancyToolBtn("##menuLayoutTop", "", u8"\xca\xed\xee\xef\xea\xe8 \xf1\xe2\xe5\xf0\xf5\xf3", u8"\xca\xe0\xea \xe2 \xf1\xf2\xe0\xf0\xee\xe9 \xe2\xe5\xf0\xf1\xe8\xe8", aw, S(46),
            { 0.43, 0.71, 1.0 }, not side, nil, "list") then
        if side then
            cfg.sidebarLayout = false
            St._resetCharScroll = true; St._resetSettScroll = true
            saveCfg()
        end
    end
    imgui.Dummy(imgui.ImVec2(0, S(4)))
    if PCS_fancyToolBtn("##menuLayoutSide", "", u8"\xc1\xee\xea\xee\xe2\xee\xe5 \xec\xe5\xed\xfe", u8"\xd0\xe0\xe7\xe4\xe5\xeb\xfb \xf1\xeb\xe5\xe2\xe0, \xef\xee\xe4-\xe2\xea\xeb\xe0\xe4\xea\xe8 \xf1\xe2\xe5\xf0\xf5\xf3", aw, S(46),
            { 0.95, 0.55, 0.25 }, side, nil, "tag") then
        if not side then
            cfg.sidebarLayout = true
            St._resetCharScroll = true; St._resetSettScroll = true
            saveCfg()
        end
    end
    imgui.Spacing()
    if side then
        if PCS_settToggleRow("##menuCollapseSw", cfg.sidebarCollapsed == true, u8"\xca\xee\xec\xef\xe0\xea\xf2\xed\xee\xe5 \xe1\xee\xea\xee\xe2\xee\xe5 \xec\xe5\xed\xfe",
                u8"\xcf\xee\xea\xe0\xe7\xfb\xe2\xe0\xf2\xfc \xe2 \xe1\xee\xea\xee\xe2\xee\xec \xec\xe5\xed\xfe \xf2\xee\xeb\xfc\xea\xee \xe7\xed\xe0\xf7\xea\xe8, \xe1\xe5\xe7 \xef\xee\xe4\xef\xe8\xf1\xe5\xe9. \xd1\xe2\xe5\xf0\xed\xf3\xf2\xfc \xec\xee\xe6\xed\xee \xe8 \xea\xed\xee\xef\xea\xee\xe9 \xe2 \xf1\xe0\xec\xee\xec \xec\xe5\xed\xfe.") then
            cfg.sidebarCollapsed = not (cfg.sidebarCollapsed == true)
            saveCfg()
        end
    end
    imgui.Dummy(imgui.ImVec2(0, S(6)))
    -- расположение тумблеров в блоках настроек
    imgui.Dummy(imgui.ImVec2(0, S(6)))
    imgui.TextColored(iv4(0.70, 0.82, 1.0, 1.0), u8"\xd2\xf3\xec\xe1\xeb\xe5\xf0\xfb \xe2 \xe1\xeb\xee\xea\xe0\xf5 \xed\xe0\xf1\xf2\xf0\xee\xe5\xea:")
    do
        local r, g, b = getAcc()
        local gap = S(6)
        local bw = math.floor((imgui.GetContentRegionAvail().x - gap) / 2)
        local topOn = (cfg.settToggleAlign or "top") ~= "bottom"
        local colT = topOn and { r, g, b } or { 0.40, 0.42, 0.50 }
        local colB = (not topOn) and { r, g, b } or { 0.40, 0.42, 0.50 }
        if PCS_gdButton(u8"\xd1\xe2\xe5\xf0\xf5\xf3##settToggleAlignTop", bw, S(28), colT, 6.0) then
            cfg.settToggleAlign = "top"; saveCfg()
        end
        imgui.SameLine(0, gap)
        if PCS_gdButton(u8"\xd1\xed\xe8\xe7\xf3##settToggleAlignBot", bw, S(28), colB, 6.0) then
            cfg.settToggleAlign = "bottom"; saveCfg()
        end
        imgui.TextColored(thDim(), "  " .. u8"\xc3\xe4\xe5 \xe2 \xea\xe0\xf0\xf2\xee\xf7\xea\xe5 \xf1\xf2\xee\xff\xf2 \xef\xe5\xf0\xe5\xea\xeb\xfe\xf7\xe0\xf2\xe5\xeb\xe8")
    end

    PCS_settSub(u8"\xcf\xee\xea\xe0\xe7 \xe2\xea\xeb\xe0\xe4\xee\xea", u8"\xca\xe0\xea\xe8\xe5 \xe2\xea\xeb\xe0\xe4\xea\xe8 \xef\xee\xea\xe0\xe7\xfb\xe2\xe0\xf2\xfc \xe2 \xec\xe5\xed\xfe.")
    PCS_drawTabsVisibility()
end

PCS_SETT_TABS = {
    { "tabs",  u8"\xcc\xe5\xed\xfe",         { 0.43, 0.71, 1.0 },  "list" },
    { "win",   u8"\xce\xea\xed\xee \xe8 \xf8\xf0\xe8\xf4\xf2",  { 0.52, 0.62, 0.85 }, "gear" },
    { "look",  u8"\xd6\xe2\xe5\xf2\xe0",         { 0.95, 0.55, 0.25 }, "tag" },
    { "char",  u8"\xcf\xe5\xf0\xf1\xee\xed\xe0\xe6",      { 0.75, 0.45, 1.0 },  "star" },
    { "notif", u8"\xd3\xe2\xe5\xe4\xee\xec\xeb\xe5\xed\xe8\xff",   { 1.0, 0.72, 0.16 },  "bell" },
    { "sound", u8"\xc7\xe2\xf3\xea\xe8",   { 1.0, 0.60, 0.90 },  "bell" },
    { "tg",    "Telegram",       { 0.30, 0.65, 0.95 }, "plane" },
    { "rc",    "Реконнект",      { 0.25, 0.90, 0.80 }, "refresh" },
    { "spawn", "Спавн",          { 0.40, 0.75, 1.00 }, "list" },
    { "clock", u8"\xd7\xe0\xf1\xfb",        { 0.43, 0.71, 1.0 },  "clock" },
    { "keys",  u8"\xca\xee\xec\xe0\xed\xe4\xfb\x20\xe8\x20\xea\xeb\xe0\xe2\xe8\xf8\xe8", { 0.35, 0.80, 0.60 }, "gear" },
}

function PCS_drawSettingsTabRowClassic()
    if not St._settTab then St._settTab = "win" end
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local aw = imgui.GetContentRegionAvail().x
    local perRow = (aw >= S(720)) and 6 or ((aw >= S(330)) and 3 or 2)
    local gap = S(6)
    local tw = math.floor((aw - gap * (perRow - 1)) / perRow)
    local th = S(42)
    for i, t in ipairs(PCS_SETT_TABS) do
        if (i - 1) % perRow ~= 0 then imgui.SameLine(0, gap) end
        local act = (St._settTab == t[1])
        local c = t[3]
        local p = imgui.GetCursorScreenPos()
        imgui.InvisibleButton("##stab" .. t[1], V2(tw, th))
        local hov, clicked = imgui.IsItemHovered(), imgui.IsItemClicked()
        local q = V2(p.x + tw, p.y + th)
        local k = act and 0.30 or (hov and 0.22 or 0.12)
        dl:AddRectFilled(p, q, U32(iv4(c[1] * k, c[2] * k, c[3] * k, 0.97)), S(10))
        dl:AddRect(p, q, U32(iv4(c[1], c[2], c[3], act and 0.95 or (hov and 0.65 or 0.35))), S(10), 0, act and 1.7 or 1.1)
        if act then
            dl:AddRectFilled(V2(p.x + S(14), q.y - S(3)), V2(q.x - S(14), q.y - S(1)), U32(iv4(c[1], c[2], c[3], 1.0)), S(2))
        end
        local ang, dy, sc = PCS_stickerAnim(hov or act, i * 0.8)
        PCS_drawSticker(dl, t[4], p.x + S(20), p.y + th * 0.5 + dy, S(8.5) * sc, ang)
        local ts = imgui.CalcTextSize(t[2])
        dl:PushClipRect(V2(p.x + S(36), p.y), q, true)
        dl:AddText(V2(p.x + S(37), p.y + (th - ts.y) * 0.5),
            U32(act and iv4(1, 1, 1, 1) or iv4(0.82, 0.85, 0.92, 0.95)), t[2])
        dl:PopClipRect()
        if clicked then
            if St._settTab ~= t[1] then St._resetSettScroll = true end
            St._settTab = t[1]
        end
    end
    imgui.Spacing()
end

function PCS_newLook()
    return not (cfg and cfg.settNewLook == false) and not PCS_NEWLOOK_FAILED
end

function PCS_nlFail(where, err)
    PCS_NEWLOOK_FAILED = true
    pcall(function() if PCS_TR then PCS_TR("newlook " .. where .. ": " .. tostring(err)) end end)
    print("[PC Stats] new settings look disabled (" .. where .. "): " .. tostring(err))
end

function PCS_settSubNew(title, desc, kind)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local r, g, b = getAcc()
    kind = kind or PCS_SETT_KIND[St._settTab or "win"] or "gear"
    imgui.Spacing()
    local dl = imgui.GetWindowDrawList()
    local aw = imgui.GetContentRegionAvail().x
    local p = imgui.GetCursorScreenPos()
    local pad, badge = S(12), S(38)
    local txX = pad + badge + S(10)
    local tw = math.max(S(40), aw - txX - pad)
    local th = PCS_textH(tostring(title or ""), tw)
    local dh = (desc and desc ~= "") and PCS_textH(desc, tw) or 0
    local h = math.max(S(54), pad + th + (dh > 0 and (S(4) + dh) or 0) + pad)
    imgui.Dummy(V2(aw, h))
    local hov = imgui.IsItemHovered()
    local q = V2(p.x + aw, p.y + h)
    dl:AddRectFilled(p, q, U32(iv4(r * 0.08, g * 0.08, b * 0.08, pcsRowA(0.97))), S(14))
    dl:PushClipRect(p, q, true)
    dl:AddCircleFilled(V2(p.x + aw - S(26), p.y + h * 0.5), S(72), U32(iv4(r, g, b, hov and 0.15 or 0.09)), 48)
    dl:AddCircleFilled(V2(p.x + aw - S(26), p.y + h * 0.5), S(40), U32(iv4(r, g, b, 0.10)), 48)
    dl:AddRectFilled(V2(p.x + S(18), q.y - S(4)), V2(p.x + S(18) + aw * 0.30, q.y - S(2)), U32(iv4(r, g, b, 0.90)), S(2))
    dl:PopClipRect()
    dl:AddRect(p, q, U32(iv4(r * 0.65, g * 0.65, b * 0.65, hov and 0.95 or 0.65)), S(14), 0, 1.2)
    local cx, cy = p.x + pad + badge * 0.5, p.y + h * 0.5
    dl:AddCircleFilled(V2(cx, cy), badge * 0.5, U32(iv4(r * 0.30, g * 0.30, b * 0.30, 1.0)), 32)
    dl:AddCircle(V2(cx, cy), badge * 0.5, U32(iv4(r, g, b, 0.85)), 32, 1.3)
    local ang, dy, sc = PCS_stickerAnim(hov, 0.4)
    PCS_drawSticker(dl, kind, cx, cy + dy, S(9.5) * sc, ang)
    PCS_textAt(p.x + txX, p.y + pad, tw, iv4(r * 0.30 + 0.70, g * 0.30 + 0.70, b * 0.30 + 0.70, 1.0), title)
    if dh > 0 then
        PCS_textAt(p.x + txX, p.y + pad + th + S(4), tw, thDim(), desc)
    end
    imgui.SetCursorScreenPos(V2(p.x, p.y + h))
    imgui.Dummy(V2(1, S(8)))
end

function PCS_settSub(title, desc, kind)
    if PCS_newLook() then
        local ok, err = pcall(PCS_settSubNew, title, desc, kind)
        if ok then return end
        PCS_nlFail("sub", err)
    end
    return PCS_settSubClassic(title, desc, kind)
end

function PCS_settToggleRowNew(id, isOn, label, desc)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local r, g, b = getAcc()
    local left = not (cfg and cfg.settToggleAlign == "bottom")
    local dl = imgui.GetWindowDrawList()
    local aw = imgui.GetContentRegionAvail().x
    local p = imgui.GetCursorScreenPos()
    local pad = S(12)
    local swW, swH = S(34), S(18)
    local chipTxt = isOn and u8"\xc2\xca\xcb" or u8"\xc2\xdb\xca\xcb"
    local cs = imgui.CalcTextSize(chipTxt)
    local chipW, chipH = cs.x + S(16), cs.y + S(6)
    local tw = math.max(S(40), aw - swW - chipW - pad * 4 - S(8))
    label = tostring(label or "")
    local lblH = PCS_textH(label, tw)
    local dh = (desc and desc ~= "") and PCS_textH(desc, tw) or 0
    local h = math.max(S(44), pad + lblH + (dh > 0 and (S(3) + dh) or 0) + pad)
    imgui.Dummy(V2(aw, h))
    local hov = imgui.IsItemHovered()
    local q = V2(p.x + aw, p.y + h)
    local k = hov and 0.14 or 0.09
    local cr, cg, cb = 0.25, 0.88, 0.48
    if not isOn then cr, cg, cb = 0.85, 0.30, 0.30 end
    dl:AddRectFilled(p, q, U32(iv4(r * k, g * k, b * k, pcsRowA(0.97))), S(12))
    dl:PushClipRect(p, q, true)
    local gx = left and (p.x + S(20)) or (q.x - S(20))
    dl:AddCircleFilled(V2(gx, p.y + h * 0.5), S(46), U32(iv4(cr, cg, cb, isOn and 0.12 or 0.07)), 40)
    dl:PopClipRect()
    dl:AddRect(p, q, U32(iv4(isOn and 0.25 or r * 0.5, isOn and 0.85 or g * 0.5, isOn and 0.45 or b * 0.5, hov and 0.85 or 0.55)), S(12), 0, 1.2)
    local tx, sx, chx
    if left then
        sx = p.x + pad
        tx = sx + swW + pad
        chx = q.x - pad - chipW
    else
        tx = p.x + pad
        sx = q.x - pad - swW
        chx = sx - pad - chipW
    end
    PCS_textAt(tx, p.y + pad, tw, iv4(1, 1, 1, 1), label)
    if dh > 0 then
        PCS_textAt(tx, p.y + pad + lblH + S(3), tw, thDim(), desc)
    end
    local cy0 = p.y + (h - chipH) * 0.5
    dl:AddRectFilled(V2(chx, cy0), V2(chx + chipW, cy0 + chipH), U32(iv4(cr * 0.30, cg * 0.30, cb * 0.30, 0.95)), S(8))
    dl:AddRect(V2(chx, cy0), V2(chx + chipW, cy0 + chipH), U32(iv4(cr, cg, cb, 0.75)), S(8), 0, 1.0)
    dl:AddText(V2(chx + S(8), cy0 + S(3)), U32(iv4(cr * 0.4 + 0.6, cg * 0.4 + 0.6, cb * 0.4 + 0.6, 1.0)), chipTxt)
    imgui.SetCursorScreenPos(V2(sx, p.y + (h - swH) * 0.5))
    local clicked = drawToggleSwitch(id, isOn)
    imgui.SetCursorScreenPos(V2(p.x, p.y + h))
    imgui.Dummy(V2(1, S(6)))
    return clicked
end

function PCS_settToggleRow(id, isOn, label, desc)
    if PCS_newLook() then
        local ok, res = pcall(PCS_settToggleRowNew, id, isOn, label, desc)
        if ok then return res end
        PCS_nlFail("toggle", res)
    end
    return PCS_settToggleRowClassic(id, isOn, label, desc)
end

function PCS_drawSettingsTabRowNew()
    if not St._settTab then St._settTab = "win" end
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local aw = imgui.GetContentRegionAvail().x
    local perRow = (aw >= S(720)) and 6 or ((aw >= S(330)) and 3 or 2)
    local gap = S(6)
    local tw = math.floor((aw - gap * (perRow - 1)) / perRow)
    local th = S(44)
    for i, t in ipairs(PCS_SETT_TABS) do
        if (i - 1) % perRow ~= 0 then imgui.SameLine(0, gap) end
        local act = (St._settTab == t[1])
        local c = t[3]
        local p = imgui.GetCursorScreenPos()
        imgui.InvisibleButton("##stab" .. t[1], V2(tw, th))
        local hov, clicked = imgui.IsItemHovered(), imgui.IsItemClicked()
        local q = V2(p.x + tw, p.y + th)
        local k = act and 0.34 or (hov and 0.22 or 0.10)
        dl:AddRectFilled(p, q, U32(iv4(c[1] * k, c[2] * k, c[3] * k, 0.98)), S(14))
        if act then
            dl:PushClipRect(p, q, true)
            dl:AddCircleFilled(V2(p.x + S(20), p.y + th * 0.5), S(34), U32(iv4(c[1], c[2], c[3], 0.20)), 32)
            dl:PopClipRect()
        end
        dl:AddRect(p, q, U32(iv4(c[1], c[2], c[3], act and 1.0 or (hov and 0.70 or 0.28))), S(14), 0, act and 1.8 or 1.0)
        if act then
            dl:AddRectFilled(V2(p.x + S(18), q.y - S(4)), V2(q.x - S(18), q.y - S(2)), U32(iv4(c[1], c[2], c[3], 1.0)), S(2))
        end
        local ang, dy, sc = PCS_stickerAnim(hov or act, i * 0.8)
        PCS_drawSticker(dl, t[4], p.x + S(20), p.y + th * 0.5 + dy, S(8.5) * sc, ang)
        local ts = imgui.CalcTextSize(t[2])
        dl:PushClipRect(V2(p.x + S(36), p.y), q, true)
        dl:AddText(V2(p.x + S(37), p.y + (th - ts.y) * 0.5),
            U32(act and iv4(1, 1, 1, 1) or iv4(0.80, 0.84, 0.92, 0.95)), t[2])
        dl:PopClipRect()
        if clicked then
            if St._settTab ~= t[1] then St._resetSettScroll = true end
            St._settTab = t[1]
        end
    end
    imgui.Spacing()
end

function PCS_drawSettingsTabRow()
    if PCS_newLook() then
        local ok, err = pcall(PCS_drawSettingsTabRowNew)
        if ok then return end
        PCS_nlFail("tabs", err)
    end
    return PCS_drawSettingsTabRowClassic()
end

function drawSettingsInner(h, sw, sh)
    if St._resetSettScroll then imgui.SetScrollY(0) end
            local r,g,b = getAcc()

        do
            local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
            local aw = imgui.GetContentRegionAvail().x
            local dl = imgui.GetWindowDrawList()
            local p = imgui.GetCursorScreenPos()
            local lh = imgui.GetTextLineHeight()
            local txX = S(76)
            local tw = math.max(S(60), aw - txX - S(14))
            local subT = u8"\xce\xea\xed\xee, \xf6\xe2\xe5\xf2\xe0, \xef\xe5\xf0\xf1\xee\xed\xe0\xe6, \xf3\xe2\xe5\xe4\xee\xec\xeb\xe5\xed\xe8\xff \xe8 Telegram. \xc8\xe7\xec\xe5\xed\xe5\xed\xe8\xff \xf1\xee\xf5\xf0\xe0\xed\xff\xfe\xf2\xf1\xff \xf1\xf0\xe0\xe7\xf3."
            local sub_h = PCS_textH(subT, tw)
            local hh = math.max(S(66), S(12) + lh + S(3) + sub_h + S(12))
            local q = V2(p.x + aw, p.y + hh)
            imgui.Dummy(V2(aw, hh))
            local hovH = imgui.IsItemHovered()
            dl:AddRectFilled(p, q, U32(iv4(r * 0.10, g * 0.10, b * 0.10, pcsRowA(0.98))), S(12))
            dl:PushClipRect(p, q, true)
            dl:AddCircleFilled(V2(p.x + aw - S(30), p.y + hh * 0.5), S(74), U32(iv4(r, g, b, 0.10)), 48)
            dl:AddCircleFilled(V2(p.x + aw - S(30), p.y + hh * 0.5), S(46), U32(iv4(r, g, b, 0.12)), 48)
            dl:AddCircleFilled(V2(p.x + S(36), p.y + hh * 0.5), S(48), U32(iv4(r, g, b, 0.10)), 48)
            dl:PopClipRect()
            dl:AddRect(p, q, U32(iv4(r, g, b, 0.75)), S(12), 0, 1.4)
            if PCS_newLook and PCS_newLook() then dl:AddRectFilled(V2(p.x + S(22), q.y - S(4)), V2(p.x + S(22) + S(96), q.y - S(2)), U32(iv4(r, g, b, 1.0)), S(2)) end
            local ang, dy, sc = PCS_stickerAnim(hovH, 0.2)
            PCS_drawSticker(dl, "gear", p.x + S(38), p.y + hh * 0.5 + dy, S(17) * sc, ang)
            PCS_textAt(p.x + txX, p.y + S(12), tw, iv4(1, 1, 1, 1), u8"\xcd\xe0\xf1\xf2\xf0\xee\xe9\xea\xe8")
            PCS_textAt(p.x + txX, p.y + S(12) + lh + S(3), tw, thDim(), subT)
            local vt = "v" .. tostring(SCRIPT_VER or "")
            local vs = imgui.CalcTextSize(vt)
            if aw > S(300) then
                local vx = p.x + aw - vs.x - S(26)
                dl:AddRectFilled(V2(vx, p.y + S(10)), V2(vx + vs.x + S(14), p.y + S(10) + vs.y + S(6)), U32(iv4(r, g, b, 0.28)), S(10))
