    -- helper: ряд R G B + квадрат + подпись (стиль MMT)
    local function mmtColorRow(labelU8, rKey, gKey, bKey, defR, defG, defB, uid)
        local rr = (cfg[rKey] and cfg[rKey] >= 0) and cfg[rKey] or defR
        local gg = (cfg[gKey] and cfg[gKey] >= 0) and cfg[gKey] or defG
        local bb = (cfg[bKey] and cfg[bKey] >= 0) and cfg[bKey] or defB
        local Ri = math.floor(rr * 255 + 0.5)
        local Gi = math.floor(gg * 255 + 0.5)
        local Bi = math.floor(bb * 255 + 0.5)
        local cellW = S(56)
        local cellH = S(26)
        local gap = S(4)
        -- R/G/B ячейки
        local function cell(txt, col)
            imgui.PushStyleColor(imgui.Col.Button, col)
            imgui.PushStyleColor(imgui.Col.ButtonHovered, col)
            imgui.PushStyleColor(imgui.Col.ButtonActive, col)
            imgui.Button(txt, imgui.ImVec2(cellW, cellH))
            imgui.PopStyleColor(3)
        end
        cell(string.format("R: %d##%sr", Ri, uid), iv4(rr * 0.55 + 0.15, 0.12, 0.12, 1.0))
        imgui.SameLine(0, gap)
        cell(string.format("G: %d##%sg", Gi, uid), iv4(0.12, gg * 0.55 + 0.15, 0.12, 1.0))
        imgui.SameLine(0, gap)
        cell(string.format("B: %d##%sb", Bi, uid), iv4(0.12, 0.12, bb * 0.55 + 0.15, 1.0))
        imgui.SameLine(0, gap)
        -- квадрат-пикер
        local key = "_mmtVec_" .. uid
        if not St[key] then St[key] = imgui.new.float[3](rr, gg, bb) end
        St[key][0], St[key][1], St[key][2] = rr, gg, bb
        imgui.PushItemWidth(S(36))
        local flags = 0
        pcall(function()
            flags = imgui.ColorEditFlags.NoInputs + imgui.ColorEditFlags.NoLabel
                + (imgui.ColorEditFlags.PickerHueBar or 0)
        end)
        if imgui.ColorEdit3("##mmt" .. uid, St[key], flags) then
            cfg[rKey], cfg[gKey], cfg[bKey] = St[key][0], St[key][1], St[key][2]
            -- синхрон буферов если есть
            if uid == "main" and St.custRbuf then
                St.custRbuf[0], St.custGbuf[0], St.custBbuf[0] = cfg[rKey], cfg[gKey], cfg[bKey]
            elseif uid == "text" and St.textRbuf then
                St.textRbuf[0], St.textGbuf[0], St.textBbuf[0] = cfg[rKey], cfg[gKey], cfg[bKey]
            elseif uid == "bg" and St.winBgRbuf then
                St.winBgRbuf[0], St.winBgGbuf[0], St.winBgBbuf[0] = cfg[rKey], cfg[gKey], cfg[bKey]
            elseif uid == "acc" and St.outlineRbuf then
                St.outlineRbuf[0], St.outlineGbuf[0], St.outlineBbuf[0] = cfg[rKey], cfg[gKey], cfg[bKey]
            elseif uid == "chat" and St.chatRbuf then
                St.chatRbuf[0], St.chatGbuf[0], St.chatBbuf[0] = cfg[rKey], cfg[gKey], cfg[bKey]
            end
            saveCfg()
        end
        imgui.PopItemWidth()
        imgui.SameLine(0, S(8))
        imgui.TextColored(iv4(1, 1, 1, 1), labelU8)
        imgui.Dummy(imgui.ImVec2(0, S(2)))
    end

    local ar, ag, ab = getAcc()
    mmtColorRow(u8"\xce\xf1\xed\xee\xe2\xed\xee\xe9 \xf6\xe2\xe5\xf2 (\xea\xed\xee\xef\xea\xe8, \xe7\xe0\xe3\xee\xeb\xee\xe2\xea\xe8)", "custR", "custG", "custB", ar, ag, ab, "main")
    mmtColorRow(u8"\xd6\xe2\xe5\xf2 \xf2\xe5\xea\xf1\xf2\xe0", "textR", "textG", "textB", 1.0, 1.0, 1.0, "text")
    mmtColorRow(u8"\xd6\xe2\xe5\xf2 \xf4\xee\xed\xe0 \xee\xea\xed\xe0", "winBgR", "winBgG", "winBgB", 0.0, 0.0, 0.0, "bg")
    mmtColorRow(u8"\xce\xe1\xe2\xee\xe4\xea\xe0 \xe8 \xe0\xea\xf6\xe5\xed\xf2\xfb", "outlineR", "outlineG", "outlineB", ar, ag, ab, "acc")
    mmtColorRow(u8"\xcf\xf0\xe5\xf4\xe8\xea\xf1 \xf1\xea\xf0\xe8\xef\xf2\xe0 \xe2 \xf7\xe0\xf2\xe5", "chatR", "chatG", "chatB", 0.0, 1.0, 0.53, "chat")

    do
        local rowAlphaBuf = imgui.new("float[1]", {cfg.rowBgAlpha or 0.98})
        imgui.PushItemWidth(S(200))
        if imgui.SliderFloat(u8"\xcf\xf0\xee\xe7\xf0\xe0\xf7\xed\xee\xf1\xf2\xfc\x20\xf4\xee\xed\xe0\x20\xe7\xe0\x20\xf2\xe5\xea\xf1\xf2\xee\xec##rowBgAlphaSlider",
                rowAlphaBuf, 0.10, 1.0) then
            cfg.rowBgAlpha = rowAlphaBuf[0]
            saveCfg()
        end
        imgui.PopItemWidth()
    end
    imgui.Spacing()

    do
        local winAlphaBuf = imgui.new("float[1]", {cfg.winBgAlpha or 1.0})
        imgui.PushItemWidth(S(200))
        if imgui.SliderFloat(u8"\xcf\xf0\xee\xe7\xf0\xe0\xf7\xed\xee\xf1\xf2\xfc \xf4\xee\xed\xe0 \xee\xea\xed\xe0##winBgAlphaSlider",
                winAlphaBuf, 0.05, 1.0, "%.2f") then
            cfg.winBgAlpha = winAlphaBuf[0]
            if not imgui.IsItemDeactivatedAfterEdit then saveCfg() end
        end
        if imgui.IsItemDeactivatedAfterEdit and imgui.IsItemDeactivatedAfterEdit() then saveCfg() end
        imgui.PopItemWidth()

        local textAlphaBuf = imgui.new("float[1]", {cfg.textAlpha or 1.0})
        imgui.PushItemWidth(S(200))
        if imgui.SliderFloat(u8"\xcf\xf0\xee\xe7\xf0\xe0\xf7\xed\xee\xf1\xf2\xfc \xf2\xe5\xea\xf1\xf2\xe0##textAlphaSlider",
                textAlphaBuf, 0.25, 1.0, "%.2f") then
            cfg.textAlpha = textAlphaBuf[0]
            if not imgui.IsItemDeactivatedAfterEdit then saveCfg() end
        end
        if imgui.IsItemDeactivatedAfterEdit and imgui.IsItemDeactivatedAfterEdit() then saveCfg() end
        imgui.PopItemWidth()
    end
    imgui.Spacing()

    imgui.Spacing()
    if PCS_settToggleRow("##animAllSw", cfg.animAllOff ~= true, u8"\xc0\xed\xe8\xec\xe0\xf6\xe8\xe8 \xe8\xed\xf2\xe5\xf0\xf4\xe5\xe9\xf1\xe0 (\xea\xed\xee\xef\xea\xe8, \xe2\xea\xeb\xe0\xe4\xea\xe8, \xec\xe5\xed\xfe)",
            u8"\xcf\xeb\xe0\xe2\xed\xfb\xe5 \xfd\xf4\xf4\xe5\xea\xf2\xfb \xea\xed\xee\xef\xee\xea, \xe2\xea\xeb\xe0\xe4\xee\xea \xe8 \xec\xe5\xed\xfe. \xc2\xfb\xea\xeb\xfe\xf7\xe8\xf2\xe5, \xe5\xf1\xeb\xe8 \xe8\xe3\xf0\xe0 \xf2\xee\xf0\xec\xee\xe7\xe8\xf2.") then
        cfg.animAllOff = not (cfg.animAllOff == true)
        saveCfg()
    end

    imgui.Spacing()
    imgui.TextColored(thDim(), u8"\xd1\xec\xfb\xf1\xeb\xee\xe2\xfb\xe5 \xf6\xe2\xe5\xf2\xe0:")
    imgui.Spacing()
    mmtColorRow(u8"\xd3\xf1\xef\xe5\xf5 / \xe3\xee\xf2\xee\xe2\xee", "successR", "successG", "successB", 0.25, 0.92, 0.48, "ok")
    mmtColorRow(u8"\xcf\xf0\xe5\xe4\xf3\xef\xf0\xe5\xe6\xe4\xe5\xed\xe8\xe5", "warnR", "warnG", "warnB", 1.0, 0.82, 0.20, "warn")
    mmtColorRow(u8"\xce\xf8\xe8\xe1\xea\xe0 / \xee\xef\xe0\xf1\xed\xee\xf1\xf2\xfc", "errorR", "errorG", "errorB", 1.0, 0.30, 0.30, "err")

    imgui.Spacing()
    -- сброс цветов
    do
        imgui.PushStyleColor(imgui.Col.Button,        iv4(0.45, 0.12, 0.12, 1.0))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(0.65, 0.18, 0.18, 1.0))
        imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(0.85, 0.25, 0.25, 1.0))
        if imgui.Button(u8"\xd1\xe1\xf0\xee\xf1 \xf6\xe2\xe5\xf2\xee\xe2 \xea \xf3\xec\xee\xeb\xf7\xe0\xed\xe8\xfe##resetColors", imgui.ImVec2(-1, S(28))) then
            cfg.custR, cfg.custG, cfg.custB = -1, -1, -1
            cfg.textR, cfg.textG, cfg.textB = -1, -1, -1
            cfg.winBgR, cfg.winBgG, cfg.winBgB = -1, -1, -1
            cfg.outlineR, cfg.outlineG, cfg.outlineB = -1, -1, -1
            cfg.chatR, cfg.chatG, cfg.chatB = -1, -1, -1
            cfg.rowBgR, cfg.rowBgG, cfg.rowBgB = -1, -1, -1
            cfg.successR, cfg.successG, cfg.successB = -1, -1, -1
            cfg.warnR, cfg.warnG, cfg.warnB = -1, -1, -1
            cfg.errorR, cfg.errorG, cfg.errorB = -1, -1, -1
            saveCfg()
        end
        imgui.PopStyleColor(3)
    end
    imgui.Spacing()
    imgui.Dummy(imgui.ImVec2(0, S(6)))

    PCS_settSub(u8"\xd1\xeb\xf3\xf7\xe0\xe9\xed\xfb\xe9 \xf6\xe2\xe5\xf2", u8"\xcf\xee\xe4\xe1\xe5\xf0\xb8\xf2 \xf1\xeb\xf3\xf7\xe0\xe9\xed\xfb\xe9 \xee\xf1\xed\xee\xe2\xed\xee\xe9 \xf6\xe2\xe5\xf2 - \xe5\xf1\xeb\xe8 \xf5\xee\xf7\xe5\xf2\xf1\xff \xe1\xfb\xf1\xf2\xf0\xee \xf1\xec\xe5\xed\xe8\xf2\xfc \xee\xf4\xee\xf0\xec\xeb\xe5\xed\xe8\xe5.")
    do
        local pr4,pg4,pb4 = getAcc()
        imgui.PushStyleColor(imgui.Col.Button,        iv4(pr4*0.35,pg4*0.35,pb4*0.35,1.0))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(pr4*0.55,pg4*0.55,pb4*0.55,1.0))
        imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(pr4*0.75,pg4*0.75,pb4*0.75,1.0))
        do local _pbRnd = prettyBtnPush(9.0)
        if imgui.Button(u8"\xd1\xeb\xf3\xf7\xe0\xe9\xed\xfb\xe9\x20\xf6\xe2\xe5\xf2##randomAccentColor", imgui.ImVec2(imgui.GetContentRegionAvail().x, S(34))) then
            math.randomseed((os.time() or 0) + (os.clock() or 0) * 1000)
            -- акцент/фон строк — не слишком тёмные (0.35..1.0 на канал),
            -- чтобы оставались хорошо заметны на тёмном фоне
            local rr = 0.35 + math.random() * 0.65
            local gg = 0.35 + math.random() * 0.65
            local bb = 0.35 + math.random() * 0.65
            cfg.custR, cfg.custG, cfg.custB = rr, gg, bb
            St.custRbuf[0], St.custGbuf[0], St.custBbuf[0] = rr, gg, bb

            local rr2 = 0.35 + math.random() * 0.65
            local gg2 = 0.35 + math.random() * 0.65
            local bb2 = 0.35 + math.random() * 0.65
            cfg.rowBgR, cfg.rowBgG, cfg.rowBgB = rr2, gg2, bb2
            St.rowBgRbuf[0], St.rowBgGbuf[0], St.rowBgBbuf[0] = rr2, gg2, bb2

            -- текст — держим светлым (0.75..1.0 на канал), чтобы оставался читаемым
            local rt = 0.75 + math.random() * 0.25
            local gt = 0.75 + math.random() * 0.25
            local bt = 0.75 + math.random() * 0.25
            cfg.textR, cfg.textG, cfg.textB = rt, gt, bt
            St.textRbuf[0], St.textGbuf[0], St.textBbuf[0] = rt, gt, bt

            -- обводка — как акцент/фон строк, хорошо заметная
            local ro = 0.35 + math.random() * 0.65
            local go = 0.35 + math.random() * 0.65
            local bo = 0.35 + math.random() * 0.65
            cfg.outlineR, cfg.outlineG, cfg.outlineB = ro, go, bo
            St.outlineRbuf[0], St.outlineGbuf[0], St.outlineBbuf[0] = ro, go, bo

            saveCfg()
        end
        prettyBtnPop(_pbRnd) end
        imgui.PopStyleColor(3)
    end

    -- (самообновление реализовано: карточка "Обновления" во вкладке
    -- "О скрипте", см. PCS_UPDATE / drawAboutInner)

    imgui.Spacing()
    imgui.Dummy(imgui.ImVec2(0, S(6)))

    end -- блок "Цвета и оформление"
    if PCS_settBlock("char", "star", u8"\xcf\xe5\xf0\xf1\xee\xed\xe0\xe6 \xed\xe0 \xf4\xee\xed\xe5", u8"\xca\xe0\xf0\xf2\xe8\xed\xea\xe0-\xef\xe5\xf0\xf1\xee\xed\xe0\xe6 \xe7\xe0 \xf1\xee\xe4\xe5\xf0\xe6\xe8\xec\xfb\xec \xee\xea\xed\xe0", { 0.75, 0.45, 1.0 }, false) then
    do
        local isOnMain = cfg.companionBgEnabled ~= false
        if PCS_settToggleRow("##companionBgToggleMain", isOnMain, u8"\xcf\xee\xea\xe0\xe7\xfb\xe2\xe0\xf2\xfc \xef\xe5\xf0\xf1\xee\xed\xe0\xe6\xe0",
                u8"\xc2\xea\xeb\xfe\xf7\xe0\xe5\xf2 \xea\xe0\xf0\xf2\xe8\xed\xea\xf3 \xef\xe5\xf0\xf1\xee\xed\xe0\xe6\xe0 \xed\xe0 \xf4\xee\xed\xe5 \xee\xea\xed\xe0.") then
            cfg.companionBgEnabled = not isOnMain
            saveCfg()
        end
        if isOnMain then
            imgui.Spacing()
            imgui.TextColored(iv4(0.70,0.82,1.0,1.0), u8"\xc2\xfb\xe1\xe5\xf0\xe8\xf2\xe5 \xef\xe5\xf0\xf1\xee\xed\xe0\xe6\xe0:")
            imgui.Spacing()
            do
                local okPk, errPk = pcall(PCS_drawSkinPicker)
                if not okPk and not PCS_pickerErrPrinted then
                    PCS_pickerErrPrinted = true
                    print("[PC Stats] skin picker error: " .. tostring(errPk))
                end
            end
            imgui.Spacing()
            local alphaBufMain = imgui.new("float[1]", {cfg.companionBgAlpha or 0.35})
            imgui.PushItemWidth(S(180))
            if imgui.SliderFloat(u8"\xcf\xf0\xee\xe7\xf0\xe0\xf7\xed\xee\xf1\xf2\xfc##companionAlphaMain",
                    alphaBufMain, 0.05, 1.0) then
                cfg.companionBgAlpha = alphaBufMain[0]
                saveCfg()
            end
            imgui.PopItemWidth()
            imgui.Spacing()
            local ctRm = imgui.new("float[1]", {cfg.companionTintR or 1.0})
            local ctGm = imgui.new("float[1]", {cfg.companionTintG or 1.0})
            local ctBm = imgui.new("float[1]", {cfg.companionTintB or 1.0})
            if not cfg.companionRainbow then
                drawSimpleColorPicker(u8"\xd6\xe2\xe5\xf2\x20\xef\xe5\xf0\xf1\xee\xed\xe0\xe6\xe0",
                    "companionTintMain", ctRm, ctGm, ctBm,
                    "companionTintR", "companionTintG", "companionTintB",
                    nil, 1.0, 1.0, 1.0)
            end

            imgui.Spacing()
            do
                local rbOnM = cfg.companionRainbow and true or false
                if PCS_settToggleRow("##companionRainbowToggleMain", rbOnM, u8"\xd0\xe0\xe4\xf3\xe6\xed\xfb\xe9 (\xef\xe5\xf0\xe5\xeb\xe8\xe2\xe0\xfe\xf9\xe8\xe9\xf1\xff) \xef\xe5\xf0\xf1\xee\xed\xe0\xe6",
                        u8"\xd6\xe2\xe5\xf2 \xef\xe5\xf0\xf1\xee\xed\xe0\xe6\xe0 \xef\xeb\xe0\xe2\xed\xee \xec\xe5\xed\xff\xe5\xf2\xf1\xff.") then
                    cfg.companionRainbow = not rbOnM
                    saveCfg()
                end
            end

            imgui.Spacing()
            do
                local oeOnM = cfg.companionOutlineEnabled ~= false
                if PCS_settToggleRow("##companionOutlineEnabledToggleMain", oeOnM, u8"\xce\xe1\xe2\xee\xe4\xea\xe0 \xef\xe5\xf0\xf1\xee\xed\xe0\xe6\xe0",
                        u8"\xd1\xe2\xe5\xf2\xff\xf9\xe8\xe9\xf1\xff \xea\xee\xed\xf2\xf3\xf0 \xe2\xee\xea\xf0\xf3\xe3 \xea\xe0\xf0\xf2\xe8\xed\xea\xe8.") then
                    cfg.companionOutlineEnabled = not oeOnM
                    saveCfg()
                end
            end

            if cfg.companionOutlineEnabled ~= false then
                imgui.Spacing()
                do
                    local obOnM = cfg.companionOutlineRainbow ~= false
                    if PCS_settToggleRow("##companionOutlineRainbowToggleMain", obOnM, u8"\xcf\xe5\xf0\xe5\xeb\xe8\xe2\xe0\xfe\xf9\xe0\xff\xf1\xff \xee\xe1\xe2\xee\xe4\xea\xe0 \xef\xe5\xf0\xf1\xee\xed\xe0\xe6\xe0",
                            u8"\xca\xee\xed\xf2\xf3\xf0 \xef\xe5\xf0\xf1\xee\xed\xe0\xe6\xe0 \xec\xe5\xed\xff\xe5\xf2 \xf6\xe2\xe5\xf2\xe0.") then
                        cfg.companionOutlineRainbow = not obOnM
                        saveCfg()
                    end
                end

                imgui.Spacing()
                do
                    local thBufM = imgui.new("float[1]", {cfg.companionOutlineThickness or 1.0})
                    imgui.PushItemWidth(S(180))
                    if imgui.SliderFloat(u8"\xd2\xee\xeb\xf9\xe8\xed\xe0\x20\xee\xe1\xe2\xee\xe4\xea\xe8##companionOutlineThicknessMain",
                            thBufM, 0.3, 3.0) then
                        cfg.companionOutlineThickness = thBufM[0]
                        saveCfg()
                    end
                    imgui.PopItemWidth()
                end
            end

            imgui.Spacing()
            do
                local okTf, errTf = pcall(PCS_drawCompanionTransform)
                if not okTf and not PCS_compTfErrPrinted then
                    PCS_compTfErrPrinted = true
                    print("[PC Stats] companion transform UI error: " .. tostring(errTf))
                end
            end
        end
        imgui.Spacing()
        imgui.Dummy(imgui.ImVec2(0, S(9)))
    end

    -- ── всплывающие уведомления (плашки), перенесены из Market Helper ──
    end -- блок "Персонаж на фоне"
    if PCS_settBlock("rc", "refresh", "", "", { 0.25, 0.90, 0.80 }, false) then
        local okRc, errRc = pcall(PCS_RC_drawReconnectBlock)
        if not okRc then print("[PC Stats] reconnect UI error: " .. tostring(errRc)) end
    end -- блок "Реконнект"
    if PCS_settBlock("spawn", "list", "", "", { 0.40, 0.75, 1.00 }, false) then
        local okSp, errSp = pcall(PCS_RC_drawSpawnBlock)
        if not okSp then print("[PC Stats] spawn UI error: " .. tostring(errSp)) end
    end -- блок "Спавн"
    if PCS_settBlock("sound", "bell", "", "", { 1.0, 0.60, 0.90 }, false) then
        local okFx, errFx = pcall(PCS_drawFxSettings)
        if not okFx then PCS_quietErr("fx settings", errFx) end
    end -- блок "Звуки"
    if PCS_settBlock("notif", "bell", u8"\xd3\xe2\xe5\xe4\xee\xec\xeb\xe5\xed\xe8\xff", u8"\xcf\xeb\xe0\xf8\xea\xe8 \xef\xee\xe2\xe5\xf0\xf5 \xe8\xe3\xf0\xfb, \xf7\xe0\xf1\xfb, PayDay, \xf1\xf2\xe8\xea\xe5\xf0\xfb \xe2 \xf7\xe0\xf2\xe5", { 1.0, 0.72, 0.16 }, false) then
    PCS_settSub(u8"\xc2\xf1\xef\xeb\xfb\xe2\xe0\xfe\xf9\xe8\xe5 \xef\xeb\xe0\xf8\xea\xe8", u8"\xca\xee\xf0\xee\xf2\xea\xe8\xe5 \xf1\xee\xee\xe1\xf9\xe5\xed\xe8\xff \xef\xee\xe2\xe5\xf0\xf5 \xe8\xe3\xf0\xfb. \xc4\xf3\xe1\xeb\xe8\xf0\xf3\xfe\xf2 \xf1\xee\xee\xe1\xf9\xe5\xed\xe8\xff \xf1\xea\xf0\xe8\xef\xf2\xe0 \xe8\xe7 \xf7\xe0\xf2\xe0.")
    pcall(PCS_drawToastSettings)
    imgui.Spacing()
    PCS_GUARD.call(PCS_GUARD_NOTE.drawSettings)
    imgui.Spacing()
    PCS_GUARD.call(PCS_MENTION.drawSettings)
    imgui.Spacing()
    PCS_settSub(u8"\xd1\xee\xee\xe1\xf9\xe5\xed\xe8\xff \xe2 \xf7\xe0\xf2\xe5", u8"\xce\xf4\xee\xf0\xec\xeb\xe5\xed\xe8\xe5 \xf1\xee\xee\xe1\xf9\xe5\xed\xe8\xe9 \xf1\xea\xf0\xe8\xef\xf2\xe0 \xe2 \xf7\xe0\xf2\xe5 \xe8\xe3\xf0\xfb.")
    if PCS_settToggleRow("##chatStickersSw", cfg.chatStickers ~= false, u8"\xd1\xf2\xe8\xea\xe5\xf0\xfb \xe2 \xf1\xee\xee\xe1\xf9\xe5\xed\xe8\xff\xf5 \xf7\xe0\xf2\xe0",
            u8"\xcc\xe0\xeb\xe5\xed\xfc\xea\xe8\xe5 \xe7\xed\xe0\xf7\xea\xe8 \xef\xe5\xf0\xe5\xe4 \xf1\xee\xee\xe1\xf9\xe5\xed\xe8\xff\xec\xe8 \xf1\xea\xf0\xe8\xef\xf2\xe0 \xe2 \xf7\xe0\xf2\xe5.") then
        cfg.chatStickers = not (cfg.chatStickers ~= false)
        saveCfg()
    end
    end -- блок "Уведомления"
    imgui.Spacing()
    imgui.Dummy(imgui.ImVec2(0, S(9)))

    -- ── нижний отступ, чтобы последний блок не прилипал к краю окна ──
    imgui.Dummy(imgui.ImVec2(0, S(40)))
end

local function drawSettings(h, sw, sh)
    imgui.PushStyleColor(imgui.Col.ChildBg, iv4(0,0,0,0))
    imgui.BeginChild("##sset", imgui.ImVec2(0, h), false)
    local ok, err = PCS_GUARD.call(drawSettingsInner, h, sw, sh)
    pcall(PCS_cardFlush)
    imgui.EndChild()
    imgui.PopStyleColor()
    St._resetSettScroll = false
    if not ok then
        PCS_quietErr("ui@15553", err)
    end
end

local function drawGlobalSettingsPanel()
    if not St._settingsPanelOpen then return end
    if not St._mainWinPos or not St._mainWinSize then return end

    local panelW = S(340)
    local sw = imgui.GetIO().DisplaySize.x
    local sh = imgui.GetIO().DisplaySize.y

    if not St._settingsPanelDetached then
