PCS_CHG_COL = {
    g = { 0.35, 0.90, 0.55 }, b = { 0.45, 0.70, 1.00 }, p = { 0.75, 0.55, 1.00 },
    o = { 1.00, 0.65, 0.25 }, y = { 1.00, 0.82, 0.25 }, c = { 0.35, 0.85, 0.95 },
    r = { 1.00, 0.45, 0.55 },
}

PCS_NEWS = { entries = nil, loading = false, ok = nil, err = nil, at = 0, cacheTried = false }

-- текст -> список версий { {ver=,label=,sub=,items={{ic,col,title,desc},...}}, ... } | nil
function PCS_chgParse(body)
    if type(body) ~= "string" then return nil end
    if body:sub(1, 3) == "\239\187\191" then body = body:sub(4) end -- BOM
    body = body:gsub("\r", "")
    local out, cur = {}, nil
    local pal = { "g", "b", "p", "o", "y", "c", "r" }
    for line in (body .. "\n"):gmatch("(.-)\n") do
        line = line:gsub("^%s+", ""):gsub("%s+$", "")
        if line == "" or line:sub(1, 2) == "//" then
            -- пусто / комментарий
        elseif line:sub(1, 1) == "#" then
            local h = line:gsub("^#+%s*", "")
            local head, sub = h:match("^(.-)%s*|%s*(.*)$")
            head = head or h
            sub  = sub or ""
            head = head:gsub("^[vV]%s*(%d)", "%1"):gsub("%s+$", "")
            if head ~= "" then
                cur = { ver = head, label = "v" .. head, sub = sub, items = {} }
                out[#out + 1] = cur
            end
        elseif cur then
            local txt = line:gsub("^[%+%-%*]+%s*", "")
            txt = txt:gsub("^\226\128\162%s*", "") -- маркер-точка
            local ic, col
            local a, b, rest = txt:match("^%(([%a_]+)[,%s]*(%a?)%)%s*(.+)$")
            if a then
                if PCS_IC[a] then
                    ic = a
                    if b ~= "" and PCS_CHG_COL[b] then col = b end
                    txt = rest
                elseif #a == 1 and b == "" and PCS_CHG_COL[a] then
                    col = a
                    txt = rest
                end
            end
            local t, d = txt:match("^(.-)%s*|%s*(.*)$")
            if not t then t, d = txt, "" end
            if t ~= "" then
                cur.items[#cur.items + 1] = { ic or "circleplus", col or pal[(#cur.items % #pal) + 1], t, d }
            end
        end
    end
    local res = {}
    for _, e in ipairs(out) do
        if #e.items > 0 then res[#res + 1] = e end
    end
    if #res == 0 then return nil end
    return res
end

function PCS_newsCachePath()
    return pcs_ver.tmpDir() .. "/PCStats_news_cache.txt"
end

-- скачать changelog.txt в фоне (можно звать каждый кадр — есть троттлинг)
function PCS_newsFetch(force)
    local N = PCS_NEWS
    if not N.cacheTried then
        N.cacheTried = true
        pcall(function()
            local body = pcs_ver.open(pcs_ver.readAll(PCS_newsCachePath()))
            local e = body and PCS_chgParse(body)
            if e then N.entries = e end
        end)
    end
    if N.loading then return end
    if not force then return end
    if not force and os.time() - (N.at or 0) < (N.ok and 600 or 90) then return end
    N.loading = true
    N.at = os.time()
    lua_thread.create(function()
        local okT, errT = pcall(function()
            local tmp = pcs_ver.tmpDir() .. "/PCStats_news.tmp"
            local body, lastErr = nil, "no urls"
            for _, url in ipairs(pcs_ver.rawUrls(pcs_ver.cfg.news or "changelog.txt")) do
                local okF, e = pcs_ver.fetch(url, tmp, 12)
                if okF then
                    body = pcs_ver.open(pcs_ver.readAll(tmp))
                    pcall(os.remove, tmp)
                    if body and #body > 5 then break end
                    body, lastErr = nil, "empty"
                else
                    lastErr = tostring(e)
                    if not lastErr:find("http_404", 1, true) then break end
                end
            end
            if not body then N.ok = false; N.err = lastErr; return end
            local entries = PCS_chgParse(body)
            if not entries then N.ok = false; N.err = "parse"; return end
            N.entries, N.ok, N.err = entries, true, nil
            pcall(function()
                local f = io.open(PCS_newsCachePath(), "wb")
                if f then f:write(pcs_ver.seal(body)); f:close() end
            end)
        end)
        if not okT then N.ok = false; N.err = tostring(errT) end
        N.loading = false
    end)
end

function PCS_chgList()
    local N = PCS_NEWS
    if N.entries and #N.entries > 0 then return N.entries, true end
    return PCS_CHANGELOG, false
end

-- запись, которая соответствует установленной версии
function PCS_chgCurrent()
    local list = PCS_chgList()
    for _, e in ipairs(list) do
        if e.ver == SCRIPT_VER then return e end
    end
    for _, e in ipairs(PCS_CHANGELOG) do
        if e.ver == SCRIPT_VER then return e end
    end
    return list[1]
end

-- список пунктов: значок + заголовок + описание, слева тонкая линия
function PCS_chgItems(items)
    if type(items) ~= "table" then return end
    local r, g, b = getAcc()
    local dl  = imgui.GetWindowDrawList()
    local U32 = imgui.ColorConvertFloat4ToU32
    local p0  = imgui.GetCursorScreenPos()
    local x0  = imgui.GetCursorPosX()
    local icoX, txtX = x0 + S(12), x0 + S(38)
    local descCol = cfg.uiLightMode and iv4(0.30, 0.32, 0.38, 1.0) or iv4(0.60, 0.65, 0.76, 1.0)
    for _, it in ipairs(items) do
        local y   = imgui.GetCursorPosY()
        local col = PCS_CHG_COL[it[2]] or { r, g, b }
        imgui.SetCursorPos(imgui.ImVec2(icoX, y + S(1)))
        imgui.TextColored(iv4(col[1], col[2], col[3], 1.0), PCS_IC[it[1]] or PCS_IC.check or "")
        imgui.SetCursorPos(imgui.ImVec2(txtX, y))
        imgui.PushTextWrapPos(imgui.GetCursorPosX() + imgui.GetContentRegionAvail().x - S(8))
        imgui.TextColored(thTxt(), it[3] or "")
        if it[4] and it[4] ~= "" then
            imgui.SetCursorPosX(txtX)
            imgui.TextColored(descCol, it[4])
        end
        imgui.PopTextWrapPos()
        imgui.Dummy(imgui.ImVec2(0, S(6)))
    end
    local p1 = imgui.GetCursorScreenPos()
    if p1.y - p0.y > S(8) then
        dl:AddRectFilled(imgui.ImVec2(p0.x + S(4), p0.y), imgui.ImVec2(p0.x + S(6), p1.y - S(6)),
            U32(iv4(r * 0.75, g * 0.75, b * 0.75, 0.55)), 1)
    end
end

-- заголовок версии (кликабельный — сворачивает/разворачивает); true = клик
function PCS_chgHeader(idx, e, isOpen)
    local r, g, b = getAcc()
    local dl  = imgui.GetWindowDrawList()
    local U32 = imgui.ColorConvertFloat4ToU32
    local p   = imgui.GetCursorScreenPos()
    local aw  = imgui.GetContentRegionAvail().x
    local h   = S(34)
    local clicked = imgui.InvisibleButton("##chgh" .. tostring(idx), imgui.ImVec2(aw, h))
    local hov = (imgui.IsItemHovered and imgui.IsItemHovered()) or false
    local k = hov and 0.34 or 0.24
    dl:AddRectFilled(p, imgui.ImVec2(p.x + aw, p.y + h),
        U32(iv4(math.max(r * k, 0.10), math.max(g * k, 0.10), math.max(b * k, 0.10), pcsRowA(0.97))), 6)
    dl:AddRect(p, imgui.ImVec2(p.x + aw, p.y + h),
        U32(iv4(r * 0.70, g * 0.70, b * 0.70, hov and 0.85 or 0.55)), 6, 0, 1.0)
    dl:AddRectFilled(imgui.ImVec2(p.x, p.y + 4), imgui.ImVec2(p.x + S(3), p.y + h - 4),
        U32(iv4(r, g, b, 1.0)), 2)

    local lab = (PCS_IC.tag or "") .. "  " .. tostring(e.label or e.ver)
    local ts  = imgui.CalcTextSize(lab)
    local ty  = p.y + (h - ts.y) * 0.5
    local x   = p.x + S(12)
    dl:AddText(imgui.ImVec2(x, ty), PCS_TA(U32(iv4(0.75, 0.80, 0.95, 1.0))),
        isOpen and (PCS_IC.chevdown or "v") or (PCS_IC.chevright or ">"))
    x = x + S(22)
    dl:AddText(imgui.ImVec2(x, ty), PCS_TA(U32(iv4(1, 1, 1, 1))), lab)
    x = x + ts.x + S(10)
    if e.ver == SCRIPT_VER then
        local bt = u8"\xd2\xc5\xca\xd3\xd9\xc0\xdf"
        local bs = imgui.CalcTextSize(bt)
        dl:AddRectFilled(imgui.ImVec2(x, p.y + S(7)), imgui.ImVec2(x + bs.x + S(14), p.y + h - S(7)),
            U32(iv4(1.0, 0.78, 0.15, 1.0)), 8)
        dl:AddText(imgui.ImVec2(x + S(7), p.y + (h - bs.y) * 0.5), PCS_TA(U32(iv4(0.10, 0.08, 0.02, 1.0))), bt)
    end
    return clicked
end

-- окно "История версий": все версии, что добавлено в каждой
function PCS_chgView()
    PCS_newsFetch(false)
    local list = PCS_chgList()
    St._chgOpen = St._chgOpen or {}
    local n = #list
    local function isOpenAt(i)
        local o = St._chgOpen[i]
        if o == nil then o = (i == 1) or (n <= 4) end
        return o
    end
    local allOpen = true
    for i = 1, n do if not isOpenAt(i) then allOpen = false; break end end

    imgui.PushStyleColor(imgui.Col.Button,        iv4(0.25, 0.35, 0.55, 1))
    imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(0.35, 0.45, 0.70, 1))
    imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(0.20, 0.28, 0.45, 1))
    do local _pb = prettyBtnPush(6.0)
    if imgui.Button((PCS_IC.arrowleft or "<") .. "  " .. u8"\xcd\xe0\xe7\xe0\xe4" .. "##chgback", imgui.ImVec2(S(110), S(28))) then
        St.showChangelog = false
    end
    prettyBtnPop(_pb) end
    imgui.PopStyleColor(3)

    imgui.SameLine(0, S(12))
    imgui.TextColored(thAccBright(), (PCS_IC.history or "") .. "  " .. u8"\xc8\xf1\xf2\xee\xf0\xe8\xff \xe2\xe5\xf0\xf1\xe8\xe9")

    imgui.SameLine(0, S(12))
    local avail = imgui.GetContentRegionAvail().x
    local bw, rw, gp = S(150), S(38), S(8)
    if avail > bw + rw + gp then imgui.SetCursorPosX(imgui.GetCursorPosX() + avail - bw - rw - gp) end
    imgui.PushStyleColor(imgui.Col.Button,        iv4(0.28, 0.32, 0.42, 1))
    imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(0.38, 0.42, 0.55, 1))
    imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(0.20, 0.24, 0.32, 1))
    do local _pb2 = prettyBtnPush(6.0)
    if imgui.Button((PCS_IC.sync or "R") .. "##chgrefresh", imgui.ImVec2(rw, S(28))) then
        PCS_newsFetch(true)
    end
    imgui.SameLine(0, gp)
    local tl = allOpen and (PCS_IC.chevright .. "  " .. u8"\xd1\xe2\xe5\xf0\xed\xf3\xf2\xfc \xe2\xf1\xe5") or (PCS_IC.chevdown .. "  " .. u8"\xd0\xe0\xe7\xe2\xe5\xf0\xed\xf3\xf2\xfc \xe2\xf1\xe5")
    if imgui.Button(tl .. "##chgtoggle", imgui.ImVec2(bw, S(28))) then
        for i = 1, n do St._chgOpen[i] = not allOpen end
    end
    prettyBtnPop(_pb2) end
    imgui.PopStyleColor(3)

    -- строка статуса: откуда сейчас взят список
    local N = PCS_NEWS
    local stTxt, stCol
    if N.loading then
        stTxt, stCol = u8"\xc7\xe0\xe3\xf0\xf3\xe7\xea\xe0 \xf1\xef\xe8\xf1\xea\xe0...", iv4(0.55, 0.75, 1.0, 1.0)
    elseif N.entries and N.ok then
        stTxt, stCol = u8"\xd1\xef\xe8\xf1\xee\xea \xe7\xe0\xe3\xf0\xf3\xe6\xe5\xed", iv4(0.40, 0.90, 0.55, 1.0)
    elseif N.entries then
        stTxt, stCol = u8"\xcd\xe5\xf2 \xf1\xe2\xff\xe7\xe8 - \xef\xee\xea\xe0\xe7\xe0\xed\xe0 \xf1\xee\xf5\xf0\xe0\xed\xb8\xed\xed\xe0\xff \xea\xee\xef\xe8\xff", iv4(1.0, 0.82, 0.25, 1.0)
    else
        stTxt, stCol = u8"\xcd\xe5\xf2 \xf1\xe2\xff\xe7\xe8 - \xef\xee\xea\xe0\xe7\xe0\xed \xe2\xf1\xf2\xf0\xee\xe5\xed\xed\xfb\xe9 \xf1\xef\xe8\xf1\xee\xea", iv4(0.65, 0.68, 0.78, 1.0)
    end
    imgui.TextColored(stCol, (PCS_IC.link or "") .. "  " .. stTxt)
    imgui.Spacing()

    imgui.BeginChild("##changelogview", imgui.ImVec2(0, 0), false)
    for i, e in ipairs(list) do
        local open = isOpenAt(i)
        if PCS_chgHeader(i, e, open) then
            open = not open
            St._chgOpen[i] = open
        end
        if open then
            imgui.Dummy(imgui.ImVec2(0, S(4)))
            if e.sub and e.sub ~= "" then
                imgui.SetCursorPosX(imgui.GetCursorPosX() + S(12))
                imgui.TextColored(thAccBright(), e.sub)
                imgui.Dummy(imgui.ImVec2(0, S(2)))
            end
            PCS_chgItems(e.items)
        end
        imgui.Dummy(imgui.ImVec2(0, S(6)))
    end
    imgui.EndChild()
end

function drawAboutInner(h)
    if St.showChangelog then
        local okC, errC = PCS_GUARD.call(PCS_chgView)
        if not okC then
            St.showChangelog = false
            PCS_quietErr("ui@16255", errC)
        end
        return
    end
    if St._resetSettScroll then imgui.SetScrollY(0) end
        local r,g,b = getAcc()
        local rra,rga,rba = getRowBgColor()
        local dl_a  = imgui.GetWindowDrawList()

        imgui.Spacing()
        local bannerH = SFtext(86) * 0.98
        local ps_a    = imgui.GetCursorScreenPos()
        local aw_a    = imgui.GetContentRegionAvail().x
        local banBgR = math.max(rra*0.22, 0.06)
        local banBgG = math.max(rga*0.22, 0.06)
        local banBgB = math.max(rba*0.22, 0.06)
        dl_a:AddRectFilled(
            imgui.ImVec2(ps_a.x,      ps_a.y),
            imgui.ImVec2(ps_a.x+aw_a, ps_a.y+bannerH),
            imgui.ColorConvertFloat4ToU32(iv4(banBgR,banBgG,banBgB,pcsRowA(1.0))), 12)
        dl_a:AddRectFilled(
            imgui.ImVec2(ps_a.x,      ps_a.y),
            imgui.ImVec2(ps_a.x+aw_a*0.5, ps_a.y+bannerH),
            imgui.ColorConvertFloat4ToU32(iv4(rra*0.10,rga*0.10,rba*0.10,0.5)), 12)
        dl_a:AddRect(
            imgui.ImVec2(ps_a.x,      ps_a.y),
            imgui.ImVec2(ps_a.x+aw_a, ps_a.y+bannerH),
            imgui.ColorConvertFloat4ToU32(iv4(r,g,b,1.0)), 12, 0, 0.9)
        dl_a:AddRectFilled(
            imgui.ImVec2(ps_a.x+20,      ps_a.y),
            imgui.ImVec2(ps_a.x+aw_a-20, ps_a.y+3),
            imgui.ColorConvertFloat4ToU32(iv4(r,g,b,1.0)), 2)
        dl_a:AddRectFilled(
            imgui.ImVec2(ps_a.x+20,      ps_a.y+bannerH-3),
            imgui.ImVec2(ps_a.x+aw_a-20, ps_a.y+bannerH),
            imgui.ColorConvertFloat4ToU32(iv4(r,g,b,0.7)), 2)
        local banBright = banBgR*0.299 + banBgG*0.587 + banBgB*0.114
        local banTitleCol = banBright > 0.35 and iv4(0.05,0.05,0.10,1.0) or iv4(1,1,1,1)

        imgui.PushStyleColor(imgui.Col.ChildBg, iv4(0,0,0,0))
        imgui.BeginChild("##banner", imgui.ImVec2(aw_a, bannerH), false,
            imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoScrollWithMouse)
            local title1 = "PC Stats"
            local title2 = "v" .. SCRIPT_VER .. "  |  Arizona RP PC"
            local titleFontScale = 1.12
            imgui.SetWindowFontScale(titleFontScale)
            local sz1 = imgui.CalcTextSize(title1)
            local sz2 = imgui.CalcTextSize(title2)
            if PCS_COMPANION_TEX and not PCS_texQuiet() then
                local icoSzA = bannerH * 0.60
                local icoWA, icoHA = PCS_companionFit(icoSzA, icoSzA)
                imgui.SetCursorPos(imgui.ImVec2(aw_a - icoWA - SFtext(16), (bannerH - icoHA)*0.5))
                local okImgA = pcall(imgui.Image, PCS_COMPANION_TEX, imgui.ImVec2(icoWA, icoHA))
                if not okImgA then PCS_disableCompanionTex() end
            end
            imgui.SetCursorPos(imgui.ImVec2(aw_a*0.5 - sz1.x*0.5, SFtext(14)))
            imgui.TextColored(banTitleCol, title1)
            imgui.SetCursorPos(imgui.ImVec2(aw_a*0.5 - sz2.x*0.5, SFtext(44)))
            imgui.TextColored(thAccBright(), title2)
            imgui.SetWindowFontScale(1.0)
        imgui.EndChild()
        imgui.PopStyleColor()
        imgui.Spacing()

        -- ── лёгкая карточка: тоньше рамка, чем infoCard() в других вкладках —
        -- здесь текста немного, тяжёлая рамка смотрелась слишком грузно ──
        local function aboutCard(id, cardH, drawFn)
            cardH = SFtext(cardH)
            local rr2,rg2,rb2 = getRowBgColor()
            local dlc = imgui.GetWindowDrawList()
            local pc  = imgui.GetCursorScreenPos()
            local awc = imgui.GetContentRegionAvail().x
            local bgR = math.max(rr2*0.13, 0.07)
            local bgG = math.max(rg2*0.13, 0.07)
            local bgB = math.max(rb2*0.13, 0.07)
            local cardBgAlpha = pcsRowA((cfg.companionBgEnabled ~= false) and 0.55 or 0.97)
            dlc:AddRectFilled(
                imgui.ImVec2(pc.x,     pc.y),
                imgui.ImVec2(pc.x+awc, pc.y+cardH),
                imgui.ColorConvertFloat4ToU32(iv4(bgR,bgG,bgB,cardBgAlpha)), 10)
            dlc:AddRect(
                imgui.ImVec2(pc.x,     pc.y),
                imgui.ImVec2(pc.x+awc, pc.y+cardH),
                imgui.ColorConvertFloat4ToU32(iv4(r*0.55,g*0.55,b*0.55,0.50)), 10, 0, 0.8)
            imgui.PushStyleColor(imgui.Col.ChildBg, iv4(0,0,0,0))
            imgui.BeginChild(id, imgui.ImVec2(awc - 2, cardH), false,
                imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoScrollWithMouse)
                local okFn, errFn = PCS_GUARD.call(drawFn, awc, cardH)
            imgui.EndChild()
            imgui.PopStyleColor()
            imgui.Spacing()
            if not okFn then
                PCS_quietErr("ui@16381", errFn)
            end
        end

        local aboutBaseScale = St.UI_SCALE * (cfg.fontSize > 0 and cfg.fontSize or 1.25)

        secTitle(u8"\xd0\xe0\xe7\xf0\xe0\xe1\xee\xf2\xf7\xe8\xea")
        aboutCard("##devcard", 124, function(aw, ch)
            imgui.SetWindowFontScale(aboutBaseScale)
            imgui.SetCursorPos(imgui.ImVec2(SFtext(16), SFtext(12)))
            imgui.TextColored(iv4(0.55,0.62,0.80,1.0), u8"\xd0\xe0\xe7\xf0\xe0\xe1\xee\xf2\xf7\xe8\xea:")
            imgui.SameLine(0,8)
            imgui.TextColored(thAccBright(), "Marco_Santiago (19)")
            imgui.SetCursorPos(imgui.ImVec2(SFtext(16), SFtext(42)))
            imgui.TextColored(iv4(0.55,0.62,0.80,1.0), u8"\xc2\xe5\xf0\xf1\xe8\xff:")
            imgui.SameLine(0,8)
            imgui.TextColored(iv4(1,1,1,1), "v" .. SCRIPT_VER)
            imgui.SameLine(0,14)
            imgui.TextColored(iv4(0.55,0.62,0.80,1.0), u8"\xcf\xf0\xee\xe5\xea\xf2:")
            imgui.SameLine(0,8)
            imgui.TextColored(iv4(0.90,0.90,0.90,1.0), "Arizona RP PC")
            imgui.SetWindowFontScale(aboutBaseScale)

            -- компактные прямоугольные кнопки связи (~20x4 по пропорциям)
            local btnCW, btnCH = SFtext(142), SFtext(24)
            local gapC = SFtext(10)
            imgui.SetCursorPos(imgui.ImVec2(SFtext(16), SFtext(94)))
            do
                local tgHandle = "@Marco8877"
                local tgUrl    = "https://t.me/Marco8877"
                local tgBp     = imgui.GetCursorScreenPos()
                imgui.PushStyleColor(imgui.Col.Button,        iv4(0.09,0.42,0.68,1.0))
                imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(0.13,0.58,0.90,1.0))
                imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(0.18,0.72,1.00,1.0))
                do local _pbtg = prettyBtnPush(6.0)
                if imgui.Button(PCS_IC.telegram .. "  " .. u8"\xd2\xe5\xf5. \xef\xee\xe4\xe4\xe5\xf0\xe6\xea\xe0##tgopen", imgui.ImVec2(btnCW, btnCH)) then
                    local opened = winOpenUrl(tgUrl)
                    -- (запасной запуск через os.execute удалён: он открывал окно cmd.exe)
                    pcall(function()
                        if imgui.SetClipboardText then imgui.SetClipboardText(tgHandle) end
                    end)
                    if opened then
                        -- sampAddChatMessage хочет сырые CP1251-байты, а не UTF8 —
                        -- u8() тут был лишним и превращал текст в чате в кракозябры
                        pcall(sampAddChatMessage, "{00FF88}[MSW] \xf0\x9f\x93\xa2 " .. "\xee\xf2\xea\xf0\xfb\xe2\xe0\xfe \xd2\xe5\xeb\xe5\xe3\xf0\xe0\xec: " .. tgHandle, -1)
                    else
                        pcall(sampAddChatMessage, "{00CCFF}[MSW] \xf0\x9f\x93\x8b Telegram: " .. tgHandle .. " (\xf1\xea\xee\xef\xe8\xf0\xee\xe2\xe0\xed\xee)", -1)
                    end
                end
                prettyBtnPop(_pbtg) end
                imgui.PopStyleColor(3)
            end
            imgui.SameLine(0, gapC)
            do
                local chUrl   = (PCS_UPDATE and PCS_UPDATE.cfg and PCS_UPDATE.cfg.channel_url)   or "https://t.me/helper_stats"
                local chShort = (PCS_UPDATE and PCS_UPDATE.cfg and PCS_UPDATE.cfg.channel_short) or "t.me/helper_stats"
                local chBp    = imgui.GetCursorScreenPos()
                imgui.PushStyleColor(imgui.Col.Button,        iv4(0.16,0.55,0.85,1.0))
                imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(0.22,0.68,0.96,1.0))
                imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(0.30,0.78,1.00,1.0))
                do local _pbch = prettyBtnPush(6.0)
                if imgui.Button(PCS_IC.telegram .. "  " .. u8"\xca\xe0\xed\xe0\xeb##tgchannel", imgui.ImVec2(btnCW, btnCH)) then
                    -- ссылку открываем без консоли (WinAPI), запасной вариант —
                    -- os.execute('start ...'); ссылка ещё и копируется в буфер
                    local opened = winOpenUrl(chUrl)
                    -- (запасной запуск через os.execute удалён: он открывал окно cmd.exe)
                    pcall(function()
                        if imgui.SetClipboardText then imgui.SetClipboardText(chUrl) end
                    end)
                    if opened then
                        pcall(sampAddChatMessage, "{00FF88}[PC Stats] " .. "\xee\xf2\xea\xf0\xfb\xe2\xe0\xfe\x20\xea\xe0\xed\xe0\xeb\x3a\x20" .. "{A0A0A0}" .. chShort, -1)
                    else
                        pcall(sampAddChatMessage, "{00CCFF}[PC Stats] " .. "\xea\xe0\xed\xe0\xeb\x3a\x20" .. "{A0A0A0}" .. chShort .. "\x20\x28\xf1\xea\xee\xef\xe8\xf0\xee\xe2\xe0\xed\xee\x29", -1)
                    end
                end
                prettyBtnPop(_pbch) end
                imgui.PopStyleColor(3)
            end
            imgui.SameLine(0, gapC)
            do
                local dcHandle = "@marco_santiago888"
                imgui.PushStyleColor(imgui.Col.Button,        iv4(0.22,0.24,0.68,1.0))
                imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(0.29,0.33,0.86,1.0))
                imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(0.37,0.42,1.00,1.0))
                do local _pbdc = prettyBtnPush(6.0)
                if imgui.Button(PCS_IC.discord .. "  Discord##dccopy", imgui.ImVec2(btnCW, btnCH)) then
                    local copied = false
                    pcall(function()
                        if imgui.SetClipboardText then
                            imgui.SetClipboardText(dcHandle)
                            copied = true
                        end
                    end)
                    if copied then
                        pcall(sampAddChatMessage, "{00FF88}[MSW] \xf0\x9f\x93\xa2 " .. "\xd1\xea\xee\xef\xe8\xf0\xee\xe2\xe0\xed\xee: " .. dcHandle, -1)
                    else
                        pcall(sampAddChatMessage, "{7289DA}[MSW] \xf0\x9f\x93\x8b Discord: " .. dcHandle, -1)
                    end
                end
                prettyBtnPop(_pbdc) end
                imgui.PopStyleColor(3)
            end
        end)

        secTitle(u8"\xce\xe1\xed\xee\xe2\xeb\xe5\xed\xe8\xff")
        do
        local U0 = PCS_UPDATE
        local showProg0 = U0 and (U0.state.installing or (tonumber(U0.state.dlProg) or 0) > 0)
        aboutCard("##updcard", showProg0 and 202 or 148, function(aw, ch)
            imgui.SetWindowFontScale(aboutBaseScale)
            local U = PCS_UPDATE
            local chShort = (U and U.cfg and U.cfg.channel_short) or "t.me/helper_stats"

            imgui.SetCursorPos(imgui.ImVec2(SFtext(16), SFtext(12)))
            imgui.TextColored(iv4(0.55,0.62,0.80,1.0), u8"\xd2\xe5\xea\xf3\xf9\xe0\xff\x20\xe2\xe5\xf0\xf1\xe8\xff\x3a")
            imgui.SameLine(0,8)
            imgui.TextColored(iv4(1,1,1,1), "v" .. SCRIPT_VER)

            imgui.SetCursorPos(imgui.ImVec2(SFtext(16), SFtext(32)))
            imgui.TextColored(iv4(0.55,0.62,0.80,1.0), u8"\xc0\xea\xf2\xf3\xe0\xeb\xfc\xed\xe0\xff\x20\xe2\xe5\xf0\xf1\xe8\xff\x3a")
            imgui.SameLine(0,8)
            local modeTag = (U and U.state.lastWasSilent) and u8"\x20\x28\xe0\xe2\xf2\xee\x29" or u8"\x20\x28\xe2\xf0\xf3\xf7\xed\xf3\xfe\x29"
            if not U then
                imgui.TextColored(iv4(0.6,0.6,0.6,1.0), u8"\xed\xe5\xe8\xe7\xe2\xe5\xf1\xf2\xed\xee")
            elseif U.state.checking then
                imgui.TextColored(iv4(0.45,0.70,1.00,1.0), u8"\xcf\xf0\xee\xe2\xe5\xf0\xea\xe0\x2e\x2e\x2e" .. modeTag)
            elseif U.state.ver_remote then
                if U.state.available then
                    imgui.TextColored(thGold(), "v" .. U.state.ver_remote .. u8"\x20\x28\xee\xe1\xed\xee\xe2\xeb\xe5\xed\xe8\xe5\x21\x29")
