-- окно по центру экрана: текст + кнопки «Да» / «Нет»
function PCS_drawDangerPopup()
    local kind = St._dangerPopupKind
    if not kind then St._dangerPopupOpenedOnce = false; return end
    local info = PCS_DANGER_INFO[kind]
    if not info then St._dangerPopupKind = nil; return end
    if not St._dangerPopupOpenedOnce then
        St._dangerPopupOpenedOnce = true
        pcall(imgui.OpenPopup, "##pcsDanger")
    end
    pcall(function()
        local io_ = imgui.GetIO()
        imgui.SetNextWindowPos(imgui.ImVec2(io_.DisplaySize.x * 0.5, io_.DisplaySize.y * 0.5),
            imgui.Cond and imgui.Cond.Appearing or 0, imgui.ImVec2(0.5, 0.5))
    end)
    pcall(imgui.SetNextWindowSize, imgui.ImVec2(S(340), 0), imgui.Cond and imgui.Cond.Appearing or 0)
    local _mps = pushModernPopupStyle()
    local began = false
    local ok, err = pcall(function()
        if imgui.BeginPopup("##pcsDanger") then
            began = true
            imgui.TextColored(iv4(info.col[1], info.col[2], info.col[3], 1.0), info.title)
            imgui.Spacing()
            imgui.PushTextWrapPos(imgui.GetCursorPosX() + S(310))
            imgui.TextColored(thDim(), info.text)
            imgui.PopTextWrapPos()
            imgui.Spacing()
            imgui.Spacing()
            local aw2 = imgui.GetContentRegionAvail().x
            local half = (aw2 - S(8)) * 0.5
            if PCS_gdButton(u8"\xcd\xe5\xf2".. "##dgNo", half, S(32), { 0.55, 0.57, 0.65 }, 8.0) then
                St._dangerPopupKind = nil
                imgui.CloseCurrentPopup()
            end
            imgui.SameLine(0, S(8))
            if PCS_gdButton(u8"\xc4\xe0".. "##dgYes", half, S(32), { info.col[1], info.col[2], info.col[3] }, 8.0) then
                St._dangerPopupKind = nil
                imgui.CloseCurrentPopup()
                local fn = info.run
                lua_thread.create(function()
                    wait(150)
                    pcall(fn)
                end)
            end
        else
            -- закрылось кликом мимо / Esc — считаем отменой
            if St._dangerPopupOpenedOnce then St._dangerPopupKind = nil end
        end
    end)
    if began then pcall(imgui.EndPopup) end
    if not ok then
        St._dangerPopupKind = nil
        PCS_quietErr("ui@danger", err)
    end
    popModernPopupStyle(_mps)
end

-- нижняя панель вкладки "О скрипте": красивые кнопки управления скриптом.
-- Каждая (кроме «Закрыть меню») открывает окно подтверждения с кнопками Да / Нет.
function drawDangerButtonsRow(aw, r, g, b)
    local gap = S(8)
    local h = S(38)
    local w3 = (aw - gap * 2) / 3
    local w2 = (aw - gap) / 2
    local y0 = imgui.GetCursorPosY()
    local V2 = imgui.ImVec2

    imgui.SetCursorPos(V2(0, y0))
    if PCS_gdButton(ICON_SYNC .. "  " .. u8"\xcf\xe5\xf0\xe5\xe7\xe0\xe3\xf0\xf3\xe7\xe8\xf2\xfc" .. "##dgReload", w3, h, { r, g, b }, 8.0) then
        St._dangerPopupKind = "reload"
    end
    imgui.SetCursorPos(V2(w3 + gap, y0))
    if PCS_gdButton(ICON_POWER .. "  " .. u8"\xc2\xfb\xea\xeb\xfe\xf7\xe8\xf2\xfc" .. "##dgDisable", w3, h, { 1.0, 0.62, 0.20 }, 8.0) then
        St._dangerPopupKind = "disable"
    end
    imgui.SetCursorPos(V2((w3 + gap) * 2, y0))
    if PCS_gdButton(PCS_IC.xmark .. "  " .. u8"\xc7\xe0\xea\xf0\xfb\xf2\xfc\x20\xec\xe5\xed\xfe" .. "##dgCloseMenu", w3, h, { 0.55, 0.65, 0.95 }, 8.0) then
        requestCloseMenu()
    end

    local y1 = y0 + h + gap
    imgui.SetCursorPos(V2(0, y1))
    if PCS_gdButton(ICON_UNDO .. "  " .. u8"\xd1\xe1\xf0\xee\xf1\xe8\xf2\xfc\x20\xe4\xe0\xed\xed\xfb\xe5" .. "##dgReset", w2, h, { 0.95, 0.35, 0.35 }, 8.0) then
        St._dangerPopupKind = "reset"
    end
    imgui.SetCursorPos(V2(w2 + gap, y1))
    if PCS_gdButton(ICON_TRASH .. "  " .. u8"\xd3\xe4\xe0\xeb\xe8\xf2\xfc" .. "##dgDelete", w2, h, { 0.90, 0.20, 0.20 }, 8.0) then
        St._dangerPopupKind = "delete"
    end
    imgui.SetCursorPos(V2(0, y1 + h))
end

-- ── Настройки -> «Команды и клавиши» ──
function PCS_drawHotkeyRow(a)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local r, g, b = getAcc()
    local dl = imgui.GetWindowDrawList()
    local aw = imgui.GetContentRegionAvail().x
    local p = imgui.GetCursorScreenPos()
    local pad = S(12)
    local h = S(76)
    local q = V2(p.x + aw, p.y + h)
    local vk = tonumber(cfg[a.cfg]) or 0
    local waiting = (St.awaitingHotkeyBind == true and St._hkBindTarget == a.cfg)
    imgui.Dummy(V2(aw, h))
    dl:AddRectFilled(p, q, U32(iv4(r * 0.10, g * 0.10, b * 0.10, pcsRowA(0.96))), S(10))
    dl:AddRect(p, q, U32(iv4(a.col[1] * 0.7, a.col[2] * 0.7, a.col[3] * 0.7, 0.70)), S(10), 0, 1.2)
    dl:AddRectFilled(V2(p.x + S(1), p.y + S(8)), V2(p.x + S(4), q.y - S(8)), U32(iv4(a.col[1], a.col[2], a.col[3], 1.0)), S(2))
    dl:AddText(V2(p.x + pad + S(4), p.y + S(9)), U32(iv4(1, 1, 1, 1)), a.name)

    local capH = S(30)
    local innerW = aw - pad * 2 - S(4)
    local nBtn = (a.id == "menu") and 3 or 2
    local gap = S(6)
    local capW = math.floor(innerW * 0.30)
    local bw = math.floor((innerW - capW - gap * nBtn) / nBtn)
    local cx, cy = p.x + pad + S(4), p.y + S(34)

    local pulse = 0.5 + 0.5 * math.sin(os.clock() * 5)
    local bg, border
    if waiting then
        bg = iv4(r * 0.22 + 0.04, g * 0.22 + 0.04, b * 0.22 + 0.04, 1.0)
        border = iv4(r, g, b, 0.50 + 0.50 * pulse)
    elseif vk > 0 then
        bg = iv4(r * 0.16 + 0.05, g * 0.16 + 0.05, b * 0.16 + 0.05, 1.0)
        border = iv4(r * 0.95, g * 0.95, b * 0.95, 0.90)
    else
        bg = iv4(0.10, 0.11, 0.15, 1.0)
        border = iv4(0.45, 0.46, 0.52, 0.80)
    end
    dl:AddRectFilled(V2(cx, cy), V2(cx + capW, cy + capH), U32(bg), 7)
    dl:AddRect(V2(cx, cy), V2(cx + capW, cy + capH), U32(border), 7, 0, 1.6)
    local label = waiting and u8"\xcd\xe0\xe6\xec\xe8\xf2\xe5\x2e\x2e\x2e" or (vk > 0 and vkName(vk) or u8"\xed\xe5\x20\xed\xe0\xe7\xed\xe0\xf7\xe5\xed\xe0")
    local ts = imgui.CalcTextSize(label)
    dl:AddText(V2(cx + math.max(2, (capW - ts.x) / 2), cy + (capH - ts.y) / 2),
        U32(waiting and iv4(1.0, 0.90, 0.50, 1.0) or iv4(1, 1, 1, 1)), label)

    local bx = cx + capW + gap
    imgui.SetCursorScreenPos(V2(bx, cy))
    if PCS_gdButton((waiting and u8"\xce\xf2\xec\xe5\xed\xe0" or u8"\xcd\xe0\xe7\xed\xe0\xf7\xe8\xf2\xfc") .. "##hkb" .. a.id, bw, capH, { r, g, b }, 6.0) then
        if waiting then
            St.awaitingHotkeyBind = false; St._hkBindTarget = nil
        else
            St._hkBindTarget = a.cfg; St.awaitingHotkeyBind = true
        end
    end
    imgui.SetCursorScreenPos(V2(bx + bw + gap, cy))
    if PCS_gdButton(u8"\xd1\xed\xff\xf2\xfc" .. "##hkc" .. a.id, bw, capH, { 0.85, 0.35, 0.35 }, 6.0) then
        St.awaitingHotkeyBind = false; St._hkBindTarget = nil
        cfg[a.cfg] = 0
        St._hkShown[a.id] = nil
        pcall(saveCfg)
    end
    if a.id == "menu" then
        imgui.SetCursorScreenPos(V2(bx + (bw + gap) * 2, cy))
        if PCS_gdButton("F9##hkd" .. a.id, bw, capH, { 0.60, 0.70, 0.90 }, 6.0) then
            St.awaitingHotkeyBind = false; St._hkBindTarget = nil
            cfg.menuHotkeyVK = 120
            pcall(saveCfg)
        end
    end
    imgui.SetCursorScreenPos(V2(p.x, q.y))
    imgui.Dummy(V2(1, S(6)))
end

