end

-- ============================================================
function fmtTaxTime(t)
    if not t or t == 0 then return u8"\xed\xe5\xf2\x20\xe4\xe0\xed\xed\xfb\xf5" end
    return os.date("%d.%m.%Y %H:%M:%S", t)
end

function fmtTaxAgo(t)
    if not t or t == 0 then return "" end
    local d = os.time() - t
    if d < 60 then return " (" .. d .. u8" \xf1\x2e \xed\xe0\xe7\xe0\xe4)" end
    if d < 3600 then return " (" .. math.floor(d/60) .. u8" \xec\xe8\xed\x2e \xed\xe0\xe7\xe0\xe4)" end
    if d < 86400 then return " (" .. math.floor(d/3600) .. u8" \xf7\x2e \xed\xe0\xe7\xe0\xe4)" end
    return " (" .. math.floor(d/86400) .. u8" \xe4\x2e \xed\xe0\xe7\xe0\xe4)"
end

-- форматирует секунды в "Чч Mм" / "Mм Cс" — для отображения оставшегося
-- времени до следующей оплаты (и "Автооплата", и "При входе")
function fmtDuration(sec)
    sec = math.max(0, math.floor(sec + 0.5))
    local hh = math.floor(sec / 3600)
    local mm = math.floor((sec % 3600) / 60)
    local ss = sec % 60
    if hh > 0 then return hh .. u8"\xf7\x20" .. mm .. u8"\xec" end
    if mm > 0 then return mm .. u8"\xec\x20" .. ss .. u8"\xf1" end
    return ss .. u8"\xf1"
end

-- ── тумблер настройки вкладки "Оплата": свитч + подпись + (опционально)
-- пояснение под ним серым цветом, единый стиль для всей вкладки ──
function taxToggleRow(id, labelU8, isOn, onToggle, descU8)
    if drawToggleSwitch(id, isOn) then
        onToggle(not isOn)
        saveCfg()
    end
    imgui.SameLine(0, S(8))
    imgui.TextColored(iv4(1,1,1,1), labelU8)
    if descU8 then
        imgui.TextColored(thDim(), "  "..descU8)
    end
    imgui.Dummy(imgui.ImVec2(0, S(4)))
end

-- ── строка мини-таблицы "Логи оплаты налогов": Время | Сумма | Способ |
-- Статус. Тот же стиль и та же разметка колонок, что и у PD.drawIncomeRow ──
function TX.drawLogRow(e)
    local avail = imgui.GetContentRegionAvail().x
    local h     = S(28)
    local dl    = imgui.GetWindowDrawList()
    local p     = imgui.GetCursorScreenPos()
    local rr,rg,rb = getRowBgColor()
    _rowIndex = _rowIndex + 1
    local shade = (_rowIndex % 2 == 0) and 0.13 or 0.07
    local minV  = (_rowIndex % 2 == 0) and 0.10 or 0.05
    local bgR = math.max(rr*shade, minV)
    local bgG = math.max(rg*shade, minV)
    local bgB = math.max(rb*shade, minV)
    dl:AddRectFilled(imgui.ImVec2(p.x, p.y), imgui.ImVec2(p.x+avail, p.y+h),
        imgui.ColorConvertFloat4ToU32(iv4(bgR,bgG,bgB,pcsRowA(0.98))), 4)

    local cols = {
        { w = 0.14, txt = e.time, col = thDim() },
        { w = 0.22, txt = e.noTax and "--" or fmtMoney(string.format("%.0f", e.amount or 0)),
          col = e.noTax and thDim() or thGold() },
        { w = 0.24, txt = (e.noTax and u8"\xed\xe5\xf2 \xed\xe0\xeb\xee\xe3\xee\xe2")
            or ((e.kind == "family") and u8"\xf1\xe5\xec. \xea\xe2\xe0\xf0\xf2\xe8\xf0\xe0")
            or ((e.kind == "org") and u8"\xee\xf0\xe3\xe0\xed\xe8\xe7\xe0\xf6\xe8\xff")
            or u8"\xed\xe0\xeb\xee\xe3\xe8",
          col = (e.kind == "family" and iv4(0.55,0.75,1.0,1.0))
            or (e.kind == "org" and iv4(0.95,0.55,0.75,1.0))
            or (e.noTax and thGold() or thGreen()) },
        { w = 0.18, txt = e.auto and u8"\xe0\xe2\xf2\xee" or u8"\xe2\xf0\xf3\xf7\xed\xf3\xfe", col = thAcc() },
        { w = 0.22, txt = e.noTax and "--" or u8"\xf3\xf1\xef\xe5\xf8\xed\xee",
          col = e.noTax and thDim() or thGreen() },
    }
    local x = p.x + S(8)
    for _, c in ipairs(cols) do
        imgui.SetCursorScreenPos(imgui.ImVec2(x, p.y + S(5)))
        imgui.TextColored(c.col, c.txt)
        x = x + avail * c.w
    end
    imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + h))
end

function TX.drawLogSection()
    if not St.taxLogLoaded then TX.loadLog() end
    local r, g, b = getAcc()

    secTitle(u8"\xcb\xee\xe3\xe8\x20\xee\xef\xeb\xe0\xf2\xfb\x20\xed\xe0\xeb\xee\xe3\xee\xe2")

    -- список дней, в которые были записи (новые сверху)
    local seenDates, dateList = {}, {}
    for _, e in ipairs(St.taxEntries or {}) do
        if not seenDates[e.date] then
            seenDates[e.date] = true
            dateList[#dateList+1] = e.date
        end
    end
    table.sort(dateList, function(a, c) return a > c end)

    if #dateList == 0 then
        imgui.TextColored(thDim(), "  " ..
            u8"\xcf\xee\xea\xe0\x20\xed\xe5\xf2\x20\xed\xe8\x20\xee\xe4\xed\xee\xe9\x20\xe7\xe0\xef\xe8\xf1\xe8\x20\xee\xe1\x20\xee\xef\xeb\xe0\xf2\xe5\x20\xed\xe0\xeb\xee\xe3\xee\xe2\x2e\x20\xc7\xe0\xef\xe8\xf1\xe8\x20\xef\xee\xff\xe2\xff\xf2\xf1\xff\x20\xef\xee\xf1\xeb\xe5\x20\xef\xe5\xf0\xe2\xee\xe9\x20\xee\xef\xeb\xe0\xf2\xfb\x2e")
        return
    end

    -- выбранный день: по умолчанию самый свежий; после выбора в календаре
    -- St._taxLogSelectedDate хранит выбранную дату
    if not (St._taxLogSelectedDate and seenDates[St._taxLogSelectedDate]) then
        St._taxLogSelectedDate = dateList[1]
    end
    local shownDate = St._taxLogSelectedDate
    local shownIdx = 1
    for i, d in ipairs(dateList) do
        if d == shownDate then shownIdx = i; break end
    end

    do
        -- плитка-кнопка: скруглённые углы, вертикальный градиент, мягкая
        -- тень, крупный заголовок (копия оформления плитки PayDay)
        local dl = imgui.GetWindowDrawList()
        local p0 = imgui.GetCursorScreenPos()
        local btnW = imgui.GetContentRegionAvail().x
        local btnH = S(52)
        local rounding = S(12)

        local hovered = imgui.IsMouseHoveringRect(p0, imgui.ImVec2(p0.x + btnW, p0.y + btnH), true)

        dl:AddRectFilled(imgui.ImVec2(p0.x + S(2), p0.y + S(4)),
            imgui.ImVec2(p0.x + btnW + S(2), p0.y + btnH + S(4)),
            imgui.ColorConvertFloat4ToU32(iv4(0, 0, 0, 0.35)), rounding)

        local topMul, botMul = hovered and 1.05 or 0.85, hovered and 0.55 or 0.40
        local colTop = imgui.ColorConvertFloat4ToU32(iv4(r*topMul, g*topMul, b*topMul, 1.0))
        local colBot = imgui.ColorConvertFloat4ToU32(iv4(r*botMul, g*botMul, b*botMul, 1.0))
        dl:AddRectFilledMultiColor(p0, imgui.ImVec2(p0.x + btnW, p0.y + btnH),
            colTop, colTop, colBot, colBot)
        dl:AddRect(p0, imgui.ImVec2(p0.x + btnW, p0.y + btnH),
            imgui.ColorConvertFloat4ToU32(iv4(1, 1, 1, hovered and 0.25 or 0.12)), rounding, 0, 1.5)

        local title = PCS_IC.calendar .. "  " .. u8"\xcb\xee\xe3\xe8\x20\xee\xef\xeb\xe0\xf2\xfb\x20\xed\xe0\xeb\xee\xe3\xee\xe2"
        local subtitle = PD.fmtDateRu(shownDate) .. "   (" .. tostring(shownIdx) .. " " ..
            u8"\xe8\xe7" .. " " .. tostring(#dateList) .. ")"

        pcall(imgui.SetWindowFontScale, 1.35)
        local titleSz = imgui.CalcTextSize(title)
        pcall(imgui.SetWindowFontScale, 1.0)
        local subSz = imgui.CalcTextSize(subtitle)
        local blockH = titleSz.y + subSz.y + S(4)
        local textX = p0.x + S(16)
        local textY = p0.y + (btnH - blockH) / 2

        dl:AddText(imgui.ImVec2(textX, textY), PCS_TA(imgui.ColorConvertFloat4ToU32(iv4(1,1,1,1))), title)
        dl:AddText(imgui.ImVec2(textX + 0.5, textY), PCS_TA(imgui.ColorConvertFloat4ToU32(iv4(1,1,1,1))), title)
        dl:AddText(imgui.ImVec2(textX, textY + titleSz.y + S(4)),
            PCS_TA(imgui.ColorConvertFloat4ToU32(iv4(0.92,0.94,0.98,0.85))), subtitle)

        local arrowTxt = u8"\xbb"
        local arrowSz = imgui.CalcTextSize(arrowTxt)
        dl:AddText(imgui.ImVec2(p0.x + btnW - arrowSz.x - S(16), p0.y + (btnH - arrowSz.y) / 2),
            PCS_TA(imgui.ColorConvertFloat4ToU32(iv4(1,1,1,0.8))), arrowTxt)

        St._taxLogBtnScreenPos = p0
        imgui.SetCursorScreenPos(p0)
        if imgui.InvisibleButton("##taxOpenCalendarBig", imgui.ImVec2(btnW, btnH)) then
            St._taxCalendarPopupOpen = true
            St._taxCalendarPopupOpenedOnce = false
        end
        if imgui.IsItemHovered and imgui.IsItemHovered() then
            pcall(function()
                imgui.BeginTooltip()
                imgui.TextColored(iv4(0.75,0.80,0.90,1.0), u8"\xca\xe0\xeb\xe5\xed\xe4\xe0\xf0\xfc\x20\xef\xee\x20\xe4\xed\xff\xec\x20\xf1\x20\xee\xef\xeb\xe0\xf2\xee\xe9\x20\xed\xe0\xeb\xee\xe3\xee\xe2")
                imgui.EndTooltip()
            end)
        end
    end

    -- итог выбранного дня — текст прямо под кнопкой
    do
        local dSum, dCnt = 0, 0
        for _, e in ipairs(St.taxEntries or {}) do
            if e.date == shownDate then
                dCnt = dCnt + 1
                if not e.noTax then dSum = dSum + (e.amount or 0) end
            end
        end
        imgui.TextColored(thGreen(), "  " .. u8"\xc8\xf2\xee\xe3\xee\x20\xe7\xe0\x20\xe4\xe5\xed\xfc" .. ": " ..
            fmtMoney(string.format("%.0f", dSum)) .. "   (" .. tostring(dCnt) .. " " .. u8"\xe7\xe0\xef\x2e" .. ")")
    end

    -- заголовок мини-таблицы (те же пропорции колонок, что и в TX.drawLogRow)
    do
        local avail = imgui.GetContentRegionAvail().x
        local p = imgui.GetCursorScreenPos()
        local headers = {
            { w = 0.16, txt = u8"\xc2\xf0\xe5\xec\xff" },
            { w = 0.28, txt = u8"\xd1\xf3\xec\xec\xe0" },
            { w = 0.28, txt = u8"\xd1\xef\xee\xf1\xee\xe1" },
            { w = 0.28, txt = u8"\xd1\xf2\xe0\xf2\xf3\xf1" },
        }
        local x = p.x + S(8)
        for _, hd in ipairs(headers) do
            imgui.SetCursorScreenPos(imgui.ImVec2(x, p.y))
            imgui.TextColored(thDim(), hd.txt)
            x = x + avail * hd.w
        end
        imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + S(18)))
    end

    imgui.PushStyleColor(imgui.Col.ChildBg, iv4(0,0,0,0))
    imgui.BeginChild("##taxLogTbl", imgui.ImVec2(0, S(220)), false)
    _rowIndex = 0
    local shown = 0
    for _, e in ipairs(St.taxEntries or {}) do
        if e.date == shownDate then
            TX.drawLogRow(e)
            shown = shown + 1
            if shown >= 200 then break end
        end
    end
    if shown == 0 then
        imgui.TextColored(thDim(), "  " .. u8"\xed\xe5\xf2\x20\xe7\xe0\xef\xe8\xf1\xe5\xe9\x20\xe7\xe0\x20\xfd\xf2\xee\xf2\x20\xe4\xe5\xed\xfc")
    end
    imgui.EndChild()
    imgui.PopStyleColor()
end

function PCS_safeManualPay()
    local ok, err = pcall(payTaxesNow, false)
    if not ok then
        _taxState = 0
        _phoneOpBusy = false
        St._phoneOpBusySince = nil
        print("[PC Stats][tax] manual pay error: " .. tostring(err))
        pcall(sampAddChatMessage, "{FF6666}[PC Stats] " .. "\xce\xef\xeb\xe0\xf2\xe0\x20\xef\xf0\xe5\xf0\xe2\xe0\xed\xe0\x20\xe8\xe7\x2d\xe7\xe0\x20\xee\xf8\xe8\xe1\xea\xe8\x2e\x20\xcf\xee\xef\xf0\xee\xe1\xf3\xe9\xf2\xe5\x20\xe5\xf9\xb8\x20\xf0\xe0\xe7\x2e", -1)
    end
end

function PCS_uiSection(titleU8, col)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local p  = imgui.GetCursorScreenPos()
    local aw = imgui.GetContentRegionAvail().x
    local hh = S(22)
    dl:AddRectFilled(V2(p.x, p.y + 2), V2(p.x + 4, p.y + hh), U32(iv4(col[1], col[2], col[3], 1.0)), 2)
    imgui.SetCursorScreenPos(V2(p.x + S(12), p.y + 2))
    imgui.TextColored(iv4(col[1], col[2], col[3], 1.0), titleU8)
    dl:AddLine(V2(p.x + S(12), p.y + hh + 2), V2(p.x + aw, p.y + hh + 2), U32(iv4(col[1], col[2], col[3], 0.28)), 1.0)
    imgui.SetCursorScreenPos(V2(p.x, p.y + hh + S(8)))
    imgui.Dummy(V2(aw, 1))
end

-- плитка "подпись + значение"
function PCS_uiTile(x, y, w, h, col, labelU8, valueStr, valCol)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    dl:AddRectFilled(V2(x, y), V2(x + w, y + h), U32(iv4(col[1]*0.10, col[2]*0.10, col[3]*0.10, pcsRowA(0.92))), 10)
    dl:AddRect(V2(x, y), V2(x + w, y + h), U32(iv4(col[1], col[2], col[3], 0.55)), 10, 0, 1.2)
    dl:AddRectFilled(V2(x + 8, y), V2(x + w - 8, y + 3), U32(iv4(col[1], col[2], col[3], 1.0)), 2)
    imgui.SetCursorScreenPos(V2(x + S(12), y + S(9)))
    imgui.TextColored(thDim(), labelU8)
    imgui.SetCursorScreenPos(V2(x + S(12), y + S(29)))
    imgui.TextColored(valCol or iv4(1, 1, 1, 1), valueStr)
end

FAM = FAM or { state = nil, busy = false, status = "", lastAttempt = 0,
               _loginFired = false, _loginAt = 0, stateAt = 0 }

function FAM.setStatus(t) FAM.status = t or "" end

-- журнал шагов квартиры: пишется в консоль и в файл fam_trace.log в папке скрипта
function FAM.log(m)
    m = tostring(m)
    print("[PC Stats][fam] " .. m)
    pcall(function()
        local f = io.open(CFG_DIR .. "/fam_trace.log", "a")
        if f then f:write(os.date("%d.%m %H:%M:%S ") .. m .. "\n"); f:close() end
    end)
end

function FAM.touch(msg)
    FAM.stateAt = os.clock()
    FAM.setStatus(msg)
    FAM.log(msg)
end

function FAM.finish(msg, ok)
    FAM.busy = false
    FAM.state = nil
    FAM.setStatus(msg)
    FAM.log("финиш: " .. tostring(msg) .. (ok and " [ok]" or " [ошибка]"))
    if ok then
        cfg.famAptLastPayTime = os.time()
        saveCfg()
    end
end

function FAM.closeMenu(msg, ok)
    FAM.state = "closing"
    FAM.pendingMsg, FAM.pendingOk = msg, ok
    FAM.touch("Закрываю меню квартиры…")
    lua_thread.create(function()
        wait(700)
        if FAM.state ~= "closing" then return end
        if sampIsDialogActive() then
            FAM.log("диалог ещё открыт — закрываю (аналог Esc)")
            sampCloseCurrentDialogWithButton(0)
            wait(300)
        end
        if FAM.state ~= "closing" then return end
        FAM.state = "closed"
        FAM.log("нажимаю кнопку закрытия 2077")
        sampSendClickTextdraw(2077)
        wait(300)
        FAM.finish(FAM.pendingMsg or "Готово", FAM.pendingOk)
    end)
end

function FAM.busyReason()
    if _taxState ~= 0 then return "идёт оплата налогов (шаг " .. tostring(_taxState) .. ")" end
    if _phoneOpBusy == true then return "телефон занят оплатой" end
    if _phoneFetchState then return "телефон обновляет данные" end
    if _cefFetching == true then return "идёт CEF-запрос" end
    if St._closePhoneRunning then return "телефон закрывается" end
    if St._taxDeferredPending then return "отложена оплата налогов" end
    if St._postPayUntil and os.clock() < St._postPayUntil then return "пауза после оплаты" end
    return nil
end

FAM.TAX_PHRASE = "\xed\xe0\xeb\xee\xe3\x20\xed\xe0\x20\xea\xe2\xe0\xf0\xf2\xe8\xf0\xf3" -- "налог на квартиру" в CP1251

function FAM.amountFrom(t)
    local plain = (tostring(t or ""):gsub("{%x%x%x%x%x%x}", ""))
    return plain:match("%$%s*(%d+)")
end

function FAM.dumpText(t)
    return (tostring(t or ""):gsub("[%c]", " "):sub(1, 400))
end

function FAM.run(isAuto)
    if FAM.busy then return false end
    if St.waitingStats then
        FAM.log("отказ: идёт сбор статистики (/stats)")
        FAM.setStatus("Подождите: идёт сбор статистики, оплата квартиры повторится позже")
        return false
    end
    local why = FAM.busyReason()
    if why then
        FAM.log("отказ: " .. why)
        FAM.setStatus("Занято: " .. why .. ", повторю позже")
        return false
    end
    if not isPlayerActuallySpawned() then
        FAM.setStatus("Сначала зайдите в игру")
        return false
    end
    FAM.busy = true
    FAM.lastAttempt = os.time()
    FAM.state = "open"
    FAM.listDone = false   -- диалог списка (2763) уже обработан
    FAM.clicked = false    -- текстдрав «Оплатить» уже нажат
    FAM.paid = false       -- диалог долга (15247) уже обработан
    FAM.seenTaxText = nil
    FAM.log("старт (" .. (isAuto and "авто" or "вручную") .. ")")
    FAM.touch("Открываю семейное меню…")
    lua_thread.create(function()
        sampSendChat("/fammenu")
        while FAM.busy do
            wait(250)
            local idle = os.clock() - (FAM.stateAt or 0)
            if FAM.state == "closing" and idle > 4 then
                FAM.finish(FAM.pendingMsg or "Готово", FAM.pendingOk)
            elseif idle > 25 then
                FAM.finish("Не удалось оплатить: меню не отвечает", false)
            end
        end
    end)
    return true
end

function FAM.onDialog(id, text, style)
    if id == 27833 then
        FAM.log("диалог 27833 style=" .. tostring(style) .. " busy=" .. tostring(FAM.busy) .. " текст: " .. FAM.dumpText(text))
    end
    if not FAM.busy then return end
    -- диалог оплаты налога на квартиру (ид 27833, стиль 1 = ввод): читаем сумму из строки
    -- «Сейчас налог на квартиру составляет $ N», вписываем N, оплачиваем, закрываем меню
    if id == 27833 and style == 1 and not FAM.paid then
        FAM.paid = true
        local amt = FAM.amountFrom(text) or (FAM.seenTaxText and FAM.amountFrom(FAM.seenTaxText))
        FAM.log("диалог оплаты 27833, налог на квартиру: " .. tostring(amt)
            .. " | строка из текстдрава: " .. FAM.dumpText(FAM.seenTaxText))
        lua_thread.create(function()
            wait(0)
            if not amt then
                FAM.finish("Не нашёл сумму налога (см. fam_trace.log)", false)
            elseif amt == "0" then
                sampCloseCurrentDialogWithButton(0)
                FAM.closeMenu("Налог на квартиру $0 — платить нечего", true)
            else
                sampSetCurrentDialogEditboxText(amt)
                wait(0)
                sampCloseCurrentDialogWithButton(1)
                FAM.closeMenu("Оплачено за квартиру: $" .. amt, true)
            end
        end)
        return
    end
    if id == 2763 and not FAM.listDone then
        FAM.listDone = true
        FAM.touch("Выбираю квартиру…")
        lua_thread.create(function()
            wait(0)
            sampSetCurrentDialogListItem(9)
            sampCloseCurrentDialogWithButton(1)
        end)
    elseif id == 15247 and FAM.clicked and not FAM.paid then
        FAM.paid = true
        local opl = tostring(text or ""):match("{ffff00}%$(%d+){f")
        FAM.log("диалог долга, сумма: " .. tostring(opl))
        lua_thread.create(function()
            wait(0)
            if opl == "0" then
                sampCloseCurrentDialogWithButton(0)
                FAM.closeMenu("Долгов по квартире нет", true)
            elseif opl then
                sampSetCurrentDialogEditboxText(opl)
                wait(0)
                sampCloseCurrentDialogWithButton(1)
                FAM.closeMenu("Оплачено за квартиру: $" .. opl, true)
            else
                sampCloseCurrentDialogWithButton(0)
                FAM.finish("Не нашёл сумму долга в диалоге квартиры", false)
            end
        end)
    end
end

function FAM.onTextDraw(id, data)
    local raw = data and tostring(data.text or "") or ""
    if raw:find("%s") and raw:find(FAM.TAX_PHRASE, 1, true) and raw:find("%$") then FAM.seenTaxText = raw end
    if not FAM.busy then return end
    if FAM.state == "closing" and id == 2077 then
        FAM.state = "closed"
        FAM.log("вижу кнопку закрытия 2077 — нажимаю")
        lua_thread.create(function()
            wait(0)
            sampSendClickTextdraw(2077)
            wait(300)
            FAM.finish(FAM.pendingMsg or "Готово", FAM.pendingOk)
        end)
        return
    end
    if FAM.clicked then return end
    for i = 2066, 2078 do
        local x, y = sampTextdrawGetPos(i)
        if x and y and math.abs(x - 369.1336) < 0.05 and math.abs(y - 209.7554) < 0.05 then
            FAM.clicked = true
            FAM.log("нашёл «Оплатить» (текстдрав " .. i .. ")")
            FAM.touch("Нажимаю «Оплатить»…")
            lua_thread.create(function()
                wait(200)
                sampSendClickTextdraw(i)
            end)
            return
        end
    end
end

lua_thread.create(function()
    while true do
        wait(60000)
        pcall(function()
            if not cfg.famAptAuto or FAM.busy then return end
            if os.time() - (FAM.lastAttempt or 0) < 600 then return end
            local iv = math.max(1, tonumber(cfg.famAptIntervalHours) or 24) * 3600
            local last = tonumber(cfg.famAptLastPayTime) or 0
            if last == 0 or os.time() - last >= iv then FAM.run(true) end
        end)
    end
end)

-- оплата квартиры при входе: через 60 секунд после спавна, один раз за заход
lua_thread.create(function()
    local wasSpawned = false
    while true do
        wait(1000)
        pcall(function()
            if not isPlayerActuallySpawned() then
                wasSpawned = false
                FAM._loginFired = false
                return
            end
            if not wasSpawned then
                wasSpawned = true
                FAM._loginAt = os.time()
            end
            if cfg.famAptOnLogin and not FAM._loginFired and os.time() - FAM._loginAt >= 60 then
                if FAM.run(true) then FAM._loginFired = true else FAM._loginAt = os.time() - 50 end
            end
        end)
    end
end)

-- новая шапка вкладки "Налоги": баннер статуса + две плитки
function PCS_txHeader(aw)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local p  = imgui.GetCursorScreenPos()
    local hasPaid = cfg.taxLastPayTime and cfg.taxLastPayTime ~= 0
    local ivSec = math.max(1, tonumber(cfg.taxAutoIntervalHours) or 1) * 3600
    local fresh = hasPaid and (os.time() - cfg.taxLastPayTime) < ivSec
    local c = fresh and { 0.30, 0.90, 0.50 } or (hasPaid and { 1.0, 0.72, 0.20 } or { 0.60, 0.64, 0.74 })
    local hH = S(60)
    dl:AddRectFilled(p, V2(p.x + aw, p.y + hH), U32(iv4(c[1]*0.10, c[2]*0.10, c[3]*0.10, pcsRowA(0.92))), 12)
    dl:AddRect(p, V2(p.x + aw, p.y + hH), U32(iv4(c[1], c[2], c[3], 0.70)), 12, 0, 1.4)
    dl:AddRectFilled(V2(p.x + 10, p.y), V2(p.x + aw - 10, p.y + 3), U32(iv4(c[1], c[2], c[3], 1.0)), 2)
    local cx, cy = p.x + S(30), p.y + hH * 0.5
    dl:AddCircleFilled(V2(cx, cy), S(18), U32(iv4(c[1], c[2], c[3], 0.22)), 28)
    dl:AddCircle(V2(cx, cy), S(18), U32(iv4(c[1], c[2], c[3], 0.90)), 28, 1.5)
    local isz = imgui.CalcTextSize(PCS_IC.taxes)
    dl:AddText(V2(cx - isz.x * 0.5, cy - isz.y * 0.5), U32(iv4(c[1], c[2], c[3], 1.0)), PCS_IC.taxes)
    imgui.SetCursorScreenPos(V2(p.x + S(58), p.y + S(10)))
    imgui.TextColored(iv4(c[1], c[2], c[3], 1.0),
        hasPaid and (fresh and u8"\xcd\xe0\xeb\xee\xe3\xe8 \xee\xef\xeb\xe0\xf7\xe5\xed\xfb" or u8"\xcf\xee\xf0\xe0 \xee\xef\xeb\xe0\xf2\xe8\xf2\xfc \xed\xe0\xeb\xee\xe3\xe8") or u8"\xcd\xe0\xeb\xee\xe3\xe8 \xe5\xf9\xb8 \xed\xe5 \xee\xef\xeb\xe0\xf7\xe8\xe2\xe0\xeb\xe8\xf1\xfc")
    imgui.SetCursorScreenPos(V2(p.x + S(58), p.y + S(32)))
    if hasPaid then
        imgui.TextColored(iv4(1, 1, 1, 1), fmtTaxTime(cfg.taxLastPayTime) .. fmtTaxAgo(cfg.taxLastPayTime))
    else
        imgui.TextColored(thDim(), u8"\x97")
    end

    local gap, tH = S(8), S(54)
    local tw = math.floor((aw - gap) / 2)
    local x0, y0 = p.x, p.y + hH + S(8)
    local hasAmt = cfg.taxLastPayAmount and cfg.taxLastPayAmount > 0
    local hasTotal = cfg.taxTotalPaid and cfg.taxTotalPaid > 0
    PCS_uiTile(x0, y0, tw, tH, { 1.0, 0.72, 0.20 }, u8"\xcf\xee\xf1\xeb\xe5\xe4\xed\xff\xff \xee\xef\xeb\xe0\xf2\xe0",
        hasAmt and fmtMoney(string.format("%.0f", cfg.taxLastPayAmount)) or u8"\x97", thGold())
    PCS_uiTile(x0 + tw + gap, y0, tw, tH, { 0.45, 0.80, 1.0 }, u8"\xc2\xf1\xe5\xe3\xee \xef\xee\xf2\xf0\xe0\xf7\xe5\xed\xee",
        hasTotal and fmtMoney(string.format("%.0f", cfg.taxTotalPaid)) or u8"\x97", thGold())
    imgui.SetCursorScreenPos(V2(p.x, y0 + tH + S(8)))
    imgui.Dummy(V2(aw, 1))
end

function drawTaxesInner(h)
    local r, g, b = getAcc()

    PCS_txHeader(imgui.GetContentRegionAvail().x)

    local _intervalSec = math.max(1, tonumber(cfg.taxAutoIntervalHours) or 1) * 3600
    local _sinceLastPay = ((tonumber(cfg.taxLastPayTime) or 0) ~= 0) and (os.time() - tonumber(cfg.taxLastPayTime)) or nil
    local _dueInSec = _sinceLastPay and math.max(0, _intervalSec - _sinceLastPay) or nil

    imgui.Dummy(imgui.ImVec2(0, S(6)))

    local _busyPay = (_taxState ~= 0) or (_phoneOpBusy == true)
    if _busyPay then
        imgui.PushStyleColor(imgui.Col.Button,        iv4(0.25,0.27,0.33,1.0))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(0.25,0.27,0.33,1.0))
        imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(0.25,0.27,0.33,1.0))
    else
        imgui.PushStyleColor(imgui.Col.Button,        iv4(0.85*0.55,0.55*0.55,0.12*0.55+0.05,1.0))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(0.95*0.75,0.65*0.75,0.15*0.75,1.0))
        imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(1.0,0.72,0.20,1.0))
    end
    if imgui.Button(PCS_IC.taxes .. u8"  \xce\xef\xeb\xe0\xf2\xe8\xf2\xfc\x20\xed\xe0\xeb\xee\xe3\xe8\x20\xf1\xe5\xe9\xf7\xe0\xf1  ", imgui.ImVec2(-1, S(38))) then
        if not _busyPay then PCS_safeManualPay() end
    end
    if imgui.IsItemHovered and imgui.IsItemHovered() then
        pcall(function()
            imgui.BeginTooltip()
            imgui.TextColored(iv4(0.75,0.80,0.90,1.0), u8"\xce\xf2\xea\xf0\xee\xe5\xf2\x20\xf2\xe5\xeb\xe5\xf4\xee\xed\x20\xe8\x20\xef\xf0\xff\xec\xee\x20\xf1\xe5\xe9\xf7\xe0\xf1\x20\xee\xef\xeb\xe0\xf2\xe8\xf2\x20\xe2\xf1\xe5\x20\xed\xe0\xeb\xee\xe3\xe8")
            imgui.EndTooltip()
        end)
    end
    imgui.PopStyleColor(3)
    imgui.TextColored(thDim(), "  "..u8"\xce\xf2\xea\xf0\xee\xe5\xf2\x20\xf2\xe5\xeb\xe5\xf4\xee\xed\x20\xe8\x20\xee\xef\xeb\xe0\xf2\xe8\xf2\x20\xe2\xf1\xe5\x20\xed\xe0\xeb\xee\xe3\xe8\x20\xef\xf0\xff\xec\xee\x20\xf1\xe5\xe9\xf7\xe0\xf1")

    -- ── красивый статус процесса, пока идёт автоматическая оплата
    -- (открытие телефона / поиск нужного пункта меню) ──
    if _taxState ~= 0 then
        imgui.Dummy(imgui.ImVec2(0, S(6)))
        imgui.TextColored(thGold(), "  \xe2\x8f\xb3 "..u8"\xc8\xe4\xb8\xf2\x20\xee\xef\xeb\xe0\xf2\xe0\x20\xed\xe0\xeb\xee\xe3\xee\xe2\x2e\x2e\x2e")
        imgui.TextColored(thDim(),  "  "..u8"\xce\xf2\xea\xf0\xfb\xe2\xe0\xfe\x20\xf2\xe5\xeb\xe5\xf4\xee\xed\x20\xe8\x20\xe8\xf9\xf3\x20\xed\xf3\xe6\xed\xfb\xe9\x20\xef\xf3\xed\xea\xf2\x20\xec\xe5\xed\xfe")
    end

    imgui.Dummy(imgui.ImVec2(0, S(10)))
    imgui.Separator()
    imgui.Dummy(imgui.ImVec2(0, S(6)))

    -- ── автооплата (тумблер + интервал в часах) ──
    PCS_uiSection(u8"\xc0\xe2\xf2\xee\xee\xef\xeb\xe0\xf2\xe0", { 0.30, 0.90, 0.50 })
    imgui.Spacing()
    taxToggleRow("##taxAutoSw", u8"\xc2\xea\xeb\xfe\xf7\xe8\xf2\xfc\x20\xe0\xe2\xf2\xee\xee\xef\xeb\xe0\xf2\xf3", cfg.taxAutoEnabled,
        function(v) cfg.taxAutoEnabled = v; St.taxAutoBuf[0] = v end,
        u8"\xd1\xea\xf0\xe8\xef\xf2\x20\xf1\xe0\xec\x20\xe1\xf3\xe4\xe5\xf2\x20\xee\xef\xeb\xe0\xf7\xe8\xe2\xe0\xf2\xfc\x20\xed\xe0\xeb\xee\xe3\xe8\x20\xef\xee\x20\xf2\xe0\xe9\xec\xe5\xf0\xf3\x2c\x20\xe1\xe5\xe7\x20\xf2\xe2\xee\xe5\xe3\xee\x20\xf3\xf7\xe0\xf1\xf2\xe8\xff")

    if cfg.taxAutoEnabled then
        if not _sinceLastPay then
            imgui.TextColored(thGold(), "  "..u8"\xd1\xeb\xe5\xe4\xf3\xfe\xf9\xe0\xff\x20\xef\xf0\xee\xe2\xe5\xf0\xea\xe0\x3a\x20\xe2\x20\xf2\xe5\xf7\xe5\xed\xe8\xe5\x20\xec\xe8\xed\xf3\xf2\xfb\x20\x28\xed\xe5\xf2\x20\xe4\xe0\xed\xed\xfb\xf5\x20\xee\x20\xef\xee\xf1\xeb\xe5\xe4\xed\xe5\xe9\x20\xee\xef\xeb\xe0\xf2\xe5\x29")
        elseif _dueInSec and _dueInSec > 0 then
            imgui.TextColored(thGold(), "  "..u8"\xd1\xeb\xe5\xe4\xf3\xfe\xf9\xe0\xff\x20\xef\xf0\xee\xe2\xe5\xf0\xea\xe0\x20\xf7\xe5\xf0\xe5\xe7\x3a\x20"..fmtDuration(_dueInSec))
        else
            imgui.TextColored(thGold(), "  "..u8"\xd1\xf0\xee\xea\x20\xef\xee\xe4\xee\xf8\xb8\xeb\x20\x97\x20\xef\xf0\xee\xe2\xe5\xf0\xea\xe0\x20\xf0\xe0\xe7\x20\xe2\x20\xec\xe8\xed\xf3\xf2\xf3")
        end
        imgui.Dummy(imgui.ImVec2(0, S(4)))
    end

    imgui.TextColored(thDim(), "  "..u8"\xc8\xed\xf2\xe5\xf0\xe2\xe0\xeb")
    imgui.SameLine(0, S(6))
    local _ivHrs = St.taxIntervalBuf[0]
    local _ivLbl = tostring(_ivHrs) .. " " .. u8"\xf7"
    if _ivHrs >= 24 then
        local _ivDays = _ivHrs / 24
        local _ivDaysStr = (math.floor(_ivDays) == _ivDays) and tostring(math.floor(_ivDays))
            or string.format("%.1f", _ivDays)
        _ivLbl = _ivLbl .. "  (" .. _ivDaysStr .. " " .. u8"\xe4\xed" .. ")"
    end
    imgui.TextColored(thAcc(), _ivLbl)
    imgui.PushStyleColor(imgui.Col.FrameBg,        iv4(r*0.16,g*0.16,b*0.16,1.0))
    imgui.PushStyleColor(imgui.Col.FrameBgHovered, iv4(r*0.24,g*0.24,b*0.24,1.0))
    imgui.PushStyleColor(imgui.Col.FrameBgActive,  iv4(r*0.30,g*0.30,b*0.30,1.0))
    imgui.PushStyleColor(imgui.Col.SliderGrab,      iv4(r,g,b,1.0))
    imgui.PushStyleColor(imgui.Col.SliderGrabActive,iv4(math.min(1,r*1.2),math.min(1,g*1.2),math.min(1,b*1.2),1.0))
    imgui.PushItemWidth(-1)
    if imgui.SliderInt('##taxInterval', St.taxIntervalBuf, 1, 120, "%d "..u8"\xf7") then
        cfg.taxAutoIntervalHours = St.taxIntervalBuf[0]
        saveCfg()
    end
    imgui.PopItemWidth()
    imgui.PopStyleColor(5)

    imgui.Dummy(imgui.ImVec2(0, S(10)))
    imgui.Separator()
    imgui.Dummy(imgui.ImVec2(0, S(6)))

    PCS_uiSection(u8"\xcf\xf0\xe8 \xe2\xf5\xee\xe4\xe5", { 0.45, 0.80, 1.0 })
    imgui.Spacing()
    taxToggleRow("##taxPayOnLoginSw", u8"\xce\xef\xeb\xe0\xf2\xe0\x20\xef\xf0\xe8\x20\xe2\xf5\xee\xe4\xe5\x20\xe2\x20\xe8\xe3\xf0\xf3", cfg.taxPayOnLogin,
        function(v) cfg.taxPayOnLogin = v; St.taxPayOnLoginBuf[0] = v end,
        u8"\xef\xee\xf1\xeb\xe5\x20\xe7\xe0\xf5\xee\xe4\xe0\x20\xe2\x20\xe8\xe3\xf0\xf3\x20\xf1\xea\xf0\xe8\xef\xf2\x20\xef\xee\xe4\xee\xe6\xe4\xb8\xf2\x20\x31\x20\xec\xe8\xed\xf3\xf2\xf3\x20\xe8\x20\xf1\xe0\xec\x20\xee\xef\xeb\xe0\xf2\xe8\xf2\x20\xed\xe0\xeb\xee\xe3\xe8")

    if cfg.taxPayOnLogin then
        if _taxLoginWaitEndTime then
            local remain = math.max(0, math.floor(_taxLoginWaitEndTime - os.time() + 0.5))
            imgui.TextColored(thGold(), "  "..u8"\xce\xef\xeb\xe0\xf2\xe0\x20\xf7\xe5\xf0\xe5\xe7\x3a\x20"..fmtDuration(remain))
        elseif _taxLoginSkippedRecent then
            imgui.TextColored(thDim(), "  "..u8"\xd3\xe6\xe5\x20\xee\xef\xeb\xe0\xf7\xe5\xed\xee\x20\xed\xe5\xe4\xe0\xe2\xed\xee\x20\x97\x20\xef\xf0\xee\xef\xf3\xf9\xe5\xed\xee\x20\xed\xe0\x20\xfd\xf2\xee\xf2\x20\xe7\xe0\xf5\xee\xe4")
        elseif _taxLoginFired then
            imgui.TextColored(thDim(), "  "..u8"\xd3\xe6\xe5\x20\xf1\xf0\xe0\xe1\xee\xf2\xe0\xeb\xee\x20\xe2\x20\xfd\xf2\xee\xe9\x20\xf1\xe5\xf1\xf1\xe8\xe8")
        else
            imgui.TextColored(thDim(), "  "..u8"\xce\xe6\xe8\xe4\xe0\xe5\xf2\x20\xe2\xf5\xee\xe4\xe0\x20\xe2\x20\xe8\xe3\xf0\xf3\x2e\x2e\x2e")
        end
    end

    -- ── семейная квартира: оплата через /fammenu (см. FAM) ──
    imgui.Dummy(imgui.ImVec2(0, S(10)))
    imgui.Separator()
    imgui.Dummy(imgui.ImVec2(0, S(6)))
    PCS_uiSection("Семейная квартира", { 0.55, 0.78, 1.0 })
    imgui.Spacing()
    taxToggleRow("##famAptAutoSw", "Автооплата квартиры", cfg.famAptAuto,
        function(v) cfg.famAptAuto = v end,
        "Оплачивает квартиру семьи по таймеру (интервал ниже).")
    taxToggleRow("##famAptLoginSw", "Оплата квартиры при входе", cfg.famAptOnLogin,
        function(v) cfg.famAptOnLogin = v end,
        "Через 1 минуту после захода в игру, один раз за заход.")
    FAM.ivBuf = FAM.ivBuf or imgui.new.int(tonumber(cfg.famAptIntervalHours) or 24)
    FAM.ivBuf[0] = math.floor(tonumber(cfg.famAptIntervalHours) or 24)
    imgui.TextColored(thDim(), "Интервал, часов")
    imgui.PushItemWidth(-1)
    if imgui.SliderInt("##famAptIv", FAM.ivBuf, 1, 120, "%d ч") then
        cfg.famAptIntervalHours = FAM.ivBuf[0]
    end
    if imgui.IsItemDeactivatedAfterEdit() then saveCfg() end
    imgui.PopItemWidth()
    imgui.Spacing()
    if PCS_gdButton("Оплатить квартиру сейчас##famAptNow", imgui.GetContentRegionAvail().x, S(34), { 0.30, 0.65, 0.95 }, 8.0) then
        FAM.run(false)
    end
    local lp = tonumber(cfg.famAptLastPayTime) or 0
    imgui.TextColored(thDim(), "  Последняя оплата: " .. (lp > 0 and os.date("%d.%m %H:%M", lp) or "ещё не было"))
    if FAM.status and FAM.status ~= "" then
        imgui.TextColored(thGold(), "  " .. FAM.status)
    end

    -- ── логи оплаты налогов — в самом низу вкладки ──
    imgui.Dummy(imgui.ImVec2(0, S(10)))
    imgui.Separator()
    imgui.Dummy(imgui.ImVec2(0, S(6)))
    TX.drawLogSection()

    imgui.Dummy(imgui.ImVec2(0, S(30)))
end

local function drawTaxPopupsGlobal()
    local r, g, b = getAcc()

    -- ── попап календаря ──
    do
        -- PERF: rebuild the date set only when the entry list actually changed
        local _te = St.taxEntries or {}
        local _key = tostring(#_te) .. "|" .. tostring(_te[1] and (_te[1].date .. _te[1].time) or "")
        if St._taxDatesKey ~= _key or not St._taxDatesCache then
            local td = {}
            for _, e in ipairs(_te) do td[e.date] = true end
            St._taxDatesCache, St._taxDatesKey = td, _key
        end
        local taxDates = St._taxDatesCache

        St._taxCalState = St._taxCalState or {}
        local anchor = St._taxLogBtnScreenPos
        if anchor then
            pcall(imgui.SetNextWindowPos, imgui.ImVec2(anchor.x, anchor.y + S(56)), imgui.Cond.Appearing)
        end

        if St._taxCalendarPopupOpen and not St._taxCalendarPopupOpenedOnce then
            St._taxCalendarPopupOpenedOnce = true
            pcall(imgui.OpenPopup, "##taxCalendarPopup")
        end

        local _mpsT = pushModernPopupStyle()

        local beganCal = false
        local okCal, errCal = pcall(function()
            if imgui.BeginPopup("##taxCalendarPopup") then
                beganCal = true
                PCS_popupHeader(u8"\xca\xe0\xeb\xe5\xed\xe4\xe0\xf0\xfc \xee\xef\xeb\xe0\xf2", u8"\xc4\xed\xe8 \xf1 \xe7\xe0\xef\xe8\xf1\xff\xec\xe8 \xef\xee\xe4\xf1\xe2\xe5\xf7\xe5\xed\xfb")
                imgui.Spacing()
                Cal.draw(St._taxCalState, taxDates, function(pickedDate)
                    St._taxLogSelectedDate = pickedDate
                    imgui.CloseCurrentPopup()
                    St._taxCalendarPopupOpen = false
                    St._taxCalendarPopupOpenedOnce = false
                end)
            end
        end)
        if beganCal then
            pcall(imgui.EndPopup)
        elseif okCal then
            -- попап закрылся сам (клик мимо/Esc) — сбрасываем флаги,
            -- чтобы кнопка могла открыть его заново
            St._taxCalendarPopupOpen = false
            St._taxCalendarPopupOpenedOnce = false
        end
        popModernPopupStyle(_mpsT)
        if not okCal then
            St._taxCalendarPopupOpen = false
            St._taxCalendarPopupOpenedOnce = false
            PCS_quietErr("ui@17560", errCal)
        end
    end

end

local function drawTaxes(h)
    imgui.PushStyleColor(imgui.Col.ChildBg, iv4(0,0,0,0))
    imgui.BeginChild("##staxes", imgui.ImVec2(0, h), false)
    local ok, err = PCS_GUARD.call(drawTaxesInner, h)
    imgui.EndChild()
    imgui.PopStyleColor()
    if not ok then
        St._taxLogEntriesPopupOpen = false
        St._taxLogEntriesOpenedOnce = false
        PCS_quietErr("ui@17578", err)
    end
end

function PCS_openDepositTab()
    St._resetCharScroll = true; St._resetSettScroll = true; St.accPopupOpen = false
    St._financeSettingsOpen = false
    St._taxLogEntriesPopupOpen = false; St._taxLogEntriesOpenedOnce = false
    St.activeTab = 10
    pcall(PCS_depLoad)
    pcall(PCS_depSyncStats)
end

function PCS_openGuardTab()
    St._resetCharScroll = true; St._resetSettScroll = true; St.accPopupOpen = false
    St._financeSettingsOpen = false
    St._taxLogEntriesPopupOpen = false; St._taxLogEntriesOpenedOnce = false
    St.activeTab = 7
    if cfg.lastTab ~= 7 then cfg.lastTab = 7; saveCfg() end
end

-- кнопка в цвет col={r,g,b}: тёмная заливка, при наведении светлее
function PCS_gdButton(label, w, h, col, round)
    local r, g, b = col[1], col[2], col[3]
    imgui.PushStyleColor(imgui.Col.Button,        iv4(r*0.30, g*0.30, b*0.30, 1.0))
    imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(r*0.55, g*0.55, b*0.55, 1.0))
    imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(r*0.80, g*0.80, b*0.80, 1.0))
    local pb = prettyBtnPush(round or 8.0)
    local clicked = imgui.Button(label, imgui.ImVec2(w, h))
    pcall(function()
        local mn = imgui.GetItemRectMin()
        PCS_GD_LASTBTN = { x = mn.x, y = mn.y }
    end)
    prettyBtnPop(pb)
    imgui.PopStyleColor(3)
    return clicked
end

-- тумблер + подпись + серое пояснение (как taxToggleRow, но сохраняет AIS)
function PCS_gdToggle(id, labelU8, isOn, descU8, onToggle)
    if drawToggleSwitch(id, isOn) then
        onToggle(not isOn)
        AIS.save()
    end
    imgui.SameLine(0, S(8))
    imgui.TextColored(iv4(1,1,1,1), labelU8)
    if descU8 then
        imgui.TextColored(thDim(), "  " .. descU8)
    end
    imgui.Dummy(imgui.ImVec2(0, S(4)))
end

-- слайдер в цвет акцента (on=true — push, on=false — pop)
function PCS_gdSliderStyle(on)
    if not on then imgui.PopStyleColor(5) return end
    local r, g, b = getAcc()
    imgui.PushStyleColor(imgui.Col.FrameBg,         iv4(r*0.16, g*0.16, b*0.16, 1.0))
    imgui.PushStyleColor(imgui.Col.FrameBgHovered,  iv4(r*0.24, g*0.24, b*0.24, 1.0))
    imgui.PushStyleColor(imgui.Col.FrameBgActive,   iv4(r*0.30, g*0.30, b*0.30, 1.0))
    imgui.PushStyleColor(imgui.Col.SliderGrab,      iv4(r, g, b, 1.0))
    imgui.PushStyleColor(imgui.Col.SliderGrabActive, iv4(math.min(1, r*1.2), math.min(1, g*1.2), math.min(1, b*1.2), 1.0))
end

-- блок выбора еды для одного охранника
function PCS_gdFoodBlock(avW, whoRaw, info, key)
    local ic = PCS_IC
    local r, g, b = getAcc()
    imgui.TextColored(thAcc(), "  " .. ic.utensils .. "  " .. u8(whoRaw))
    local sel = AIS.FOOD[tonumber(info.type)]
    imgui.TextColored(thDim(), "  " .. u8"\xc2\xfb\xe1\xf0\xe0\xed\xee:")
    imgui.SameLine(0, S(6))
    if sel then
        imgui.TextColored(thGold(), u8(sel))
    else
        imgui.TextColored(thDim(), u8"\xed\xe5 \xe2\xfb\xe1\xf0\xe0\xed\xee")
    end
    if (tonumber(info.quantity) or 0) > 0 then
        imgui.SameLine(0, S(10))
        imgui.TextColored(thDim(), u8"\xe2 \xe8\xed\xe2\xe5\xed\xf2\xe0\xf0\xe5: " .. tostring(info.quantity))
    end
    imgui.Spacing()
    local gap = S(6)
    local bw = math.floor((avW - gap * 2) / 3)
    for k, fid in ipairs(AIS.FOOD_ORDER) do
        if k > 1 then imgui.SameLine(0, gap) end
        local on = tonumber(info.type) == fid
        local col = on and { r, g, b } or { 0.55, 0.58, 0.66 }
        local lbl = (on and ic.check or ic.bone) .. "  " .. u8(AIS.FOOD[fid]) .. "##gdf" .. key .. tostring(fid)
        if PCS_gdButton(lbl, bw, S(30), col, 8.0) then
            info.type = fid
            AIS.save()
            AIS.msg(whoRaw .. ": \xf2\xe8\xef \xe5\xe4\xfb \x97 " .. AIS.FOOD[fid])
        end
    end
    imgui.Dummy(imgui.ImVec2(0, S(8)))
end

-- карточка одного охранника из списка
function PCS_gdPetCard(i, pet, avW)
    local s = AIS.s
    local ic = PCS_IC
    local r, g, b = getAcc()
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local pet1, pet2 = s.SpPet1 or {}, s.SpPet2 or {}
    local id = tonumber(pet.id)
    local spawned = tonumber(pet.spawned) == 1
    local isMain   = id ~= nil and tonumber(pet1.id) == id
    local isSecond = id ~= nil and tonumber(pet2.id) == id

    local cardH = S(88)
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local e = isMain and { 1.0, 0.82, 0.20 } or (isSecond and { 0.45, 0.80, 1.0 } or (spawned and { 0.25, 0.92, 0.48 } or { 0.55, 0.58, 0.66 }))
    dl:AddRectFilled(p, V2(p.x + avW, p.y + cardH), U32(iv4(r*0.07, g*0.07, b*0.07, pcsRowA(0.92))), 10)
    dl:AddRect(p, V2(p.x + avW, p.y + cardH), U32(iv4(e[1], e[2], e[3], 0.55)), 10, 0, 1.2)
    dl:AddRectFilled(V2(p.x, p.y + 6), V2(p.x + 4, p.y + cardH - 6), U32(iv4(e[1], e[2], e[3], 1.0)), 2)
    do -- плашка статуса справа
        local pc = spawned and { 0.25, 0.92, 0.48 } or { 1.0, 0.40, 0.40 }
        local pt = spawned and u8"\xcf\xd0\xc8\xc7\xc2\xc0\xcd" or u8"\xcd\xc5 \xcf\xd0\xc8\xc7\xc2\xc0\xcd"
        local tsz = imgui.CalcTextSize(pt)
        local px0 = p.x + avW - tsz.x - S(24)
        dl:AddRectFilled(V2(px0, p.y + S(7)), V2(px0 + tsz.x + S(14), p.y + S(9) + tsz.y + S(6)), U32(iv4(pc[1]*0.22, pc[2]*0.22, pc[3]*0.22, 1.0)), 8)
        dl:AddRect(V2(px0, p.y + S(7)), V2(px0 + tsz.x + S(14), p.y + S(9) + tsz.y + S(6)), U32(iv4(pc[1], pc[2], pc[3], 0.90)), 8, 0, 1.2)
        dl:AddText(V2(px0 + S(7), p.y + S(10)), U32(iv4(pc[1], pc[2], pc[3], 1.0)), pt)
    end

    -- строка 1: статус-иконка, имя, ID/Slot, метка роли
    imgui.SetCursorScreenPos(V2(p.x + S(14), p.y + S(8)))
    if spawned then
        imgui.TextColored(thGreen(), ic.check)
    else
        imgui.TextColored(thRed(), ic.xcircle)
    end
    imgui.SameLine(0, S(6))
    imgui.TextColored(iv4(1,1,1,1), u8(tostring(pet.name or "?")))
    imgui.SameLine(0, S(10))
    imgui.TextColored(thDim(), "ID: " .. tostring(id or "?") .. "   Slot: " .. tostring(pet.slot or "?"))
    if isMain then
        imgui.SameLine(0, S(10))
        imgui.TextColored(thGold(), ic.star .. " " .. u8"\xce\xd1\xcd\xce\xc2\xcd\xce\xc9")
    elseif isSecond then
        imgui.SameLine(0, S(10))
        imgui.TextColored(iv4(0.45, 0.80, 1.0, 1.0), ic.userplus .. " " .. u8"\xc2\xd2\xce\xd0\xce\xc9")
    end

    -- строка 2: состояние
    imgui.SetCursorScreenPos(V2(p.x + S(14), p.y + S(28)))
    if spawned then
        imgui.TextColored(thGreen(), u8"\xef\xf0\xe8\xe7\xe2\xe0\xed")
    else
        imgui.TextColored(thRed(), u8"\xed\xe5 \xef\xf0\xe8\xe7\xe2\xe0\xed")
    end

    -- кнопки
    local gap = S(6)
    local bw = math.floor((avW - S(14) * 2 - gap * 2) / 3)
    imgui.SetCursorScreenPos(V2(p.x + S(14), p.y + cardH - S(34)))
    if PCS_gdButton(ic.star .. "  " .. u8"\xce\xf1\xed\xee\xe2\xed\xee\xe9" .. "##gdm" .. i, bw, S(26), { 1.0, 0.82, 0.20 }, 6.0) then
        s.SpPet1 = { name = pet.name, id = pet.id, slot = pet.slot, spawned = pet.spawned }
        AIS.save()
        AIS.msg("\xce\xf1\xed\xee\xe2\xed\xfb\xec \xe2\xfb\xe1\xf0\xe0\xed: " .. tostring(pet.name))
    end
    imgui.SameLine(0, gap)
    if PCS_gdButton(ic.userplus .. "  " .. u8"\xc2\xf2\xee\xf0\xee\xe9" .. "##gds" .. i, bw, S(26), { 0.45, 0.80, 1.0 }, 6.0) then
        s.SpPet2 = { name = pet.name, id = pet.id, slot = pet.slot, spawned = pet.spawned }
        AIS.save()
        AIS.msg("\xc2\xf2\xee\xf0\xfb\xec \xe2\xfb\xe1\xf0\xe0\xed: " .. tostring(pet.name))
    end
    imgui.SameLine(0, gap)
    if spawned then
        if PCS_gdButton(ic.walk .. "  " .. u8"\xd3\xe1\xf0\xe0\xf2\xfc" .. "##gdo" .. i, bw, S(26), { 1.0, 0.40, 0.40 }, 6.0) then
            if isMain then
                AIS.run(AIS.OffPet, 1)
            elseif isSecond then
                AIS.run(AIS.OffPet, 2)
            else
                AIS.msg("\xd1\xed\xe0\xf7\xe0\xeb\xe0 \xed\xe0\xe7\xed\xe0\xf7\xfc\xf2\xe5 \xee\xf5\xf0\xe0\xed\xed\xe8\xea\xe0 \xee\xf1\xed\xee\xe2\xed\xfb\xec \xe8\xeb\xe8 \xe2\xf2\xee\xf0\xfb\xec.")
            end
        end
    else
        if PCS_gdButton(ic.paw .. "  " .. u8"\xcf\xf0\xe8\xe7\xe2\xe0\xf2\xfc" .. "##gdp" .. i, bw, S(26), { 0.30, 0.90, 0.50 }, 6.0) then
            if isMain then
                AIS.run(AIS.SpawnPet, 1)
            elseif isSecond then
                if s.SOTG then
                    AIS.run(AIS.SpawnPet, 2)
                else
                    AIS.msg("\xc2\xea\xeb\xfe\xf7\xe8\xf2\xe5 \xf0\xe5\xe6\xe8\xec \xe4\xe2\xf3\xf5 \xee\xf5\xf0\xe0\xed\xed\xe8\xea\xee\xe2.")
                end
            else
                AIS.msg("\xd1\xed\xe0\xf7\xe0\xeb\xe0 \xed\xe0\xe7\xed\xe0\xf7\xfc\xf2\xe5 \xee\xf5\xf0\xe0\xed\xed\xe8\xea\xe0 \xee\xf1\xed\xee\xe2\xed\xfb\xec \xe8\xeb\xe8 \xe2\xf2\xee\xf0\xfb\xec.")
            end
        end
    end

    imgui.SetCursorScreenPos(V2(p.x, p.y + cardH + S(6)))
    imgui.Dummy(V2(avW, S(2)))
end

function PCS_drawGuardInner(h)
    if not AIS.s then AIS.load() end
    local s = AIS.s
    local ic = PCS_IC
    local r, g, b = getAcc()
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local avW = imgui.GetContentRegionAvail().x

    -- назад к финансам
    if PCS_drawBackBar(u8"\xce\xf5\xf0\xe0\xed\xed\xe8\xea", r, g, b, "gdBack") then
        St._resetCharScroll = true
        St.activeTab = 3
        if cfg.lastTab ~= 3 then cfg.lastTab = 3; saveCfg() end
    end

    -- шапка: баннер + плитки + кнопка обновления
    do
        local dl = imgui.GetWindowDrawList()
        local p = imgui.GetCursorScreenPos()
        local total, spawnedN = 0, 0
        for _, pet in ipairs(s.Security or {}) do
            total = total + 1
            if tonumber(pet.spawned) == 1 then spawnedN = spawnedN + 1 end
        end
        local c = spawnedN > 0 and { 0.30, 0.90, 0.50 } or { 0.45, 0.80, 1.0 }
        local hH = S(56)
        dl:AddRectFilled(p, V2(p.x + avW, p.y + hH), U32(iv4(c[1]*0.10, c[2]*0.10, c[3]*0.10, pcsRowA(0.92))), 12)
        dl:AddRect(p, V2(p.x + avW, p.y + hH), U32(iv4(c[1], c[2], c[3], 0.70)), 12, 0, 1.4)
        dl:AddRectFilled(V2(p.x + 10, p.y), V2(p.x + avW - 10, p.y + 3), U32(iv4(c[1], c[2], c[3], 1.0)), 2)
        local cx, cy = p.x + S(28), p.y + hH * 0.5
        dl:AddCircleFilled(V2(cx, cy), S(17), U32(iv4(c[1], c[2], c[3], 0.22)), 28)
        dl:AddCircle(V2(cx, cy), S(17), U32(iv4(c[1], c[2], c[3], 0.90)), 28, 1.5)
        local isz = imgui.CalcTextSize(ic.shield)
        dl:AddText(V2(cx - isz.x * 0.5, cy - isz.y * 0.5), U32(iv4(c[1], c[2], c[3], 1.0)), ic.shield)
        imgui.SetCursorScreenPos(V2(p.x + S(54), p.y + S(9)))
        imgui.TextColored(iv4(c[1], c[2], c[3], 1.0), u8"\xcb\xe8\xf7\xed\xfb\xe5 \xee\xf5\xf0\xe0\xed\xed\xe8\xea\xe8")
        imgui.SetCursorScreenPos(V2(p.x + S(54), p.y + S(30)))
        imgui.TextColored(thDim(), s.SOTG and u8"\xd0\xe5\xe6\xe8\xec: \xe4\xe2\xe0 \xee\xf5\xf0\xe0\xed\xed\xe8\xea\xe0" or u8"\xd0\xe5\xe6\xe8\xec: \xee\xe4\xe8\xed \xee\xf5\xf0\xe0\xed\xed\xe8\xea")
        local gap, tH = S(8), S(54)
        local tw = math.floor((avW - gap) / 2)
        local x0, y0 = p.x, p.y + hH + S(8)
        PCS_uiTile(x0, y0, tw, tH, { 0.45, 0.80, 1.0 }, u8"\xc2\xf1\xe5\xe3\xee \xee\xf5\xf0\xe0\xed\xed\xe8\xea\xee\xe2", tostring(total), iv4(1, 1, 1, 1))
        PCS_uiTile(x0 + tw + gap, y0, tw, tH, { 0.30, 0.90, 0.50 }, u8"\xd1\xe5\xe9\xf7\xe0\xf1 \xef\xf0\xe8\xe7\xe2\xe0\xed\xee", tostring(spawnedN), thGreen())
