function PCS_drawGuardTab(h)
    imgui.PushStyleColor(imgui.Col.ChildBg, iv4(0,0,0,0))
    imgui.BeginChild("##sguard", imgui.ImVec2(0, h), false)
    local ok, err = PCS_GUARD.call(PCS_drawGuardInner, h)
    imgui.EndChild()
    imgui.PopStyleColor()
    if not ok and St._gdLastErr ~= tostring(err) then
        St._gdLastErr = tostring(err)
        PCS_quietErr("ui@17916", err)
    end
end

function PCS_hotkeyDispatch(id)
    -- пока печатаешь в чате ИИ, буквенные хоткеи не срабатывают (F-клавиши — да)
    if PCS_AI and PCS_AI.typing then
        local vk = (id == "ai") and (tonumber(cfg.hkAiVK) or 0) or 0
        if not (vk >= 112 and vk <= 135) then return end
    end
    lua_thread.create(function()
        wait(0)
        local ok, err = pcall(function()
            if id == "menu" then
                local dialogActive = false
                pcall(function() dialogActive = sampIsDialogActive() and true or false end)
                if not dialogActive and type(toggleMenuWindow) == "function" then toggleMenuWindow() end
            elseif id == "ai" then
                PCS_AI.toggle()
            elseif id == "tax" then
                PCS_safeManualPay()
            elseif id == "rates" then
                if not _cefFetching then fetchRatesViaCEF() end
            elseif id == "calc" then
                St._calcPanelOpen = not St._calcPanelOpen
                if St._calcPanelOpen then
                    St._chartPanelOpen = false
                    -- калькулятор открывается сам, главное меню не трогаем
                end
            elseif id == "guard" then
                if AIS and AIS.on and AIS.on() then AIS.run(AIS.SpawnPet, 1) end
            end
        end)
        if not ok then PCS_quietErr("hotkey:" .. tostring(id), err) end
    end)
end

function PCS_hotkeyLoop()
    local prev = {}
    local bindSkip = nil
    local function isDown(vk)
        if type(isKeyDown) ~= "function" then return false end
        local ok, d = pcall(isKeyDown, vk)
        return ok and d == true
    end
    while true do
        wait(0)
        pcall(function()
            -- ── режим «назначить клавишу»: ждём первое нажатие ──
            if St.awaitingHotkeyBind then
                if not bindSkip then
                    bindSkip = {}
                    for vk = 8, 222 do if isDown(vk) then bindSkip[vk] = true end end
                end
                for vk = 8, 222 do
                    local d = isDown(vk)
                    if d and not bindSkip[vk] and vk ~= 16 and vk ~= 17 and vk ~= 18 then
                        St.awaitingHotkeyBind = false
                        bindSkip = nil
                        St._hkEscGuardUntil = os.clock() + 0.4   -- Esc отмены не должен ещё и закрыть меню
                        if vk ~= 27 then   -- Esc = отмена, ничего не меняем
                            local tgt = St._hkBindTarget or "menuHotkeyVK"
                            local clashName
                            for _, ha in ipairs(PCS_HK_ACTIONS or {}) do
                                if ha.cfg ~= tgt and (tonumber(cfg[ha.cfg]) or 0) == vk then clashName = ha.chat end
                            end
                            if clashName then
                                pcall(sampAddChatMessage, "{FF6666}[PC Stats] " .. "\xca\xeb\xe0\xe2\xe8\xf8\xe0\x20\xf3\xe6\xe5\x20\xe7\xe0\xed\xff\xf2\xe0\x3a\x20" .. clashName, -1)
                            else
                                cfg[tgt] = vk
                                pcall(saveCfg)
                                pcall(sampAddChatMessage, "{00FF88}[PC Stats] " .. "\xc3\xee\xf0\xff\xf7\xe0\xff\x20\xea\xeb\xe0\xe2\xe8\xf8\xe0\x20\xed\xe0\xe7\xed\xe0\xf7\xe5\xed\xe0\x3a\x20" .. vkName(vk), -1)
                            end
                        end
                        St._hkBindTarget = nil
                        break
                    elseif not d then
                        bindSkip[vk] = nil   -- отпустили — дальше эта клавиша уже «новая»
                    end
                end
                prev = {}
                return
            end
            bindSkip = nil

            -- ── обычный режим: клавиши действий (меню / налоги / курсы / охранник) ──
            local newPrev, hits = {}, {}
            for _, ha in ipairs(PCS_HK_ACTIONS or {}) do
                local vk = tonumber(cfg[ha.cfg]) or 0
                if vk > 0 then
                    local d = isDown(vk)
                    newPrev[vk] = d
                    if d and not prev[vk] then hits[#hits + 1] = ha end
                end
            end
            prev = newPrev
            if #hits == 0 then return end
            -- в поле ввода меню клавиша — это просто символ, ничего не делаем
            if St.winOpen and St._anyItemActive then return end
            local chatActive, paused = false, false
            pcall(function() chatActive = sampIsChatInputActive() and true or false end)
            pcall(function() paused = isGamePaused() and true or false end)
            if chatActive or paused then return end
            for _, ha in ipairs(hits) do
                if ha.id == "menu" then
                    -- как в рабочей сборке 1.8.6: клавиша меню открывает/закрывает окно
                    -- напрямую из цикла, без отдельного потока на каждое нажатие
                    local dialogActive = false
                    pcall(function() dialogActive = sampIsDialogActive() and true or false end)
                    if not dialogActive and type(toggleMenuWindow) == "function" then
                        pcall(toggleMenuWindow)
                    end
                else
                    PCS_hotkeyDispatch(ha.id)
                end
            end
        end)
    end
end

-- ── ВЫБОР ШРИФТА МЕНЮ ──
function PCS_fontChoices()
    local t = { { name = "", label = u8"\xd1\xf2\xe0\xed\xe4\xe0\xf0\xf2\xed\xfb\xe9" } }
    if type(PCS_FONTS) == "table" then
        for _, e in ipairs(PCS_FONTS) do t[#t + 1] = { name = e.name, label = e.name } end
    end
    return t
end

-- выбранный шрифт -> PCS_CUR_FONT; жирный шрифт кнопок подстраивается под него
function PCS_applyFontChoice()
    local want = tostring(cfg.fontName or "")
    local f = nil
    if want ~= "" and type(PCS_FONTS) == "table" then
        for _, e in ipairs(PCS_FONTS) do
            if e.name == want then f = e.font; break end
        end
    end
    PCS_CUR_FONT = f
    if f then
        PCS_BOLD_FONT = (not PCS_BOLD_OFF) and f or nil
    elseif PCS_FONT_DEFAULT_BOLD ~= nil then
        PCS_BOLD_FONT = PCS_FONT_DEFAULT_BOLD
    end
    PCS_FONT_APPLIED = want
end

function PCS_fontPush()
    pcall(function()
        if PCS_FONT_APPLIED ~= tostring(cfg.fontName or "") then PCS_applyFontChoice() end
    end)
    local f = PCS_CUR_FONT
    if not f then return false end
    local ok = pcall(imgui.PushFont, f)
    return ok and true or false
end

function PCS_fontPop(pushed)
    if pushed then pcall(imgui.PopFont) end
end

local _mainWinBegan = false

imgui.OnFrame(
    function()
        if os.clock() < (PCS_NOUI_UNTIL or 0) then return false end
        return St.winOpen or St._winVisible
    end,
    function(self)
        St._gMain = PCS_GUARD.snap()
        PCS_GUARD.mark("frame: main start")
        local _fontPushed = PCS_fontPush()
        local _okFrame, _errFrame = pcall(function()
        if St.winOpen or St._winVisible then
        St._metricTileIdx = 0
        St._chipIdx = 0
        St.chipSide = false
        pcall(CH.add)

        do
            local okA, act = pcall(function() return imgui.IsAnyItemActive and imgui.IsAnyItemActive() end)
            St._anyItemActive = (okA and act) and true or false
        end

        if not St.awaitingHotkeyBind and os.clock() >= (St._hkEscGuardUntil or 0) then
            local okEsc, pressedEsc = pcall(imgui.IsKeyPressed, 27, false)
            if okEsc and pressedEsc and not (imgui.IsAnyItemActive and imgui.IsAnyItemActive()) then
                pcall(toggleMenuWindow)
            end
        end

        local sw = imgui.GetIO().DisplaySize.x
        local sh = imgui.GetIO().DisplaySize.y

        if sh > 0 then
            St.UI_SCALE = math.max(St.UI_SCALE_MIN, math.min(St.UI_SCALE_MAX, sh / 1080.0))
        end

        if math.abs(sw - St._lastSw) > 2 or math.abs(sh - St._lastSh) > 2 then
            if St._lastSw > 0 then _sw_win_init = nil end
            St._lastSw, St._lastSh = sw, sh
        end

        local wPct = cfg.winWPct > 0 and cfg.winWPct or 0.60
        local hPct = cfg.winHPct > 0 and cfg.winHPct or 0.76
        local ww   = math.floor(sw * wPct)
        local wh   = math.floor(sh * hPct)
        ww = math.max(math.floor(sw * 0.30), math.min(ww, math.floor(sw * 0.98)))
        wh = math.max(math.floor(sh * 0.35), math.min(wh, math.floor(sh * 0.95)))

        if not _sw_win_init then
            imgui.SetNextWindowSize(imgui.ImVec2(ww, wh), imgui.Cond.Always)
            imgui.SetNextWindowPos(imgui.ImVec2(sw*0.5, sh*0.5), imgui.Cond.Always, imgui.ImVec2(0.5,0.5))
            _sw_win_init = true
        else
            imgui.SetNextWindowSize(imgui.ImVec2(ww, wh), imgui.Cond.Once)
        end

        do
            local tnow = os.clock()
            if St._finShiftLastTime == nil then St._finShiftLastTime = tnow end
            local dt = tnow - St._finShiftLastTime
            St._finShiftLastTime = tnow
            if dt < 0 or dt > 0.5 then dt = 0 end -- защита от скачков (первый кадр / лаги)

            local target = ((St._financeSettingsOpen and not St._financeSettingsDetached)
                or (St._settingsPanelOpen and not St._settingsPanelDetached)) and 1.0 or 0.0
            local speed  = 6.0
            if St._finShiftAnim < target then
                St._finShiftAnim = math.min(target, St._finShiftAnim + dt*speed)
            elseif St._finShiftAnim > target then
                St._finShiftAnim = math.max(target, St._finShiftAnim - dt*speed)
            end

            local finShiftPx = S(96) * St._finShiftAnim

            if St._finShiftAppliedPx < 0.5 and St._mainWinPos then
                St._finShiftAnchorX = St._mainWinPos.x
            end

            St._finShiftAppliedPx = finShiftPx

            if St._finShiftAnchorX and finShiftPx > 0.01 then
                local fx, fy = St._finShiftAnchorX - finShiftPx, St._mainWinPos.y
                if PCS_isFinite(fx) and PCS_isFinite(fy) then
                    imgui.SetNextWindowPos(imgui.ImVec2(fx, fy), imgui.Cond.Always)
                end
            end
        end

        PCS_GUARD.mark("frame: anim")
        local menuFadeAlpha = 1.0
        do
            local target = St.winOpen and 1.0 or 0.0
            if cfg.smoothMenuAnim == false or cfg.animAllOff == true then
                St._menuOpenAnim = target
            else
                local tnow = os.clock()
                if not St._menuOpenAnimT then St._menuOpenAnimT = tnow end
                local dt = tnow - St._menuOpenAnimT
                St._menuOpenAnimT = tnow
                if dt < 0 or dt > 0.5 then dt = 0.016 end
                local sp = 15.0
                if (St._menuOpenAnim or 0) < target then
                    St._menuOpenAnim = math.min(target, (St._menuOpenAnim or 0) + dt * sp)
                elseif (St._menuOpenAnim or 0) > target then
                    St._menuOpenAnim = math.max(target, (St._menuOpenAnim or 0) - dt * sp)
                end
            end
            local a = St._menuOpenAnim or 1.0
            menuFadeAlpha = a
            if a < 0.999 then
                pcall(function() imgui.SetNextWindowBgAlpha(0.92 * a) end)
                if St._mainWinPos then
                    if not St._menuSlideAnchor then
                        St._menuSlideAnchor = { x = St._mainWinPos.x, y = St._mainWinPos.y }
                    end
                    local slidePx = S(26) * (1 - a)
                    local ax, ay = St._menuSlideAnchor.x, St._menuSlideAnchor.y + slidePx
                    if PCS_isFinite(ax) and PCS_isFinite(ay) then
                        imgui.SetNextWindowPos(imgui.ImVec2(ax, ay), imgui.Cond.Always)
                    end
                end
            else
                St._menuSlideAnchor = nil
            end
            if target < 0.5 and a < 0.01 then
                if St._pendingCloseReset then
                    St.activeTab = 1
                    _sw_win_init = nil
                    St._pendingCloseReset = false
                end
                St._winVisible = false
            end
        end

        PCS_GUARD.mark("frame: style")
        applyStyle()
        PCS_GUARD.mark("frame: style done")
        local flags = imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoTitleBar
        PCS_GUARD.mark("frame: before Begin")
        imgui.Begin("###sw", nil, flags)
        _mainWinBegan = true
        PCS_GUARD.mark("frame: Begin ok")
        pcall(PCS_applyPendingCompanionTex)
        imgui.SetWindowFontScale(St.UI_SCALE * (cfg.fontSize > 0 and cfg.fontSize or 1.25))

        local _svMenuFade = 0
        if menuFadeAlpha < 0.999 then
            if pcall(imgui.PushStyleVar, imgui.StyleVar.Alpha, math.max(0.02, menuFadeAlpha)) then
                _svMenuFade = 1
            end
        end

        if PCS_DIAG_NO_COMPANION then PCS_COMPANION_TEX = nil end
        if PCS_TEX_RECREATE_PENDING and not PCS_texQuiet() then
            PCS_TEX_RECREATE_PENDING = false
            _pcsCompanionRetried = false
            pcall(loadCompanionTexture)
            PCS_TEX_QUIET_UNTIL = math.max(PCS_TEX_QUIET_UNTIL or 0, os.clock() + 1.5)
            -- персонаж пересоздаёт поток PCS_texWatchdogLoop, а не кадр (см. выше)
            -- атлас смайлов тоже пересоздаём с диска (сетка сама вызовет loadTex)
            if PCS_STICK and PCS_STICK.tex then
                PCS_STICK.texBroken = true
                PCS_STICK.reloadAt = os.clock()
            end
        end
        PCS_UI("ui:companion bg", PCS_COMPANION_TEX and "tex" or "none")
        -- защита: битая/невалидная текстура при открытии меню роняла игру (native assert)
        if PCS_COMPANION_TEX and cfg.companionBgEnabled ~= false and not PCS_texQuiet() and not PCS_TEX_NO_RECREATE then
            local okImgBg = pcall(function()
                local dlBg = imgui.GetWindowDrawList()
                if not dlBg then return end
                local wpBg = imgui.GetWindowPos()
                local wsBg = imgui.GetWindowSize()
                if not wpBg or not wsBg or not wsBg.x or wsBg.x < 10 or not wsBg.y or wsBg.y < 10 then return end
                local sizeBg = math.min(wsBg.x, wsBg.y) * 0.46
                -- размер и положение персонажа (Настройки → «Персонаж на фоне»)
                local cScale = cfg.companionScale or 1.0
                local cx = wpBg.x + wsBg.x * (0.5 + (cfg.companionOffX or 0.0))
                local cy = wpBg.y + wsBg.y * (0.5 + (cfg.companionOffY or 0.0))
                local cbAlpha = cfg.companionBgAlpha or 0.35
                local cbTintR, cbTintG, cbTintB
                if cfg.companionRainbow then
                    local hue = (os.clock() % 4.0) / 4.0
                    cbTintR, cbTintG, cbTintB = hsv2rgb(hue, 0.75, 1.0)
                else
                    cbTintR = cfg.companionTintR or 1.0
                    cbTintG = cfg.companionTintG or 1.0
                    cbTintB = cfg.companionTintB or 1.0
                end
                if PCS_COMPANION_OPAQUE then
                    local asp = PCS_COMPANION_ASPECT or 1
                    local wr = wsBg.x / math.max(1, wsBg.y)
                    local u0, v0, u1, v1 = 0, 0, 1, 1
                    if asp > wr then
                        local k = wr / asp; u0 = (1 - k) * 0.5; u1 = 1 - u0
                    else
                        local k = asp / wr; v0 = (1 - k) * 0.5; v1 = 1 - v0
                    end
                    local wrnd = S(8)
                    pcall(function() wrnd = imgui.GetStyle().WindowRounding end)
                    local pA = cbAlpha * math.max(0, math.min(1, menuFadeAlpha or 1))
                    local pTint = imgui.ColorConvertFloat4ToU32(iv4(cbTintR, cbTintG, cbTintB, pA))
                    -- своё фото: тот же масштаб/сдвиг (выходящее за окно обрезается окном)
                    local pHW, pHH = wsBg.x * cScale * 0.5, wsBg.y * cScale * 0.5
                    local pMin = imgui.ImVec2(cx - pHW, cy - pHH)
                    local pMax = imgui.ImVec2(cx + pHW, cy + pHH)
                    local okR = pcall(function()
                        dlBg:AddImageRounded(PCS_COMPANION_TEX, pMin, pMax,
                            imgui.ImVec2(u0, v0), imgui.ImVec2(u1, v1), pTint, wrnd, 0)
                    end)
                    if not okR then
                        dlBg:AddImage(PCS_COMPANION_TEX, pMin, pMax,
                            imgui.ImVec2(u0, v0), imgui.ImVec2(u1, v1), pTint)
                    end
                    if cfg.companionOutlineEnabled ~= false then
                        local oR, oG, oB
                        if cfg.companionOutlineRainbow ~= false then
                            oR, oG, oB = hsv2rgb((os.clock() % 5.0) / 5.0, 0.80, 1.0)
                        else
                            oR, oG, oB = getAcc()
                        end
                        dlBg:AddRect(pMin, pMax, imgui.ColorConvertFloat4ToU32(iv4(oR, oG, oB, math.min(1.0, pA + 0.45))),
                            wrnd, 0, S(2) * (cfg.companionOutlineThickness or 1.0))
                    end
                    return
                end
                local halfBgW, halfBgH = PCS_companionFit(sizeBg, sizeBg)
                if (PCS_COMPANION_ASPECT or 1) < 1 then
                    halfBgH = math.min(wsBg.y * 0.64, sizeBg * 1.5)
                    halfBgW = halfBgH * PCS_COMPANION_ASPECT
                end
                halfBgW, halfBgH = halfBgW * 0.5 * cScale, halfBgH * 0.5 * cScale
                if cfg.companionOutlineEnabled ~= false then
                    local obR, obG, obB
                    if cfg.companionOutlineRainbow ~= false then
                        local hue2 = (os.clock() % 5.0) / 5.0
                        obR, obG, obB = hsv2rgb(hue2, 0.80, 1.0)
                    else
                        obR, obG, obB = getAcc()
                    end
                    local obAlpha = math.min(1.0, cbAlpha + 0.45)
                    local outlineU  = imgui.ColorConvertFloat4ToU32(iv4(obR, obG, obB, obAlpha))
                    local outlineU2 = imgui.ColorConvertFloat4ToU32(iv4(obR, obG, obB, obAlpha * 0.45))
                    local obThick = cfg.companionOutlineThickness or 1.0
                    if PCS_COMPANION_OPAQUE then
                        local fx0, fy0 = cx - halfBgW, cy - halfBgH
                        local fx1, fy1 = cx + halfBgW, cy + halfBgH
                        local rnd = S(14)
                        for k = 4, 1, -1 do
                            local e = S(2.2) * k * obThick
                            dlBg:AddRect(imgui.ImVec2(fx0 - e, fy0 - e), imgui.ImVec2(fx1 + e, fy1 + e),
                                imgui.ColorConvertFloat4ToU32(iv4(obR, obG, obB, obAlpha * 0.30 / k)),
                                rnd + e, 0, S(2))
                        end
                        dlBg:AddRect(imgui.ImVec2(fx0, fy0), imgui.ImVec2(fx1, fy1), outlineU,
                            rnd, 0, S(2.4) * obThick)
                    else
                        local DIRS = 12
                        -- мягкое внешнее свечение (побольше сдвиг, слабее альфа)
                        local offGlow = S(6) * obThick
                        for i = 0, DIRS - 1 do
                            local rad = (i / DIRS) * math.pi * 2
                            local dx, dy = math.cos(rad) * offGlow, math.sin(rad) * offGlow
                            dlBg:AddImage(PCS_COMPANION_TEX,
                                imgui.ImVec2(cx - halfBgW + dx, cy - halfBgH + dy),
                                imgui.ImVec2(cx + halfBgW + dx, cy + halfBgH + dy),
                                imgui.ImVec2(0, 0), imgui.ImVec2(1, 1), outlineU2)
                        end
                        -- чёткая тонкая обводка вплотную к силуэту
                        local offEdge = S(2.5) * obThick
                        for i = 0, DIRS - 1 do
                            local rad = (i / DIRS) * math.pi * 2
                            local dx, dy = math.cos(rad) * offEdge, math.sin(rad) * offEdge
                            dlBg:AddImage(PCS_COMPANION_TEX,
                                imgui.ImVec2(cx - halfBgW + dx, cy - halfBgH + dy),
                                imgui.ImVec2(cx + halfBgW + dx, cy + halfBgH + dy),
                                imgui.ImVec2(0, 0), imgui.ImVec2(1, 1), outlineU)
                        end
                    end -- (силуэт / рамка)
                end

                local mainTintU = imgui.ColorConvertFloat4ToU32(iv4(cbTintR, cbTintG, cbTintB, cbAlpha))
                local drawnRounded = false
                if PCS_COMPANION_OPAQUE then
                    -- фото со скруглёнными углами под рамку (если mimgui умеет)
                    drawnRounded = pcall(function()
                        dlBg:AddImageRounded(PCS_COMPANION_TEX,
                            imgui.ImVec2(cx - halfBgW, cy - halfBgH),
                            imgui.ImVec2(cx + halfBgW, cy + halfBgH),
                            imgui.ImVec2(0, 0), imgui.ImVec2(1, 1), mainTintU, S(14), 0)
                    end)
                end
                if not drawnRounded then
                    dlBg:AddImage(PCS_COMPANION_TEX,
                        imgui.ImVec2(cx - halfBgW, cy - halfBgH),
                        imgui.ImVec2(cx + halfBgW, cy + halfBgH),
                        imgui.ImVec2(0, 0), imgui.ImVec2(1, 1), mainTintU)
                end
            end)
            if not okImgBg then PCS_disableCompanionTex() end
        end

        do
            local r0,g0,b0 = getAcc()
            local dl0 = imgui.GetWindowDrawList()
            local wp  = imgui.GetCursorScreenPos()
            local aw0 = imgui.GetContentRegionAvail().x
            local th0 = S(36)
            dl0:AddRectFilled(
                imgui.ImVec2(wp.x,      wp.y),
                imgui.ImVec2(wp.x+aw0,  wp.y+th0),
                imgui.ColorConvertFloat4ToU32(iv4(r0*0.12,g0*0.12,b0*0.12,1.0)), 10)
            dl0:AddRect(
                imgui.ImVec2(wp.x,      wp.y),
                imgui.ImVec2(wp.x+aw0,  wp.y+th0),
                imgui.ColorConvertFloat4ToU32(iv4(r0*0.55,g0*0.55,b0*0.55,0.60)), 10, 0, 1)
            dl0:AddRectFilled(
                imgui.ImVec2(wp.x,   wp.y+4),
                imgui.ImVec2(wp.x+4, wp.y+th0-4),
                imgui.ColorConvertFloat4ToU32(iv4(r0,g0,b0,1.0)), 2)
            imgui.PushStyleColor(imgui.Col.ChildBg, iv4(0,0,0,0))
            imgui.BeginChild("##titlebar", imgui.ImVec2(aw0, th0), false)
            pcall(function()
                if PCS_COMPANION_TEX and not PCS_texQuiet() then
                    local icoSz = th0 - S(4)
                    local icoW, icoH = PCS_companionFit(icoSz, icoSz)
                    imgui.SetCursorPos(imgui.ImVec2(S(6), (th0 - icoH) * 0.5))
                    local okImgTb = pcall(imgui.Image, PCS_COMPANION_TEX, imgui.ImVec2(icoW, icoH))
                    if not okImgTb then PCS_disableCompanionTex() end
                end

                -- шапка: название скрипта (жирным), чип с версией и значок сервера
                local srvNow = detectArzServerName()
                local tTitle = u8"PC Stats"
                local tVer = "v" .. tostring(SCRIPT_VER)
                local gapH = S(10)
                local pushedT = false
                if PCS_BOLD_FONT then pushedT = pcall(imgui.PushFont, PCS_BOLD_FONT) end
                local tsz = imgui.CalcTextSize(tTitle)
                imgui.SetCursorPos(imgui.ImVec2(math.max(0, aw0*0.5 - S(120)), (th0 - tsz.y)*0.5))
                imgui.TextColored(iv4(1,1,1,1), tTitle)
                if pushedT then pcall(imgui.PopFont) end
                local vsz = imgui.CalcTextSize(tVer)
                imgui.SameLine(0, gapH)
                do
                    local U32h = imgui.ColorConvertFloat4ToU32
                    local hr, hg, hb = getAcc()
                    local dlh = imgui.GetWindowDrawList()
                    local ph = imgui.GetCursorScreenPos()
                    local chipW, chipH = vsz.x + S(14), vsz.y + S(6)
                    dlh:AddRectFilled(imgui.ImVec2(ph.x, ph.y + S(2)), imgui.ImVec2(ph.x + chipW, ph.y + S(2) + chipH), U32h(iv4(hr, hg, hb, 0.30)), chipH * 0.5)
                    dlh:AddRect(imgui.ImVec2(ph.x, ph.y + S(2)), imgui.ImVec2(ph.x + chipW, ph.y + S(2) + chipH), U32h(iv4(hr, hg, hb, 0.85)), chipH * 0.5, 0, 1.0)
                    dlh:AddText(imgui.ImVec2(ph.x + S(7), ph.y + S(5)), U32h(iv4(1, 1, 1, 0.95)), tVer)
                    imgui.Dummy(imgui.ImVec2(chipW, chipH + S(4)))
                end
                if srvNow then
                    -- значок сервера — в правом верхнем углу шапки
                    local szS = S(22)
                    local nameW = imgui.CalcTextSize(srvNow).x
                    local badgeW = szS + S(8) + nameW
                    imgui.SetCursorPos(imgui.ImVec2(math.max(0, aw0 - badgeW - S(14)), (th0 - szS) * 0.5))
                    PCS_serverBadge(srvNow, szS)
                end

                St._profilePopupOpen = false
            end)
            imgui.EndChild()
            imgui.PopStyleColor()
        end
        imgui.Spacing()

        -- ── БОКОВОЕ МЕНЮ (разделы) + ОБЛАСТЬ КОНТЕНТА ──────────────────
        local oldLayout = not (cfg.sidebarLayout == true)
        local collapsed = cfg.sidebarCollapsed and not oldLayout
        local sideW   = oldLayout and 0 or (collapsed and S(52) or S(112))
        local gapSB   = oldLayout and 0 or S(6)
        local availSB = imgui.GetContentRegionAvail()
        local contW   = availSB.x - sideW - gapSB
        local fullH   = availSB.y

        if not oldLayout then
            imgui.PushStyleColor(imgui.Col.ChildBg, iv4(0,0,0,0))
            imgui.BeginChild("##sidebarNav", imgui.ImVec2(sideW, fullH), false)
                -- ── гамбургер (☰): сворачивает/разворачивает подписи разделов ──
                do
                    local pr0,pg0,pb0 = getAcc()
                    imgui.PushStyleColor(imgui.Col.Button,        iv4(pr0*0.15,pg0*0.15,pb0*0.15,1.0))
                    imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(pr0*0.32,pg0*0.32,pb0*0.32,1.0))
                    imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(pr0*0.50,pg0*0.50,pb0*0.50,1.0))
                    -- fa + линии-стикер (unicode ☰ в клиенте = "?")
                    local barsIcon = (PCS_IC and (PCS_IC.listcheck or PCS_IC.gear)) or ""
                    if imgui.Button(tostring(barsIcon) .. "##sidebarCollapseBtn", imgui.ImVec2(sideW, S(30))) then
                        cfg.sidebarCollapsed = not cfg.sidebarCollapsed
                        saveCfg()
                    end
                    if imgui.IsItemVisible and imgui.IsItemVisible() then
                        pcall(function()
                            local mn, mx = imgui.GetItemRectMin(), imgui.GetItemRectMax()
                            local dl = imgui.GetWindowDrawList()
                            local U32 = imgui.ColorConvertFloat4ToU32
                            local midY = (mn.y + mx.y) * 0.5
                            local x0 = mn.x + (mx.x - mn.x - S(16)) * 0.5
                            local col = U32(iv4(1, 1, 1, 0.90))
                            for k = -1, 1 do
                                local yy = midY + k * S(5)
                                dl:AddLine(imgui.ImVec2(x0, yy), imgui.ImVec2(x0 + S(16), yy), col, 2.2)
                            end
                        end)
                    end
                    if imgui.IsItemHovered and imgui.IsItemHovered() then
                        pcall(outlinedTooltip, cfg.sidebarCollapsed and u8"\xd0\xe0\xe7\xe2\xe5\xf0\xed\xf3\xf2\xfc" or u8"\xd1\xe2\xe5\xf0\xed\xf3\xf2\xfc", pr0, pg0, pb0)
                    end
                    imgui.PopStyleColor(3)
                end
                imgui.Dummy(imgui.ImVec2(0, S(6)))

                PCS_UI("ui:sections")
                local curSection = sectionOfTab(St.activeTab)
                for si, sec in ipairs(SECTION_DEFS) do
                    if not PCS_tabHidden(sec.tabs[1].tab) then
                    if si > 1 then imgui.Dummy(imgui.ImVec2(0, S(5))) end
                    local btnLabel = collapsed and sec.icon or sec.label
                    if tabButton(btnLabel, curSection == si, sideW, sec.r, sec.g, sec.b, S(46)) then
                        if curSection ~= si then
                            St._resetCharScroll = true; St._resetSettScroll = true; St.accPopupOpen = false
                            St._financeSettingsOpen = false
                            St._taxLogEntriesPopupOpen = false
                            St._taxLogEntriesOpenedOnce = false
                            local newTab = sec.tabs[1].tab
                            St.activeTab = newTab
                            if cfg.lastTab ~= newTab then cfg.lastTab = newTab; saveCfg() end
                        end
                    end
                    if collapsed and imgui.IsItemHovered() then
                        outlinedTooltip(sec.name, sec.r, sec.g, sec.b)
                    end
                    end
                end
            imgui.EndChild()
            imgui.PopStyleColor()

            imgui.SameLine(0, gapSB)
        end

        imgui.PushStyleColor(imgui.Col.ChildBg, iv4(0,0,0,0))
        imgui.BeginChild("##sectionContent", imgui.ImVec2(contW, fullH), false)
St._gSC = PCS_GUARD.snap()
local _okSC, _errSC = pcall(function()

        if not oldLayout then
            local flatSB = flattenTabs()
            if PCS_tabHidden(St.activeTab) and flatSB[1] then
                St.activeTab = flatSB[1].tab
                St._resetCharScroll = true; St._resetSettScroll = true
            end
        end
        if oldLayout then
            -- ── старый единый ряд из 7 вкладок сверху (без бокового меню) ──
            local flat = flattenTabs()
            -- если активная вкладка скрыта (или её скрыли только что) — уходим на первую видимую
            if PCS_tabHidden(St.activeTab) and flat[1] then
                St.activeTab = flat[1].tab
                St._resetCharScroll = true; St._resetSettScroll = true
            end
            local avOL = imgui.GetContentRegionAvail().x
            local nOL  = #flat
            local twOL = (avOL - (nOL-1)*S(4)) / nOL
            for i, td in ipairs(flat) do
                if i > 1 then imgui.SameLine(0,S(4)) end
                if tabButton(td.label, St.activeTab==td.tab, twOL, td.r, td.g, td.b) then
                    if St.activeTab ~= td.tab then
                        St._resetCharScroll = true; St._resetSettScroll = true; St.accPopupOpen = false
                        St._financeSettingsOpen = false
                        St._taxLogEntriesPopupOpen = false
                        St._taxLogEntriesOpenedOnce = false
                    end
                    St.activeTab = td.tab
                    if cfg.lastTab ~= td.tab then cfg.lastTab = td.tab; saveCfg() end
                end
            end
            imgui.Spacing()
        end

        if not oldLayout then
        do
            local sec = SECTION_DEFS[sectionOfTab(St.activeTab)]
            local visTabs = {}
            if sec then
                for _, td0 in ipairs(sec.tabs) do
                    if not td0.hidden then visTabs[#visTabs+1] = td0 end
                end
            end
            if sec and #visTabs > 1 then
                local avSub = imgui.GetContentRegionAvail().x
                local nSub  = #visTabs
                local twSub = (avSub - (nSub-1)*S(4)) / nSub
                for i, td in ipairs(visTabs) do
                    if i > 1 then imgui.SameLine(0,S(4)) end
                    -- вкладка "Охранник" (7) считается частью "Финансов" (3)
                    if tabButton(td.label, St.activeTab==td.tab or ((St.activeTab==7 or St.activeTab==10) and td.tab==3), twSub, td.r or sec.r, td.g or sec.g, td.b or sec.b) then
                        if St.activeTab ~= td.tab then
                            St._resetCharScroll = true; St._resetSettScroll = true; St.accPopupOpen = false
                            St._financeSettingsOpen = false
                            St._taxLogEntriesPopupOpen = false
                            St._taxLogEntriesOpenedOnce = false
                        end
                        St.activeTab = td.tab
                        if cfg.lastTab ~= td.tab then cfg.lastTab = td.tab; saveCfg() end
                    end
                end
                imgui.Spacing()
            end
        end
        end

        do
            local r3,g3,b3 = getAcc()
            local dl3 = imgui.GetWindowDrawList()
            local ps  = imgui.GetCursorScreenPos()
            local aw3 = imgui.GetContentRegionAvail().x
            dl3:AddRectFilled(
                imgui.ImVec2(ps.x,     ps.y+2),
                imgui.ImVec2(ps.x+aw3, ps.y+3),
                imgui.ColorConvertFloat4ToU32(iv4(r3*0.45,g3*0.45,b3*0.45,0.60)))
        end
        imgui.Spacing()

        if St.activeTab == 1 and St.statsData and St.statsData.name ~= "" then
            local r2,g2,b2 = getAcc()
            local rr2,rg2,rb2 = getRowBgColor()
            local dl2 = imgui.GetWindowDrawList()
            local ph  = imgui.GetCursorScreenPos()
            local aw  = imgui.GetContentRegionAvail().x
            local hdrH = (hasVal(St.statsData.authDate) or _sessionStartTime) and S(78) or S(60)
            local hdrBgR = math.max(rr2*0.22, 0.06)
            local hdrBgG = math.max(rg2*0.22, 0.06)
            local hdrBgB = math.max(rb2*0.22, 0.06)
            dl2:AddRectFilled(
                imgui.ImVec2(ph.x,    ph.y),
                imgui.ImVec2(ph.x+aw, ph.y+hdrH),
                imgui.ColorConvertFloat4ToU32(iv4(hdrBgR,hdrBgG,hdrBgB,pcsRowA(0.97))), 12)
            dl2:AddRectFilled(
                imgui.ImVec2(ph.x,    ph.y),
                imgui.ImVec2(ph.x+aw*0.6, ph.y+hdrH),
                imgui.ColorConvertFloat4ToU32(iv4(rr2*0.10,rg2*0.10,rb2*0.10,0.40)), 12)
            dl2:AddRect(
                imgui.ImVec2(ph.x,    ph.y),
                imgui.ImVec2(ph.x+aw, ph.y+hdrH),
                imgui.ColorConvertFloat4ToU32(iv4(r2*0.60,g2*0.60,b2*0.60,0.80)), 12, 0, 1.4)
            dl2:AddRectFilled(
                imgui.ImVec2(ph.x,   ph.y+6),
                imgui.ImVec2(ph.x+4, ph.y+hdrH-6),
                imgui.ColorConvertFloat4ToU32(iv4(r2,g2,b2,1.0)), 2)
            dl2:AddRectFilled(
                imgui.ImVec2(ph.x+12,    ph.y),
                imgui.ImVec2(ph.x+aw-12, ph.y+2),
                imgui.ColorConvertFloat4ToU32(iv4(r2,g2,b2,0.85)), 2)
            local hdrBright = hdrBgR*0.299 + hdrBgG*0.587 + hdrBgB*0.114
            local hdrLabelCol = hdrBright > 0.35 and iv4(0.10,0.10,0.15,1.0) or thDim()
            local hdrTextCol  = hdrBright > 0.35 and iv4(0.05,0.05,0.10,1.0) or iv4(0.48,0.48,0.55,1.0)
            imgui.PushStyleColor(imgui.Col.ChildBg, iv4(0,0,0,0))
            imgui.BeginChild("##hdr", imgui.ImVec2(aw, hdrH), false,
                imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoScrollWithMouse)
                imgui.SetCursorPos(imgui.ImVec2(S(14), S(6)))
                imgui.TextColored(hdrLabelCol, u8"\xcf\xc5\xd0\xd1\xce\xcd\xc0\xc6")
                imgui.SameLine(0,7)
                imgui.TextColored(thAccBright(), u8(St.statsData.name))
                if St.statsData.accountNumber~="" then
                    imgui.SameLine(0,7)
                    imgui.TextColored(hdrTextCol, "["..St.statsData.accountNumber.."]")
                end
                imgui.SetCursorPos(imgui.ImVec2(S(14), S(28)))
                if St.statsData.level~="" then
                    imgui.TextColored(iv4(0.55,0.58,0.68,1.0), u8"\xd3\xf0.")
                    imgui.SameLine(0,4)
                    imgui.TextColored(thGold(), u8(St.statsData.level))
                    imgui.SameLine(0,14)
                end
                if St.statsData.respect~="" then
                    imgui.TextColored(iv4(0.55,0.58,0.68,1.0), "EXP:")
                    imgui.SameLine(0,4)
                    imgui.TextColored(thAcc(), u8(St.statsData.respect))
                    imgui.SameLine(0,14)
                end
                if St.statsData.health~="" then
                    local hp    = tonumber((St.statsData.health or ""):match("%d+")) or 100
                    local maxhp = tonumber((St.statsData.health or ""):match("/(%d+)")) or 100
                    local hcol  = hp>=80 and thGreen() or hp>=40 and thGold() or thRed()
                    imgui.TextColored(iv4(0.55,0.58,0.68,1.0), "HP:")
                    imgui.SameLine(0,4)
                    imgui.TextColored(hcol, u8(St.statsData.health))
                    imgui.SameLine(0,S(10))
                    local bw2 = S(80)
                    local bp  = imgui.GetCursorScreenPos()
                    local dl3 = imgui.GetWindowDrawList()
                    local bh2 = S(10)
                    imgui.SetCursorPos(imgui.ImVec2(imgui.GetCursorPosX(), imgui.GetCursorPosY()+3))
                    dl3:AddRectFilled(
                        imgui.ImVec2(bp.x,        bp.y+3),
                        imgui.ImVec2(bp.x+bw2,    bp.y+3+bh2),
                        imgui.ColorConvertFloat4ToU32(iv4(0.12,0.12,0.14,0.90)), 5)
                    local pct = math.max(0, math.min(1, hp / math.max(1, maxhp)))
                    local fc  = pct>=0.8 and iv4(0.20,0.88,0.40,0.95) or pct>=0.4 and iv4(0.95,0.75,0.10,0.95) or iv4(0.95,0.22,0.22,0.95)
                    if pct > 0 then
                        dl3:AddRectFilled(
                            imgui.ImVec2(bp.x,           bp.y+3),
                            imgui.ImVec2(bp.x+bw2*pct,   bp.y+3+bh2),
                            imgui.ColorConvertFloat4ToU32(fc), 5)
                    end
                    imgui.Dummy(imgui.ImVec2(bw2, bh2))
                end

                if hasVal(St.statsData.authDate) or _sessionStartTime then
                    imgui.SetCursorPos(imgui.ImVec2(S(14), S(50)))
                    if hasVal(St.statsData.authDate) then
                        imgui.TextColored(iv4(1,1,1,1), u8(St.statsData.authDate))
                    end
                    if _sessionStartTime then
                        if hasVal(St.statsData.authDate) then imgui.SameLine(0,10) end
                        imgui.TextColored(iv4(0.55,0.58,0.68,1.0), u8"\xc2\x20\xe8\xe3\xf0\xe5:")
                        imgui.SameLine(0,4)
                        imgui.TextColored(thGold(), fmtSessionDuration(os.time() - _sessionStartTime))
                    end
                end

            imgui.EndChild()
            imgui.PopStyleColor()
            imgui.Spacing()

        end

        if St.waitingStats then
            imgui.TextColored(thGold(), u8"  \xe7\xe0\xe3\xf0\xf3\xe7\xea\xe0...")
            imgui.Spacing()
        elseif St.statusMsg ~= "" and St.statusMsg ~= u8"\xc3\xee\xf2\xee\xe2\xee" then
            imgui.TextColored(thGold(), "  "..St.statusMsg)
            imgui.Spacing()
        end

        if St.statsData and St.activeTab <= 2 then
            local s    = St.statsData
            local av   = imgui.GetContentRegionAvail().x
            local hasAZ = hasVal(s.azCoins) or hasVal(s.accountState)
            local nTiles = hasAZ and 4 or 3
            local mw   = (av - (nTiles-1)*4) / nTiles
            local cashVal  = s.cashSas~="" and fmtMoney(s.cashSas) or "-"
            local bankVal  = s.bank~="" and fmtMoney(s.bank) or "-"
            local depVal   = s.moneyDay~="" and fmtMoney(s.moneyDay) or "-"
            local azVal    = hasVal(s.accountState) and u8(s.accountState) or (hasVal(s.azCoins) and u8(s.azCoins) or "-")
            metricTile(u8"\xcd\xe0\xeb. SA$", cashVal, thGreen(), mw, function()
                pcall(sampAddChatMessage, "{00FF88}[MSW] \xf0\x9f\x92\xb5 \xcd\xe0\xeb. SA$: " .. cashVal, -1)
            end)
            imgui.SameLine(0,4)
            metricTile(u8"\xc1\xe0\xed\xea", bankVal, thAcc(), mw, function()
                pcall(sampAddChatMessage, "{00AAFF}[MSW] \xf0\x9f\x8f\xa6 \xc1\xe0\xed\xea: " .. bankVal, -1)
            end)
            imgui.SameLine(0,4)
            metricTile(u8"\xc4\xe5\xef\xee\xe7\xe8\xf2", depVal, thGold(), mw, function()
                pcall(sampAddChatMessage, "{FFD700}[MSW] \xf0\x9f\x92\xb3 \xc4\xe5\xef\xee\xe7\xe8\xf2: " .. depVal, -1)
            end)
            if hasAZ then
                imgui.SameLine(0,4)
                metricTile("AZ-Coins", azVal, thGold(), mw, function()
                    pcall(sampAddChatMessage, "{FFD700}[MSW] \xf0\x9f\xaa\x99 AZ-Coins: " .. azVal, -1)
                end)
            end
            imgui.Spacing()
        end

        -- ── НИЖНЯЯ ПАНЕЛЬ ───────────────────────────────────────────
        PCS_UI("ui:bottom bar pre")
        local bottomBarH = (St.activeTab == 5) and (46 + S(50)) or 46
        local contentH = imgui.GetContentRegionAvail().y - bottomBarH - 20

        local _svTabFade = 0
        do
            if St._tabAnimActiveTab ~= St.activeTab then
                St._tabAnimActiveTab = St.activeTab
                St._tabAnimT = 0.0
            end
            if cfg.smoothTabAnim == false or cfg.animAllOff == true then
                St._tabAnimT = 1.0
            else
                local tnowTA = os.clock()
                if not St._tabAnimLastT then St._tabAnimLastT = tnowTA end
                local dtTA = tnowTA - St._tabAnimLastT
                St._tabAnimLastT = tnowTA
                if dtTA < 0 or dtTA > 0.5 then dtTA = 0.016 end
                St._tabAnimT = math.min(1.0, (St._tabAnimT or 1.0) + dtTA * 4.2)
            end
            local taRaw = St._tabAnimT or 1.0
            local taA = 1 - (1 - taRaw) * (1 - taRaw) * (1 - taRaw) -- easeOutCubic
            if taRaw < 0.999 then
                if pcall(imgui.PushStyleVar, imgui.StyleVar.Alpha, math.max(0.05, taA)) then
                    _svTabFade = 1
                end
                imgui.Dummy(imgui.ImVec2(0, (1 - taA) * S(22)))
            end
        end

        PCS_UI("ui:tab", St.activeTab)
        if St.activeTab == 4 then
            drawSettings(contentH, sw, sh)
        elseif St.activeTab == 5 then
            drawAbout(contentH)
        elseif St.activeTab == 6 then
            drawTaxes(contentH)
        elseif St.activeTab == 7 then
            PCS_drawGuardTab(contentH)
        elseif St.activeTab == 8 then
            PCS_REM.draw(contentH)
        elseif St.activeTab == 9 then
            PCS_AD.draw(contentH)
        elseif St.activeTab == 10 then
            PCS_drawDepositTab(contentH)
        elseif St.activeTab == 3 and St.statsData then
            drawTotal(St.statsData, contentH)
        elseif not St.statsData then
            imgui.Spacing()
            if St.waitingStats then
                imgui.TextColored(thGold(), u8"  \xc7\xe0\xe3\xf0\xf3\xe7\xea\xe0...")
            elseif St.statusMsg ~= "" then
                imgui.TextColored(thGold(), "  "..St.statusMsg)
            else
                imgui.TextColored(thDim(), u8"  \xcd\xe0\xe6\xec\xe8\xf2\xe5 \"\xce\xe1\xed\xee\xe2\xe8\xf2\xfc\" \xe4\xeb\xff \xe7\xe0\xe3\xf0\xf3\xe7\xea\xe8 \xf1\xf2\xe0\xf2\xe8\xf1\xf2\xe8\xea\xe8")
            end
        else
            local s = St.statsData
            PCS_GUARD.mark("frame: content tab " .. tostring(St.activeTab))
            PCS_UI("ui:tab " .. tostring(St.activeTab))
            PCS_UI("ui:content tab", St.activeTab)
            if     St.activeTab == 1 then drawChar(s, contentH)
            elseif St.activeTab == 2 then drawBattle(s, contentH)
            end
        end

        if _svTabFade > 0 then pcall(imgui.PopStyleVar, _svTabFade) end

        imgui.Spacing()
        if St.activeTab == 4 then
            imgui.Dummy(imgui.ImVec2(0, S(10)))
        end

        local r4,g4,b4 = getAcc()
        do
            if St.activeTab == 5 then
                local awDanger = imgui.GetContentRegionAvail().x
                drawDangerButtonsRow(awDanger, r4, g4, b4)
            else
                local bw = (imgui.GetContentRegionAvail().x - 6) * 0.5
                if St.activeTab == 6 then
                    -- вкладка "Налоги": кнопка "Сброс" возвращает к дефолту
                    -- тумблеры автооплаты налогов
                    imgui.PushStyleColor(imgui.Col.Button,        iv4(0.55,0.12,0.12,1.0))
                    imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(0.78,0.18,0.18,1.0))
                    imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(1.0, 0.25,0.25,1.0))
                    if imgui.Button(PCS_IC.undo .. u8"  \xd1\xe1\xf0\xee\xf1  ##taxReset", imgui.ImVec2(bw, S(40))) then
                        cfg.taxAutoEnabled       = false
                        cfg.taxAutoIntervalHours = 1
                        cfg.taxPayOnLogin        = false
                        St.taxAutoBuf[0]         = false
                        St.taxIntervalBuf[0]     = 1
                        St.taxPayOnLoginBuf[0]   = false
                        saveCfg()
                    end
                    if imgui.IsItemHovered and imgui.IsItemHovered() then
                        pcall(function()
                            imgui.BeginTooltip()
                            imgui.TextColored(iv4(0.75,0.80,0.90,1.0), u8"\xd1\xe1\xf0\xe0\xf1\xfb\xe2\xe0\xe5\xf2\x20\xe2\xf1\xe5\x20\xf2\xf3\xec\xe1\xeb\xe5\xf0\xfb\x20\xe8\x20\xed\xe0\xf1\xf2\xf0\xee\xe9\xea\xe8\x20\xe2\xea\xeb\xe0\xe4\xea\xe8\x20\xab\xce\xef\xeb\xe0\xf2\xe0\xbb\x20\xea\x20\xe7\xed\xe0\xf7\xe5\xed\xe8\xff\xec\x20\xef\xee\x20\xf3\xec\xee\xeb\xf7\xe0\xed\xe8\xfe")
                            imgui.EndTooltip()
                        end)
                    end
                    imgui.PopStyleColor(3)
                elseif St.activeTab == 4 then
                    imgui.PushStyleColor(imgui.Col.Button,        iv4(0.55,0.12,0.12,1.0))
                    imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(0.78,0.18,0.18,1.0))
                    imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(1.0, 0.25,0.25,1.0))
                    if imgui.Button(u8"  \xd1\xe1\xf0\xee\xf1\xe8\xf2\xfc \xe2\xf1\xb8  ", imgui.ImVec2(bw, S(40))) then
                        cfg.winWPct    = 0.60; cfg.winHPct   = 0.76
                        cfg.custR      = -1;   cfg.custG      = -1;   cfg.custB = -1
                        cfg.rowBgR     = -1;   cfg.rowBgG     = -1;   cfg.rowBgB= -1
                        cfg.fontSize   = 1.25
                        cfg.fontName   = ""; pcall(PCS_applyFontChoice)
                        St.winWbuf[0]=0.60; St.winHbuf[0]=0.76
                        St.fontSizeBuf[0] = 1.25
                        local a = getTheme().acc
                        St.custRbuf[0]=a[1]; St.custGbuf[0]=a[2]; St.custBbuf[0]=a[3]
                        St.rowBgRbuf[0]=a[1]; St.rowBgGbuf[0]=a[2]; St.rowBgBbuf[0]=a[3]
                        _sw_win_init=nil
                        cfg.companionBgEnabled = true
                        -- цвета: текст, фон окна, обводка, чат, смысловые цвета
                        cfg.textR, cfg.textG, cfg.textB = -1, -1, -1
                        cfg.winBgR, cfg.winBgG, cfg.winBgB = -1, -1, -1
                        cfg.outlineR, cfg.outlineG, cfg.outlineB = -1, -1, -1
                        cfg.chatR, cfg.chatG, cfg.chatB = -1, -1, -1
                        cfg.successR, cfg.successG, cfg.successB = -1, -1, -1
                        cfg.warnR, cfg.warnG, cfg.warnB = -1, -1, -1
                        cfg.errorR, cfg.errorG, cfg.errorB = -1, -1, -1
                        cfg.textAlpha  = 1.0
                        cfg.winBgAlpha = 1.0
                        cfg.rowBgAlpha = 0.98
                        if St.textRbuf then St.textRbuf[0], St.textGbuf[0], St.textBbuf[0] = 1.0, 1.0, 1.0 end
                        if St.winBgRbuf then St.winBgRbuf[0], St.winBgGbuf[0], St.winBgBbuf[0] = 0.0, 0.0, 0.0 end
                        if St.outlineRbuf then St.outlineRbuf[0], St.outlineGbuf[0], St.outlineBbuf[0] = a[1], a[2], a[3] end
                        if St.chatRbuf then St.chatRbuf[0], St.chatGbuf[0], St.chatBbuf[0] = 0.0, 1.0, 0.53 end

                        saveCfg()
                    end
                    imgui.PopStyleColor(3)
                elseif St.activeTab == 3 then
                    imgui.PushStyleColor(imgui.Col.Button,        iv4(0.55,0.35,0.05,1.0))
                    imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(0.75,0.50,0.08,1.0))
                    imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(0.95,0.65,0.12,1.0))
                    if imgui.Button(u8"  \xd1\xe1\xf0\xee\xf1 \xea\xf3\xf0\xf1 \xe2\xe0\xeb\xfe\xf2  ", imgui.ImVec2(bw, S(40))) then
                        cfg.rateAZ = 35000.0; cfg.rateBTC = 0.0; cfg.rateEUR = 0.0
                        cfg.rateVC = 0.0;     cfg.rateASC = 0.0
                        St.rateAZBuf[0]  = 35000; St.rateBTCBuf[0] = 0; St.rateEURBuf[0] = 0
                        St.rateVCBuf[0]  = 0;     St.rateASCBuf[0] = 0
                        St._cefLastResult = ""
                        saveCfg()
                        pcall(sampAddChatMessage, "{FFAA00}[Stats] \xe2\x9a\xa0\xef\xb8\x8f \xea\xf3\xf0\xf1\xfb \xe2\xe0\xeb\xfe\xf2 \xf1\xe1\xf0\xee\xf8\xe5\xed\xfb \xea \xe7\xed\xe0\xf7\xe5\xed\xe8\xff\xec \xef\xee \xf3\xec\xee\xeb\xf7\xe0\xed\xe8\xfe", -1)
                    end
                    imgui.PopStyleColor(3)
                elseif St.activeTab == 9 then
                    -- вкладка "Пиар": снизу "Сброс настроек" + (общая справа) "Закрыть меню"
                    local armed = (PCS_AD._resetArmUntil or 0) > os.clock()
                    local lbl = armed and u8"\xcf\xee\xe4\xf2\xe2\xe5\xf0\xe4\xe8\xf2\xfc?" or u8"\xd1\xe1\xf0\xee\xf1 \xed\xe0\xf1\xf2\xf0\xee\xe5\xea"
                    if PCS_gdButton(PCS_IC.undo .. u8"  " .. lbl .. "##adResetBottom", bw, S(40),
                        armed and { 0.95, 0.30, 0.30 } or { 0.95, 0.62, 0.20 }, PCS_AD.round()) then
                        if armed then
                            PCS_AD._resetArmUntil = 0
                            PCS_AD.resetSettings()
                            pcall(sampAddChatMessage, "{FFAA00}[PC Stats] \xcd\xe0\xf1\xf2\xf0\xee\xe9\xea\xe8 \xef\xe8\xe0\xf0\xe0 \xf1\xe1\xf0\xee\xf8\xe5\xed\xfb", -1)
                        else
                            PCS_AD._resetArmUntil = os.clock() + 3.0
                        end
                    end
                elseif St.activeTab == 8 then
                    if PCS_gdButton(PCS_IC.trash .. u8"  \xce\xf7\xe8\xf1\xf2\xe8\xf2\xfc \xe2\xfb\xef\xee\xeb\xed\xe5\xed\xed\xfb\xe5##remClearBottom", bw, S(40), { 0.90, 0.50, 0.20 }, 8.0) then
                        PCS_REM.clearDone()
                    end
                elseif St.activeTab == 7 then
                    -- Вкладка "Охранник": обновить список охранников из инвентаря
                    imgui.PushStyleColor(imgui.Col.Button,        iv4(r4*0.18,g4*0.18,b4*0.18,1.0))
                    imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(r4*0.40,g4*0.40,b4*0.40,1.0))
                    imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(r4*0.62,g4*0.62,b4*0.62,1.0))
                    if imgui.Button(PCS_IC.sync .. u8"  \xce\xe1\xed\xee\xe2\xe8\xf2\xfc \xf1\xef\xe8\xf1\xee\xea##gdRefreshBottom", imgui.ImVec2(bw, S(40))) then
                        AIS.run(AIS.CheckAllPet)
                    end
                    imgui.PopStyleColor(3)
                else
                    imgui.PushStyleColor(imgui.Col.Button,        iv4(r4*0.18,g4*0.18,b4*0.18,1.0))
                    imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(r4*0.40,g4*0.40,b4*0.40,1.0))
                    imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(r4*0.62,g4*0.62,b4*0.62,1.0))
                    if imgui.Button(PCS_IC.sync .. u8"  \xce\xe1\xed\xee\xe2\xe8\xf2\xfc  ", imgui.ImVec2(bw, S(40))) then
                        requestStats()
                    end
                    imgui.PopStyleColor(3)
                end
                imgui.SameLine(0,6)
                imgui.PushStyleColor(imgui.Col.Button,        iv4(0.35,0.06,0.06,1.0))
                imgui.PushStyleColor(imgui.Col.ButtonHovered, iv4(0.58,0.12,0.12,1.0))
                imgui.PushStyleColor(imgui.Col.ButtonActive,  iv4(0.80,0.22,0.22,1.0))
                local closeLbl = (St.activeTab == 9) and u8"  \xc7\xe0\xea\xf0\xfb\xf2\xfc \xec\xe5\xed\xfe  " or u8"  \xc7\xe0\xea\xf0\xfb\xf2\xfc  "
                if imgui.Button(PCS_IC.xmark .. closeLbl .. "##closeBottom", imgui.ImVec2(bw, S(40))) then
                    requestCloseMenu()
                end
                imgui.PopStyleColor(3)
            end
        end

end) -- конец pcall для "##sectionContent"
        PCS_GUARD.unwind(St._gSC, "sectionContent")
        imgui.EndChild() -- ##sectionContent
        if not _okSC then
            PCS_quietErr("ui@18982", _errSC)
        end
        imgui.PopStyleColor()

        do
            local okP, p = pcall(imgui.GetWindowPos)
            local okS, s = pcall(imgui.GetWindowSize)
            if okP and okS then St._mainWinPos, St._mainWinSize = p, s end
        end
        if _svMenuFade > 0 then pcall(imgui.PopStyleVar, _svMenuFade) end
        PCS_UI("ui:main before End")
        imgui.End()
        _mainWinBegan = false
        PCS_UI("ui:main after End")

        PCS_UI("ui:panel finance")
        PCS_GUARD.callr(drawFinanceSettingsPanel)
        PCS_GUARD.callr(PCS_drawDepositPanel)
        PCS_UI("ui:panel chart")
        PCS_GUARD.callr(PCS_drawChartPanel)
        PCS_UI("ui:panel calc")
        -- калькулятор рисуется отдельным кадром (S.frameCalc), не из главного окна
        PCS_UI("ui:panel global settings")
        PCS_GUARD.callr(drawGlobalSettingsPanel)
        PCS_UI("ui:panel profile")
        PCS_GUARD.callr(drawProfilePopup) -- п.6/14: тонкая карточка ник/ЗП/сервер/итого
        PCS_UI("ui:panel close confirm")
        PCS_GUARD.callr(drawCloseConfirmPopup) -- п.12: подтверждение закрытия
        PCS_UI("ui:panel danger confirm")
        PCS_GUARD.callr(PCS_drawDangerPopup) -- окно Да/Нет для кнопок управления скриптом
        PCS_UI("ui:panel photo")
        PCS_GUARD.callr(PCS_drawPhotoPopup) -- окно «Своё фото или стикер»
        PCS_UI("ui:panel tax popups")
        PCS_GUARD.callr(drawTaxPopupsGlobal)
        PCS_UI("ui:panels done")
        end -- konec if St.winOpen
        end) -- konec pcall _okFrame
        PCS_GUARD.unwind(St._gMain, "main frame")
        PCS_GUARD.mark("frame: end ok")

        if not _okFrame then
            if _mainWinBegan then
                pcall(imgui.End)
                _mainWinBegan = false
            end
            -- сбрасываем состояние окна и пересчёт размеров, чтобы при
            -- следующем открытии окно не унаследовало сломанное состояние
            St.winOpen = false
            St._winVisible = false -- аварийное закрытие: без анимации, сразу
            St._pendingCloseReset = false
            _sw_win_init = nil
            -- CRASH HARDEN: после падения кадра не трогаем текстуры/телефон
            pcall(PCS_texQuietFor, 15)
            pcall(function()
                PCS_COMPANION_TEX = nil
                if PCS_STICK then PCS_STICK.texBroken = true; PCS_STICK.tex = nil end
                _phoneOpBusy = false
                St._phoneOpBusySince = nil
                _taxState = 0
                _cefFetching = false
                _phoneFetchState = false
            end)
            PCS_quietErr("ui@19031", _errFrame)
        end
        PCS_fontPop(_fontPushed)
    end
)

function requestStats(force)
    -- во время оплаты квартиры /stats не шлём: он прячет текстдравы меню квартиры
    if FAM and FAM.busy then return end
    if St.waitingStats then return end
    -- НИКОГДА не шлём /stats, пока идёт оплата/курс или сразу после оплаты
    -- (диалог телефона ещё закрывается) — ждём в отдельном потоке
    if not force and (PCS_phoneIsBusy() or (St._statsQuietUntil and os.clock() < St._statsQuietUntil)) then
        if not St._statsDeferred then
            St._statsDeferred = true
            lua_thread.create(function()
                pcall(function()
                    local t0 = os.clock()
                    while os.clock() - t0 < 30 and (PCS_phoneIsBusy()
                        or (St._statsQuietUntil and os.clock() < St._statsQuietUntil)) do wait(250) end
                    wait(500)
                end)
                St._statsDeferred = false
                if St.winOpen then pcall(requestStats, true) end
            end)
        end
        return
    end
    if not isSampAvailable() then
        St.statusMsg = u8"\xd1\xe0\xec\xef \xed\xe5 \xe4\xee\xf1\xf2\xf3\xef\xe5\xed"
        return
    end
    St.waitingStats    = true
    captureStarted  = false
    lastReqTime     = now()
    lastTdTime      = now()
    tdCollector     = {}
    tdCollectorSize = 0
    St.statusMsg       = u8"\xce\xe1\xed\xee\xe2\xeb\xe5\xed\xe8\xe5..."
    lua_thread.create(function()
        wait(300)
        local ok, err = pcall(sampSendChat, "/stats")
        if not ok then
            St.waitingStats = false
            St.statusMsg = u8"\xce\xf8\xe8\xe1\xea\xe0 \xea\xee\xec\xe0\xed\xe4\xfb: " .. tostring(err)
            pcall(pcs_notify, St.statusMsg, "error")
        end
    end)
end

local function finalize()
    if not St.waitingStats or finalizing then return end
    finalizing = true
    if next(tdCollector) == nil then
        St.waitingStats = false
        finalizing = false
        return
    end
    local rows={}
    for _,td in pairs(tdCollector) do table.insert(rows,td) end
    table.sort(rows, function(a, b)
        local ay, by2 = tonumber(a.y) or 0, tonumber(b.y) or 0
        if ay ~= by2 then return ay < by2 end
        return (tonumber(a.id) or 0) < (tonumber(b.id) or 0)
    end)
    do
        local grouped, gi = {}, 1
        while gi <= #rows do
            local y0 = tonumber(rows[gi].y) or 0
            local grp = { rows[gi] }
            local gj = gi + 1
            while gj <= #rows and math.abs((tonumber(rows[gj].y) or 0) - y0) < 5 do
                grp[#grp + 1] = rows[gj]; gj = gj + 1
            end
            table.sort(grp, function(a, b)
                local ax, bx = tonumber(a.x) or 0, tonumber(b.x) or 0
                if ax ~= bx then return ax < bx end
                return (tonumber(a.id) or 0) < (tonumber(b.id) or 0)
            end)
            for _, td in ipairs(grp) do grouped[#grouped + 1] = td end
            gi = gj
        end
        rows = grouped
    end
    local lines,seen={},{}
    for _,td in ipairs(rows) do
        local t=trim(td.text)
        if t~="" and not seen[t]
            and t~="\xcf\xf0\xe5\xe4\xec\xe5\xf2\xfb"
            and t~="\xc7\xe0\xea\xf0\xfb\xf2\xfc" then
            seen[t]=true; table.insert(lines,t)
        end
    end
    local raw=table.concat(lines,"\n")
    if raw~="" then
        St.statsData=parseStats(raw)
        St.statusMsg=u8"\xc3\xee\xf2\xee\xe2\xee"
    else
        St.statusMsg=u8"\xcd\xe5\xf2 \xe4\xe0\xed\xed\xfb\xf5"
    end
    St.waitingStats=false; captureStarted=false; tdCollector={}; tdCollectorSize=0
    finalizing = false
end

function PCS_taxNoTaxes(line)
    local wasAuto = _taxIsAuto
    _taxState = 0
    _taxExpectedDialogId = nil
    cfg.taxLastPayTime = os.time()
    pcall(saveCfg)
    pcall(TX.addEntry, wasAuto, 0, true)
    if type(line) == "string" and line ~= "" then
        pcall(sampAddChatMessage, "{FFD700}[PC Stats] " .. line, -1)
    else
        pcall(sampAddChatMessage, "{FFD700}[PC Stats] " .. "\xcd\xe0\xeb\xee\xe3\xe8\x20\xf3\xe6\xe5\x20\xee\xef\xeb\xe0\xf7\xe5\xed\xfb", -1)
    end
    pcall(pcs_notify, u8"\xcd\xe0\xeb\xee\xe3\xee\xe2\x20\xea\x20\xee\xef\xeb\xe0\xf2\xe5\x20\xed\xe5\xf2", "info")
    lua_thread.create(function()
        wait(500)
        PCS_phoneRelease(5)
    end)
end
function PCS_onShowDialogImpl(id, style, title, btn1, btn2, text)
    PCS_GUARD.mark("onShowDialog id=" .. tostring(id))
    -- ── AIS (охоронці): якщо обробили діалог — не йдемо в податки ──
    if AIS and AIS.onShowDialog then
        local aisOk, aisRet = pcall(AIS.onShowDialog, id, style, title, btn1, btn2, text)
        if not aisOk then
            print("[PC Stats/guard] onShowDialog(AIS) error: " .. tostring(aisRet))
        elseif aisRet == false then
            return false
        end
    end
    if PCS_RC and PCS_RC.onDialog then
        local rcOk, rcRet = pcall(PCS_RC.onDialog, id, style, title, btn1, btn2, text)
        if rcOk and rcRet == false then return false end
    end
    -- авто-пиар: свои диалоги /vr и /ad (налоги/телефон имеют приоритет внутри)
    if PCS_AD and PCS_AD.onDialog then
        local adOk, adRet = pcall(PCS_AD.onDialog, id, style, title, btn1, btn2, text)
        if adOk and adRet == true then return false end
    end
    -- ── автоматизация оплаты налогов (см. payTaxesNow) ──
    if _taxState ~= 0 then
        _taxDlgSeq = (_taxDlgSeq or 0) + 1
        pcall(PCS_TR, "tax: dialog id=" .. tostring(id) .. " state=" .. tostring(_taxState))
        St._taxDlgIds = St._taxDlgIds or {}
        St._taxDlgIds[tonumber(id) or -1] = os.clock()
        local handledTax = false

        pcall(function()
            local lines = splitTaxLines(text)

            if _taxState == 1 then
                for i, line in ipairs(lines) do
                    if line:find(TAX_NEEDLE_PAY_ALL, 1, true) then
                        _taxState = 2
                        _taxExpectedDialogId = id
                        _taxAnsweredThisDialog = false
                        local curDialog, curIndex = id, i - 1
                        local _seq = _taxDlgSeq
                        PCS_taxThread("dialog-step", function()
                            wait(TAX_STEP_DELAY)
                            if not PCS_taxAnswerOk(_seq, curDialog) then return end
                            pcall(PCS_TR, "tax: send id=" .. tostring(curDialog) .. " item=" .. tostring(curIndex))
                            PCS_sendDialogIfId(curDialog, 1, curIndex, "")
                        end)
                        handledTax = true
                        return
                    end
                end
                if _taxNavAttempts < TAX_NAV_MAX_ATTEMPTS then
                    for i, line in ipairs(lines) do
                        if line:find(TAX_NEEDLE_APP_ICON, 1, true)
                            and not line:find(TAX_NEEDLE_FINE, 1, true) then
                            _taxNavAttempts = _taxNavAttempts + 1
                            local curDialog, curIndex = id, i - 1
                            local _seq = _taxDlgSeq
                            PCS_taxThread("dialog-step", function()
                                wait(TAX_STEP_DELAY)
                                -- см. комментарий выше: диалог скрыт хуком, проверяем отмену и свежесть id
                                if not PCS_taxAnswerOk(_seq, curDialog) then return end
                                pcall(PCS_TR, "tax: send id=" .. tostring(curDialog) .. " item=" .. tostring(curIndex))
                                PCS_sendDialogIfId(curDialog, 1, curIndex, "")
                            end)
                            handledTax = true
                            return
                        end
                    end
                    for i, line in ipairs(lines) do
                        if line:find(BANK_NEEDLE_APP_ICON, 1, true)
                            and not line:find(TAX_NEEDLE_FINE, 1, true) then
                            _taxNavAttempts = _taxNavAttempts + 1
                            local curDialog, curIndex = id, i - 1
                            local _seq = _taxDlgSeq
                            PCS_taxThread("dialog-step", function()
                                wait(TAX_STEP_DELAY)
                                -- см. комментарий выше: диалог скрыт хуком, проверяем отмену и свежесть id
                                if not PCS_taxAnswerOk(_seq, curDialog) then return end
                                pcall(PCS_TR, "tax: send id=" .. tostring(curDialog) .. " item=" .. tostring(curIndex))
                                PCS_sendDialogIfId(curDialog, 1, curIndex, "")
                            end)
                            handledTax = true
                            return
                        end
                    end
                end
                _taxState = 0
                _taxExpectedDialogId = nil
                cfg.taxLastPayTime = os.time()
                pcall(saveCfg)
                TX.addEntry(_taxIsAuto, 0, true)
                pcall(sampAddChatMessage, "{FFD700}[PC Stats] " ..
                    "\xcd\xe0\xeb\xee\xe3\xe8\x20\xf3\xe6\xe5\x20\xee\xef\xeb\xe0\xf7\xe5\xed\xfb", -1)
                pcall(pcs_notify, u8"\xcd\xe0\xeb\xee\xe3\xe8\x20\xf3\xe6\xe5\x20\xee\xef\xeb\xe0\xf7\xe5\xed\xfb", "info")
                -- без close — только release (close после tax = native crash)
                lua_thread.create(function()
                    wait(500)
                    PCS_phoneRelease(5)
                end)
                handledTax = true
                return
            end

            if _taxState == 2 then
                if _taxAnsweredThisDialog then
                    handledTax = true
                    return
                end
                local curDialog = id
                local wasAuto = _taxIsAuto
                for _, line in ipairs(lines) do
                    if line:find(TAX_NEEDLE_NO_TAX, 1, true) then
                        _taxState = 0
                        _taxExpectedDialogId = nil
                        cfg.taxLastPayTime = os.time()
                        pcall(saveCfg)
                        TX.addEntry(wasAuto, 0, true)
                        pcall(sampAddChatMessage, "{FFD700}[PC Stats] " .. line, -1)
                        pcall(pcs_notify, u8"\xf3\x20\xe2\xe0\xf1\x20\xed\xe5\xf2\x20\xed\xe0\xeb\xee\xe3\xee\xe2\x2c\x20\xea\xee\xf2\xee\xf0\xfb\xe5\x20\xf2\xf0\xe5\xe1\xf3\xe5\xf2\xf1\xff\x20\xee\xef\xeb\xe0\xf2\xe8\xf2\xfc", "info")
                        lua_thread.create(function()
                            wait(500)
                            PCS_phoneRelease(5)
                        end)
                        handledTax = true
                        return
                    end
                end
                _taxPendingAmount = extractTaxAmount(text)
                for i, line in ipairs(lines) do
                    if line:find(TAX_NEEDLE_PAY_BTN, 1, true) then
                        _taxAnsweredThisDialog = true
                        local _seq = _taxDlgSeq
                        PCS_taxThread("dialog-step", function()
                            wait(TAX_STEP_DELAY)
                            -- отмена или пришёл новый диалог (устаревший id)
                            if not PCS_taxAnswerOk(_seq, curDialog) then return end
                            pcall(PCS_TR, "tax: send id=" .. tostring(curDialog) .. " item=" .. tostring(i - 1)); PCS_taxStage("pay clicked")
                            PCS_sendDialogIfId(curDialog, 1, i - 1, "")
                            _taxState = 3
                            _taxExpectedDialogId = nil
                            wait(_TAX_POST_PAY_WAIT_MS)
                            if _taxState == 3 then
                                local okSucc = pcall(PCS_taxSuccessDeferred, wasAuto, _taxPendingAmount)
                                if not okSucc then
                                    _taxState = 0
                                    _taxExpectedDialogId = nil
                                    pcall(PCS_phoneRelease, 5, 2)
                                end
                            end
                        end)
                        handledTax = true
                        return
                    end
                end
                if (btn1 or ""):find(TAX_NEEDLE_PAY_BTN, 1, true) then
                    _taxAnsweredThisDialog = true
                    local _seq = _taxDlgSeq
                    PCS_taxThread("dialog-step", function()
                        wait(TAX_STEP_DELAY)
                        if not PCS_taxAnswerOk(_seq, curDialog) then return end   -- отмена / устаревший диалог
                        pcall(PCS_TR, "tax: send id=" .. tostring(curDialog) .. " item=" .. tostring(0))
                        PCS_sendDialogIfId(curDialog, 1, 0, "")
                        _taxState = 3
                        _taxExpectedDialogId = nil
                        wait(_TAX_POST_PAY_WAIT_MS)
                        if _taxState == 3 then
                            local okSucc = pcall(PCS_taxSuccessDeferred, wasAuto, _taxPendingAmount)
                            if not okSucc then
                                _taxState = 0
                                _taxExpectedDialogId = nil
                                pcall(PCS_phoneRelease, 5, 2)
                            end
                        end
                    end)
                    handledTax = true
                    return
                end
                -- не нашли кнопку "Оплатить" — сдаёмся
                _taxState = 0
                _taxExpectedDialogId = nil
                pcall(sampAddChatMessage, "{FF6666}[PC Stats] " ..
                    "\xed\xe5\x20\xed\xe0\xf8\xb8\xeb\x20\xea\xed\xee\xef\xea\xf3\x20\x22\xce\xef\xeb\xe0\xf2\xe8\xf2\xfc\x22\x20\xe4\xeb\xff\x20\xed\xe0\xeb\xee\xe3\xee\xe2", -1)
                lua_thread.create(function()
                    wait(500)
                    PCS_phoneRelease(5)
                end)
                handledTax = true
            end

            if _taxState == 3 and PCS_TAX_CONFIRM_ENTER then
                local _id3, _text3, _seq3 = id, text, _taxDlgSeq
                PCS_taxThread("dialog-step", function()
                    wait(TAX_STEP_DELAY)
                    if _taxState ~= 3 then return end
                    pcall(PCS_TR, "tax: confirm dialog id=" .. tostring(_id3))
                    PCS_sendDialogIfId(_id3, 1, 0, "")
                    local wasAuto3 = _taxIsAuto
                    if not (_taxPendingAmount and _taxPendingAmount > 0) then
                        local okA, amA = pcall(extractTaxAmount, _text3)
                        if okA then _taxPendingAmount = amA end
                    end
                    local okSucc = pcall(PCS_taxSuccessDeferred, wasAuto3, _taxPendingAmount)
                    if not okSucc then
                        _taxState = 0
                        _taxExpectedDialogId = nil
                        pcall(PCS_phoneRelease, 5, 2)
                    end
                end)
                handledTax = true
            end
        end)
        if handledTax then return end
    end

    if _phoneFetchState == "waiting" then
        local handled = false
        pcall(function()
            if isCryptoRatesDialog(title, text) then
                local got = parsePhoneRatesText(tostring(text or ""))
                _phoneFetchState = false
                if got then
                    St._cefLastResult = "\xea\xf3\xf0\xf1\xfb \xee\xe1\xed\xee\xe2\xeb\xe5\xed\xfb \xe8\xe7 \xf2\xe5\xeb\xe5\xf4\xee\xed\xe0"
                    pcall(sampAddChatMessage, "{00FF88}[Stats] \xf0\x9f\x92\xb1 " .. "\xea\xf3\xf0\xf1\xfb \xee\xe1\xed\xee\xe2\xeb\xe5\xed\xfb \xe8\xe7 \xf2\xe5\xeb\xe5\xf4\xee\xed\xe0", -1)
                else
                    St._cefLastResult = "\xed\xe5 \xf3\xe4\xe0\xeb\xee\xf1\xfc \xf0\xe0\xe7\xee\xe1\xf0\xe0\xf2\xfc \xea\xf3\xf0\xf1\xfb \xe2 \xee\xf2\xea\xf0\xfb\xf2\xee\xec \xf0\xe0\xe7\xe4\xe5\xeb\xe5"
                    pcall(sampAddChatMessage, "{FF6666}[Stats] " .. tostring(St._cefLastResult), -1)
                end
                -- закрываем меню курсов и саму вкладку телефона, чтобы не
                -- оставлять телефон открытым поверх интерфейса игрока
                do local _rid = id; lua_thread.create(function() wait(120); pcall(PCS_closeDialogIfId, _rid) end) end
                handled = true
            end
        end)
        if handled then
            return false
        end
    end

    local isStatsDialog = false
    pcall(function()
        local tT  = tostring(title or "")
        local tX  = tostring(text or "")
        local tTl = tT:lower()
        local isStatsTitle = tTl:find("\xf1\xf2\xe0\xf2") or tTl:find("stat")
                          or tTl:find("\xce\xf1\xed\xee\xe2\xed\xe0\xff \xf1\xf2\xe0\xf2")
        if isStatsTitle or isStatsPiece(tX) then
            local cleaned = stripColor(tX)
            if isStatsPiece(cleaned) or (isStatsTitle and cleaned~="") then
                if St.waitingStats and not FAM.busy then isStatsDialog = true end
                St.statsData       = parseStats(cleaned)
                St.statusMsg       = u8"\xc3\xee\xf2\xee\xe2\xee"
                St.waitingStats    = false
                tdCollector     = {}
                tdCollectorSize = 0
            end
        end
    end)
    if isStatsDialog and cfg.hideNativeStats then
        local _hideId = id
        lua_thread.create(function()
            wait(120)
            pcall(PCS_GUARD.mark, "stats: close native dialog")
            local okA, act = pcall(function() return sampIsDialogActive() end)
            if okA and act and type(sampCloseCurrentDialogWithButton) == "function" then
                local okI, cid = pcall(function() return sampGetCurrentDialogId() end)
                if okI and cid == _hideId then
                    pcall(sampCloseCurrentDialogWithButton, 0)
                end
            end
            pcall(PCS_GUARD.mark, "stats: close native dialog done")
        end)
    end
end

function sampev.onShowDialog(id, style, title, btn1, btn2, text)
    pcall(FAM.onDialog, id, text, style)
    local okD, ret = pcall(PCS_onShowDialogImpl, id, style, title, btn1, btn2, text)
    if not okD then
        print("[PC Stats/guard] onShowDialog error: " .. tostring(ret))
        pcall(PCS_TR, "dialog: error id=" .. tostring(id) .. " " .. tostring(ret))
        return nil
    end
    return ret
end

function pcsHandlePhoneBusyServerError(text)
    local clean = stripColor(tostring(text or ""))
    local low = cp1251Lower(clean)
    if not (low:find("\xee\xf8\xe8\xe1\xea", 1, true)) then return false end
    if not (low:find("\xf2\xe5\xeb\xe5\xf4\xee\xed", 1, true)) then return false end
    if not (low:find("\xee\xf2\xea\xf0\xfb\xf2", 1, true) or low:find("\xe7\xe0\xed\xff\xf2", 1, true)) then return false end

    _phoneOpBusy      = false
    St._phoneOpBusySince = nil
    _cefFetching      = false
    _phoneFetchState  = false
    _taxState         = 0
    pcall(PCS_texQuietFor, 10)
    _taxExpectedDialogId = nil
    _taxPhoneAlreadyOpen = false

    St._phoneCooldownUntil = math.max(St._phoneCooldownUntil or 0, os.time() + 6)

    return true
end

-- ── уведомление "Ваш личный охранник голоден, его необходимо покормить!" ──
PCS_GUARD_NOTE = PCS_GUARD_NOTE or { lastT = -10 }
PCS_GUARD_NOTE.key = "\xee\xf5\xf0\xe0\xed\xed\xe8\xea \xe3\xee\xeb\xee\xe4\xe5\xed"

-- нижний регистр для CP1251 (А-Я, Ё)
function PCS_GUARD_NOTE.lower(s)
    local r = string.gsub(s, "[\192-\223\168]", function(c)
        local b = string.byte(c)
        if b == 168 then return "\184" end
        return string.char(b + 32)
    end)
    return (string.lower(r))
end

function PCS_GUARD_NOTE.check(text)
    if cfg.notifyGuard == false and cfg.guardTg == false then return end
    local clean = string.gsub(tostring(text or ""), "{%x+}", "")
    if not string.find(PCS_GUARD_NOTE.lower(clean), PCS_GUARD_NOTE.key, 1, true) then return end
    local now = os.clock()
    if now - PCS_GUARD_NOTE.lastT < 2 then return end
    PCS_GUARD_NOTE.lastT = now
    if cfg.notifyGuard ~= false then
        PCS_NO_TOAST_ONCE = true
        pcall(sampAddChatMessage, "{FFAA00}[PC Stats] {FFFFFF}" .. clean, -1)
        PCS_NO_TOAST_ONCE = false
        PCS_TOAST_FROM_CHAT = true
        pcall(pcs_notify, u8(clean), "warning")
        PCS_TOAST_FROM_CHAT = false
    end
    if cfg.guardTg ~= false and PCS_TG and PCS_TG.ready and PCS_TG.ready() then
        pcall(PCS_TG.send, "\240\159\144\182 " .. u8(clean))
    end
end

