PCS_MENTION = PCS_MENTION or { lastText = "", lastT = 0 }

function PCS_MENTION.ignored(nick)
    local list = tostring(cfg.mentionIgnore or "")
    if list == "" or not nick then return false end
    local low = string.lower(nick)
    for name in string.gmatch(list, "[^,;%s]+") do
        if string.lower(name) == low then return true end
    end
    return false
end

-- ник отправителя: первый подключённый игрок, упомянутый в строке
function PCS_MENTION.findSender(clean, selfNick)
    for nick in string.gmatch(clean, "[A-Za-z0-9_]+") do
        nick = string.gsub(nick, "[%[%(]%d+[%]%)]", "")
        if #nick <= 24 and nick ~= selfNick then
            for id = 0, 999 do
                if sampIsPlayerConnected(id) and sampGetPlayerNickname(id) == nick then
                    return nick
                end
            end
        end
    end
    return nil
end

function PCS_MENTION.check(text)
    if cfg.mentionEnabled == false then return end
    local clean = string.gsub(tostring(text or ""), "{%x+}", "")
    local okS, selfId = pcall(function() return select(2, sampGetPlayerIdByCharHandle(PLAYER_PED)) end)
    if not okS or selfId == nil then return end
    local selfNick = string.gsub(sampGetPlayerNickname(selfId) or "", "^%[.-%]", "")
    local ci = cfg.mentionCase ~= false
    local hit = false
    for w in string.gmatch(clean, "%S+%p*") do
        w = string.gsub(w, "%p*$", "")
        if cfg.mentionSelf ~= false then
            if w == "@" .. selfId then hit = true; break end
            if ci then
                if string.lower(w) == string.lower("@" .. selfNick) then hit = true; break end
            elseif w == "@" .. selfNick then hit = true; break end
        end
        local lw = string.lower(w)
        if cfg.mentionAll ~= false and (lw == "@all" or lw == "@everyone") then hit = true; break end
    end
    if not hit then return end
    local sender = PCS_MENTION.findSender(clean, selfNick)
    if PCS_MENTION.ignored(sender) then return end
    PCS_MENTION.notify(clean, sender)
end

function PCS_MENTION.notify(clean, sender)
    local now = os.clock()
    if PCS_MENTION.lastText == clean and now - PCS_MENTION.lastT < 2 then return end
    PCS_MENTION.lastText, PCS_MENTION.lastT = clean, now
    local who = (cfg.mentionSender ~= false and sender) and (sender .. ": ") or ""
    local line = who .. clean
    if cfg.mentionToast ~= false then
        PCS_TOAST_FROM_CHAT = true
        pcall(pcs_notify, u8(line), "mention")
        PCS_TOAST_FROM_CHAT = false
    end
    if cfg.mentionTg ~= false and PCS_TG and PCS_TG.ready and PCS_TG.ready() then
        pcall(PCS_TG.send, "\240\159\146\172 " .. u8(line))
    end
end

-- тумблер в настройках (та же строка, что у остальных настроек Telegram)
function PCS_MENTION.row(id, key, label, desc, dflt)
    local on = cfg[key]
    if on == nil then on = dflt end
    if PCS_settToggleRow(id, on ~= false, label, desc) then
        cfg[key] = not (on ~= false)
        saveCfg()
    end
end

