function sampev.onServerMessage(color, text)
    pcall(pcsHandlePhoneBusyServerError, text)
    pcall(PCS_GUARD_NOTE.check, text)
    pcall(PCS_MENTION.check, text)
    pcall(PCS_AD.onServerMessage, text)
    pcall(PCS_QUEUE.onServerMessage, text)

    pcall(function()
        local cleanPd = stripColor(text or "")
        local pdHandled = PD.onStandaloneLine(cleanPd) or PD.onLine(cleanPd)
        if pdHandled then
            St._paydayLastLineT = os.clock()
            lua_thread.create(function()
                local myT = St._paydayLastLineT
                wait(600)
                if St._paydayLastLineT == myT then
                    pcall(PD.flush)
                end
            end)
        end
    end)

    pcall(function()
        local clean = stripColor(text or "")
        local low   = cp1251Lower(clean)
        if not low:find(TAX_WORD, 1, true) then return end
        if not low:find(PAID_WORD, 1, true) then return end

        local amount = TX.extractChatAmount(clean)
        if low:find("\xe2\xfb\x20\xee\xef\xeb\xe0\xf2\xe8\xeb", 1, true) then -- "вы оплатил"
            -- строка успешной оплаты пришла: если скрипт ждёт её для перезапуска — перезапускаемся
            -- через 1.5 с (лог с суммой допишется ниже, до перезапуска)
            St._taxChatOkAt = os.clock()
            if St._taxReloadArmedAt then PCS_taxReloadNow(1000) end
            if _taxState ~= 0 and not _taxFinalizeDone then
                if amount > 0 then _taxPendingAmount = amount end
                return
            end
            local sinceLast = (cfg.taxLastPayTime ~= 0) and (os.time() - cfg.taxLastPayTime) or math.huge
            if _taxFinalizeDone and sinceLast <= 15 then
                -- скрипт только что записал оплату (возможно, с нулевой
                -- суммой) — дописываем сумму из чата в лог/статистику
                if amount > 0 then
                    TX.fixLastAmount(amount)
                    cfg.taxLastPayAmount = amount
                end
                cfg.taxLastPayTime = os.time()
                saveCfg()
                return
            end
            _taxFinalizeDone = false
            _taxScriptRun = false
            lua_thread.create(function()
                wait(50)
                pcall(PCS_taxSuccessDeferred, false, amount)
            end)
            return
        end
    end)

    -- ── AIS: повідомлення про охоронців / інвентар ──
    pcall(function()

    pcall(function()
        local t = tostring(text or "")
        if t:find("%[Family%]") and (t:find("\xf1\xe5\xec\xe5\xe9\xed") or t:find("\xea\xe2\xe0\xf0\xf2")) then
            if t:find("\xed\xe0\xeb\xee\xe3") or t:find("\xea\xe2\xe0\xf0\xf2") then
                local amount = 0
                local raw = t:match("([%d][%d%., ]*[%d])")
                if raw then
                    local n = tostring(raw):gsub("%s+", ""):gsub("%.", ""):gsub(",", "")
                    amount = tonumber(n) or 0
                end
                if TX and TX.addEntry then TX.addEntry(false, amount, amount <= 0, "family") end
                if amount > 0 then
                    cfg.taxLastPayAmount = amount
                    cfg.taxLastPayTime = os.time()
                    pcall(saveCfg)
                end
                pcall(sampAddChatMessage, "{00FF88}[PC Stats] Family apt tax log: " .. tostring(amount), -1)
            end

    -- оплата налогов организации (чат [Organization]/ и т.п.)
    pcall(function()
        local t = tostring(text or "")
        local low = cp1251Lower(stripColor(t))
        local isOrg = (t:find("%[Org") or t:find("%[ORG") or low:find("\xee\xf0\xe3\xe0\xed\xe8\xe7", 1, true))
            and (low:find("\xed\xe0\xeb\xee\xe3", 1, true) or low:find("\xee\xef\xeb\xe0\xf2", 1, true))
        if isOrg then
            local amount = TX.extractChatAmount(stripColor(t))
            if amount <= 0 then
                local raw = t:match("([%d][%d%., ]*[%d])")
                if raw then
                    local n = tostring(raw):gsub("%s+", ""):gsub("%.", ""):gsub(",", "")
                    amount = tonumber(n) or 0
                end
            end
            if TX and TX.addEntry then TX.addEntry(false, amount, amount <= 0, "org") end
            if amount > 0 then
                cfg.taxLastPayAmount = amount
                cfg.taxLastPayTime = os.time()
                pcall(saveCfg)
            end
            pcall(sampAddChatMessage, "{00FF88}[PC Stats] Org tax log: " .. tostring(amount), -1)
        end
    end)
end
    end)

        if AIS and AIS.onServerMessage then
            AIS.onServerMessage(color, text)
        end
    end)
end

function sampev.onShowTextDraw(id, data)
    pcall(FAM.onTextDraw, id, data)
    if not St.waitingStats or FAM.busy then return end
    local hidden = false
    pcall(function()
        local raw = tostring((data and data.text) or "")
        local cl  = trim(stripColor(raw))
        if cl=="" or looksTexture(cl) then return end
        local x,y = 0,0
        if data then
            if type(data.position)=="table" then
                x=tonumber(data.position.x) or 0; y=tonumber(data.position.y) or 0
            elseif tonumber(data.x) then
                x=tonumber(data.x) or 0; y=tonumber(data.y) or 0
            end
        end
        if x > 550 then return end
        local matched = isStatsPiece(cl)
        if matched then captureStarted=true end
        local inZone  = x>=-10 and x<=550 and y>=-10 and y<=1200
        if matched or (captureStarted and inZone) then
            if tdCollectorSize == nil then tdCollectorSize = 0 end
            if tdCollectorSize < 300 then
                if not tdCollector[id] then tdCollectorSize = tdCollectorSize + 1 end
                tdCollector[id]={id=id,x=x,y=y,text=cl}; lastTdTime=now()
            end
            if cfg.hideNativeStats then
                hidden = true
            end
        end
    end)
    if hidden then return false end
end

function sampev.onSetTextDraw(id, data)
    if not St.waitingStats then return end
    local hidden = false
    pcall(function()
        if not tdCollector[id] then return end
        if not data or not data.text then return end
        local raw = tostring((data and data.text) or "")
        local cl  = trim(stripColor(raw))
        if cl=="" or looksTexture(cl) then return end
        tdCollector[id].text=cl; lastTdTime=now()
        if cfg.hideNativeStats then
            hidden = true
        end
    end)
    if hidden then return false end
end

PCS_TG = PCS_TG or { q = {}, status = "", statusOk = nil }

-- тело effil-потока: без upvalue
function PCS_TG.threadBody(url, body, timeout)
    local okR, req = pcall(require, "requests")
    if not okR or type(req) ~= "table" then okR, req = pcall(require, "lib.requests") end
    if not okR or type(req) ~= "table" or not req.post then return "ERR no_requests" end
    local ok, resp = pcall(req.post, url, {
        data = body,
        headers = { ["Content-Type"] = "application/json", ["User-Agent"] = "PCStats" },
        timeout = timeout,
    })
    if not ok or type(resp) ~= "table" then return "ERR " .. tostring(resp):sub(1, 80) end
    return "CODE " .. tostring(tonumber(resp.status_code or resp.status) or 0)
end

function PCS_TG.ready()
    local tok = tostring(cfg.tgToken or ""):gsub("%s+", "")
    local chat = tostring(cfg.tgChatId or ""):gsub("%s+", "")
    return cfg.tgEnabled == true and #tok >= 20 and chat ~= ""
end

function PCS_TG.explain(info, code)
    if info == "diag_bad_token" then return u8"\xcd\xe5\xe2\xe5\xf0\xed\xfb\xe9 \xf2\xee\xea\xe5\xed \xe1\xee\xf2\xe0. \xd1\xea\xee\xef\xe8\xf0\xf3\xe9\xf2\xe5 \xf2\xee\xea\xe5\xed \xf6\xe5\xeb\xe8\xea\xee\xec \xe8\xe7 @BotFather (\xe2\xe8\xe4 123456789:AAH...)." end
    if info == "diag_bad_chat" then return u8"\xc1\xee\xf2 \xed\xe5 \xed\xe0\xf8\xb8\xeb \xfd\xf2\xee\xf2 \xf7\xe0\xf2. \xcb\xe8\xf7\xea\xe0: \xee\xf2\xea\xf0\xee\xe9\xf2\xe5 \xe1\xee\xf2\xe0 \xe8 \xed\xe0\xe6\xec\xe8\xf2\xe5 Start. \xc3\xf0\xf3\xef\xef\xe0: \xe4\xee\xe1\xe0\xe2\xfc\xf2\xe5 \xe1\xee\xf2\xe0 \xe2 \xe3\xf0\xf3\xef\xef\xf3 \xe8 \xed\xe0\xef\xe8\xf8\xe8\xf2\xe5 \xf2\xe0\xec \xeb\xfe\xe1\xee\xe5 \xf1\xee\xee\xe1\xf9\xe5\xed\xe8\xe5. ID \xe3\xf0\xf3\xef\xef\xfb \xed\xe0\xf7\xe8\xed\xe0\xe5\xf2\xf1\xff \xf1 -100 (\xf3\xe7\xed\xe0\xf2\xfc: @getidsbot \xe8\xeb\xe8 @RawDataBot)." .. (PCS_TG._botName and (" @" .. PCS_TG._botName) or "") end
    if info == "diag_private" then return u8"\xd7\xe0\xf2 \xed\xe0\xe9\xe4\xe5\xed, \xed\xee \xe1\xee\xf2 \xed\xe5 \xec\xee\xe6\xe5\xf2 \xef\xe8\xf1\xe0\xf2\xfc \xef\xe5\xf0\xe2\xfb\xec: \xee\xf2\xea\xf0\xee\xe9\xf2\xe5 \xe1\xee\xf2\xe0 \xe8 \xed\xe0\xe6\xec\xe8\xf2\xe5 Start." .. (PCS_TG._botName and (" @" .. PCS_TG._botName) or "") end
    if info == "diag_norights" then return u8"\xc1\xee\xf2 \xe5\xf1\xf2\xfc \xe2 \xf7\xe0\xf2\xe5, \xed\xee \xef\xe8\xf1\xe0\xf2\xfc \xed\xe5 \xec\xee\xe6\xe5\xf2: \xe2 \xe3\xf0\xf3\xef\xef\xe5 \xf0\xe0\xe7\xf0\xe5\xf8\xe8\xf2\xe5 \xe5\xec\xf3 \xee\xf2\xef\xf0\xe0\xe2\xeb\xff\xf2\xfc \xf1\xee\xee\xe1\xf9\xe5\xed\xe8\xff, \xe2 \xea\xe0\xed\xe0\xeb\xe5 \xf1\xe4\xe5\xeb\xe0\xe9\xf2\xe5 \xe5\xe3\xee \xe0\xe4\xec\xe8\xed\xe8\xf1\xf2\xf0\xe0\xf2\xee\xf0\xee\xec." end
    if info == "diag_text" then return u8"\xd7\xe0\xf2 \xe8 \xf2\xee\xea\xe5\xed \xe2\xe5\xf0\xed\xfb, \xed\xee Telegram \xee\xf2\xea\xeb\xee\xed\xe8\xeb \xf2\xe5\xea\xf1\xf2 \xf1\xee\xee\xe1\xf9\xe5\xed\xe8\xff. \xd1\xee\xee\xe1\xf9\xe8\xf2\xe5 \xee\xe1 \xfd\xf2\xee\xec \x97 \xef\xf0\xe8\xf8\xeb\xfe \xe8\xf1\xef\xf0\xe0\xe2\xeb\xe5\xed\xe8\xe5." end
    if info == "http_error" then return u8"\xd1\xee\xee\xe1\xf9\xe5\xed\xe8\xe5 \xed\xe5 \xef\xf0\xe8\xed\xff\xf2\xee: \xef\xf0\xee\xe2\xe5\xf0\xfc\xf2\xe5 \xf2\xee\xea\xe5\xed, Chat ID \xe8 \xed\xe0\xe6\xec\xe8\xf2\xe5 Start \xf3 \xe1\xee\xf2\xe0" end
    if code == 401 or code == 404 then return u8"\xcd\xe5\xe2\xe5\xf0\xed\xfb\xe9 \xf2\xee\xea\xe5\xed \xe1\xee\xf2\xe0" end
    if code == 400 then return u8"\xcd\xe5\xe2\xe5\xf0\xed\xfb\xe9 Chat ID, \xeb\xe8\xe1\xee \xe1\xee\xf2 \xed\xe5 \xec\xee\xe6\xe5\xf2 \xef\xe8\xf1\xe0\xf2\xfc \xe2 \xfd\xf2\xee\xf2 \xf7\xe0\xf2 (\xed\xe0\xe6\xec\xe8\xf2\xe5 Start \xf3 \xe1\xee\xf2\xe0)" end
    if code == 403 then return u8"\xc1\xee\xf2 \xe7\xe0\xe1\xeb\xee\xea\xe8\xf0\xee\xe2\xe0\xed \xe8\xeb\xe8 \xed\xe5 \xe4\xee\xe1\xe0\xe2\xeb\xe5\xed \xe2 \xf7\xe0\xf2" end
    if code == 429 then return u8"\xd1\xeb\xe8\xf8\xea\xee\xec \xf7\xe0\xf1\xf2\xee, \xef\xee\xe2\xf2\xee\xf0\xe8\xf2\xe5 \xef\xee\xe7\xe6\xe5" end
    return u8"\xce\xf8\xe8\xe1\xea\xe0: " .. tostring(info)
end

function PCS_TG.urlenc(s)
    return (tostring(s):gsub("[^%w%-_%.~]", function(c) return string.format("%%%02X", c:byte()) end))
end

function PCS_TG.cutUtf8(t, n)
    if #t <= n then return t end
    t = t:sub(1, n)
    -- не режем многобайтовый символ посередине
    local i = #t
    while i > 0 do
        local c = t:byte(i)
        if c < 0x80 then break end
        if c >= 0xC0 then t = t:sub(1, i - 1); break end
        i = i - 1
    end
    return t
end

-- текст в валидный UTF-8: одиночные байты CP1251 (ник, данные игры) -> кириллица
function PCS_TG.utf8clean(s)
    s = tostring(s or "")
    local out, i, n = {}, 1, #s
    while i <= n do
        local c = s:byte(i)
        local len = (c < 0x80 and 1) or (c >= 0xC2 and c < 0xE0 and 2) or (c >= 0xE0 and c < 0xF0 and 3)
            or (c >= 0xF0 and c < 0xF5 and 4) or 0
        local ok = len > 0 and i + len - 1 <= n
        if ok then
            for k = 1, len - 1 do
                local b = s:byte(i + k)
                if b < 0x80 or b > 0xBF then ok = false; break end
            end
        end
        if ok then
            out[#out + 1] = s:sub(i, i + len - 1); i = i + len
        else
            local cp
            if c >= 0xC0 then cp = 0x410 + (c - 0xC0) elseif c == 0xA8 then cp = 0x401 elseif c == 0xB8 then cp = 0x451 end
            if cp then out[#out + 1] = string.char(0xC0 + math.floor(cp / 64), 0x80 + cp % 64) else out[#out + 1] = "?" end
            i = i + 1
        end
    end
    return table.concat(out)
end

-- Chat ID: "123456789" (личка с ботом), "-1001234567890" (группа/супергруппа),
-- "@channel" (канал), "-1001234567890:12" (тема форума: chat:thread)
function PCS_TG.parseChat(raw)
    raw = tostring(raw or ""):gsub("%s+", "")
    local chat, thread = raw:match("^(.-):(%d+)$")
    if not chat or chat == "" then chat, thread = raw, nil end
    return chat, thread
end

-- один запрос к Bot API через нативный загрузчик; возвращает тело (или nil) и done
function PCS_TG.call(method, query)
    local token = (tostring(cfg.tgToken or ""):gsub("%s+", ""))
    if type(downloadUrlToFile) ~= "function" then return nil, false end
    local url = "https://api.telegram.org/bot" .. token .. "/" .. method .. (query and ("?" .. query) or "")
    PCS_TG._seq = (PCS_TG._seq or 0) + 1
    local okW, wd = pcall(getWorkingDirectory)
    local ddir = (okW and type(wd) == "string" and wd ~= "") and (wd .. "/config/PCStats") or CFG_DIR
    pcall(createDirectory, ddir)
    local dest = ddir .. "/tg_resp_" .. tostring(PCS_TG._seq % 4) .. ".tmp"
    pcall(os.remove, dest)
    pcall(PCS_GUARD.mark, "net: tg " .. tostring(method))
    pcall(PCS_TR, "net: tg " .. tostring(method))
    -- мьютекс загрузок (см. PCS_dlFile). "nofile" = загрузка завершилась без
    -- файла (4xx) -> запрос считается завершённым
    local okF, why = PCS_dlFile(url, dest, 15, 15)
    local done = (okF == true) or (why == "nofile")
    local body
    local f = io.open(dest, "rb")
    if f then body = f:read("*a"); f:close() end
    pcall(os.remove, dest)
    return body, done
end

function PCS_TG.diagnose()
    local body = PCS_TG.call("getMe")
    if not body or not body:find('"ok"%s*:%s*true') then return "diag_bad_token" end
    PCS_TG._botName = body:match('"username"%s*:%s*"([^"]*)"')
    local chat, thread = PCS_TG.parseChat(cfg.tgChatId)
    local cands = { chat }
    if chat:match("^%d+$") then cands[#cands + 1] = "-" .. chat; cands[#cands + 1] = "-100" .. chat end
    for _, c in ipairs(cands) do
        local b = PCS_TG.call("getChat", "chat_id=" .. PCS_TG.urlenc(c))
        if b and b:find('"ok"%s*:%s*true') then
            local typ = b:match('"type"%s*:%s*"(%w+)"')
            if c ~= chat then
                cfg.tgChatId = c .. (thread and (":" .. thread) or "")
                pcall(function()
                    local T = St._tg
                    if T and T.chat then ffi.fill(T.chat, 64); ffi.copy(T.chat, cfg.tgChatId:sub(1, 60)) end
                end)
                pcall(saveCfg)
                return "fixed", c
            end
            if typ == "private" then return "diag_private" end
            return "diag_norights"
        end
    end
    return "diag_bad_chat"
end

function PCS_TG.post(text, _retry)
    local chat, thread = PCS_TG.parseChat(cfg.tgChatId)
    local txt = PCS_TG.utf8clean(text)
    -- URL ограничен ~2000 символов: режем текст так, чтобы закодированный влез
    while #PCS_TG.urlenc(txt) > 1500 and #txt > 10 do
        txt = PCS_TG.cutUtf8(txt, math.floor(#txt * 0.8))
    end
    local q = "chat_id=" .. PCS_TG.urlenc(chat) .. "&disable_web_page_preview=true"
        .. (thread and ("&message_thread_id=" .. thread) or "")
        .. "&text=" .. PCS_TG.urlenc(txt)
    local body, done = PCS_TG.call("sendMessage", q)
    if type(downloadUrlToFile) ~= "function" then return false, "no_downloader" end
    if body and body:find('"ok"%s*:%s*true') then return true, "http 200", 200 end
    local code = body and tonumber(body:match('"error_code"%s*:%s*(%d+)'))
    if not done then return false, "timeout" end
    local d = PCS_TG.diagnose()
    if d == "fixed" and not _retry then return PCS_TG.post(text, true) end
    if d == "diag_norights" then
        -- токен и чат верны: проверим, не текст ли виноват (простое ASCII-сообщение)
        local b2 = PCS_TG.call("sendMessage", "chat_id=" .. PCS_TG.urlenc(chat)
            .. (thread and ("&message_thread_id=" .. thread) or "") .. "&text=PC%20Stats")
        if b2 and b2:find('"ok"%s*:%s*true') then return false, "diag_text" end
    end
    if d == "fixed" then d = "diag_text" end
    return false, d, code
end

-- ник для Telegram: только Nick_Name, без номера аккаунта ([123], (123), #123, №123)
function PCS_TG.nick()
    local n = ""
    pcall(function() n = tostring(PCS_getNick() or "") end)
    n = n:gsub("%[.-%]", " "):gsub("%(.-%)", " "):gsub("#%s*%d+", " "):gsub("\226\132\150%s*%d+", " ")
    n = n:gsub("^%s+", "")
    local tok = n:match("^([%w_%.%-]+)")
    return tok or ""
end

-- text — UTF-8. force=true — для кнопки "Тест" (игнорирует тумблер)
function PCS_TG.send(text, force)
    text = tostring(text or "")
    if text == "" then return false end
    if not force and not PCS_TG.ready() then return false end
    local now = os.clock()
    if not force and PCS_TG._lastText == text and now - (PCS_TG._lastT or 0) < 5 then return false end
    PCS_TG._lastText, PCS_TG._lastT = text, now

    local nick = PCS_TG.nick()
    local stk = tostring(cfg.tgCharSticker or "")
    local msg = (stk ~= "" and (stk .. " ") or "") .. "[PC Stats]" .. (nick ~= "" and (" " .. nick) or "") .. "\n" .. text

    PCS_TG.q = PCS_TG.q or {}
    if #PCS_TG.q >= 8 then table.remove(PCS_TG.q, 1) end
    PCS_TG.q[#PCS_TG.q + 1] = msg
    if PCS_TG._worker and os.clock() - (PCS_TG._workerAt or 0) < 90 then return true end
    PCS_TG._worker = true
    PCS_TG._workerAt = os.clock()
    lua_thread.create(function()
        while #PCS_TG.q > 0 do
            local tw = os.clock()
            while os.clock() - tw < 60 do
                local okq, quiet = pcall(function()
                    if _phoneOpBusy or St._closePhoneRunning or St._taxDeferredPending then return false end
                    if _sessionStartTime and (os.time() - _sessionStartTime) < 45 then return false end -- no network right after join
                    if St._postPayUntil and os.clock() < St._postPayUntil then return false end
                    if _taxState and _taxState ~= 0 then return false end
                    local g = AIS and AIS.st
                    if g and (g.SpawnProcessing or g.OffProcessing or g.AddVerifi or g.scanBusy
                        or g.checkAllPet or g.checkinv or g.checksecurityinv or g.CheckAutoSpawn
                        or g.FreezePlayer or g.sppet1 or g.sppet2 or g.offpet1 or g.offpet2
                        or g.eatpet1 or g.eatpet2) then return false end
                    PCS_TG._guardQuietAt = PCS_TG._guardQuietAt or 0
                    local ta = St and St._taxFinalizedAt
                    if ta and (os.time() - ta) < 8 then return false end
                    if PCS_AIS_lastBusy and (os.clock() - PCS_AIS_lastBusy) < 6 then return false end
                    return true
                end)
                if not okq or quiet then break end
                PCS_TG._workerAt = os.clock()
                wait(500)
            end
            local m = table.remove(PCS_TG.q, 1)
            local pok, ok, info, code = pcall(PCS_TG.post, m)
            if not pok then info = tostring(ok); ok = false; code = nil end
            PCS_TG._workerAt = os.clock()
            if ok then
                PCS_TG.status, PCS_TG.statusOk = "ok", true
            else
                PCS_TG.status, PCS_TG.statusOk = PCS_TG.explain(info, code), false
                print("[PC Stats][tg] send failed: " .. tostring(info))
                PCS_TG.q = {}
            end
            wait(300)
        end
        PCS_TG._worker = false
    end)
    return true
end

-- тосты скрипта -> Telegram (по типу и тумблерам)
function PCS_TG.onToast(text, ntype)
    if not PCS_TG.ready() then return end
    if PCS_TG._remBusy then return end
    -- одно сообщение на событие: повторы того же типа за 20 сек (второй тост
    -- той же функции) в Telegram не отправляются
    PCS_TG._lastByType = PCS_TG._lastByType or {}
    local nowT = os.clock()
    if nowT - (PCS_TG._lastByType[tostring(ntype)] or -100) < 20 then return end
    local icon
    if ntype == "payday" then
        if cfg.tgOnPayday == false then return end
        icon = "\240\159\146\176 "
    elseif ntype == "success" then
        if cfg.tgOnTax == false then return end
        icon = "\226\156\133 "
    elseif ntype == "warning" then
        if cfg.tgOnError == false then return end
        icon = "\226\154\160 "
    elseif ntype == "error" then
        if cfg.tgOnError == false then return end
        icon = "\226\157\140 "
    else
        return
    end
    PCS_TG._lastByType[tostring(ntype)] = nowT
    PCS_TG.send(icon .. tostring(text))
end

function PCS_TG.onUpdate(ver)
    if cfg.tgOnUpdate == false or not PCS_TG.ready() then return end
    if PCS_TG._updVer == tostring(ver) then return end
    PCS_TG._updVer = tostring(ver)
    PCS_TG.send("\240\159\148\132 " .. u8"\xc4\xee\xf1\xf2\xf3\xef\xed\xee \xee\xe1\xed\xee\xe2\xeb\xe5\xed\xe8\xe5 PC Stats v" .. tostring(ver))
end

-- напоминания из вкладки "Напоминания" -> Telegram
function PCS_TG.onReminder(text)
    if cfg.tgOnMention == false or not PCS_TG.ready() then return end
    PCS_TG.send("\226\143\176 " .. tostring(text))
end

-- подмена pcs_notify: тосты дублируются в Telegram
if not PCS_TG._hooked and type(pcs_notify) == "function" then
    PCS_TG._hooked = true
    PCS_TG._origNotify = pcs_notify
    pcs_notify = function(text, ntype, duration)
        if not PCS_TOAST_FROM_CHAT then pcall(PCS_TG.onToast, text, ntype) end
        return PCS_TG._origNotify(text, ntype, duration)
    end
end

PCS_TG_STICKERS = {
    { "robot", "\240\159\164\150" }, { "money", "\240\159\146\176" }, { "bell", "\240\159\148\148" }, { "star", "\226\173\144" },
    { "check", "\226\156\133" }, { "mega", "\240\159\147\162" }, { "plane", "\240\159\154\128" }, { "warn", "\226\154\160\239\184\143" },
}

-- «пилюля»-кнопка со стикером слева; возвращает true при клике
function PCS_tgPill(id, text, kind, c, w, h)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local lh = imgui.GetTextLineHeight()
    local ts = imgui.CalcTextSize(text)
    h = h or (lh + S(12))
    w = w or (ts.x + h + S(14))
    local p = imgui.GetCursorScreenPos()
    imgui.InvisibleButton("##pill" .. id, V2(w, h))
    local hov, clicked = imgui.IsItemHovered(), imgui.IsItemClicked()
    local k = hov and 0.36 or 0.22
    local q = V2(p.x + w, p.y + h)
    dl:AddRectFilled(p, q, U32(iv4(c[1] * k, c[2] * k, c[3] * k, 1.0)), h * 0.5)
    dl:AddRect(p, q, U32(iv4(c[1], c[2], c[3], hov and 1.0 or 0.70)), h * 0.5, 0, 1.3)
    if kind then
        local ang, dy, sc = PCS_stickerAnim(hov, 0.3 + #id * 0.13)
        PCS_drawSticker(dl, kind, p.x + h * 0.5 + S(2), p.y + h * 0.5 + dy * 0.6, S(6.2) * sc, ang)
    end
    dl:AddText(V2(p.x + h + S(2), p.y + (h - ts.y) * 0.5), U32(iv4(1, 1, 1, 1)), text)
    return clicked
end

-- ширина чипа-копирования (учитывает надпись «Скопировано!»)
function PCS_tgChipW(text)
    local lh = imgui.GetTextLineHeight()
    local w = math.max(imgui.CalcTextSize(text).x, imgui.CalcTextSize(u8"\xd1\xea\xee\xef\xe8\xf0\xee\xe2\xe0\xed\xee!").x)
    return w + (lh + S(12)) + S(14)
end

-- чип: клик копирует text в буфер обмена
function PCS_tgChip(id, text)
    local T = St._tg
    local r, g, b = getAcc()
    local done = T.copied and T.copied.id == id and (os.clock() - T.copied.t) < 1.6
    local clicked = PCS_tgPill("chip" .. id, done and u8"\xd1\xea\xee\xef\xe8\xf0\xee\xe2\xe0\xed\xee!" or text,
        done and "check" or "copy", done and { 0.30, 0.85, 0.50 } or { r, g, b }, PCS_tgChipW(text))
    if clicked then
        pcall(imgui.SetClipboardText, text)
        T.copied = { id = id, t = os.clock() }
    end
end

-- кнопка «Открыть» ссылку в браузере/Telegram
function PCS_tgOpenW(label)
    return imgui.CalcTextSize(label).x + (imgui.GetTextLineHeight() + S(12)) + S(14)
end
function PCS_tgOpen(id, url, label)
    if PCS_tgPill("open" .. id, label, "link", { 0.35, 0.60, 0.90 }, PCS_tgOpenW(label)) then
        local okO, res = pcall(winOpenUrl, url)
        if not (okO and res) then pcall(imgui.SetClipboardText, url) end
    end
end

-- ряд чипов/кнопок с переносом по ширине maxW
function PCS_tgItemsRow(items, maxW)
    local gap = S(6)
    local used = 0
    for i, it in ipairs(items) do
        local w = (it[1] == "chip") and PCS_tgChipW(it[3]) or PCS_tgOpenW(it[4])
        if i > 1 then
            if used + gap + w <= maxW then
                imgui.SameLine(0, gap); used = used + gap
            else
                used = 0
            end
        end
        if it[1] == "chip" then PCS_tgChip(it[2], it[3]) else PCS_tgOpen(it[2], it[3], it[4]) end
        used = used + w
    end
end

-- шаг инструкции: стикер с номером, заголовок, описание, чипы
function PCS_tgStep(num, kind, title, desc, items)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local r, g, b = getAcc()
    local dl = imgui.GetWindowDrawList()
    local aw = PCS_cardW()
    local p = imgui.GetCursorScreenPos()
    local stk = S(46)
    local tw = math.max(S(60), aw - stk)
    local th = PCS_textH(title, tw)
    local dh = PCS_textH(desc, tw)
    local hgt = math.max(th + S(2) + dh, S(38))
    imgui.Dummy(V2(aw, hgt))
    local hov = imgui.IsItemHovered()
    local ang, dy, sc = PCS_stickerAnim(hov, num * 0.8)
    PCS_drawSticker(dl, kind, p.x + S(17), p.y + S(20) + dy, S(8.5) * sc, ang)
    dl:AddCircleFilled(V2(p.x + S(32), p.y + S(8)), S(7.5), U32(iv4(r, g, b, 1.0)), 16)
    local ns = tostring(num)
    local nsz = imgui.CalcTextSize(ns)
    dl:AddText(V2(p.x + S(32) - nsz.x * 0.5, p.y + S(8) - nsz.y * 0.5), U32(iv4(0, 0, 0, 1)), ns)
    PCS_textAt(p.x + stk, p.y, tw, iv4(1.0, 0.95, 0.70, 1.0), title)
    PCS_textAt(p.x + stk, p.y + th + S(2), tw, thDim(), desc)
    imgui.SetCursorScreenPos(V2(p.x, p.y + hgt + S(2)))
    if items and #items > 0 then
        imgui.Indent(stk)
        imgui.SetCursorScreenPos(V2(p.x + stk, p.y + hgt + S(4)))
        PCS_tgItemsRow(items, tw)
        imgui.Unindent(stk)
    end
    imgui.Dummy(V2(1, S(10)))
end

-- поле ввода со стикером слева (как PCS_input, но с флагами и шириной)
function PCS_tgField(id, buf, size, hint, kind, w, h, flags)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local r, g, b = getAcc()
    local padX = S(40)
    local changed = false
    local padY = math.max(S(6), ((h or (imgui.GetTextLineHeight() + S(16))) - imgui.GetTextLineHeight()) * 0.5)
    PCS_pushInput(padY, padX)
    local ok, err = pcall(function()
        imgui.PushItemWidth(w or -1)
        changed = imgui.InputText(id, buf, size, flags or 0)
        imgui.PopItemWidth()
    end)
    PCS_popInput()
    if not ok then print("[PC Stats][tg] input: " .. tostring(err)); return false, S(34) end
    local dl = imgui.GetWindowDrawList()
    local mn, mx = imgui.GetItemRectMin(), imgui.GetItemRectMax()
    local fh = mx.y - mn.y
    local act, hov = imgui.IsItemActive(), imgui.IsItemHovered()
    if act then
        dl:AddRect(V2(mn.x - 1, mn.y - 1), V2(mx.x + 1, mx.y + 1), U32(iv4(r, g, b, 0.95)), S(9), 0, 2.0)
    end
    local ang, dy, sc = PCS_stickerAnim(hov or act, 0.7)
    PCS_drawSticker(dl, kind or "text", mn.x + S(21), mn.y + fh * 0.5 + dy, S(9.5) * sc, ang)
    if buf[0] == 0 and hint then
        local lh = imgui.GetTextLineHeight()
        dl:AddText(V2(mn.x + padX, mn.y + (fh - lh) * 0.5), U32(iv4(0.55, 0.58, 0.66, 0.85)), hint)
    end
    return changed, fh
end

-- скрытое поле токена: рисуется примитивами, без InputText/Password
function PCS_tgMaskedField(w, h, hint)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local r, g, b = getAcc()
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    imgui.Dummy(V2(w, h))
    local q = V2(p.x + w, p.y + h)
    dl:AddRectFilled(p, q, U32(iv4(r * 0.12 + 0.02, g * 0.12 + 0.02, b * 0.12 + 0.03, 1.0)), S(9))
    dl:AddRect(p, q, U32(iv4(r * 0.85, g * 0.85, b * 0.85, 0.75)), S(9), 0, 1.3)
    PCS_drawSticker(dl, "key", p.x + S(21), p.y + h * 0.5, S(9.5), -0.2)
    local tok = tostring(cfg.tgToken or "")
    local lh = imgui.GetTextLineHeight()
    local txt, col
    if tok == "" then
        txt, col = hint or "", U32(iv4(0.55, 0.58, 0.66, 0.85))
    else
        txt, col = string.rep("*", math.min(#tok, 28)), U32(iv4(1, 1, 1, 1))
    end
    dl:AddText(V2(p.x + S(40), p.y + (h - lh) * 0.5), col, txt)
end

-- маленькая заметка со стикером (внутри карточки)
function PCS_tgNote(kind, text, c)
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local aw = PCS_cardW()
    local p = imgui.GetCursorScreenPos()
    local tw = math.max(S(60), aw - S(40))
    local th = PCS_textH(text, tw)
    local h = math.max(S(36), th + S(16))
    imgui.Dummy(V2(aw, h))
    local q = V2(p.x + aw, p.y + h)
    dl:AddRectFilled(p, q, U32(iv4(c[1] * 0.16, c[2] * 0.16, c[3] * 0.16, 1.0)), S(9))
    dl:AddRect(p, q, U32(iv4(c[1], c[2], c[3], 0.55)), S(9), 0, 1.0)
    local ang, dy, sc = PCS_stickerAnim(false, 1.3)
    PCS_drawSticker(dl, kind, p.x + S(20), p.y + h * 0.5 + dy, S(8) * sc, ang)
    PCS_textAt(p.x + S(38), p.y + (h - th) * 0.5, tw, iv4(0.92, 0.92, 0.95, 1.0), text)
    imgui.SetCursorScreenPos(V2(p.x, p.y + h))
    imgui.Dummy(V2(1, S(4)))
end

-- выбор стикера-смайлика: плитки с векторными стикерами
function PCS_tgStickerPicker()
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local r, g, b = getAcc()
    local T = St._tg
    local dl = imgui.GetWindowDrawList()
    local W = PCS_cardW()
    local n = #PCS_TG_STICKERS
    local gap = S(6)
    local per = math.max(2, math.min(n, math.floor((W + gap) / (S(46) + gap))))
    local cell = math.min(S(56), math.floor((W - gap * (per - 1)) / per))
    local cur = tostring(cfg.tgCharSticker or "")
    for i, st in ipairs(PCS_TG_STICKERS) do
        if (i - 1) % per ~= 0 then imgui.SameLine(0, gap) end
        local p = imgui.GetCursorScreenPos()
        imgui.InvisibleButton("##tgstk" .. i, V2(cell, cell))
        local hov, clk = imgui.IsItemHovered(), imgui.IsItemClicked()
        local sel = (cur == st[2])
        local c = PCS_STICKER_COL[st[1]] or { r, g, b }
        local q = V2(p.x + cell, p.y + cell)
        local k = sel and 0.30 or (hov and 0.22 or 0.12)
        dl:AddRectFilled(p, q, U32(iv4(c[1] * k, c[2] * k, c[3] * k, 1.0)), S(10))
        dl:AddRect(p, q, U32(iv4(c[1], c[2], c[3], sel and 1.0 or (hov and 0.7 or 0.35))), S(10), 0, sel and 2.0 or 1.0)
        local ang, dy, sc = PCS_stickerAnim(hov or sel, i * 0.6)
        PCS_drawSticker(dl, st[1], p.x + cell * 0.5, p.y + cell * 0.5 + dy, cell * 0.26 * sc, ang)
        if sel then
            dl:AddCircleFilled(V2(q.x - S(8), p.y + S(8)), S(6), U32(iv4(0.25, 0.88, 0.48, 1.0)), 14)
            dl:AddLine(V2(q.x - S(11), p.y + S(8)), V2(q.x - S(9), p.y + S(10.5)), U32(iv4(0, 0, 0, 1)), 1.8)
            dl:AddLine(V2(q.x - S(9), p.y + S(10.5)), V2(q.x - S(5), p.y + S(5.5)), U32(iv4(0, 0, 0, 1)), 1.8)
        end
        if clk then
            cfg.tgCharSticker = st[2]
            ffi.copy(T.charSticker, st[2])
            saveCfg()
        end
    end
end

-- превью сообщения в стиле Telegram-пузыря
function PCS_tgPreview()
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local dl = imgui.GetWindowDrawList()
    local lh = imgui.GetTextLineHeight()
    local W = PCS_cardW()
    local h = lh * 2 + S(24)
    local p = imgui.GetCursorScreenPos()
    imgui.Dummy(V2(W, h))
    local q = V2(p.x + W, p.y + h)
    dl:AddRectFilled(p, q, U32(iv4(0.10, 0.16, 0.24, 1.0)), S(12))
    dl:AddRect(p, q, U32(iv4(0.30, 0.65, 0.95, 0.55)), S(12), 0, 1.0)
    local cur, kind = tostring(cfg.tgCharSticker or ""), nil
    for _, s in ipairs(PCS_TG_STICKERS) do if s[2] == cur then kind = s[1] end end
    local ang, dy, sc = PCS_stickerAnim(false, 0.5)
    if kind then
        PCS_drawSticker(dl, kind, p.x + S(24), p.y + h * 0.5 + dy, S(9.5) * sc, ang)
    else
        PCS_drawSticker(dl, "star", p.x + S(24), p.y + h * 0.5 + dy, S(9.5) * sc, ang)
    end
    local nick = PCS_TG.nick()
    if nick == "" then nick = "Nick_Name" end
    dl:AddText(V2(p.x + S(46), p.y + S(9)), U32(iv4(0.50, 0.78, 1.0, 1.0)), "[PC Stats] " .. nick)
    dl:AddText(V2(p.x + S(46), p.y + S(9) + lh + S(3)), U32(iv4(1, 1, 1, 1)), u8"\xce\xef\xeb\xe0\xf2\xe0 \xed\xe0\xeb\xee\xe3\xee\xe2 \xe2\xfb\xef\xee\xeb\xed\xe5\xed\xe0")
end

function PCS_drawTelegramSettings()
    pcall(PCS_GUARD.mark, "tg-tab: begin")
    St._tg = St._tg or {}
    local T = St._tg
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    if not T.tok then
        T.tok = imgui.new("char[160]")
        T.chat = imgui.new("char[64]")
        T.charSticker = imgui.new("char[32]")
        ffi.copy(T.tok, tostring(cfg.tgToken or ""):sub(1, 150))
        ffi.copy(T.chat, tostring(cfg.tgChatId or ""):sub(1, 60))
        ffi.copy(T.charSticker, tostring(cfg.tgCharSticker or "\240\159\164\150"):sub(1, 30))
        T.instrOpen = not PCS_TG.ready()
    end
    if T.dirty and os.clock() - T.dirty > 1.5 then
        T.dirty = nil
        pcall(saveCfg)
    end
    local TG = { 0.30, 0.65, 0.95 }
    local dl = imgui.GetWindowDrawList()
    local lh = imgui.GetTextLineHeight()

    -- ── шапка со статусом подключения ──
    do
        local aw = imgui.GetContentRegionAvail().x
        local p = imgui.GetCursorScreenPos()
        local h = math.max(S(60), lh * 2 + S(26))
        local q = V2(p.x + aw, p.y + h)
        imgui.Dummy(V2(aw, h))
        local hov = imgui.IsItemHovered()
        dl:AddRectFilled(p, q, U32(iv4(0.05, 0.12, 0.20, 0.98)), S(12))
        dl:PushClipRect(p, q, true)
        dl:AddCircleFilled(V2(q.x - S(30), p.y + h * 0.5), S(64), U32(iv4(TG[1], TG[2], TG[3], 0.12)), 48)
        dl:AddCircleFilled(V2(q.x - S(30), p.y + h * 0.5), S(38), U32(iv4(TG[1], TG[2], TG[3], 0.14)), 48)
        dl:PopClipRect()
        dl:AddRect(p, q, U32(iv4(TG[1], TG[2], TG[3], 0.80)), S(12), 0, 1.4)
        local ang, dy, sc = PCS_stickerAnim(hov, 0.1)
        PCS_drawSticker(dl, "plane", p.x + S(34), p.y + h * 0.5 + dy, S(16) * sc, ang)
        local stTxt, stCol
        if cfg.tgEnabled ~= true then
            stTxt, stCol = u8"\xc2\xfb\xea\xeb\xfe\xf7\xe5\xed\xee", { 0.62, 0.65, 0.72 }
        elseif not PCS_TG.ready() then
            stTxt, stCol = u8"\xcd\xe5 \xe7\xe0\xef\xee\xeb\xed\xe5\xed \xf2\xee\xea\xe5\xed \xe8\xeb\xe8 Chat ID", { 1.0, 0.72, 0.20 }
        elseif PCS_TG.statusOk == false and PCS_TG.status ~= "" and PCS_TG.status ~= "sending" then
            stTxt, stCol = u8"\xce\xf8\xe8\xe1\xea\xe0 \xee\xf2\xef\xf0\xe0\xe2\xea\xe8 \x97 \xf1\xec. \xed\xe8\xe6\xe5", { 1.0, 0.40, 0.40 }
        else
            stTxt, stCol = u8"\xcf\xee\xe4\xea\xeb\xfe\xf7\xe5\xed\xee, \xf1\xee\xee\xe1\xf9\xe5\xed\xe8\xff \xe1\xf3\xe4\xf3\xf2 \xef\xf0\xe8\xf5\xee\xe4\xe8\xf2\xfc", { 0.35, 0.92, 0.55 }
        end
        local tx = p.x + S(68)
        local tw = math.max(S(60), aw - S(68) - S(12))
        PCS_textAt(tx, p.y + S(11), tw, iv4(1, 1, 1, 1), u8"Telegram-\xe1\xee\xf2")
        dl:AddCircleFilled(V2(tx + S(5), p.y + S(11) + lh + S(3) + lh * 0.5), S(4.5), U32(iv4(stCol[1], stCol[2], stCol[3], 1.0)), 12)
        PCS_textAt(tx + S(16), p.y + S(11) + lh + S(3), tw - S(16), iv4(stCol[1], stCol[2], stCol[3], 1.0), stTxt)
        imgui.SetCursorScreenPos(V2(p.x, p.y + h))
        imgui.Dummy(V2(1, S(8)))
    end

    pcall(PCS_GUARD.mark, "tg-tab: header done")
    if PCS_settToggleRow("##tgEnabled", cfg.tgEnabled == true, u8"\xce\xf2\xef\xf0\xe0\xe2\xeb\xff\xf2\xfc \xf1\xee\xee\xe1\xf9\xe5\xed\xe8\xff \xe2 Telegram",
            u8"\xc2\xea\xeb\xfe\xf7\xe8\xf2\xe5 \xef\xee\xf1\xeb\xe5 \xf2\xee\xe3\xee, \xea\xe0\xea \xe2\xf1\xf2\xe0\xe2\xe8\xf2\xe5 \xf2\xee\xea\xe5\xed \xe1\xee\xf2\xe0 \xe8 Chat ID.") then
        cfg.tgEnabled = not (cfg.tgEnabled == true)
        saveCfg()
    end

    -- ── инструкция (сворачиваемая) ──
    PCS_settSub(u8"\xca\xe0\xea \xef\xee\xe4\xea\xeb\xfe\xf7\xe8\xf2\xfc", u8"\xcf\xee\xf8\xe0\xe3\xee\xe2\xe0\xff \xe8\xed\xf1\xf2\xf0\xf3\xea\xf6\xe8\xff. \xcd\xe8\xea\xe8 \xe1\xee\xf2\xee\xe2 \xe8 \xea\xee\xec\xe0\xed\xe4\xfb \xea\xee\xef\xe8\xf0\xf3\xfe\xf2\xf1\xff \xed\xe0\xe6\xe0\xf2\xe8\xe5\xec.", "info")
    do
        local aw = imgui.GetContentRegionAvail().x
        local p = imgui.GetCursorScreenPos()
        local h = S(36)
        imgui.InvisibleButton("##tgInstrHdr", V2(aw, h))
        local hov, clk = imgui.IsItemHovered(), imgui.IsItemClicked()
        if clk then T.instrOpen = not T.instrOpen end
        local q = V2(p.x + aw, p.y + h)
        local k = hov and 0.30 or 0.20
        dl:AddRectFilled(p, q, U32(iv4(TG[1] * k, TG[2] * k, TG[3] * k, 1.0)), S(10))
        dl:AddRect(p, q, U32(iv4(TG[1], TG[2], TG[3], hov and 1.0 or 0.75)), S(10), 0, 1.3)
        local ang, dy, sc = PCS_stickerAnim(hov, 0.9)
        PCS_drawSticker(dl, "list", p.x + S(22), p.y + h * 0.5 + dy, S(8.5) * sc, ang)
        local label = T.instrOpen and u8"\xd1\xea\xf0\xfb\xf2\xfc \xe8\xed\xf1\xf2\xf0\xf3\xea\xf6\xe8\xfe" or u8"\xcf\xee\xea\xe0\xe7\xe0\xf2\xfc \xe8\xed\xf1\xf2\xf0\xf3\xea\xf6\xe8\xfe (6 \xf8\xe0\xe3\xee\xe2)"
        local ts = imgui.CalcTextSize(label)
        dl:AddText(V2(p.x + S(42), p.y + (h - ts.y) * 0.5), U32(iv4(1, 1, 1, 1)), label)
        local ax, ay = q.x - S(22), p.y + h * 0.5
        local ac = U32(iv4(1, 1, 1, 0.95))
        if T.instrOpen then
            dl:AddTriangleFilled(V2(ax - S(6), ay - S(3)), V2(ax + S(6), ay - S(3)), V2(ax, ay + S(4)), ac)
        else
            dl:AddTriangleFilled(V2(ax - S(3), ay - S(6)), V2(ax - S(3), ay + S(6)), V2(ax + S(4), ay), ac)
        end
    end
    imgui.Dummy(V2(1, S(6)))
    if T.instrOpen then
        PCS_card(TG, function()
            PCS_tgStep(1, "plane", u8"\xce\xf2\xea\xf0\xee\xe9\xf2\xe5 @BotFather",
                u8"\xdd\xf2\xee \xee\xf4\xe8\xf6\xe8\xe0\xeb\xfc\xed\xfb\xe9 \xe1\xee\xf2 Telegram \xe4\xeb\xff \xf1\xee\xe7\xe4\xe0\xed\xe8\xff \xe1\xee\xf2\xee\xe2. \xd1\xea\xee\xef\xe8\xf0\xf3\xe9\xf2\xe5 \xed\xe8\xea, \xed\xe0\xe9\xe4\xe8\xf2\xe5 \xe5\xe3\xee \xe2 \xef\xee\xe8\xf1\xea\xe5 Telegram \xe8 \xee\xf2\xef\xf0\xe0\xe2\xfc\xf2\xe5 \xe5\xec\xf3 \xea\xee\xec\xe0\xed\xe4\xf3 /newbot.",
                { { "chip", "bf", "@BotFather" }, { "chip", "newbot", "/newbot" },
                  { "open", "bf", "https://t.me/BotFather", u8"\xce\xf2\xea\xf0\xfb\xf2\xfc" } })
            PCS_tgStep(2, "tag", u8"\xcf\xf0\xe8\xe4\xf3\xec\xe0\xe9\xf2\xe5 \xe8\xec\xff \xe8 username",
                u8"\xc8\xec\xff \xe1\xee\xf2\xe0 \x97 \xeb\xfe\xe1\xee\xe5. Username \xe4\xee\xeb\xe6\xe5\xed \xe7\xe0\xea\xe0\xed\xf7\xe8\xe2\xe0\xf2\xfc\xf1\xff \xed\xe0 bot, \xed\xe0\xef\xf0\xe8\xec\xe5\xf0 PCStats_ivan_bot.", nil)
            PCS_tgStep(3, "key", u8"\xd1\xea\xee\xef\xe8\xf0\xf3\xe9\xf2\xe5 \xf2\xee\xea\xe5\xed \xe1\xee\xf2\xe0",
                u8"BotFather \xef\xf0\xe8\xf8\xeb\xb8\xf2 \xf2\xee\xea\xe5\xed \xe2\xe8\xe4\xe0 123456789:AAH... \xcd\xe0\xe6\xec\xe8\xf2\xe5 \xed\xe0 \xed\xe5\xe3\xee \xe2 \xf7\xe0\xf2\xe5 Telegram, \xf7\xf2\xee\xe1\xfb \xf1\xea\xee\xef\xe8\xf0\xee\xe2\xe0\xf2\xfc, \xe8 \xe2\xf1\xf2\xe0\xe2\xfc\xf2\xe5 \xe2 \xef\xee\xeb\xe5 \xab\xd2\xee\xea\xe5\xed \xe1\xee\xf2\xe0\xbb \xed\xe8\xe6\xe5.", nil)
            PCS_tgStep(4, "check", u8"\xcd\xe0\xe6\xec\xe8\xf2\xe5 Start \xf3 \xf1\xe2\xee\xe5\xe3\xee \xe1\xee\xf2\xe0",
                u8"\xce\xf2\xea\xf0\xee\xe9\xf2\xe5 \xf1\xee\xe7\xe4\xe0\xed\xed\xee\xe3\xee \xe1\xee\xf2\xe0 \xef\xee \xf1\xf1\xfb\xeb\xea\xe5 \xee\xf2 BotFather \xe8 \xed\xe0\xe6\xec\xe8\xf2\xe5 Start (\xe8\xeb\xe8 \xee\xf2\xef\xf0\xe0\xe2\xfc\xf2\xe5 /start). \xc1\xe5\xe7 \xfd\xf2\xee\xe3\xee \xe1\xee\xf2 \xed\xe5 \xf1\xec\xee\xe6\xe5\xf2 \xe2\xe0\xec \xef\xe8\xf1\xe0\xf2\xfc.",
                { { "chip", "start", "/start" } })
            PCS_tgStep(5, "id", u8"\xd3\xe7\xed\xe0\xe9\xf2\xe5 \xf1\xe2\xee\xe9 Chat ID",
                u8"\xce\xf2\xea\xf0\xee\xe9\xf2\xe5 @userinfobot \xe8 \xed\xe0\xe6\xec\xe8\xf2\xe5 Start \x97 \xee\xed \xef\xf0\xe8\xf8\xeb\xb8\xf2 \xe2\xe0\xf8 Id (\xf7\xe8\xf1\xeb\xee). \xdd\xf2\xee \xe8 \xe5\xf1\xf2\xfc Chat ID. \xc4\xeb\xff \xe3\xf0\xf3\xef\xef\xfb: \xe4\xee\xe1\xe0\xe2\xfc\xf2\xe5 \xe2 \xed\xe5\xb8 \xe1\xee\xf2\xe0 @getmyid_bot \x97 \xee\xed \xef\xee\xea\xe0\xe6\xe5\xf2 ID \xe3\xf0\xf3\xef\xef\xfb (\xed\xe0\xf7\xe8\xed\xe0\xe5\xf2\xf1\xff \xf1 -100).",
                { { "chip", "uib", "@userinfobot" }, { "chip", "gmi", "@getmyid_bot" },
                  { "open", "uib", "https://t.me/userinfobot", u8"\xce\xf2\xea\xf0\xfb\xf2\xfc" } })
            PCS_tgStep(6, "paste", u8"\xc2\xf1\xf2\xe0\xe2\xfc\xf2\xe5 \xe4\xe0\xed\xed\xfb\xe5 \xe8 \xef\xf0\xee\xe2\xe5\xf0\xfc\xf2\xe5",
                u8"\xc2\xf1\xf2\xe0\xe2\xfc\xf2\xe5 \xf2\xee\xea\xe5\xed \xe8 Chat ID \xe2 \xef\xee\xeb\xff \xed\xe8\xe6\xe5 \xe8 \xed\xe0\xe6\xec\xe8\xf2\xe5 \xab\xce\xf2\xef\xf0\xe0\xe2\xe8\xf2\xfc \xf2\xe5\xf1\xf2\xbb \x97 \xe2 Telegram \xef\xf0\xe8\xe4\xb8\xf2 \xf1\xee\xee\xe1\xf9\xe5\xed\xe8\xe5.", nil)
            PCS_tgNote("warn", u8"\xcd\xe8\xea\xee\xec\xf3 \xed\xe5 \xef\xee\xea\xe0\xe7\xfb\xe2\xe0\xe9\xf2\xe5 \xf2\xee\xea\xe5\xed \xe1\xee\xf2\xe0: \xf1 \xed\xe8\xec \xec\xee\xe6\xed\xee \xf3\xef\xf0\xe0\xe2\xeb\xff\xf2\xfc \xe2\xe0\xf8\xe8\xec \xe1\xee\xf2\xee\xec.", { 1.0, 0.72, 0.20 })
        end)
    end

    pcall(PCS_GUARD.mark, "tg-tab: instr done")
    -- ── данные подключения ──
    PCS_settSub(u8"\xc4\xe0\xed\xed\xfb\xe5 \xef\xee\xe4\xea\xeb\xfe\xf7\xe5\xed\xe8\xff", u8"\xd2\xee\xea\xe5\xed \xe1\xee\xf2\xe0 \xe8 Chat ID \x97 \xea\xf3\xe4\xe0 \xee\xf2\xef\xf0\xe0\xe2\xeb\xff\xf2\xfc \xf1\xee\xee\xe1\xf9\xe5\xed\xe8\xff.", "key")
    PCS_card(TG, function()
        local W = PCS_cardW()
        local gap = S(6)
        local fh = lh + S(16)
        local function paste(buf, size)
            local okC, s = pcall(imgui.GetClipboardText)
            if okC and s then
                if type(s) ~= "string" then
                    local okP, addr = pcall(function() return tonumber(ffi.cast("uintptr_t", s)) end)
                    if okP and addr and addr ~= 0 then okC, s = pcall(ffi.string, s) else okC = false end
                end
                if okC and type(s) == "string" then
                    s = (s:gsub("%s+", ""))
                    ffi.fill(buf, size)
                    ffi.copy(buf, s:sub(1, size - 10))
                    return s:sub(1, size - 10)
                end
            end
        end

        imgui.TextColored(iv4(0.70, 0.82, 1.0, 1.0), u8"\xd2\xee\xea\xe5\xed \xe1\xee\xf2\xe0")
        local showTxt = T.showTok and u8"\xd1\xea\xf0\xfb\xf2\xfc" or u8"\xcf\xee\xea\xe0\xe7\xe0\xf2\xfc"
        local pasteTxt = u8"\xc2\xf1\xf2\xe0\xe2\xe8\xf2\xfc"
        local w1 = imgui.CalcTextSize(showTxt).x + fh + S(14)
        local w2 = imgui.CalcTextSize(pasteTxt).x + fh + S(14)
        local tokW = math.max(S(80), W - w1 - w2 - gap * 2)
        if T.showTok then
            local ch = PCS_tgField("##tgToken", T.tok, 160, u8"123456789:AAH...", "key", tokW, fh, 0)
            if ch then
                cfg.tgToken = (ffi.string(T.tok):gsub("%s+", ""))
                T.dirty = os.clock()
            end
        else
            PCS_tgMaskedField(tokW, fh, u8"123456789:AAH...")
        end
        imgui.SameLine(0, gap)
        if PCS_tgPill("tokshow", showTxt, "search", { 0.55, 0.60, 0.80 }, w1, fh) then T.showTok = not T.showTok end
        imgui.SameLine(0, gap)
        if PCS_tgPill("tokpaste", pasteTxt, "paste", TG, w2, fh) then
            local s = paste(T.tok, 160)
            if s then cfg.tgToken = s; T.dirty = os.clock() end
        end
        local tok = tostring(cfg.tgToken or "")
        if tok ~= "" then
            if #tok >= 30 and tok:match("^%d+:[%w_%-]+$") then
                imgui.TextColored(iv4(0.40, 1.0, 0.55, 1.0), PCS_IC.check .. "  " .. u8"\xd4\xee\xf0\xec\xe0\xf2 \xf2\xee\xea\xe5\xed\xe0 \xe2\xe5\xf0\xed\xfb\xe9")
            else
                imgui.PushTextWrapPos(imgui.GetCursorPosX() + W)
