function PCS_wrapHooks()
    local function pass(name, ok, ...)
        if ok then return ... end
        PCS_quietErr("hook " .. name, (...))
        return nil
    end
    for _, name in ipairs({ "onShowDialog", "onServerMessage", "onShowTextDraw", "onSetTextDraw", "onDisplayGameText" }) do
        local orig = sampev[name]
        if type(orig) == "function" then
            sampev[name] = function(...) return pass(name, pcall(orig, ...)) end
        end
    end
end
PCS_wrapHooks()

PCS_RC = PCS_RC or {}
;(function()
local RC = PCS_RC
local CFG_FILE = CFG_DIR .. "/connect.json"
local SRV_FILE = CFG_DIR .. "/connect_servers.json"

-- ── кодировки: UTF-8 (imgui, json) <-> CP1251 (игра, чат) ──
local function toGame(s)
    s = tostring(s or "")
    local ok, r = pcall(function() return _u8_raw:decode(s) end)
    return (ok and type(r) == "string") and r or s
end
local function toUi(s)
    s = tostring(s or "")
    local ok, r = pcall(function() return u8(s) end)
    return (ok and type(r) == "string") and r or s
end
local function isUtf8Cyr(s)
    if not s:find("[\208\209][\128-\191]") then return false end
    local i, n = 1, #s
    while i <= n do
        local b = s:byte(i)
        local len = (b < 128 and 1) or (b >= 194 and b <= 223 and 2) or (b >= 224 and b <= 239 and 3) or (b >= 240 and b <= 244 and 4) or 0
        if len == 0 or i + len - 1 > n then return false end
        for j = i + 1, i + len - 1 do
            local c = s:byte(j)
            if c < 128 or c > 191 then return false end
        end
        i = i + len
    end
    return true
end
-- игровая строка (CP1251) -> UTF-8; если уже UTF-8 — не трогаем
local function gameToUi(s)
    s = tostring(s or "")
    if isUtf8Cyr(s) then return s end
    return toUi(s)
end
local function chat(color, text)
    pcall(sampAddChatMessage, "{" .. color .. "}[Sweet Connect] {FFFFFF}" .. toGame(text), -1)
end
local function notify(text, kind, dur)
    pcall(function() if pcs_notify then pcs_notify(text, kind or "info", dur) end end)
end

-- ── конфиг (поля и значения по умолчанию — как cfg в Sweet Connect) ──
local DEF = {
    autoreconnect = true, reconnecting_window = true, notif = true,
    save_button = true, autoresponse = true, autoresponse_delay = 0,
    spawn_delay = 1500,
    sc_timeout = 16, disconnect_timeout = 16,
    lost_connection_timeout = 36, banned_ip_timeout = 320,
    use_connecting_timeout = false, connecting_timeout = 5000,
    pause = false, pause_from_hour = 4, pause_from_min = 55,
    pause_to_hour = 5, pause_to_min = 25,
    check_content = true, check_title = false, check_id = false,
    -- AutoSelectSpawn
    sp_enabled = false, priority = {}, last_spawn_dialog = {},
}
local C = {}
local servers = {}
local function copyDefaults()
    for k, v in pairs(DEF) do
        if type(v) == "table" then C[k] = {} else C[k] = v end
    end
end
copyDefaults()
local function readJson(path)
    local f = io.open(path, "rb")
    if not f then return nil end
    local body = f:read("*a"); f:close()
    if not body or body == "" then return nil end
    local ok, d = pcall(decodeJson, body)
    if ok and type(d) == "table" then return d end
    return nil
end
local function writeJson(path, data)
    pcall(function()
        local ok, js = pcall(encodeJson, data)
        if not ok or type(js) ~= "string" then return end
        local f = io.open(path, "wb")
        if not f then return end
        f:write(js); f:close()
    end)
end
function RC.load()
    copyDefaults()
    local d = readJson(CFG_FILE)
    if d then
        for k, v in pairs(DEF) do
            if type(v) == "boolean" then
                if type(d[k]) == "boolean" then C[k] = d[k] end
            elseif type(v) == "number" then
                local n = tonumber(d[k]); if n then C[k] = math.floor(n) end
            elseif type(v) == "table" then
                if type(d[k]) == "table" then
                    local arr = {}
                    for _, s in ipairs(d[k]) do if type(s) == "string" and s ~= "" then arr[#arr + 1] = s end end
                    C[k] = arr
                end
            end
        end
    end
    local sv = readJson(SRV_FILE)
    servers = {}
    if sv then
        for _, s in ipairs(sv) do
            if type(s) == "table" and s.ip and s.port and type(s.logins) == "table" then servers[#servers + 1] = s end
        end
    end
end
RC._dirty = false
function RC.save()
    RC._dirty = false
    writeJson(CFG_FILE, C)
end
local function saveServers() writeJson(SRV_FILE, servers) end
local function markDirty() RC._dirty = true; RC._dirtyAt = os.clock() end
RC.cfg = C

-- ── константы SAMPFUNCS / RakNet ──
local K = {}
local function initConsts()
    pcall(require, "sampfuncs")
    local okR, R = pcall(require, "lib.samp.raknet")
    local RPC = okR and R and R.RPC or {}
    K.PK_FAILED = PACKET_CONNECTION_ATTEMPT_FAILED or 29
    K.PK_DISC   = PACKET_DISCONNECTION_NOTIFICATION or 32
    K.PK_LOST   = PACKET_CONNECTION_LOST or 33
    K.PK_BANNED = PACKET_CONNECTION_BANNED or 36
    K.PK_PASS   = PACKET_INVALID_PASSWORD or 37
    K.RPC_INIT  = RPC_SCRINITGAME or RPC.SCRINITGAME or 139
    K.RPC_REJ   = RPC.CONNECTIONREJECTED or 130
    K.GS_DISC   = GAMESTATE_DISCONNECTED
    K.GS_WAIT   = GAMESTATE_WAIT_CONNECT
    K.GS_REST   = GAMESTATE_RESTARTING
    K.ok = (K.GS_DISC ~= nil and K.GS_WAIT ~= nil
        and type(sampSetGamestate) == "function"
        and type(sampGetGamestate) == "function"
        and type(sampDisconnectWithReason) == "function")
end

local S = {
    thread = nil,          -- sc_thread
    show = false,          -- imw_reconnecting
    text = "00:00:00",     -- reconnecting_text
    startConnecting = nil, -- start_connecting
    saving = false,        -- imw_saving
    wdFails = 0,
}
RC.S = S

local function secondsToClock(seconds)
    seconds = tonumber(seconds) or 0
    if seconds <= 0 then return "00:00:00" end
    local h = math.floor(seconds / 3600)
    local m = math.floor(seconds / 60 - h * 60)
    local s = math.floor(seconds - h * 3600 - m * 60)
    return string.format("%02d:%02d:%02d", h, m, s)
end

local function explode(div, str)
    local pos, arr = 1, {}
    while true do
        local st, sp = string.find(str, div, pos, true)
        if not st then break end
        arr[#arr + 1] = string.sub(str, pos, st - 1)
        pos = sp + 1
    end
    arr[#arr + 1] = string.sub(str, pos)
    return arr
end
local function generateCommonPattern(ip, port)
    local bit = require("bit")
    local p = explode(".", ip)
    local b1 = bit.band(port, 0xFF)
    local b2 = bit.band(bit.rshift(port, 8), 0xFF)
    return "SAMP" .. string.char(p[1]) .. string.char(p[2]) .. string.char(p[3]) .. string.char(p[4])
        .. string.char(b1) .. string.char(b2)
end
-- «пинг» сервера (как в Sweet Connect): запрос i/p/c/r по UDP
local function pingServer(ip, port)
    local socket = require("socket")
    local pat = generateCommonPattern(ip, port)
    local udp = socket.udp()
    udp:settimeout(3)
    udp:setsockname("*", 0)
    udp:sendto(pat .. "i", ip, port)
    udp:sendto(pat .. "p" .. "aaaa", ip, port)
    udp:sendto(pat .. "c", ip, port)
    udp:sendto(pat .. "r", ip, port)
    udp:close()
end

local function sampGetNickname()
    local ok, result, id = pcall(sampGetPlayerIdByCharHandle, PLAYER_PED)
    if ok and result then
        local okN, nk = pcall(sampGetPlayerNickname, id)
        if okN and nk then return nk end
    end
    return ""
end

local function getServer(ip, port)
    for _, s in ipairs(servers) do
        if s.ip == ip and s.port == port then return s end
    end
end
local function getTimeout(field)
    local ok, ip, port = pcall(sampGetCurrentServerAddress)
    local server = ok and getServer(ip, port) or nil
    if server and server.use_timeouts and server[field] then return server[field] end
    return C[field]
end

-- сбрасываем замки телефона/налогов: после обрыва они не должны «залипнуть»
local function resetPhoneLocks()
    pcall(function()
        _phoneOpBusy, _cefFetching, _phoneFetchState = false, false, false
        _taxState = 0
        St._phoneOpBusySince = nil
        St._closePhoneRunning = false
        PCS_NOUI_UNTIL = 0
    end)
end

local function threadAlive()
    local t = S.thread
    if not t then return false end
    local ok, dead = pcall(function() return t.dead end)
    return ok and not dead
end
local function killThread()
    if S.thread then pcall(function() S.thread:terminate() end) end
end

-- cmd_sc из Sweet Connect: (отключиться) -> ждать timeout -> подключиться
local function cmd_sc(timeout_sec, disconnect_now, doPing)
    if disconnect_now == nil then disconnect_now = true end
    timeout_sec = tonumber(timeout_sec) or getTimeout("sc_timeout")
    killThread()
    resetPhoneLocks()
    if doPing then
        local ok, ip, port = pcall(sampGetCurrentServerAddress)
        if ok then pcall(pingServer, ip, port) end
    end
    S.thread = lua_thread.create_suspended(function()
        local okT, errT = pcall(function()
        wait(0)
        if disconnect_now and sampGetGamestate() ~= K.GS_REST then
            sampSetGamestate(K.GS_DISC)
            sampDisconnectWithReason(0)
        end
        local t0 = os.clock()
        while true do
            wait(0)
            local passed = os.clock() - t0
            if passed < timeout_sec then
                S.text = secondsToClock(timeout_sec - passed)
                S.show = true
            else
                break
            end
        end
        S.show = false
        if not disconnect_now and sampGetGamestate() ~= K.GS_REST then
            sampSetGamestate(K.GS_DISC)
            sampDisconnectWithReason(0)
        end
        if sampIsDialogActive() then sampCloseCurrentDialogWithButton(0) end
        sampSetGamestate(K.GS_WAIT)
        S.startConnecting = os.clock()
        end)
        if not okT then
            S.show = false
            print("[PC Stats][rc] reconnect thread error: " .. tostring(errT))
        end
    end)
    S.thread:run()
end
RC.cmd_sc = cmd_sc

local function cmd_scd()
    killThread()
    S.show = false
    S.startConnecting = nil
    pcall(sampSetGamestate, K.GS_DISC)
    chat("ABCDEF", "Отключён. Для подключения: /sc")
end
local function cancelReconnect()
    S.show = false
    killThread()
end
RC.cancel = cancelReconnect

-- расписание паузы (get_pause_sec)
local function get_pause_sec(h1, m1, h2, m2)
    local epoch = os.time(os.date("*t"))
    local dt = os.date("*t", epoch)
    dt.hour, dt.min, dt.sec = h1, m1, 0
    local start = os.time(dt)
    dt.hour, dt.min, dt.sec = h2, m2, 0
    local finish = os.time(dt)
    if finish <= start then
        dt.hour, dt.min = h2, m2
        dt.day = dt.day + 1
        finish = os.time(dt)
        if epoch < start and epoch < finish then epoch = epoch + 86400 end
    end
    if epoch > start and epoch < finish then return finish - epoch end
    return false
end

local function autoReconnect(field, disconnect_now)
    if not C.autoreconnect then return end
    if C.pause then
        local psec = get_pause_sec(C.pause_from_hour, C.pause_from_min, C.pause_to_hour, C.pause_to_min)
        if psec then cmd_sc(psec, disconnect_now); return end
    end
    cmd_sc(getTimeout(field), disconnect_now)
end

-- ── пакеты и RPC: как onReceivePacket / onReceiveRpc в Sweet Connect ──
local function hookPacket(id, bs)
    if id == K.PK_PASS then
        S.startConnecting = nil
        autoReconnect("disconnect_timeout", true)
    elseif id == K.PK_DISC then
        S.startConnecting = nil
        autoReconnect("disconnect_timeout", false)
    elseif id == K.PK_LOST then
        S.startConnecting = nil
        autoReconnect("lost_connection_timeout", true)
    elseif id == K.PK_BANNED then
        S.startConnecting = nil
        autoReconnect("banned_ip_timeout", true)
    elseif id == K.PK_FAILED then
        if not S.startConnecting then S.startConnecting = os.clock() end
        local ok, ip, port = pcall(sampGetCurrentServerAddress)
        if ok then pcall(pingServer, ip, port) end
    elseif id == 239 then
        RC.onCefPacket(bs)
    end
end
local function hookRpc(id, bs)
    if id == K.RPC_INIT then
        S.startConnecting = nil
        S.wdFails = 0 -- успешно подключились — сбрасываем бэкофф
    elseif id == K.RPC_REJ then
        S.startConnecting = nil
        autoReconnect("lost_connection_timeout", true)
    end
end

local function gen_gauth_code(skey)
    local okB, basexx = pcall(require, "basexx")
    local okS, sha1 = pcall(require, "sha1")
    if not (okB and okS) then return nil end
    local bit = require("bit")
    local key = basexx.from_base32(skey)
    local value = math.floor(os.time() / 30)
    value = string.char(0, 0, 0, 0,
        bit.band(value, 0xFF000000) / 0x1000000,
        bit.band(value, 0xFF0000) / 0x10000,
        bit.band(value, 0xFF00) / 0x100,
        bit.band(value, 0xFF))
    local hash = sha1.hmac_binary(key, value)
    local offset = bit.band(hash:sub(-1):byte(1, 1), 0xF)
    local a, b, c, d = hash:byte(offset + 1, offset + 4)
    local n = a * 0x1000000 + b * 0x10000 + c * 0x100 + d
    n = bit.band(n, 0x7FFFFFFF) % 1000000
    return ("%06d"):format(n)
end

local function add_dialog(args)
    local dialog = {
        id = args.id, title = args.title, user_title = args.user_title,
        text = args.text, style = args.style,
        check_id = args.check_id, check_content = args.check_content, check_title = args.check_title,
        response_button = args.response_button, response_text = args.response_text,
        response_index = args.response_index,
        use_gauth = args.use_gauth, spawn_player = args.spawn_player,
        spawn_delay = args.spawn_delay, gauth_key = args.gauth_key,
    }
    for _, server in ipairs(servers) do
        if server.ip == args.ip and server.port == args.port then
            for _, login in ipairs(server.logins) do
                if login.nickname == args.nickname then
                    login.dialogs[#login.dialogs + 1] = dialog
                    return
                end
            end
            server.logins[#server.logins + 1] = { nickname = args.nickname, dialogs = { dialog } }
            return
        end
    end
    servers[#servers + 1] = {
        ip = args.ip, port = args.port, name = args.name,
        sc_timeout = C.sc_timeout, disconnect_timeout = C.disconnect_timeout,
        banned_ip_timeout = C.banned_ip_timeout, lost_connection_timeout = C.lost_connection_timeout,
        use_timeouts = false,
        logins = { { nickname = args.nickname, dialogs = { dialog } } },
    }
end

local function get_dialog(args)
    for _, server in ipairs(servers) do
        if server.ip == args.ip and server.port == args.port then
            for _, login in ipairs(server.logins) do
                if login.nickname == args.nickname then
                    for _, d in ipairs(login.dialogs) do
                        if (not d.check_id or d.id == args.id)
                            and (not d.check_title or d.title == args.title)
                            and (not d.check_content or d.text == args.text)
                            and (not d.check_content or d.style == args.style) then
                            if d.check_id or d.check_title or d.check_content then return d end
                        end
                    end
                end
            end
        end
    end
end

local function delete_dialog(si, li, di)
    local server = servers[si]
    if not server then return end
    local login = server.logins[li]
    if not login then return end
    table.remove(login.dialogs, di)
    if #login.dialogs == 0 then table.remove(server.logins, li) end
    if #server.logins == 0 then table.remove(servers, si) end
    saveServers()
end

-- сохранение: sampev.onSendDialogResponse, пока открыто окно «Сохранение диалога»
S.userTitle = ""; S.useGauth = false; S.gauthKey = ""; S.spawnPlayer = false
function RC.onSendResponse(id, button, index, text)
    if not S.saving then return end
    local ok, ip, port = pcall(sampGetCurrentServerAddress)
    if not ok then return end
    local okN, srvName = pcall(sampGetCurrentServerName)
    local okC, caption = pcall(sampGetDialogCaption)
    local okT, dtext = pcall(sampGetDialogText)
    local okS, style = pcall(sampGetCurrentDialogType)
    add_dialog {
        ip = ip, port = port, name = toUi(okN and srvName or ""),
        nickname = sampGetNickname(),
        id = id, title = toUi(okC and caption or ""), user_title = S.userTitle,
        text = toUi(okT and dtext or ""), style = okS and style or nil,
        check_content = C.check_content, check_title = C.check_title, check_id = C.check_id,
        response_button = button, response_index = index, response_text = toUi(text or ""),
        use_gauth = S.useGauth, gauth_key = S.gauthKey,
        spawn_player = S.spawnPlayer, spawn_delay = C.spawn_delay,
    }
    saveServers()
    S.saving = false
    S.useGauth, S.gauthKey, S.spawnPlayer = false, "", false
    chat("88FF88", "Диалог сохранён")
end

local function normSpawn(s)
    s = tostring(s or "")
    if s:find("Сохраненная точка", 1, true) or s:find("Сохранённая точка", 1, true) then
        return "Сохраненная точка"
    end
    return s
end
local function rememberSeen(parsed)
    local clean = {}
    for _, n in ipairs(parsed) do if n ~= "" then clean[#clean + 1] = n end end
    local same = (#clean == #C.last_spawn_dialog)
    if same then for i = 1, #clean do if clean[i] ~= C.last_spawn_dialog[i] then same = false; break end end end
    if not same then C.last_spawn_dialog = clean; markDirty() end
end

-- SAMP-диалог «Выбор места спавна» (как sampev.onShowDialog в AutoSelectSpawnV4)
local function onSpawnDialog(id, title, text)
    if not title:find("Выбор места спавна", 1, true) then return nil end
    local parsed = {}
    for n in (text .. "\n"):gmatch("([^\r\n]+)") do
        local line = n:match("%[%d+%] %{ffffff%}%s*(.+)")
        if line then parsed[#parsed + 1] = normSpawn(line) else parsed[#parsed + 1] = "" end
    end
    rememberSeen(parsed)
    if C.sp_enabled then
        for i = 1, #C.priority do
            local pri = C.priority[i]
            for idx = 1, #parsed do
                if parsed[idx] == pri then
                    sampSendDialogResponse(id, 1, idx - 1, "")
                    chat("00FF88", "Автоспавн: " .. pri)
                    return false
                end
            end
        end
    end
    return nil
end

-- главный обработчик диалогов: вернуть false = диалог обработан (не показывать)
function RC.onDialog(id, style, title, b1, b2, text)
    local t8, x8 = gameToUi(title), gameToUi(text)
    local r = onSpawnDialog(id, t8, x8)
    if r == false then return false end
    if C.autoresponse then
        local ok, ip, port = pcall(sampGetCurrentServerAddress)
        if ok then
            local dialog = get_dialog { ip = ip, port = port, nickname = sampGetNickname(),
                id = id, title = t8, text = x8, style = style }
            if dialog then
                lua_thread.create(function()
                    wait(C.autoresponse_delay)
                    if dialog.use_gauth then
                        local sec = os.date("*t").sec
                        local offset = 5
                        local mode = sec % 30
                        if mode < offset then wait((offset - mode) * 1000)
                        elseif mode > (30 - offset) then wait((30 - mode + offset) * 1000) end
                        local code = gen_gauth_code(dialog.gauth_key or "")
                        if not code then chat("FF6666", "Нет библиотек sha1/basexx для Google Auth") end
                        sampSendDialogResponse(id, dialog.response_button, dialog.response_index,
                            code or toGame(dialog.response_text or ""))
                    else
                        sampSendDialogResponse(id, dialog.response_button, dialog.response_index,
                            toGame(dialog.response_text or ""))
                    end
                    if dialog.spawn_player then
                        wait(dialog.spawn_delay or C.spawn_delay)
                        sampSpawnPlayer()
                    end
                end)
                if C.notif then notify("Автоответ на диалог", "info", 2) end
                return false
            end
        end
    end
    return nil
end

-- CEF-экран Arizona: пакет 239 -> event.auth.initializeSpawnPoints
local function arizonaSendSelectSpawn(id)
    local s = "authSpawn|" .. tostring(id)
    local bs = raknetNewBitStream()
    if not bs then return end
    local ok, err = pcall(function()
        raknetBitStreamWriteInt8(bs, 220)
        raknetBitStreamWriteInt8(bs, 18)
        raknetBitStreamWriteInt32(bs, #s)
        raknetBitStreamWriteString(bs, s)
        raknetBitStreamWriteInt32(bs, 0)
        raknetSendBitStreamEx(bs, 1, 7, 1)
    end)
    pcall(raknetDeleteBitStream, bs)
    if not ok then print("[PC Stats][spawn] send error: " .. tostring(err)) end
end
local function bitStreamText(bs)
    local n = raknetBitStreamGetNumberOfBytesUsed(bs)
    if type(n) ~= "number" or n < 20 or n > 32768 then return nil end
    local t = {}
    for i = 1, n do
        local b = raknetBitStreamReadInt8(bs)
        if b < 0 then b = b + 256 end
        if b >= 32 and b ~= 37 then t[#t + 1] = string.char(b) end
    end
    raknetBitStreamResetReadPointer(bs)
    return table.concat(t)
end
function RC.onCefPacket(bs)
    local ok, text = pcall(bitStreamText, bs)
    if not ok or not text then return end
    if not text:find("initializeSpawnPoints", 1, true) then return end
    local event, payload = text:match("window%.executeEvent%('([%w%.]+)',%s*'(.+)'%)")
    if event ~= "event.auth.initializeSpawnPoints" then return end
    local okJ, arr = pcall(decodeJson, payload)
    if not okJ or type(arr) ~= "table" then return end
    local points = arr[1]
    if type(points) ~= "table" then return end
    local parsed, ids = {}, {}
    for _, p in ipairs(points) do
        if type(p) == "table" and p.spawn ~= nil then
            parsed[#parsed + 1] = normSpawn(gameToUi(p.spawn))
            ids[#ids + 1] = p.id
        end
    end
    rememberSeen(parsed)
    if not C.sp_enabled then return end
    for i = 1, #C.priority do
        local pri = C.priority[i]
        for idx = 1, #parsed do
            if parsed[idx] == pri then
                pcall(arizonaSendSelectSpawn, ids[idx])
                chat("00FF88", "Автоспавн: " .. pri)
                return
            end
        end
    end
end

local ffi = require("ffi")
local UI = {}
local function accent()
    local ok, r, g, b = pcall(function() return PCS_getAccG() end)
    if ok and r then return r, g, b end
    return 0.35, 0.65, 1.0
end
local function V4(r, g, b, a) return imgui.ImVec4(r, g, b, a or 1) end
local function V2(x, y) return imgui.ImVec2(x, y) end

local function U32(r, g, b, a)
    local function c(x) x = math.floor((x or 0) * 255 + 0.5); if x < 0 then x = 0 elseif x > 255 then x = 255 end; return x end
    return c(a) * 16777216 + c(b) * 65536 + c(g) * 256 + c(r)
end
local function cardTitle(text)
    local ar, ag, ab = accent()
    local dl = imgui.GetWindowDrawList()
    local aw = imgui.GetContentRegionAvail().x
    local p = imgui.GetCursorScreenPos()
    local h = imgui.GetTextLineHeight() + 10
    dl:AddRectFilled(p, V2(p.x + aw, p.y + h), U32(ar * 0.22, ag * 0.22, ab * 0.22, 0.60), 6)
    dl:AddRectFilled(p, V2(p.x + 3, p.y + h), U32(ar, ag, ab, 1), 2)
    dl:AddText(V2(p.x + 12, p.y + 5), U32(1, 1, 1, 1), text)
    imgui.Dummy(V2(aw, h + 6))
end
local function hint(text)
    imgui.PushStyleColor(imgui.Col.Text, V4(0.6, 0.63, 0.68, 1))
    imgui.TextWrapped(text)
    imgui.PopStyleColor()
end

-- бейдж состояния (ВКЛЮЧЕНО / ВЫКЛЮЧЕНО)
local function pill(text, on)
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local tw = imgui.CalcTextSize(text).x + 22
    local th = imgui.GetTextLineHeight() + 6
    if on then
        dl:AddRectFilled(p, V2(p.x + tw, p.y + th), U32(0.20, 0.75, 0.40, 0.25), th / 2)
        dl:AddRect(p, V2(p.x + tw, p.y + th), U32(0.30, 0.90, 0.50, 0.90), th / 2, 0, 1.2)
        dl:AddText(V2(p.x + 11, p.y + 3), U32(0.75, 1, 0.82, 1), text)
    else
        dl:AddRectFilled(p, V2(p.x + tw, p.y + th), U32(0.35, 0.35, 0.40, 0.25), th / 2)
        dl:AddRect(p, V2(p.x + tw, p.y + th), U32(0.6, 0.6, 0.65, 0.7), th / 2, 0, 1.0)
        dl:AddText(V2(p.x + 11, p.y + 3), U32(0.78, 0.78, 0.82, 1), text)
    end
    imgui.Dummy(V2(tw, th + 2))
end

-- строка выбора места: квадратик-галочка + зелёная подсветка, клик = выбрать/снять
local function spawnRow(id, label, selected)
    local dl = imgui.GetWindowDrawList()
    local aw = imgui.GetContentRegionAvail().x
    local h = imgui.GetTextLineHeight() + 12
    local p = imgui.GetCursorScreenPos()
    local clicked = imgui.InvisibleButton("##spr" .. tostring(id), V2(aw, h))
    local hov = imgui.IsItemHovered()
    local q = V2(p.x + aw, p.y + h)
    if selected then
        dl:AddRectFilled(p, q, U32(0.20, 0.75, 0.40, 0.22), 8)
        dl:AddRect(p, q, U32(0.30, 0.90, 0.50, 0.85), 8, 0, 1.3)
    elseif hov then
        dl:AddRectFilled(p, q, U32(1, 1, 1, 0.06), 8)
    end
    local bx, by = p.x + 12, p.y + (h - 16) / 2
    if selected then
        dl:AddRectFilled(V2(bx, by), V2(bx + 16, by + 16), U32(0.25, 0.85, 0.45, 1), 4)
        dl:AddLine(V2(bx + 4, by + 8), V2(bx + 7, by + 12), U32(1, 1, 1, 1), 2)
        dl:AddLine(V2(bx + 7, by + 12), V2(bx + 13, by + 4), U32(1, 1, 1, 1), 2)
    else
        dl:AddRect(V2(bx, by), V2(bx + 16, by + 16), U32(1, 1, 1, 0.35), 4, 0, 1.4)
    end
    local ty = p.y + (h - imgui.GetTextLineHeight()) / 2
    dl:AddText(V2(bx + 26, ty), selected and U32(0.75, 1, 0.82, 1) or U32(1, 1, 1, 0.92), tostring(label))
    return clicked
end

-- стильная кнопка: акцентная заливка (filled) или контур
local function fancyButton(id, label, w, h, r, g, b, filled)
    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetCursorScreenPos()
    local clicked = imgui.InvisibleButton("##fb" .. tostring(id), V2(w, h))
    local hov = imgui.IsItemHovered()
    local held = imgui.IsItemActive()
    local q = V2(p.x + w, p.y + h)
    if filled then
        local k = held and 0.80 or (hov and 1.10 or 1.0)
        dl:AddRectFilled(V2(p.x, p.y + 3), V2(q.x, q.y + 3), U32(0, 0, 0, 0.28), 9)
        dl:AddRectFilled(p, q, U32(math.min(r * k, 1), math.min(g * k, 1), math.min(b * k, 1), 1), 9)
        dl:AddRectFilled(p, V2(q.x, p.y + h * 0.45), U32(1, 1, 1, 0.08), 9)
        dl:AddRect(p, q, U32(1, 1, 1, hov and 0.35 or 0.15), 9, 0, 1.0)
    else
        dl:AddRectFilled(p, q, U32(0.10, 0.11, 0.14, hov and 0.95 or 0.70), 9)
        dl:AddRect(p, q, U32(r, g, b, hov and 0.95 or 0.55), 9, 0, 1.3)
    end
    local ts = imgui.CalcTextSize(label)
    dl:AddText(V2(p.x + (w - ts.x) / 2, p.y + (h - ts.y) / 2), U32(1, 1, 1, 1), label)
    return clicked
end

-- ник игрока и IP сервера (с кнопкой скрыть/показать IP)
RC._hideIp = RC._hideIp or false
local function getMyNick()
    local okId, res, id = pcall(sampGetPlayerIdByCharHandle, PLAYER_PED)
    if okId and res and id then
        local okN, nk = pcall(sampGetPlayerNickname, id)
        if okN and nk and nk ~= "" then return tostring(nk) end
    end
    return "не в игре"
end
local function getServerAddr()
    local okA, ip, port = pcall(sampGetCurrentServerAddress)
    if okA and ip and tostring(ip) ~= "" then return tostring(ip) .. ":" .. tostring(port or "") end
    return nil
end
local function drawServerCard()
    local ar, ag, ab = accent()
    local dl = imgui.GetWindowDrawList()
    local aw = imgui.GetContentRegionAvail().x
    local p = imgui.GetCursorScreenPos()
    local h = 88
    local addr = getServerAddr()
    local ipText
    if not addr then ipText = "нет подключения"
    elseif RC._hideIp then ipText = "***.***.***.***:*****"
    else ipText = addr end
    dl:AddRectFilled(p, V2(p.x + aw, p.y + h), U32(0.08, 0.09, 0.12, 0.96), 10)
    dl:AddRectFilled(V2(p.x, p.y + 10), V2(p.x + 3, p.y + h - 10), U32(ar, ag, ab, 1), 2)
    dl:AddRect(p, V2(p.x + aw, p.y + h), U32(ar, ag, ab, 0.25), 10, 0, 1.0)
    dl:AddText(V2(p.x + 16, p.y + 10), U32(0.55, 0.58, 0.64, 1), "НИК")
    dl:AddText(V2(p.x + 16, p.y + 26), U32(1, 1, 1, 1), getMyNick())
    dl:AddText(V2(p.x + 16, p.y + 54), U32(0.55, 0.58, 0.64, 1), "IP СЕРВЕРА")
    dl:AddText(V2(p.x + 16, p.y + 68), U32(ar * 0.6 + 0.4, ag * 0.6 + 0.4, ab * 0.6 + 0.4, 1), ipText)
    imgui.SetCursorScreenPos(V2(p.x + aw - 132, p.y + 30))
    if fancyButton("hideip", RC._hideIp and "Показать IP" or "Скрыть IP", 118, 28, ar, ag, ab, false) then
        RC._hideIp = not RC._hideIp
    end
    imgui.SetCursorScreenPos(V2(p.x, p.y + h))
    imgui.Dummy(V2(aw, h + 8))
end

