-- ── кнопка «+» и окно «Сохранение диалога» (как в Sweet Connect) ──
PCS_QUEUE = PCS_QUEUE or { active = false, startT = 0, lastT = 0, pos = nil, total = nil, samples = {} }
local QUEUE_CP_OCH = "\xEE\xF7\xE5\xF0\xE5\xE4" -- "очеред" в CP1251 (текст чата игры)
local QUEUE_CP_IZ  = "\xE8\xE7"                     -- "из" в CP1251

function PCS_QUEUE.onServerMessage(text)
    text = tostring(text or "")
    if not text:find(QUEUE_CP_OCH, 1, true) then return end
    local pos = text:match(QUEUE_CP_OCH .. "[^%d]*(%d+)") or text:match("(%d+)[^%d]*" .. QUEUE_CP_OCH)
    if not pos then return end
    local q = PCS_QUEUE
    local t = os.time()
    if not q.active or (t - q.lastT) > 120 then
        q.startT = t
        q.samples = {}
    end
    q.active = true
    q.lastT = t
    q.pos = tonumber(pos)
    q.total = tonumber(text:match(QUEUE_CP_IZ .. "%s*(%d+)")) or q.total
    q.samples[#q.samples + 1] = { t = t, pos = q.pos }
    while #q.samples > 40 do table.remove(q.samples, 1) end
end

-- примерно сколько секунд до входа: скорость продвижения по последним сообщениям
function PCS_QUEUE.eta()
    local q = PCS_QUEUE
    local smp = q.samples
    if #smp < 2 or not q.pos then return nil end
    local a, b = smp[1], smp[#smp]
    local dt, dp = b.t - a.t, a.pos - b.pos
    if dt < 15 or dp <= 0 then return nil end
    return math.floor(b.pos / (dp / dt) + 0.5)
end

function PCS_QUEUE.check()
    local q = PCS_QUEUE
    if not q.active then return false end
    if os.time() - q.lastT > 120 or isPlayerActuallySpawned() then
        q.active = false
        return false
    end
    return true
end

