local function sliderRow(text, key, lo, hi, fmt)
    imgui.TextUnformatted(text); imgui.SameLine(250)
    imgui.PushItemWidth(200)
    if not UI[key] then UI[key] = imgui.new.int(C[key]) end
    if UI[key][0] ~= C[key] and not imgui.IsAnyItemActive() then UI[key][0] = C[key] end
    if imgui.SliderInt("##rcsl_" .. key, UI[key], lo, hi, fmt or "%d c") then C[key] = UI[key][0]; markDirty() end
    imgui.PopItemWidth()
end
local function toggleRow(key, label, desc)
    if PCS_settToggleRow("##rct_" .. key, C[key] and true or false, label, desc) then
        C[key] = not C[key]; markDirty()
    end
end

