local function drawSpawnTab()
    toggleRow("sp_enabled", "Автовыбор спавна", "Выбирает место спавна по списку приоритетов (диалог SAMP и экран Arizona).")
    imgui.Spacing()
    pill(C.sp_enabled and "ВКЛЮЧЕНО" or "ВЫКЛЮЧЕНО", C.sp_enabled)
    imgui.Spacing()
    cardTitle("Приоритеты спавна (сверху вниз)")
    if #C.priority == 0 then hint("Пусто. Отметьте места в списке ниже.") end
    local swapA, swapB, del
    for i, v in ipairs(C.priority) do
        imgui.PushStyleColor(imgui.Col.Text, V4(0.40, 0.90, 0.55, 1))
        imgui.TextUnformatted(tostring(i) .. ".")
        imgui.PopStyleColor()
        imgui.SameLine(34)
        imgui.TextUnformatted(v)
        imgui.SameLine(300)
        if imgui.SmallButton("Вверх##u" .. i) and i > 1 then swapA, swapB = i, i - 1 end
        imgui.SameLine()
        if imgui.SmallButton("Вниз##d" .. i) and i < #C.priority then swapA, swapB = i, i + 1 end
        imgui.SameLine()
        if imgui.SmallButton("x##x" .. i) then del = i end
    end
    if swapA then C.priority[swapA], C.priority[swapB] = C.priority[swapB], C.priority[swapA]; markDirty() end
    if del then table.remove(C.priority, del); markDirty() end
    imgui.Spacing()
    cardTitle("Последний диалог спавна — нажмите, чтобы добавить/убрать")
    if #C.last_spawn_dialog == 0 then hint("Появится после первого экрана выбора спавна.") end
    for i, v in ipairs(C.last_spawn_dialog) do
        local idx
        for pi, pv in ipairs(C.priority) do if pv == v then idx = pi; break end end
        if spawnRow(i, v, idx ~= nil) then
            if idx then table.remove(C.priority, idx) else C.priority[#C.priority + 1] = v end
            markDirty()
        end
    end
    imgui.Spacing()
    hint("Если ни одно место из приоритетов не найдено — выбор остаётся за вами.")
end

