function RC.openMenu(tab)
    St._settTab = (tab == 2) and "spawn" or "rc"
    St.activeTab = 4
    St._resetSettScroll = true
    if not St._winVisible then
        St.winOpen = true
        St._winVisible = true
    end
end

function RC.start()
    if RC._started then return end
    RC._started = true
    RC.load()
    initConsts()
    if K.ok then
        pcall(addEventHandler, "onReceivePacket", function(id, bs)
            local ok, err = pcall(hookPacket, id, bs)
            if not ok then print("[PC Stats/connect] packet: " .. tostring(err)) end
        end)
        pcall(addEventHandler, "onReceiveRpc", function(id, bs)
            local ok, err = pcall(hookRpc, id, bs)
            if not ok then print("[PC Stats/connect] rpc: " .. tostring(err)) end
        end)
    else
        print("[PC Stats/connect] SAMPFUNCS gamestate API не найден — реконнект выключен")
    end
    if sampev then
        local prev = sampev.onSendDialogResponse
        sampev.onSendDialogResponse = function(id, button, index, text)
            local ok, err = pcall(RC.onSendResponse, id, button, index, text)
            if not ok then print("[PC Stats/connect] save: " .. tostring(err)) end
            if prev then return prev(id, button, index, text) end
        end
    end
    pcall(sampRegisterChatCommand, "sc", function(arg) if K.ok then S.wdFails = 0; cmd_sc(arg) end end)
    pcall(sampRegisterChatCommand, "scd", function() if K.ok then cmd_scd() end end)
    pcall(sampRegisterChatCommand, "scm", function() RC.openMenu(1) end)
    pcall(sampRegisterChatCommand, "rcm", function() RC.openMenu(1) end)
    pcall(sampRegisterChatCommand, "setsp", function() RC.openMenu(2) end)
    lua_thread.create(function()
        while true do
            wait(50)
            if RC._dirty and os.clock() - (RC._dirtyAt or 0) > 0.6 then RC.save() end
            if K.ok and C.use_connecting_timeout and not S.show and S.startConnecting then
                local baseMs = math.max(tonumber(C.connecting_timeout) or 5000, 1000)
                local effMs = math.min(baseMs * (1 + math.min(S.wdFails, 6)), 60000)
                if (os.clock() - S.startConnecting) > (effMs / 1000) then
                    S.startConnecting = nil
                    S.wdFails = (S.wdFails or 0) + 1
                    if S.wdFails == 1 or S.wdFails % 3 == 0 then
                        chat("FFD700", "\xd1\xe5\xf0\xe2\xe5\xf0 \xed\xe5 \xee\xf2\xe2\xe5\xf7\xe0\xe5\xf2, \xef\xf0\xee\xe1\xf3\xfe \xf1\xed\xee\xe2\xe0 (\xef\xee\xef\xfb\xf2\xea\xe0 " .. S.wdFails .. ")")
                    end
                    cmd_sc(0, true, true)
                end
            end
        end
    end)
    print("[PC Stats] Sweet Connect + AutoSelectSpawn загружены (/sc /scd /scm /setsp)")
end

end)() -- PCS_RC

do
PCS_AI = PCS_AI or {
    msgs = {}, open = false, anim = 0, busy = false,
    rem = nil, lim = nil, resetAt = 0, model = "",
    online = nil, lastSend = -10, lastStatus = -999,
    scrollDown = false, focus = false, typing = false,
}

PCS_AI._B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"

function PCS_AI.b64enc(s)
    local out = {}
    for i = 1, #s, 3 do
        local a, b, c = s:byte(i, i + 2)
        local n = a * 65536 + (b or 0) * 256 + (c or 0)
        local c1 = math.floor(n / 262144) % 64
        local c2 = math.floor(n / 4096) % 64
        local c3 = math.floor(n / 64) % 64
        local c4 = n % 64
        out[#out + 1] = PCS_AI._B64:sub(c1 + 1, c1 + 1) .. PCS_AI._B64:sub(c2 + 1, c2 + 1)
        if b then out[#out + 1] = PCS_AI._B64:sub(c3 + 1, c3 + 1) end
        if c then out[#out + 1] = PCS_AI._B64:sub(c4 + 1, c4 + 1) end
    end
    return table.concat(out)
end

function PCS_AI.b64dec(s)
    local map = PCS_AI._b64map
    if not map then
        map = {}
        for i = 1, 64 do map[PCS_AI._B64:byte(i)] = i - 1 end
        PCS_AI._b64map = map
    end
    local out, acc, bits = {}, 0, 0
    for i = 1, #s do
        local v = map[s:byte(i)]
        if v then
            acc = acc * 64 + v
            bits = bits + 6
            if bits >= 8 then
                bits = bits - 8
                local d = 2 ^ bits
                local byte = math.floor(acc / d)
                acc = acc - byte * d
                out[#out + 1] = string.char(byte)
            end
        end
    end
    return table.concat(out)
end

function PCS_AI.urlenc(s)
    return (tostring(s):gsub("[^%w%-_%.~]", function(c) return string.format("%%%02X", c:byte()) end))
end

-- обрезка UTF-8 строки до n байт без разрыва символа
function PCS_AI.cutUtf8(t, n)
    if #t <= n then return t end
    t = t:sub(1, n)
    local i = #t
    while i > 0 do
        local c = t:byte(i)
        if c < 0x80 then break end
        if c >= 0xC0 then t = t:sub(1, i - 1); break end
        i = i - 1
    end
    return t
end

-- ── очистка текста: оставляем только то, что умеет шрифт (ASCII + кодировка
-- CP1251 в UTF-8), эмодзи и прочее выбрасываем; чистим markdown ──
function PCS_AI.rev()
    if PCS_AI._rev then return PCS_AI._rev end
    local rev = {}
    for b = 0x80, 0xFF do
        local u = CP1251_TO_UTF8 and CP1251_TO_UTF8[b]
        if u and #u >= 2 and b ~= 0x98 then rev[u] = string.char(b) end
    end
    PCS_AI._rev = rev
    return rev
end

PCS_AI._EXTRA = { ["→"] = "->", ["←"] = "<-", ["×"] = "x", ["✓"] = "+", ["✔"] = "+", ["≈"] = "~", ["−"] = "-", ["\194\160"] = " " }

function PCS_AI.clean(text)
    text = tostring(text or "")
    local rev = PCS_AI.rev()
    local out = {}
    for ch in text:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
        if #ch == 1 then
            local b = ch:byte()
            if b == 9 then out[#out + 1] = " "
            elseif b == 10 or b >= 32 then out[#out + 1] = ch end
        elseif rev[ch] then out[#out + 1] = ch
        elseif PCS_AI._EXTRA[ch] then out[#out + 1] = PCS_AI._EXTRA[ch] end
    end
    local s = table.concat(out)
    s = s:gsub("\r", ""):gsub("%*%*", ""):gsub("`", ""):gsub("\n%s*#+%s*", "\n"):gsub("^%s*#+%s*", "")
    s = s:gsub("\n%s*[%*%-]%s+", "\n- "):gsub("\n\n\n+", "\n\n")
    return (s:gsub("^%s+", ""):gsub("%s+$", ""))
end

-- UTF-8 -> CP1251 для чата игры
function PCS_AI.toCp(text)
    local rev = PCS_AI.rev()
    local out = {}
    for ch in tostring(text or ""):gmatch("[%z\1-\127\194-\244][\128-\191]*") do
        if #ch == 1 then out[#out + 1] = ch else out[#out + 1] = rev[ch] or "" end
    end
    return table.concat(out)
end

-- сообщение в чат игры (UTF-8 -> CP1251, с переносом по словам)
function PCS_AI.chatSay(text, color)
    color = color or "{C9B3FF}"
    local cp = PCS_AI.toCp(text)
    local first = true
    for para in (cp .. "\n"):gmatch("(.-)\n") do
        para = para:gsub("^%s+", "")
        while #para > 0 do
            local piece = para
            if #piece > 100 then
                local cut = piece:sub(1, 100):match("^.*()%s") or 100
                if cut < 40 then cut = 100 end
                piece = para:sub(1, cut)
                para = para:sub(cut + 1):gsub("^%s+", "")
            else
                para = ""
            end
            pcall(sampAddChatMessage, (first and "{9B7CFF}[AI] " or "{9B7CFF}      ") .. color .. piece, -1)
            first = false
        end
    end
end

-- ── состояние / конфиг ──
function PCS_AI.devId()
    if type(cfg.aiDevId) ~= "string" or #cfg.aiDevId < 12 then
        math.randomseed(os.time() + math.floor(os.clock() * 100000))
        local t = {}
        for i = 1, 20 do t[i] = string.format("%x", math.random(0, 15)) end
        cfg.aiDevId = table.concat(t)
        pcall(saveCfg)
    end
    return cfg.aiDevId
end

function PCS_AI.base()
    local u = tostring(cfg.aiUrl or ""):gsub("%s+", ""):gsub("/+$", "")
    if u == "" then return nil end
    if not u:find("^https?://") then u = "https://" .. u end
    return u
end

function PCS_AI.ready()
    return cfg.aiEnabled ~= false and PCS_AI.base() ~= nil and tostring(cfg.aiKey or ""):gsub("%s+", "") ~= ""
end

function PCS_AI.addMsg(role, text)
    local m = PCS_AI.msgs
    m[#m + 1] = { role = role, text = text, t = os.date("%H:%M") }
    while #m > 60 do table.remove(m, 1) end
    PCS_AI.scrollDown = true
end

function PCS_AI.fmtReset(sec)
    sec = math.max(0, math.floor(tonumber(sec) or 0))
    return string.format("%d:%02d", math.floor(sec / 3600), math.floor(sec % 3600 / 60))
end

function PCS_AI.errText(code)
    local AI = PCS_AI
    if code == "limit" then
        return "Лимит сообщений на сегодня исчерпан. Обновится через " .. AI.fmtReset(math.max(0, (AI.resetAt or 0) - os.time())) .. " ч."
    end
    local map = {
        auth = "Неверный ключ доступа — проверь его в админке бэкенда.",
        bad_user = "Бэкенд не принял ID устройства.",
        disabled = "ИИ отключён администратором.",
        banned = "Тебе закрыт доступ к ИИ.",
        busy = "Подожди ответа на предыдущее сообщение.",
        empty = "Пустое сообщение.",
        rate = "Слишком часто, подожди минуту.",
        no_provider = "На бэкенде не добавлен API-ключ ИИ (админка -> API-ключи).",
        upstream = "ИИ-провайдер сейчас не отвечает, попробуй позже.",
        net = "Нет связи с бэкендом. Проверь адрес (на бесплатном Render первый запрос может идти ~минуту).",
        nourl = "Не указан адрес бэкенда.",
        nokey = "Не указан ключ доступа.",
    }
    return map[code] or ("Ошибка: " .. tostring(code))
end

function PCS_AI.request(path, extra)
    local AI = PCS_AI
    local base = AI.base()
    if not base then return nil, "nourl" end
    local key = tostring(cfg.aiKey or ""):gsub("%s+", "")
    if key == "" then return nil, "nokey" end
    if type(downloadUrlToFile) ~= "function" or type(PCS_dlFile) ~= "function" then return nil, "net" end
    local nick = ""
    pcall(function()
        local okId, id = sampGetPlayerIdByCharHandle(PLAYER_PED)
        if okId then nick = tostring(sampGetPlayerNickname(id) or "") end
    end)
    nick = nick:gsub("[^%w_%.%-%[%]]", ""):sub(1, 30)
    AI._seq = (AI._seq or 0) + 1
    local url = base .. "/api/" .. path .. "?k=" .. AI.urlenc(key) .. "&u=" .. AI.devId()
        .. "&nick=" .. AI.urlenc(nick) .. (extra or "") .. "&t=" .. tostring(os.time()) .. tostring(AI._seq)
    local okW, wd = pcall(getWorkingDirectory)
    local ddir = (okW and type(wd) == "string" and wd ~= "") and (wd .. "/config/PCStats") or CFG_DIR
    pcall(createDirectory, ddir)
    local dest = ddir .. "/ai_resp_" .. tostring(AI._seq % 3) .. ".tmp"
    pcall(os.remove, dest)
    pcall(PCS_GUARD.mark, "net: ai " .. tostring(path))
    local okF, why = PCS_dlFile(url, dest, 75, 5)
    local body
    local f = io.open(dest, "rb")
    if f then body = f:read("*a"); f:close() end
    pcall(os.remove, dest)
    if not body or body == "" or not body:find('"ok"') then return nil, "net" end
    local res = { ok = body:find('"ok"%s*:%s*true') ~= nil }
    res.err = body:match('"err"%s*:%s*"([%w_]+)"')
    local r = body:match('"r"%s*:%s*"([%w%-_]*)"')
    if r then res.reply = AI.b64dec(r) end
    res.remaining = tonumber(body:match('"remaining"%s*:%s*(-?%d+)'))
    res.limit = tonumber(body:match('"limit"%s*:%s*(-?%d+)'))
    res.resetIn = tonumber(body:match('"resetIn"%s*:%s*(%d+)'))
    res.model = body:match('"model"%s*:%s*"([^"]*)"')
    if res.remaining then
        AI.rem, AI.lim = res.remaining, res.limit
        AI.resetAt = os.time() + (res.resetIn or 0)
    end
    if res.model and res.model ~= "" then AI.model = res.model end
    return res
end

-- ── действия ──
function PCS_AI.refresh(announce)
    local AI = PCS_AI
    if AI.checking or not AI.ready() then
        if not AI.ready() then AI.online = nil end
        return
    end
    AI.checking = true
    AI.lastStatus = os.clock()
    lua_thread.create(function()
        wait(0)
        local ok, err = pcall(function()
            local res, why = AI.request("status")
            if not res then
                AI.online = false; AI.statusMsg = AI.errText(why)
            elseif res.ok then
                AI.online = true; AI.statusMsg = ""
            else
                AI.online = false; AI.statusMsg = AI.errText(res.err)
            end
            if announce then
                AI.testResult = AI.online and "Соединение установлено" or AI.statusMsg
                AI.testOk = AI.online
            end
        end)
        if not ok then pcall(PCS_quietErr, "ai:refresh", err) end
        AI.checking = false
    end)
end

function PCS_AI.send(text, toChat)
    local AI = PCS_AI
    text = tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if text == "" then return end
    if AI.busy then
        if toChat then PCS_AI.chatSay(PCS_AI.errText("busy"), "{FF9966}") end
        return
    end
    if cfg.aiEnabled == false then
        AI.addMsg("err", "ИИ выключен в настройках.")
        if toChat then PCS_AI.chatSay("ИИ выключен в настройках", "{FF9966}") end
        return
    end
    if not AI.ready() then
        local t = AI.base() and AI.errText("nokey") or AI.errText("nourl")
        AI.addMsg("err", t)
        if toChat then PCS_AI.chatSay(t, "{FF9966}") end
        return
    end
    if os.clock() - AI.lastSend < 1.0 then return end
    AI.lastSend = os.clock()
    text = AI.clean(text):gsub("\n", " ")
    -- URL у WinInet ограничен ~2000 символов: режем текст под лимит
    local base = AI.base() or ""
    local maxB64 = 1900 - #base - #tostring(cfg.aiKey or "") - 90
    local m = AI.b64enc(text)
    while #m > maxB64 and #text > 5 do
        text = AI.cutUtf8(text, math.floor(#text * 0.85))
        m = AI.b64enc(text)
    end
    AI.addMsg("user", text)
    AI.busy = true
    lua_thread.create(function()
        wait(0)
        local ok, err = pcall(function()
            local res, why = AI.request("chat", "&m=" .. m)
            if not res then
                AI.online = false
                local t = AI.errText(why); AI.addMsg("err", t)
                if toChat then AI.chatSay(t, "{FF9966}") end
            elseif res.ok and res.reply and res.reply ~= "" then
                AI.online = true
                local ans = AI.clean(res.reply)
                if ans == "" then ans = "(пустой ответ)" end
                AI.addMsg("ai", ans)
                if PCS_FXC and PCS_FXC.soundAi ~= false then pcall(PCS_FX.play, "ai") end
                if toChat or cfg.aiMirrorChat == true then AI.chatSay(ans) end
                if toChat and res.remaining and res.remaining >= 0 then
                    AI.chatSay("Осталось сообщений: " .. tostring(res.remaining) .. "/" .. tostring(res.limit), "{8888AA}")
                end
            else
                local t = AI.errText(res.err or "upstream"); AI.addMsg("err", t)
                if res.err == "auth" or res.err == "disabled" or res.err == "banned" then AI.online = false end
                if toChat then AI.chatSay(t, "{FF9966}") end
            end
        end)
        if not ok then
            pcall(PCS_quietErr, "ai:send", err)
            AI.addMsg("err", AI.errText("net"))
        end
        AI.busy = false
        AI.scrollDown = true
    end)
end

function PCS_AI.clear()
    local AI = PCS_AI
    AI.msgs = {}
    if AI.ready() and not AI.busy then
        lua_thread.create(function()
            wait(0)
            pcall(AI.request, "clear")   -- сбрасываем память диалога на сервере
        end)
    end
end

function PCS_AI.toggle(force)
    local AI = PCS_AI
    local want = force
    if want == nil then want = not AI.open end
    AI.open = want and true or false
    if AI.open then
        AI.focus = true
        AI.scrollDown = true
        if AI.ready() and os.clock() - AI.lastStatus > 20 then AI.refresh() end
    else
        AI.typing = false
    end
end

function PCS_AI.init()
    if PCS_AI._inited then return end
    PCS_AI._inited = true
    pcall(PCS_AI.devId)
    pcall(sampRegisterChatCommand, "ai", function(arg)
        local t = u8(tostring(arg or ""))
        if t:gsub("%s+", "") == "" then PCS_AI.toggle() else PCS_AI.send(t, true) end
    end)
    pcall(sampRegisterChatCommand, "aichat", function() PCS_AI.toggle() end)
    pcall(sampRegisterChatCommand, "aiclear", function()
        PCS_AI.clear()
        PCS_AI.chatSay("Память диалога очищена")
    end)
end

-- ── цвета ──
function PCS_AI.counterColor()
    local AI = PCS_AI
    if not AI.rem or not AI.lim then return 0.62, 0.65, 0.75 end
    if AI.lim < 0 then return 0.45, 0.80, 1.0 end
    local f = AI.rem / math.max(1, AI.lim)
    if AI.rem <= 0 then return 1.0, 0.36, 0.42 end
    if f <= 0.2 then return 1.0, 0.62, 0.20 end
    if f <= 0.5 then return 1.0, 0.85, 0.30 end
    return 0.30, 0.90, 0.55
end

function PCS_AI.counterText()
    local AI = PCS_AI
    if not AI.rem or not AI.lim then return "—" end
    if AI.lim < 0 then return "без лимита" end
    return tostring(AI.rem) .. " / " .. tostring(AI.lim)
end

function PCS_AI.drawPanel()
    local AI = PCS_AI
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    local io = imgui.GetIO()
    local sw, sh = io.DisplaySize.x, io.DisplaySize.y
    local dt = tonumber(io.DeltaTime) or 0.016
    local target = AI.open and 1 or 0
    AI.anim = AI.anim + (target - AI.anim) * math.min(1, dt * 11)
    if math.abs(target - AI.anim) < 0.004 then AI.anim = target end
    if AI.anim <= 0 then AI.typing = false; return end

    local ease = 1 - (1 - AI.anim) ^ 3
    local pad = S(12)
    local W = S(math.max(300, math.min(560, tonumber(cfg.aiPanelW) or 380)))
    W = math.min(W, sw - S(20))
    local H = sh - S(24)
    local x = -W + (W + S(12)) * ease
    local y = S(12)
    local AR, AG, AB = 0.62, 0.45, 1.0

    imgui.SetNextWindowPos(V2(x, y), imgui.Cond.Always)
    imgui.SetNextWindowSize(V2(W, H), imgui.Cond.Always)
    imgui.SetNextWindowBgAlpha(0.0)
    local flags = imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoMove
        + imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoSavedSettings
        + imgui.WindowFlags.NoBackground
    if not imgui.Begin("##pcs_ai_panel", nil, flags) then imgui.End(); return end

    local dl = imgui.GetWindowDrawList()
    local p = imgui.GetWindowPos()
    local q = V2(p.x + W, p.y + H)
    local lh = imgui.GetTextLineHeight()
    local al = ease

    -- фон + свечение + рамка
    dl:AddRectFilled(V2(p.x + 3, p.y + 5), V2(q.x + 3, q.y + 5), U32(iv4(0, 0, 0, 0.35 * al)), S(16))
    dl:AddRectFilled(p, q, U32(iv4(0.055, 0.060, 0.085, 0.965 * al)), S(16))
    dl:PushClipRect(p, q, true)
    dl:AddCircleFilled(V2(p.x + W * 0.85, p.y + S(20)), S(150), U32(iv4(AR, AG, AB, 0.10 * al)), 56)
    dl:AddCircleFilled(V2(p.x + S(10), q.y - S(30)), S(110), U32(iv4(0.25, 0.55, 1.0, 0.07 * al)), 56)
    dl:PopClipRect()
    dl:AddRect(p, q, U32(iv4(AR, AG, AB, 0.70 * al)), S(16), 0, 1.5)

    -- ── шапка ──
    local hh = S(62)
    dl:PushClipRect(p, V2(q.x, p.y + hh), true)
    dl:AddRectFilled(p, q, U32(iv4(AR * 0.22, AG * 0.22, AB * 0.30, 0.85 * al)), S(16))
    dl:PopClipRect()
    dl:AddLine(V2(p.x + S(14), p.y + hh), V2(q.x - S(14), p.y + hh), U32(iv4(AR, AG, AB, 0.35 * al)), 1.0)
    local cx, cy = p.x + S(34), p.y + hh * 0.5
    dl:AddCircleFilled(V2(cx, cy), S(19), U32(iv4(AR, AG, AB, 0.28 * al)), 32)
    dl:AddCircle(V2(cx, cy), S(19), U32(iv4(AR, AG, AB, 0.85 * al)), 32, 1.6)
    pcall(PCS_drawSticker, dl, "star", cx, cy + math.sin(os.clock() * 2.2) * 1.2, S(10), math.sin(os.clock() * 1.5) * 0.12)
    dl:AddText(V2(p.x + S(62), p.y + S(11)), U32(iv4(1, 1, 1, al)), "ИИ-помощник")
    -- статус
    local stCol, stTxt
    if cfg.aiEnabled == false then stCol, stTxt = { 0.62, 0.65, 0.72 }, "выключен"
    elseif not AI.ready() then stCol, stTxt = { 1.0, 0.72, 0.20 }, "не настроен"
    elseif AI.busy then stCol, stTxt = { 0.62, 0.45, 1.0 }, "думает…"
    elseif AI.online == false then stCol, stTxt = { 1.0, 0.40, 0.40 }, "нет связи"
    elseif AI.online == true then stCol, stTxt = { 0.35, 0.92, 0.55 }, (AI.model ~= "" and AI.model or "онлайн")
    else stCol, stTxt = { 0.62, 0.65, 0.75 }, "проверка…" end
    local pulse = (AI.busy or AI.checking) and (0.6 + 0.4 * math.sin(os.clock() * 7)) or 1
    dl:AddCircleFilled(V2(p.x + S(68), p.y + S(11) + lh + S(7)), S(4), U32(iv4(stCol[1], stCol[2], stCol[3], pulse * al)), 12)
    dl:AddText(V2(p.x + S(78), p.y + S(11) + lh + S(0)), U32(iv4(stCol[1], stCol[2], stCol[3], 0.95 * al)), stTxt)

    -- кнопки шапки: очистить / закрыть
    local bs = S(30)
    local function hdrBtn(id, bx, kind)
        imgui.SetCursorScreenPos(V2(bx, p.y + (hh - bs) * 0.5))
        local clicked = imgui.InvisibleButton(id, V2(bs, bs))
        local hov = imgui.IsItemHovered()
        local a, b2 = V2(bx, p.y + (hh - bs) * 0.5), V2(bx + bs, p.y + (hh - bs) * 0.5 + bs)
        local c = (kind == "x") and { 1.0, 0.40, 0.45 } or { 0.62, 0.70, 1.0 }
        dl:AddRectFilled(a, b2, U32(iv4(c[1], c[2], c[3], hov and 0.30 or 0.14)), S(9))
        local mx, my = bx + bs * 0.5, p.y + hh * 0.5
        local col = U32(iv4(1, 1, 1, 0.92))
        if kind == "x" then
            dl:AddLine(V2(mx - S(5), my - S(5)), V2(mx + S(5), my + S(5)), col, 2.0)
            dl:AddLine(V2(mx + S(5), my - S(5)), V2(mx - S(5), my + S(5)), col, 2.0)
        else -- корзина
            dl:AddRect(V2(mx - S(5), my - S(3)), V2(mx + S(5), my + S(6)), col, S(2), 0, 1.6)
            dl:AddLine(V2(mx - S(7), my - S(4)), V2(mx + S(7), my - S(4)), col, 1.8)
            dl:AddLine(V2(mx - S(2), my - S(7)), V2(mx + S(2), my - S(7)), col, 1.8)
        end
        return clicked
    end
    if hdrBtn("##aiClose", q.x - bs - S(10), "x") then PCS_AI.toggle(false) end
    if hdrBtn("##aiClear", q.x - bs * 2 - S(16), "trash") then PCS_AI.clear() end

    -- ── счётчик сообщений ──
    local cy0 = p.y + hh + S(10)
    local ch = S(46)
    local cr, cg, cb = PCS_AI.counterColor()
    dl:AddRectFilled(V2(p.x + pad, cy0), V2(q.x - pad, cy0 + ch), U32(iv4(cr * 0.10, cg * 0.10, cb * 0.10 + 0.03, 0.95 * al)), S(11))
    dl:AddRect(V2(p.x + pad, cy0), V2(q.x - pad, cy0 + ch), U32(iv4(cr, cg, cb, 0.45 * al)), S(11), 0, 1.2)
    dl:AddText(V2(p.x + pad + S(10), cy0 + S(6)), U32(iv4(0.75, 0.78, 0.88, al)), "Осталось сообщений")
    local ct = PCS_AI.counterText()
    local cts = imgui.CalcTextSize(ct)
    dl:AddText(V2(q.x - pad - S(10) - cts.x, cy0 + S(6)), U32(iv4(cr, cg, cb, al)), ct)
    local bx0, bx1, by = p.x + pad + S(10), q.x - pad - S(10), cy0 + ch - S(13)
    dl:AddRectFilled(V2(bx0, by), V2(bx1, by + S(6)), U32(iv4(1, 1, 1, 0.09 * al)), S(3))
    local frac = (AI.rem and AI.lim and AI.lim > 0) and math.max(0, math.min(1, AI.rem / AI.lim)) or ((AI.lim and AI.lim < 0) and 1 or 0)
    if frac > 0.005 then
        dl:AddRectFilled(V2(bx0, by), V2(bx0 + (bx1 - bx0) * frac, by + S(6)), U32(iv4(cr, cg, cb, 0.95 * al)), S(3))
    end

    -- ── лента сообщений ──
    local logY = cy0 + ch + S(8)
    local inH = S(40)
    local footH = lh + S(6)
    local logH = (q.y - pad - footH - inH - S(8)) - logY
    imgui.SetCursorScreenPos(V2(p.x + pad, logY))
    imgui.PushStyleColor(imgui.Col.ChildBg, iv4(0, 0, 0, 0))
    imgui.BeginChild("##pcsAiLog", V2(W - pad * 2, logH), false)
    local aw = imgui.GetContentRegionAvail().x
    local ldl = imgui.GetWindowDrawList()
    local bpad = S(10)
    local gap = S(8)
    if #AI.msgs == 0 and not AI.busy then
        local p0 = imgui.GetCursorScreenPos()
        imgui.Dummy(V2(aw, logH - S(4)))
        local hint1 = "Спроси что угодно"
        local hint2 = "Enter — отправить"
        local hint3 = "В чате игры: /ai текст"
        local ccx, ccy = p0.x + aw * 0.5, p0.y + logH * 0.38
        ldl:AddCircleFilled(V2(ccx, ccy), S(30), U32(iv4(AR, AG, AB, 0.14)), 40)
        ldl:AddCircle(V2(ccx, ccy), S(30), U32(iv4(AR, AG, AB, 0.55)), 40, 1.5)
        pcall(PCS_drawSticker, ldl, "star", ccx, ccy, S(15), math.sin(os.clock() * 1.5) * 0.15)
        local function ctr(t, yy, a, col) local s2 = imgui.CalcTextSize(t); ldl:AddText(V2(ccx - s2.x * 0.5, yy), U32(iv4(col[1], col[2], col[3], a)), t) end
        ctr(hint1, ccy + S(42), 1.0, { 1, 1, 1 })
        ctr(hint2, ccy + S(42) + lh + S(4), 0.7, { 0.7, 0.74, 0.86 })
        ctr(hint3, ccy + S(42) + (lh + S(4)) * 2, 0.7, { 0.7, 0.74, 0.86 })
    end
    for i, m in ipairs(AI.msgs) do
        local isUser = (m.role == "user")
        local isErr = (m.role == "err")
        local maxBW = aw * 0.88
        local tw = maxBW - bpad * 2
        local okSz, sz = pcall(imgui.CalcTextSize, m.text, nil, false, tw)
        if not okSz or not sz then sz = V2(tw, lh) end
        local textW = math.min(tw, math.max(sz.x, S(60)))
        local th = PCS_textH(m.text, tw)
        local who = isUser and ("Ты · " .. m.t) or (isErr and ("Ошибка · " .. m.t) or ("ИИ · " .. m.t))
        local whoW = imgui.CalcTextSize(who).x
        local bw = math.max(textW, whoW) + bpad * 2
        local bh = bpad + lh + S(3) + th + bpad
        local p0 = imgui.GetCursorScreenPos()
        imgui.Dummy(V2(aw, bh + gap))
        local x0 = isUser and (p0.x + aw - bw) or p0.x
        local a, b2 = V2(x0, p0.y), V2(x0 + bw, p0.y + bh)
        local bg, bd, tc, wc
        if isUser then
            bg, bd, tc, wc = iv4(AR * 0.40, AG * 0.40, AB * 0.55, 0.95), iv4(AR, AG, AB, 0.65), iv4(1, 1, 1, 1), iv4(0.78, 0.70, 1.0, 0.95)
        elseif isErr then
            bg, bd, tc, wc = iv4(0.30, 0.09, 0.11, 0.95), iv4(1.0, 0.38, 0.42, 0.70), iv4(1.0, 0.82, 0.84, 1), iv4(1.0, 0.50, 0.55, 0.95)
        else
            bg, bd, tc, wc = iv4(0.11, 0.125, 0.17, 0.98), iv4(0.35, 0.45, 0.75, 0.45), iv4(0.93, 0.95, 1.0, 1), iv4(0.50, 0.75, 1.0, 0.95)
        end
        ldl:AddRectFilled(a, b2, U32(bg), S(12))
        ldl:AddRect(a, b2, U32(bd), S(12), 0, 1.1)
        ldl:AddText(V2(x0 + bpad, p0.y + bpad), U32(wc), who)
        PCS_textAt(x0 + bpad, p0.y + bpad + lh + S(3), tw, tc, m.text)
        imgui.SetCursorScreenPos(V2(p0.x, p0.y + bh + gap))
        imgui.Dummy(V2(1, 1))
    end
    if AI.busy then
        local p0 = imgui.GetCursorScreenPos()
        local bw, bh = S(70), S(34)
        imgui.Dummy(V2(aw, bh + gap))
        ldl:AddRectFilled(p0, V2(p0.x + bw, p0.y + bh), U32(iv4(0.11, 0.125, 0.17, 0.98)), S(12))
        ldl:AddRect(p0, V2(p0.x + bw, p0.y + bh), U32(iv4(AR, AG, AB, 0.55)), S(12), 0, 1.1)
        for k = 0, 2 do
            local ph = math.sin(os.clock() * 6 - k * 0.8)
            ldl:AddCircleFilled(V2(p0.x + bw * 0.5 + (k - 1) * S(14), p0.y + bh * 0.5 - ph * S(3)), S(4), U32(iv4(AR, AG, AB, 0.55 + 0.45 * math.max(0, ph))), 12)
        end
    end
    if AI.scrollDown then
        if imgui.SetScrollHereY then pcall(imgui.SetScrollHereY, 1.0)
        elseif imgui.SetScrollHere then pcall(imgui.SetScrollHere, 1.0)
        else pcall(function() imgui.SetScrollY(imgui.GetScrollMaxY()) end) end
        AI.scrollDown = false
    end
    imgui.EndChild()
    imgui.PopStyleColor(1)

    -- ── поле ввода ──
    AI.buf = AI.buf or imgui.new("char[512]")
    local inY = logY + logH + S(8)
    imgui.SetCursorScreenPos(V2(p.x + pad, inY))
    local btnW = S(92)
    local inW = W - pad * 2 - btnW - S(8)
    if AI.focus then
        pcall(imgui.SetKeyboardFocusHere, 0)
        AI.focus = false
    end
    local flagsIn = imgui.InputTextFlags and imgui.InputTextFlags.EnterReturnsTrue or 0
    local enter = false
    if type(PCS_tgField) == "function" then
        enter = PCS_tgField("##aiInput", AI.buf, 500, "Напиши сообщение…", "text", inW, inH, flagsIn)
    else
        imgui.PushItemWidth(inW)
        enter = imgui.InputText("##aiInput", AI.buf, 500, flagsIn)
        imgui.PopItemWidth()
    end
    AI.typing = imgui.IsItemActive() and true or false
    imgui.SameLine(0, S(8))
    local canSend = (not AI.busy)
    local sendCol = canSend and { 0.62, 0.45, 1.0 } or { 0.40, 0.40, 0.48 }
    local clicked = PCS_gdButton("Отправить##aiSend", btnW, inH, sendCol, 9.0)
    if (enter or clicked) and canSend then
        local txt = ffi.string(AI.buf)
        if txt:gsub("%s+", "") ~= "" then
            PCS_AI.send(txt, false)
            ffi.fill(AI.buf, 512)
        end
        AI.focus = true
    end

    -- подсказка внизу
    local foot = (AI.lim and AI.lim >= 0 and AI.rem == 0) and "Лимит на сегодня исчерпан" or "/ai текст — спросить из чата игры"
    local fs = imgui.CalcTextSize(foot)
    dl:AddText(V2(p.x + (W - fs.x) * 0.5, q.y - pad - lh + S(2)), U32(iv4(0.50, 0.54, 0.65, 0.9 * al)), foot)

    imgui.End()
end

PCS_AI.frame = imgui.OnFrame(
    function()
        if PCS_NOUI_UNTIL and os.clock() < PCS_NOUI_UNTIL then return false end
        return PCS_AI.open or (PCS_AI.anim or 0) > 0.002
    end,
    function(self)
        self.HideCursor = not PCS_AI.open
        local pushed = PCS_fontPush and PCS_fontPush()
        local ok, err = pcall(PCS_AI.drawPanel)
        if pushed and PCS_fontPop then pcall(PCS_fontPop, pushed) end
        if not ok then
            PCS_AI.open = false; PCS_AI.anim = 0; PCS_AI.typing = false
            pcall(PCS_quietErr, "ai:panel", err)
        end
    end
)

function PCS_AI.drawSettings()
    local AI = PCS_AI
    local V2, U32 = imgui.ImVec2, imgui.ColorConvertFloat4ToU32
    St._ai = St._ai or {}
    local T = St._ai
    if not T.url then
        T.url = imgui.new("char[160]")
        T.key = imgui.new("char[100]")
        ffi.copy(T.url, tostring(cfg.aiUrl or ""):sub(1, 150))
        ffi.copy(T.key, tostring(cfg.aiKey or ""):sub(1, 90))
        T.w = imgui.new.float(tonumber(cfg.aiPanelW) or 380)
    end
    if T.dirty and os.clock() - T.dirty > 1.5 then
        T.dirty = nil
        pcall(saveCfg)
        AI.lastStatus = -999
    end
    -- автообновление счётчика, пока блок открыт
    if AI.ready() and not AI.checking and os.clock() - AI.lastStatus > 45 then AI.refresh() end

    local AR, AG, AB = 0.62, 0.45, 1.0
    local dl = imgui.GetWindowDrawList()
    local lh = imgui.GetTextLineHeight()

    -- ── шапка ──
    do
        local aw = imgui.GetContentRegionAvail().x
        local p = imgui.GetCursorScreenPos()
        local h = math.max(S(64), lh * 2 + S(28))
        local q = V2(p.x + aw, p.y + h)
        imgui.Dummy(V2(aw, h))
        local hov = imgui.IsItemHovered()
        dl:AddRectFilled(p, q, U32(iv4(0.09, 0.07, 0.17, 0.98)), S(12))
        dl:PushClipRect(p, q, true)
        dl:AddCircleFilled(V2(q.x - S(30), p.y + h * 0.5), S(70), U32(iv4(AR, AG, AB, 0.12)), 48)
        dl:AddCircleFilled(V2(q.x - S(30), p.y + h * 0.5), S(40), U32(iv4(AR, AG, AB, 0.14)), 48)
        dl:AddCircleFilled(V2(p.x + S(30), p.y + h * 0.5), S(46), U32(iv4(0.25, 0.55, 1.0, 0.08)), 48)
        dl:PopClipRect()
        dl:AddRect(p, q, U32(iv4(AR, AG, AB, 0.80)), S(12), 0, 1.4)
        local ang, dy, sc = PCS_stickerAnim(hov, 0.3)
        PCS_drawSticker(dl, "star", p.x + S(34), p.y + h * 0.5 + dy, S(16) * sc, ang)
        local stTxt, stCol
        if cfg.aiEnabled == false then stTxt, stCol = "Выключено", { 0.62, 0.65, 0.72 }
        elseif not AI.base() or tostring(cfg.aiKey or "") == "" then stTxt, stCol = "Укажи адрес бэкенда и ключ доступа", { 1.0, 0.72, 0.20 }
        elseif AI.checking then stTxt, stCol = "Проверка соединения…", { 0.62, 0.45, 1.0 }
        elseif AI.online == false then stTxt, stCol = (AI.statusMsg ~= "" and AI.statusMsg or "Нет связи с бэкендом"), { 1.0, 0.40, 0.40 }
        elseif AI.online == true then stTxt, stCol = "Подключено" .. ((AI.model or "") ~= "" and (" · " .. AI.model) or ""), { 0.35, 0.92, 0.55 }
        else stTxt, stCol = "Ожидание проверки", { 0.62, 0.65, 0.75 } end
        local tx = p.x + S(68)
        local tw = math.max(S(60), aw - S(68) - S(12))
        PCS_textAt(tx, p.y + S(11), tw, iv4(1, 1, 1, 1), "ИИ-помощник")
        dl:AddCircleFilled(V2(tx + S(5), p.y + S(11) + lh + S(3) + lh * 0.5), S(4.5), U32(iv4(stCol[1], stCol[2], stCol[3], 1.0)), 12)
        PCS_textAt(tx + S(16), p.y + S(11) + lh + S(3), tw - S(16), iv4(stCol[1], stCol[2], stCol[3], 1.0), stTxt)
        imgui.SetCursorScreenPos(V2(p.x, p.y + h))
        imgui.Dummy(V2(1, S(8)))
    end

    -- ── карточка лимита ──
    do
        local aw = imgui.GetContentRegionAvail().x
        local p = imgui.GetCursorScreenPos()
        local h = S(92)
        local q = V2(p.x + aw, p.y + h)
        local cr, cg, cb = PCS_AI.counterColor()
        imgui.Dummy(V2(aw, h))
        dl:AddRectFilled(p, q, U32(iv4(cr * 0.09, cg * 0.09, cb * 0.09 + 0.03, 0.98)), S(12))
        dl:AddRect(p, q, U32(iv4(cr, cg, cb, 0.55)), S(12), 0, 1.3)
        dl:AddText(V2(p.x + S(14), p.y + S(10)), U32(iv4(0.72, 0.76, 0.88, 1)), "Сообщений осталось сегодня")
        local big = PCS_AI.counterText()
        dl:AddText(V2(p.x + S(14), p.y + S(10) + lh + S(4)), U32(iv4(cr, cg, cb, 1)), big)
        if AI.rem and AI.lim and AI.lim > 0 then
            local rt = "сброс через " .. PCS_AI.fmtReset(AI.resetAt - os.time()) .. " ч"
            local rs = imgui.CalcTextSize(rt)
            dl:AddText(V2(q.x - S(14) - rs.x, p.y + S(10) + lh + S(4)), U32(iv4(0.62, 0.66, 0.78, 1)), rt)
        end
        local bx0, bx1, by = p.x + S(14), q.x - S(14), q.y - S(22)
        dl:AddRectFilled(V2(bx0, by), V2(bx1, by + S(8)), U32(iv4(1, 1, 1, 0.09)), S(4))
        local frac = (AI.rem and AI.lim and AI.lim > 0) and math.max(0, math.min(1, AI.rem / AI.lim)) or ((AI.lim and AI.lim < 0) and 1 or 0)
        if frac > 0.005 then dl:AddRectFilled(V2(bx0, by), V2(bx0 + (bx1 - bx0) * frac, by + S(8)), U32(iv4(cr, cg, cb, 0.95)), S(4)) end
        imgui.SetCursorScreenPos(V2(p.x, p.y + h))
        imgui.Dummy(V2(1, S(6)))
    end
    PCS_settHint("Лимит сообщений и API-ключи ИИ меняются в админке бэкенда" .. (AI.base() and (": " .. AI.base() .. "/admin") or "") .. ". Здесь только счётчик.")
    imgui.Spacing()

    -- ── переключатели ──
    if PCS_settToggleRow("##aiEnabled", cfg.aiEnabled ~= false, "Включить ИИ", "Чат с ИИ в игре: панель слева и команда /ai.") then
        cfg.aiEnabled = not (cfg.aiEnabled ~= false)
        saveCfg()
    end
    if PCS_settToggleRow("##aiMirror", cfg.aiMirrorChat == true, "Дублировать ответы в чат игры", "Ответы из панели тоже печатаются в чат SA-MP (на /ai — всегда).") then
        cfg.aiMirrorChat = not (cfg.aiMirrorChat == true)
        saveCfg()
    end

    -- ── подключение ──
    PCS_settSub("Подключение к бэкенду", "Адрес сервера и ключ доступа (CLIENT_KEY) из настроек бэкенда.")
    local fh = S(38)
    imgui.TextColored(thDim(), "Адрес бэкенда")
    local ch1 = PCS_tgField("##aiUrl", T.url, 160, "https://my-ai.onrender.com", "text", -1, fh, 0)
    if ch1 then cfg.aiUrl = (ffi.string(T.url):gsub("%s+", "")); T.dirty = os.clock() end
    imgui.Dummy(V2(0, S(4)))
    imgui.TextColored(thDim(), "Ключ доступа")
    local ch2 = PCS_tgField("##aiKey", T.key, 100, "CLIENT_KEY", "key", -1, fh, 0)
    if ch2 then cfg.aiKey = (ffi.string(T.key):gsub("%s+", "")); T.dirty = os.clock() end
    imgui.Dummy(V2(0, S(6)))

    local aw = imgui.GetContentRegionAvail().x
    local gap = S(8)
    local bw = math.floor((aw - gap * 2) / 3)
    if PCS_gdButton("Проверить##aiTest", bw, S(36), { 0.30, 0.65, 0.95 }, 8.0) then
        T.dirty = nil; pcall(saveCfg)
        AI.testResult = nil
        AI.refresh(true)
    end
    imgui.SameLine(0, gap)
    if PCS_gdButton("Открыть чат##aiOpen", bw, S(36), { 0.62, 0.45, 1.0 }, 8.0) then PCS_AI.toggle(true) end
    imgui.SameLine(0, gap)
    if PCS_gdButton("Очистить##aiClr", bw, S(36), { 0.95, 0.45, 0.45 }, 8.0) then PCS_AI.clear() end
    if AI.testResult then
        imgui.Dummy(V2(0, S(4)))
        local c = AI.testOk and iv4(0.35, 0.92, 0.55, 1) or iv4(1, 0.45, 0.45, 1)
        imgui.PushTextWrapPos(imgui.GetCursorPosX() + imgui.GetContentRegionAvail().x)
        imgui.TextColored(c, AI.testResult)
        imgui.PopTextWrapPos()
    end
    imgui.Dummy(V2(0, S(8)))

    -- ── управление ──
    PCS_settSub("Управление", "Горячая клавиша, размер панели, команды.")
    for _, a in ipairs(PCS_HK_ACTIONS or {}) do
        if a.id == "ai" then pcall(PCS_drawHotkeyRow, a) end
    end
    imgui.Dummy(V2(0, S(6)))
    imgui.TextColored(thDim(), "Ширина панели чата")
    imgui.PushItemWidth(-1)
    T.w[0] = tonumber(cfg.aiPanelW) or 380
    if imgui.SliderFloat("##aiPanelW", T.w, 300, 560, "%.0f px") then
        cfg.aiPanelW = math.floor(T.w[0])
        T.dirty = os.clock()
    end
    imgui.PopItemWidth()
    imgui.Spacing()
    PCS_settHint("Команды: /ai текст — вопрос ИИ с ответом в чат игры; /ai — открыть/закрыть панель; /aichat — панель; /aiclear — очистить память диалога.")
end
end

PCS_FXC = {
    soundOn = true, soundTab = true, soundDp = true, soundToast = true, volume = 60,
    soundAi = true, soundMention = true, soundTax = true, pack = 1,
}
PCS_FX = PCS_FX or {}

function PCS_FX.sc(n) return math.floor(n * (tonumber(St.UI_SCALE) or 1) + 0.5) end

function PCS_FX.load()
    pcall(function()
        local f = io.open(CFG_DIR .. "/fx.json", "rb")
        if not f then return end
        local body = f:read("*a"); f:close()
        if type(decodeJson) ~= "function" or not body or body == "" then return end
        local ok, t = pcall(decodeJson, body)
        if ok and type(t) == "table" then
            for k, v in pairs(t) do
                if PCS_FXC[k] ~= nil and type(v) == type(PCS_FXC[k]) then PCS_FXC[k] = v end
            end
        end
    end)
end

-- отложенное сохранение (слайдеры дёргают каждый кадр)
function PCS_FX.save() PCS_FX._dirtyAt = os.clock() end
function PCS_FX.flush(force)
    local d = PCS_FX._dirtyAt
    if not d then return end
    if not force and os.clock() - d < 0.6 then return end
    PCS_FX._dirtyAt = nil
    pcall(function()
        if type(encodeJson) ~= "function" then return end
        local f = io.open(CFG_DIR .. "/fx.json", "wb")
        if f then f:write(encodeJson(PCS_FXC)); f:close() end
    end)
end

-- ── звук: WAV генерируется из тонов (частота от-до в Гц, длительность в мс) ──
PCS_FX.RATE = 22050
PCS_FX.SETS = {
    tab     = { { 1400, 1100, 45 } },
    dp      = { { 660, 660, 90 }, { 880, 880, 140 } },
    info    = { { 880, 880, 110 }, { 1320, 1320, 160 } },
    success = { { 700, 1000, 120 }, { 1200, 1200, 150 } },
    warning = { { 560, 560, 110 }, { 420, 420, 160 } },
    error   = { { 500, 300, 230 } },
    payday  = { { 1000, 1000, 90 }, { 1000, 1000, 90 }, { 1500, 1500, 170 } },
    mention = { { 1046, 1046, 70 }, { 1568, 1568, 110 } },
    ai      = { { 520, 900, 120 }, { 900, 1300, 160 } },
    tax     = { { 1800, 1800, 60 }, { 2400, 2400, 60 }, { 1800, 1800, 110 } },
}
PCS_FX.TONE_COL = {
    info = { 0.25, 0.55, 0.95 }, success = { 0.22, 0.78, 0.40 }, warning = { 0.95, 0.66, 0.15 },
    error = { 0.92, 0.26, 0.26 }, payday = { 0.98, 0.80, 0.25 },
}

-- наборы тембров: harm[k] — громкость k-й гармоники, decay — скорость затухания
PCS_FX.PACKS = {
    { name = "Классика", harm = { 1 },                  decay = 3.0 },
    { name = "Мягкий",   harm = { 1, 0.25 },            decay = 2.2 },
    { name = "Колокол",  harm = { 1, 0, 0.5, 0, 0.25 }, decay = 4.5 },
    { name = "Электро",  harm = { 1, 0, 0.33, 0, 0.2 }, decay = 5.0 },
}
function PCS_FX.curPack()
    local k = math.floor(tonumber(PCS_FXC.pack) or 1)
    if not PCS_FX.PACKS[k] then k = 1 end
    return k
end

function PCS_FX.synth(parts, vol, pk)
    local rate = PCS_FX.RATE
    local P = PCS_FX.PACKS[pk or 1] or PCS_FX.PACKS[1]
    local wsum = 0
    for _, w in ipairs(P.harm) do wsum = wsum + w end
    local amp = (vol / 100) * 0.40 * 32767
    local out, phase = {}, 0
    for _, p in ipairs(parts) do
        local n = math.floor(rate * p[3] / 1000)
        for i = 0, n - 1 do
            local t = i / n
            local f = p[1] + (p[2] - p[1]) * t
            phase = phase + 2 * math.pi * f / rate
            local env = math.min(1, i / 110) * math.exp(-P.decay * t)
            local sm = 0
            for k, w in ipairs(P.harm) do sm = sm + w * math.sin(k * phase) end
            local v = math.floor(amp * env * sm / wsum + 0.5)
            if v < 0 then v = v + 65536 end
            out[#out + 1] = string.char(v % 256, math.floor(v / 256))
        end
    end
    return table.concat(out)
end

function PCS_FX.wav(pcm)
    local rate = PCS_FX.RATE
    local function u32(n)
        return string.char(n % 256, math.floor(n / 256) % 256, math.floor(n / 65536) % 256, math.floor(n / 16777216) % 256)
    end
    local function u16(n) return string.char(n % 256, math.floor(n / 256) % 256) end
    return "RIFF" .. u32(36 + #pcm) .. "WAVE" .. "fmt " .. u32(16) .. u16(1) .. u16(1)
        .. u32(rate) .. u32(rate * 2) .. u16(2) .. u16(16) .. "data" .. u32(#pcm) .. pcm
end

-- файлы пересоздаются только когда изменились громкость или набор звуков
function PCS_FX.ensureFiles()
    local vol = math.floor(tonumber(PCS_FXC.volume) or 60)
    local pk = PCS_FX.curPack()
    local key = vol .. ":" .. pk
    if PCS_FX._genKey == key and PCS_FX._genOk then return end
    pcall(winCreateDir, CFG_DIR .. "/sounds")
    local ok = true
    for name, parts in pairs(PCS_FX.SETS) do
        local f = io.open(CFG_DIR .. "/sounds/fx_" .. pk .. "_" .. name .. ".wav", "wb")
        if f then f:write(PCS_FX.wav(PCS_FX.synth(parts, vol, pk))); f:close() else ok = false end
    end
    PCS_FX._genKey, PCS_FX._genOk = key, ok
end

PCS_FX._ready = false
function PCS_FX.setupSound()
    pcall(function()
        if not ffi then return end
        pcall(ffi.cdef, "int PlaySoundA(const char *pszSound, void *hmod, unsigned long fdwSound);")
        PCS_FX._winmm = ffi.load("winmm")
        PCS_FX._ready = PCS_FX._winmm ~= nil
    end)
end

PCS_FX._lastPlay = 0
function PCS_FX.play(name, force)
    if not PCS_FX._ready then return end
    if not force and PCS_FXC.soundOn == false then return end
    if (tonumber(PCS_FXC.volume) or 0) <= 0 then return end
    local now = os.clock()
    if now - PCS_FX._lastPlay < 0.15 then return end
    PCS_FX._lastPlay = now
    pcall(PCS_FX.ensureFiles)
    local path = CFG_DIR .. "/sounds/fx_" .. PCS_FX.curPack() .. "_" .. name .. ".wav"
    pcall(function() PCS_FX._winmm.PlaySoundA(path, nil, 0x20003) end)
end

-- звук уведомления по его типу (вызывается из pcs_notify)
function PCS_FX.onToast(ntype, text)
    if PCS_FX._silent then return end
    local k = ntype or "info"
    if not PCS_FX.SETS[k] then k = "info" end
    if PCS_FXC.soundToast ~= false and not (k == "mention" and PCS_FXC.soundMention == false) then PCS_FX.play(k) end
end

-- ── переключение вкладок и окна ДП ──
function PCS_FX.tick()
    local tab = St.activeTab
    if PCS_FX._lastTab ~= nil and tab ~= PCS_FX._lastTab and St.winOpen then
        if tab == 10 then
            if PCS_FXC.soundDp ~= false then PCS_FX.play("dp") end
        elseif PCS_FXC.soundTab ~= false then
            PCS_FX.play("tab")
        end
    end
    PCS_FX._lastTab = tab
    local dep = St._depositOpen == true
    if dep and not PCS_FX._lastDep and tab ~= 10 and PCS_FXC.soundDp ~= false then PCS_FX.play("dp") end
    PCS_FX._lastDep = dep
    PCS_FX.flush(false)
end

function PCS_FX.init()
    PCS_FX.load()
    PCS_FX.setupSound()
    if not PCS_FX._threads then
        PCS_FX._threads = true
        lua_thread.create(function()
            while true do wait(200); pcall(PCS_FX.tick) end
        end)
    end
end

-- ── блок настроек «Звуки и помощник» (вкладка «Настройки» → «Уведомления») ──
function PCS_FX.slider(key, label, mn, mx)
    local C = PCS_FXC
    local bk = "fxBuf_" .. key
    if not St[bk] then St[bk] = imgui.new.int(math.floor(tonumber(C[key]) or mn)) end
    local buf = St[bk]
    buf[0] = math.floor(tonumber(C[key]) or mn)
    imgui.TextColored(iv4(0.70, 0.82, 1.0, 1.0), label)
    imgui.PushItemWidth(-1)
    if imgui.SliderInt("##fx_" .. key, buf, mn, mx, "%d") then
        C[key] = buf[0]
        PCS_FX.save()
    end
    imgui.PopItemWidth()
end

function PCS_drawFxSettings()
    local C = PCS_FXC
    local function tog(id, key, label, desc)
        if PCS_settToggleRow(id, C[key] ~= false, label, desc) then
            C[key] = not (C[key] ~= false)
            PCS_FX.save()
        end
    end
    local aw = imgui.GetContentRegionAvail().x
    local bh = PCS_FX.sc(28)

    PCS_settSub(u8"\xc7\xe2\xf3\xea\xe8", u8"\xca\xee\xf0\xee\xf2\xea\xe8\xe5\x20\xe7\xe2\xf3\xea\xe8\x20\xef\xf0\xe8\x20\xef\xe5\xf0\xe5\xea\xeb\xfe\xf7\xe5\xed\xe8\xe8\x20\xe2\xea\xeb\xe0\xe4\xee\xea\x2c\x20\xee\xf2\xea\xf0\xfb\xf2\xe8\xe8\x20\xc4\xcf\x20\xe8\x20\xf3\xe2\xe5\xe4\xee\xec\xeb\xe5\xed\xe8\xff\xf5\x2e\x20\xc3\xf0\xee\xec\xea\xee\xf1\xf2\xfc\x20\xee\xe1\xf9\xe0\xff\x2e")
    tog("##fxSound", "soundOn", u8"\xc7\xe2\xf3\xea\xe8\x20\xe2\xea\xeb\xfe\xf7\xe5\xed\xfb", u8"\xc3\xeb\xe0\xe2\xed\xfb\xe9\x20\xe2\xfb\xea\xeb\xfe\xf7\xe0\xf2\xe5\xeb\xfc\x20\xe2\xf1\xe5\xf5\x20\xe7\xe2\xf3\xea\xee\xe2\x20\xf1\xea\xf0\xe8\xef\xf2\xe0\x2e")
    tog("##fxSoundTab", "soundTab", u8"\xc7\xe2\xf3\xea\x20\xef\xe5\xf0\xe5\xea\xeb\xfe\xf7\xe5\xed\xe8\xff\x20\xe2\xea\xeb\xe0\xe4\xee\xea", u8"\xca\xee\xf0\xee\xf2\xea\xe8\xe9\x20\xf9\xe5\xeb\xf7\xee\xea\x20\xef\xf0\xe8\x20\xf1\xec\xe5\xed\xe5\x20\xe2\xea\xeb\xe0\xe4\xea\xe8\x20\xe2\x20\xec\xe5\xed\xfe\x2e")
    tog("##fxSoundDp", "soundDp", u8"\xc7\xe2\xf3\xea\x20\xee\xf2\xea\xf0\xfb\xf2\xe8\xff\x20\xc4\xcf", u8"\xcc\xe5\xeb\xee\xe4\xe8\xff\x20\xef\xf0\xe8\x20\xee\xf2\xea\xf0\xfb\xf2\xe8\xe8\x20\xe2\xea\xeb\xe0\xe4\xea\xe8\x20\xe8\xeb\xe8\x20\xee\xea\xed\xe0\x20\xab\xc4\xe5\xef\xee\xe7\xe8\xf2\xbb\x2e")
    tog("##fxSoundToast", "soundToast", u8"\xc7\xe2\xf3\xea\x20\xf3\xe2\xe5\xe4\xee\xec\xeb\xe5\xed\xe8\xe9", u8"\xd1\xe2\xee\xe9\x20\xf2\xee\xed\x20\xe4\xeb\xff\x20\xf3\xf1\xef\xe5\xf5\xe0\x2c\x20\xee\xf8\xe8\xe1\xea\xe8\x2c\x20\xef\xf0\xe5\xe4\xf3\xef\xf0\xe5\xe6\xe4\xe5\xed\xe8\xff\x20\xe8\x20\x50\x61\x79\x44\x61\x79\x2e")
    tog("##fxSoundMention", "soundMention", "Звук упоминания", "Отдельный звук, когда тебя упомянули в чате.")
    tog("##fxSoundTax", "soundTax", "Звук оплаты налогов", "Монетка после успешной оплаты налогов.")
    PCS_FX.slider("volume", u8"\xc3\xf0\xee\xec\xea\xee\xf1\xf2\xfc\x2c\x20\x25", 0, 100)
    -- ── набор звуков (тембр) ──
    imgui.TextColored(iv4(0.70, 0.82, 1.0, 1.0), "Набор звуков")
    do
        local packs = PCS_FX.PACKS
        local cur = PCS_FX.curPack()
        local gap = PCS_FX.sc(6)
        local pw = (aw - gap * (#packs - 1)) / #packs
        for i, pk in ipairs(packs) do
            if i > 1 then imgui.SameLine(0, gap) end
            local col = (i == cur) and { 0.30, 0.65, 0.95 } or { 0.26, 0.30, 0.40 }
            if PCS_gdButton(pk.name .. "##fxPack" .. i, pw, bh, col, 8.0) then
                PCS_FXC.pack = i
                PCS_FX.save()
                PCS_FX.play("info", true)
            end
        end
    end
    imgui.Spacing()

    -- ── проверка каждого звука (цвет — по смыслу уведомления) ──
    imgui.TextColored(iv4(0.70, 0.82, 1.0, 1.0), "Проверка звуков")
    do
        local tnames = {
            { "info",    "Инфо",       { 0.25, 0.55, 0.95 } },
            { "success", "Успех",      { 0.22, 0.75, 0.42 } },
            { "warning", "Внимание",   { 0.95, 0.66, 0.15 } },
            { "error",   "Ошибка",     { 0.90, 0.28, 0.28 } },
            { "payday",  "PayDay",     { 0.98, 0.78, 0.22 } },
            { "mention", "Упоминание", { 0.62, 0.45, 1.00 } },
            { "tax",     "Налоги",     { 0.20, 0.72, 0.78 } },
            { "tab",     "Вкладка",    { 0.42, 0.46, 0.58 } },
            { "dp",      "ДП",         { 0.92, 0.40, 0.66 } },
        }
        local cols = 4
        local tw = (aw - PCS_FX.sc(6) * (cols - 1)) / cols
        for ti, tn in ipairs(tnames) do
            if (ti - 1) % cols ~= 0 then imgui.SameLine(0, PCS_FX.sc(6)) end
            if PCS_gdButton(tn[2] .. "##fxT_" .. tn[1], tw, bh, tn[3], 8.0) then PCS_FX.play(tn[1], true) end
        end
    end
    imgui.Spacing()
    if PCS_gdButton("Проверить звук##fxTestSnd", aw, bh, { 0.30, 0.60, 0.95 }, 8.0) then
        PCS_FX.play("success", true)
    end
    imgui.Spacing()
end

function main()
    -- На случай переиспользования Lua-стейта: стартуем с чистыми флагами телефона/налогов
    _phoneOpBusy, _taxState, _cefFetching, _phoneFetchState = false, 0, false, false
    _taxOpenInProgress, _taxDlgSeq, _taxFinalizeDone = false, 0, false
    St._phoneOpBusySince = nil
    loadCfg()
    pcall(PCS_FX.init) -- звуки, помощник, случайные фразы
    pcall(PCS_AI.init)
    if saveCfgLater then saveCfg(); saveCfgLater = false end
    St.activeTab = 1

    St.winWbuf[0] = cfg.winWPct > 0 and cfg.winWPct or 0.60
    St.winHbuf[0] = cfg.winHPct > 0 and cfg.winHPct or 0.76
    if cfg.custR >= 0 then
        St.custRbuf[0] = cfg.custR
        St.custGbuf[0] = cfg.custG
        St.custBbuf[0] = cfg.custB
    else
        local a = getTheme().acc
        St.custRbuf[0] = a[1]; St.custGbuf[0] = a[2]; St.custBbuf[0] = a[3]
    end
    if cfg.rowBgR >= 0 then
        St.rowBgRbuf[0] = cfg.rowBgR
        St.rowBgGbuf[0] = cfg.rowBgG
        St.rowBgBbuf[0] = cfg.rowBgB
    else
        local a = getTheme().acc
        St.rowBgRbuf[0] = a[1]; St.rowBgGbuf[0] = a[2]; St.rowBgBbuf[0] = a[3]
    end
    -- синхронизация цвета текста / фона окна / обводки
    if cfg.textR >= 0 then
        St.textRbuf[0] = cfg.textR; St.textGbuf[0] = cfg.textG; St.textBbuf[0] = cfg.textB
    else
        St.textRbuf[0] = 1.0; St.textGbuf[0] = 1.0; St.textBbuf[0] = 1.0
    end
    if cfg.winBgR >= 0 then
        St.winBgRbuf[0] = cfg.winBgR; St.winBgGbuf[0] = cfg.winBgG; St.winBgBbuf[0] = cfg.winBgB
    else
        St.winBgRbuf[0] = 0.0; St.winBgGbuf[0] = 0.0; St.winBgBbuf[0] = 0.0
    end
    if cfg.outlineR >= 0 then
        St.outlineRbuf[0] = cfg.outlineR; St.outlineGbuf[0] = cfg.outlineG; St.outlineBbuf[0] = cfg.outlineB
    else
        local a2 = getTheme().acc
        St.outlineRbuf[0] = a2[1]*0.45; St.outlineGbuf[0] = a2[2]*0.45; St.outlineBbuf[0] = a2[3]*0.45
    end
    if cfg.chatR and cfg.chatR >= 0 then
        St.chatRbuf[0] = cfg.chatR; St.chatGbuf[0] = cfg.chatG; St.chatBbuf[0] = cfg.chatB
    else
        St.chatRbuf[0] = 0.0; St.chatGbuf[0] = 1.0; St.chatBbuf[0] = 0.53
    end
    chkBuf2[0] = cfg.hideNativeStats
    St.fontSizeBuf[0] = cfg.fontSize > 0 and cfg.fontSize or 1.25
    pcall(function() St.menuCmdBuf = imgui.new("char[16]", cfg.menuOpenCmd or "sw") end)
    if not St.menuCmdBuf then
        St.menuCmdBuf = imgui.new("char[16]", "sw")
    end

    -- ── синхронизация буферов вкладки "Налоги" ──
    St.taxAutoBuf[0]         = cfg.taxAutoEnabled
    St.taxIntervalBuf[0]     = cfg.taxAutoIntervalHours
    St.taxPayOnLoginBuf[0]   = cfg.taxPayOnLogin

    repeat wait(100) until isSampAvailable()

    local _lastToggleClock = 0
    function toggleMenuWindow()
        local nowC = os.clock()
        if nowC - _lastToggleClock < 0.15 then return end
        _lastToggleClock = nowC
        if not isSampAvailable() then return end
        if not St.winOpen and PCS_uiLocked and PCS_uiLocked() then
            if os.clock() - (St._uiLockNoteAt or 0) > 2 then
                St._uiLockNoteAt = os.clock()
                pcall(sampAddChatMessage, "{FFB347}[PC Stats] {FFFFFF}\xcf\xee\xe4\xee\xe6\xe4\xe8\xf2\xe5, \xe8\xe4\xb8\xf2 \xee\xef\xe5\xf0\xe0\xf6\xe8\xff \xf1 \xf2\xe5\xeb\xe5\xf4\xee\xed\xee\xec\x85", -1)
            end
            return
        end
        if St.winOpen then
            requestCloseMenu()
            return
        end
        if not St._winVisible then
            St._menuOpenAnim = (cfg.smoothMenuAnim == false or cfg.animAllOff == true) and 1 or 0
            St._menuOpenAnimT = nil
            St._menuSlideAnchor = nil
            St._taxCalendarPopupOpen = false; St._taxCalendarPopupOpenedOnce = false
            St._taxLogEntriesPopupOpen = false; St._taxLogEntriesOpenedOnce = false
            St._closeConfirmOpen = false
        end
        St.winOpen = true
        St._winVisible = true
        St._toastSessionActive = true
        _sw_win_init = nil
        do
            local okW, wd = pcall(getWorkingDirectory)
            local dir = (okW and type(wd) == "string" and wd ~= "") and (wd .. "/config/PCStats") or CFG_DIR
            pcall(createDirectory, wd and (wd .. "/config") or "moonloader/config")
            pcall(createDirectory, dir)
            PCS_TRACE_PATH = dir .. "/crashtrace.txt"
            pcall(PCS_GUARD.traceOpen, PCS_TRACE_PATH)
            if not PCS_TRACE_SHOWN then
                PCS_TRACE_SHOWN = true
                print("[PC Stats] trace file: " .. tostring(PCS_TRACE_PATH))
            end
        end
        PCS_GUARD.mark("toggleMenuWindow: open")
        lastAutoTime = now()
        if not St.statsData then
            pcall(requestStats)
        end
        PCS_GUARD.mark("toggleMenuWindow: requestStats returned")
    end

    function registerMenuCommand(cmdName)
        cmdName = tostring(cmdName or "sw"):gsub("^/+", ""):gsub("%s+", "")
        if cmdName == "" then cmdName = "sw" end
        if _registeredMenuCmd then
            pcall(sampUnregisterChatCommand, _registeredMenuCmd)
        end
        local ok = pcall(sampRegisterChatCommand, cmdName, toggleMenuWindow)
        if ok then _registeredMenuCmd = cmdName end
        return ok, cmdName
    end

    registerMenuCommand(cfg.menuOpenCmd)

    -- ── горячая клавиша открытия меню (cfg.menuHotkeyVK) — отдельный поток ──
    lua_thread.create(PCS_hotkeyLoop)

    -- ── AIS (охоронці): команди /sppet /offpet /fasteat /ais... ──
    pcall(function()
        if AIS and AIS.init then AIS.init() end
    end)

    pcall(sampRegisterChatCommand, "paytax", function() PCS_safeManualPay() end)

    -- ── диагностика: запись исходящих пакетов (/pcspkt) — чтобы узнать, как Arizona
    -- отправляет предмет/стикер в чат. Пишет в config/PCStats/packets.txt ──
    PCS_PKT = PCS_PKT or { on = false, n = 0 }
    local function pktDump(tag, id, bs)
        if not PCS_PKT.on then return end
        pcall(function()
            if tag == "PKT" and id ~= 220 then return end
            if tag == "RPC" and id ~= 50 and id ~= 101 then return end
            PCS_PKT.n = PCS_PKT.n + 1
            if PCS_PKT.n > 400 then PCS_PKT.on = false; return end
            local n = raknetBitStreamGetNumberOfBytesUsed(bs)
            if n > 300 then n = 300 end
            raknetBitStreamResetReadPointer(bs)
            local hex, asc = {}, {}
            for i = 1, n do
                local v = raknetBitStreamReadInt8(bs) % 256
                hex[i] = string.format("%02X", v)
                asc[i] = (v >= 32 and v < 127) and string.char(v) or "."
            end
            raknetBitStreamResetReadPointer(bs)
            local f = io.open(CFG_DIR .. "/packets.txt", "a")
            if f then
                f:write(os.date("%H:%M:%S") .. " " .. tag .. " id=" .. tostring(id) .. " len=" .. tostring(n) .. "\n")
                f:write("  HEX: " .. table.concat(hex, " ") .. "\n")
                f:write("  TXT: " .. table.concat(asc) .. "\n")
                f:close()
            end
        end)
    end
    pcall(addEventHandler, "onSendPacket", function(id, bs) pktDump("PKT", id, bs) end)
    pcall(addEventHandler, "onSendRpc", function(id, bs) pktDump("RPC", id, bs) end)
    pcall(sampRegisterChatCommand, "pcspkt", function()
        PCS_PKT.on = not PCS_PKT.on
        PCS_PKT.n = 0
        if PCS_PKT.on then
            pcall(os.remove, CFG_DIR .. "/packets.txt")
            pcall(sampAddChatMessage, "{00FF88}[PC Stats] \xe7\xe0\xef\xe8\xf1\xfc\x20\xef\xe0\xea\xe5\xf2\xee\xe2\x20\xc2\xca\xcb\x2e\x20\xc2\xf1\xf2\xe0\xe2\xfc\xf2\xe5\x20\xef\xf0\xe5\xe4\xec\xe5\xf2\x20\xe2\x20\xf7\xe0\xf2\x20\xe8\x20\xee\xf2\xef\xf0\xe0\xe2\xfc\xf2\xe5\x2c\x20\xe7\xe0\xf2\xe5\xec\x20\xf1\xed\xee\xe2\xe0\x20\x2f\x70\x63\x73\x70\x6b\x74", -1)
        else
            pcall(sampAddChatMessage, "{FFAA00}[PC Stats] \xe7\xe0\xef\xe8\xf1\xfc\x20\xef\xe0\xea\xe5\xf2\xee\xe2\x20\xe2\xfb\xea\xeb\xfe\xf7\xe5\xed\xe0\x3a\x20\x63\x6f\x6e\x66\x69\x67\x2f\x50\x43\x53\x74\x61\x74\x73\x2f\x70\x61\x63\x6b\x65\x74\x73\x2e\x74\x78\x74", -1)
        end
    end)
    pcall(function() PCS_REM.load(); PCS_REM.registerCmd(); PCS_REM.start() end)
    pcall(function() if PCS_RC and PCS_RC.start then PCS_RC.start() end end)
    pcall(function() if PCS_AD and PCS_AD.init then PCS_AD.init() end end)

    pcall(sampRegisterChatCommand, "pcsupdate", function(arg)
        arg = tostring(arg or ""):gsub("^%s+", ""):gsub("%s+$", ""):lower()
        if arg == "install" or arg == "update" then
            pcsInstallUpdate()
        else
            pcsCheckForUpdate(false)
        end
    end)

    pcall(function()
        if PCS_UPDATE and PCS_UPDATE.cleanup then PCS_UPDATE.cleanup()
        elseif PCS_UPDATE and PCS_UPDATE.cleanupHttpTmp then PCS_UPDATE.cleanupHttpTmp() end
    end)

    if (cfg.autoCheckUpdates ~= false) and (not PCS_UPDATE.cfg or PCS_UPDATE.cfg.autoCheck ~= false) then
        lua_thread.create(function()
            for _i = 1, 180 do
                local okS, spawned = pcall(function()
                    return sampIsLocalPlayerSpawned and sampIsLocalPlayerSpawned()
                end)
                if okS and spawned then break end
                wait(1000)
            end
            wait(3000)
            pcall(pcsCheckForUpdate, true)
            local sec = tonumber(PCS_UPDATE_AUTO_SECONDS) or 300
            if sec < 300 then sec = 300 end
            if sec > 3600 then sec = 3600 end
            while true do
                wait(sec * 1000)
                if cfg.autoCheckUpdates ~= false then
                    pcall(pcsCheckForUpdate, true)
                end
            end
        end)
    end

    PCS_REOPEN_AFTER_TAX = false
    do
        local rf = io.open(PCS_reopenFlagPath(), "rb")
        if rf then
            local ts = tonumber(rf:read("*a") or "")
            rf:close()
            pcall(os.remove, PCS_reopenFlagPath())
            if ts and (os.time() - ts) < 90 then PCS_REOPEN_AFTER_TAX = true end
        end
    end
    if PCS_REOPEN_AFTER_TAX then
        lua_thread.create(function()
            for _ = 1, 60 do
                wait(250)
                if isPlayerActuallySpawned() then break end
            end
            wait(6000)
            St._menuOpenAnim = (cfg.smoothMenuAnim == false or cfg.animAllOff == true) and 1 or 0
            St._menuOpenAnimT = nil
            St._menuSlideAnchor = nil
            _sw_win_init = nil
            St.winOpen = true
            St._winVisible = true
            St._toastSessionActive = true
            wait(1500)
            if not St.statsData then pcall(requestStats, true) end
        end)
    end

    do
        local sf = io.open(PCS_taxStageFile(), "rb")
        if sf then
            local last = sf:read("*a") or ""
            sf:close()
            if last ~= "" and not last:find("^DONE") then
                pcall(PCS_TR, "tax: PREVIOUS RUN ENDED AT STAGE " .. last)
                lua_thread.create(function()
                    wait(8000)
                    pcall(sampAddChatMessage, "{FF6666}[PC Stats] {FFFFFF}\xcf\xf0\xee\xf8\xeb\xfb\xe9 \xe7\xe0\xef\xf3\xf1\xea \xf1\xea\xf0\xe8\xef\xf2\xe0 \xef\xf0\xe5\xf0\xe2\xe0\xeb\xf1\xff \xe2\xee \xe2\xf0\xe5\xec\xff \xee\xef\xeb\xe0\xf2\xfb \xed\xe0\xeb\xee\xe3\xee\xe2. \xcf\xf0\xe8\xf7\xe8\xed\xe0 \xed\xe5 \xee\xe1\xff\xe7\xe0\xf2\xe5\xeb\xfc\xed\xee \xe2\xfb\xeb\xe5\xf2 \xe8\xe3\xf0\xfb, \xfd\xf2\xee \xec\xee\xe3 \xe1\xfb\xf2\xfc \xf2\xe0\xea\xe6\xe5 \xf0\xe0\xe7\xf0\xfb\xe2 \xf1\xee\xe5\xe4\xe8\xed\xe5\xed\xe8\xff, \xef\xe5\xf0\xe5\xef\xee\xe4\xea\xeb\xfe\xf7\xe5\xed\xe8\xe5 \xea \xe4\xf0\xf3\xe3\xee\xec\xf3 \xf1\xe5\xf0\xe2\xe5\xf0\xf3 \xe8\xeb\xe8 \xe7\xe0\xea\xf0\xfb\xf2\xe8\xe5 \xe8\xe3\xf0\xfb. {FFD700}\xcf\xee\xf1\xeb\xe5\xe4\xed\xe8\xe9 \xfd\xf2\xe0\xef: " .. last, -1)
                end)
            end
        end
        pcall(PCS_taxStage, "DONE (startup)")
    end
    pcall(sampRegisterChatCommand, "taxsoft", function()
        PCS_TAX_SOFT_REFRESH = not PCS_TAX_SOFT_REFRESH
        if PCS_TAX_SOFT_REFRESH then
            pcall(os.remove, CFG_DIR .. "/tax_reload.flag")
        else
            local f = io.open(CFG_DIR .. "/tax_reload.flag", "wb"); if f then f:write("1"); f:close() end
        end
        pcall(sampAddChatMessage, "{00FF88}[PC Stats] {FFFFFF}\xd0\xe5\xe6\xe8\xec \xef\xee\xf1\xeb\xe5 \xee\xef\xeb\xe0\xf2\xfb \xed\xe0\xeb\xee\xe3\xee\xe2: " ..
            (PCS_TAX_SOFT_REFRESH and "{00FF88}\xec\xff\xe3\xea\xee\xe5 \xee\xe1\xed\xee\xe2\xeb\xe5\xed\xe8\xe5 (\xe1\xe5\xe7 \xef\xe5\xf0\xe5\xe7\xe0\xe3\xf0\xf3\xe7\xea\xe8 \xf1\xea\xf0\xe8\xef\xf2\xe0)" or "{FFD700}\xef\xe5\xf0\xe5\xe7\xe0\xe3\xf0\xf3\xe7\xea\xe0 \xf1\xea\xf0\xe8\xef\xf2\xe0"), -1)
    end)

    pcall(sampRegisterChatCommand, "pcsdesign", function()
        cfg.uiDesignV2 = not cfg.uiDesignV2
        saveCfg()
        pcall(sampAddChatMessage, "{00FF88}[PC Stats] {FFFFFF}\xc4\xe8\xe7\xe0\xe9\xed \xec\xe5\xed\xfe: " ..
            (cfg.uiDesignV2 and "{00FF88}\xef\xeb\xee\xf1\xea\xe8\xe9 (v2)" or "{FFD700}\xf1\xf2\xe0\xed\xe4\xe0\xf0\xf2\xed\xfb\xe9"), -1)
    end)

    if _restoredMenuCmd and not PCS_REOPEN_AFTER_TAX then
        PCS_NO_TOAST_ONCE = true
        pcall(sampAddChatMessage, "{00FF88}[PC Stats] \xf0\x9f\x94\x93 " ..
            "\xc2\xee\xf1\xf1\xf2\xe0\xed\xee\xe2\xeb\xe5\xed\xe0\x20\xea\xee\xec\xe0\xed\xe4\xe0\x20\xee\xf2\xea\xf0\xfb\xf2\xe8\xff\x20\xec\xe5\xed\xfe: /" .. tostring(_registeredMenuCmd or cfg.menuOpenCmd), -1)
    end

    lua_thread.create(function()
        for _i = 1, 120 do
            wait(500)
            local spawned = false
            pcall(function()
                local ok, res = pcall(function()
                    return sampIsLocalPlayerSpawned and sampIsLocalPlayerSpawned()
                end)
                if ok and res then spawned = true end
            end)
            if spawned then break end
        end
        _sessionStartTime = os.time()
        wait(2000)
        pcall(function()
            if cfg.rateVC <= 0 and cfg.rateBTC <= 0 then
                fetchArzWikiRates(true)
            end
        end)
        local _startCmd = tostring(_registeredMenuCmd or cfg.menuOpenCmd or "sw")
        if PCS_REOPEN_AFTER_TAX then return end   -- после перезапуска по налогам: без сообщений
        PCS_NO_TOAST_ONCE = true
        pcall(sampAddChatMessage,
            "{00FF88}[MSW v" .. SCRIPT_VER .. "] {FFFFFF}PC Stats | Cmd: {00FF88}/" .. _startCmd, -1)
        pcall(function()
            if type(pcs_notify) == "function" then
                pcs_notify(u8"\xd1\xea\xf0\xe8\xef\xf2\x20\xf3\xf1\xef\xe5\xf8\xed\xee\x20\xe7\xe0\xef\xf3\xf9\xe5\xed\x21\x20\x20\xca\xee\xec\xe0\xed\xe4\xe0\x3a\x20\x2f" .. _startCmd, "success", 9)
            end
        end)
    end)

    lua_thread.create(function()
        local lastSpawned = false
        while true do
            local okT, errT = pcall(function()
                if not isPlayerActuallySpawned() then
                    if lastSpawned then
                        -- вышли/перезашли в игру: заново взводим оплату при входе
                        _taxLoginFired = false
                        _taxLoginSkippedRecent = false
                        _taxLoginWaitEndTime = nil
                    end
                    lastSpawned = false
                    wait(500)
                    return
                end
                lastSpawned = true
                if not (cfg.taxPayOnLogin and not _taxLoginFired) then
                    wait(1000)
                    return
                end
                local delaySec = 60
                _taxLoginWaitEndTime = os.time() + delaySec
                local left = delaySec
                while left > 0 do
                    wait(1000); left = left - 1
                    if not cfg.taxPayOnLogin or not isPlayerActuallySpawned() then break end
                end
                _taxLoginWaitEndTime = nil
                if left > 0 then return end
                for _try = 1, 10 do
                    if not cfg.taxPayOnLogin or not isPlayerActuallySpawned() then break end
                    pcall(payTaxesNow, true)
                    if _taxState ~= 0 then _taxLoginFired = true; break end
                    local lastT = tonumber(cfg.taxLastPayTime) or 0
                    local gap = math.max(3600, math.max(1, tonumber(cfg.taxAutoIntervalHours) or 1) * 3600)
                    if lastT ~= 0 and (os.time() - lastT) < gap then
                        _taxLoginFired = true; _taxLoginSkippedRecent = true; break
                    end
                    wait(30000)
                end
            end)
            if not okT then
                print("[PC Stats][tax] login thread error: " .. tostring(errT))
                _taxLoginWaitEndTime = nil
                wait(2000)
            end
        end
    end)

    lastAutoTime = now()
    while true do
        wait(100)

        local okLoop, errLoop = pcall(function()
            if St.waitingStats then
                local dt = now() - lastTdTime
                local dr = now() - lastReqTime
                if next(tdCollector) ~= nil and captureStarted and dt >= TD_DELAY then
                    local ok2, err2 = pcall(finalize)
                    if not ok2 then
                        St.waitingStats    = false
                        tdCollector     = {}
                        tdCollectorSize = 0
                        St.statusMsg = u8"\xce\xf8\xe8\xe1\xea\xe0 \xef\xe0\xf0\xf1\xe8\xed\xe3\xe0"
                        PCS_quietErr("ui@20160", err2)
                        pcall(pcs_notify, St.statusMsg, "error")
                    end
                elseif dr >= REQ_TIMEOUT then
                    St.waitingStats    = false
                    tdCollector     = {}
                    tdCollectorSize = 0
                    if not St.statsData then
                        St.statusMsg = u8"\xcd\xe5 \xf3\xe4\xe0\xeb\xee\xf1\xfc"
                    end
                end
            end

            if St._cfgDirtyAt and os.clock() - St._cfgDirtyAt > 0.6 then
                PCS_saveCfgFlush()
            end

            if os.time() ~= PCS_AD._lastTick then
                PCS_AD._lastTick = os.time()
                pcall(PCS_AD.tick)
            end

            if _phoneOpBusy and St._phoneOpBusySince and (os.time() - St._phoneOpBusySince) > 30 then
                _phoneOpBusy         = false
                _taxState            = 0
                _cefFetching         = false
                _phoneFetchState     = false
                St._phoneOpBusySince = nil
                _taxOpenInProgress   = false
                St._closePhoneRunning = false
                pcall(PCS_texQuietFor, 10)
                PCS_quietErr("watchdog", "phone released")
            end
            if St._closePhoneRunning and St._closePhoneSince and (os.time() - St._closePhoneSince) > 20 then
                St._closePhoneRunning = false
                _phoneOpBusy = false
            end

        end)

        if not okLoop then
            St.waitingStats = false
            St.awaitingHotkeyBind = false
            tdCollector = {}
            tdCollectorSize = 0
            local errText = tostring(errLoop)
            local nowT = os.time()
            if errText ~= St._lastLoopErrMsg or not St._lastLoopErrTime or (nowT - St._lastLoopErrTime) > 10 then
                St._lastLoopErrMsg  = errText
                St._lastLoopErrTime = nowT
                PCS_quietErr("loop", errText)
            end
        end
    end
end

-- ник игрока (нужен для определения мута и Telegram; никуда ничего не отправляет)
function PCS_getNick()
    local n = ""
    pcall(function()
        if St and St.statsData and St.statsData.name and St.statsData.name ~= "" then
            n = tostring(St.statsData.name)
        end
    end)
    if n == "" then
        pcall(function()
            if sampGetPlayerIdByCharHandle and sampGetPlayerNickname and PLAYER_PED then
                local ok, id = pcall(sampGetPlayerIdByCharHandle, PLAYER_PED)
                if ok and id then n = tostring(sampGetPlayerNickname(id) or "") end
            end
        end)
    end
    return n
end

function onScriptTerminate(s, q)
    if s == thisScript() then
        pcall(function()
            if PCS_TAX_STAGE and not tostring(PCS_TAX_STAGE):find("^DONE") then
                PCS_taxStage("DONE (terminated)")
            end
        end)
        pcall(function() if PCS_AD and PCS_AD.flush then PCS_AD.flush() end end)
        -- сбрасываем замки телефона/налогов, чтобы выгрузка посреди операции
        -- не оставила "залипшее" состояние при переиспользовании стейта
        pcall(function()
            _phoneOpBusy, _taxState, _cefFetching, _phoneFetchState = false, 0, false, false
            _taxOpenInProgress, _taxFinalizeDone = false, false
        end)
        pcall(PCS_saveCfgNow)
        pcall(PCS_toastFlush, true)
        pcall(function() if PCS_GDIP and PCS_GDIP.shutdown then PCS_GDIP.shutdown() end end)
        pcall(function()
            if PCS_GUARD and PCS_GUARD.tf then
                pcall(PCS_GUARD.tf.close, PCS_GUARD.tf)
                PCS_GUARD.tf = nil
            end
        end)
    end
end
